def _load_settings_files():
    """Reads KEY=VALUE lines from payments.env (and .env) next to this file, so payment
    keys can be set without touching the code. Real environment variables win."""
    here = os.path.dirname(os.path.abspath(__file__))
    for name in ('.env', 'payments.env'):
        path = os.path.join(here, name)
        if not os.path.exists(path):
            continue
        with open(path, encoding='utf-8-sig') as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                k, v = line.split('=', 1)
                v = v.split(' #')[0].strip().strip('"').strip("'")
                if k.strip() and v:
                    os.environ.setdefault(k.strip(), v)


_load_settings_files()
# ============ SETTINGS FILE (.env) ============
# Put your keys in a file called .env next to backen.py, one per line:
#   GOOGLE_CLIENT_ID=...
#   GOOGLE_CLIENT_SECRET=...
#   FLASK_SECRET_KEY=...
#   MAIL_USERNAME=...
#   MAIL_PASSWORD=...
# They load every time the server starts, so you no longer have to set
# $env:... in each new terminal. Real environment variables still win.
# Never commit .env or paste these values into a template.
def _load_env_file(path=None):
    path = path or os.path.join(os.path.dirname(os.path.abspath(__file__)), '.env')
    try:
        with open(path, encoding='utf-8') as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                key, val = line.split('=', 1)
                key = key.strip().removeprefix('export ').removeprefix('$env:').strip()
                val = val.strip().strip('"').strip("'")
                if key and key not in os.environ:
                    os.environ[key] = val
    except FileNotFoundError:
        pass


_load_env_file()

