# ============ SECURITY ============
import hmac as _hmac_cmp
import secrets as _secrets
import time as _clock
from werkzeug.security import generate_password_hash, check_password_hash


def _load_secret_key():
    """The secret key signs every sign-in cookie and reset link. Anyone who
    knows it could sign in as anyone, so it must never be a known value.
    Uses FLASK_SECRET_KEY if you set one (e.g. in .env); otherwise creates a
    long random key once and keeps it in the file .secret_key next to this
    file, so people stay signed in when the server restarts.
    Never share .secret_key or put it on GitHub."""
    key = (os.environ.get("FLASK_SECRET_KEY") or '').strip()
    if key and key != 'super_secret_key_123' and len(key) >= 16:
        return key
    if key:
        print("FLASK_SECRET_KEY is too short or is the old default; using .secret_key instead.")
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), '.secret_key')
    try:
        with open(path, encoding='utf-8') as fh:
            saved = fh.read().strip()
        if len(saved) >= 32:
            return saved
    except FileNotFoundError:
        pass
    saved = _secrets.token_hex(32)
    with open(path, 'w', encoding='utf-8') as fh:
        fh.write(saved)
    print("Created a new secret key in .secret_key (keep this file private).")
    return saved


app.secret_key = _load_secret_key()

