# ---- Passwords are stored scrambled (hashed), never as plain text ----
def hash_password(plain):
    return generate_password_hash(plain)


def _is_password_hash(value):
    return isinstance(value, str) and value.startswith(('scrypt:', 'pbkdf2:'))


def password_matches(stored, given):
    """True if `given` is the right password for the stored value."""
    if not stored or not given:
        return False
    if _is_password_hash(stored):
        try:
            return check_password_hash(stored, given)
        except (ValueError, TypeError):
            return False
    # an old plain-text password (they are all upgraded when the server starts)
    return _hmac_cmp.compare_digest(str(stored).encode(), given.encode())


def _upgrade_plain_passwords():
    """One-time upgrade: scrambles any passwords still stored as plain text.
    People keep signing in with the same password as before."""
    conn = sqlite3.connect('users.db', timeout=10)
    try:
        rows = conn.execute("SELECT id, password FROM users WHERE password IS NOT NULL AND password != ''").fetchall()
        todo = [(hash_password(pw), uid) for uid, pw in rows if not _is_password_hash(pw)]
        if todo:
            conn.executemany('UPDATE users SET password = ? WHERE id = ?', todo)
            conn.commit()
            print(f"Secured {len(todo)} password(s) that were stored as plain text.")
    except sqlite3.Error as e:
        print(f"Password upgrade skipped: {e}")
    finally:
        conn.close()


# ---- Too many wrong passwords: wait before trying again ----
LOGIN_MAX_FAILS_PER_EMAIL = 5      # wrong passwords for one email ...
LOGIN_MAX_FAILS_PER_DEVICE = 20    # ... or from one network address ...
LOGIN_LOCK_MINUTES = 15            # ... within this many minutes
_login_fails = {}


def _login_keys(email):
    return [('em:' + (email or '').strip().lower(), LOGIN_MAX_FAILS_PER_EMAIL),
            ('ip:' + (request.remote_addr or ''), LOGIN_MAX_FAILS_PER_DEVICE)]


def login_wait_minutes(email):
    """0 if signing in is allowed now, otherwise minutes left to wait."""
    now, window, wait = _clock.time(), LOGIN_LOCK_MINUTES * 60, 0
    for key, limit in _login_keys(email):
        recent = [t for t in _login_fails.get(key, []) if now - t < window]
        _login_fails[key] = recent
        if len(recent) >= limit:
            wait = max(wait, int((window - (now - recent[-limit])) // 60) + 1)
    return wait


def login_failed(email):
    now = _clock.time()
    for key, _ in _login_keys(email):
        _login_fails.setdefault(key, []).append(now)


def login_succeeded(email):
    _login_fails.pop('em:' + (email or '').strip().lower(), None)


def too_many_attempts_message(minutes):
    return f"Too many wrong passwords. For your safety, please wait {minutes} minute{'s' if minutes != 1 else ''} and try again, or use Forgot password."

