# ---- CSRF: a form or script on another website must not be able to act as a signed-in user ----
# Every POST/PUT/PATCH/DELETE must come from Eschool's own pages. Browsers always say where a
# request comes from (Sec-Fetch-Site / Origin / Referer), so this works for every page without
# changing any of them. Payment providers calling us back are the only exceptions.
CSRF_EXEMPT_PREFIXES = ('/api/stripe/webhook', '/api/mpesa/callback/', '/api/mpesa/b2c/')


def _same_site_request():
    site = request.headers.get('Sec-Fetch-Site')
    if site:
        return site in ('same-origin', 'none')
    origin = request.headers.get('Origin') or request.headers.get('Referer')
    if not origin:
        return True                      # very old browsers / tools: the SameSite cookie still protects
    from urllib.parse import urlparse
    return urlparse(origin).netloc == request.host


@app.before_request
def _csrf_guard():
    if request.method in ('GET', 'HEAD', 'OPTIONS'):
        return None
    if request.path.startswith(CSRF_EXEMPT_PREFIXES):
        return None
    if not _same_site_request():
        print(f"blocked cross-site {request.method} {request.path} from {request.headers.get('Origin') or request.headers.get('Referer')}")
        return jsonify({'success': False, 'message': 'This request was blocked for your safety. Please reload the page and try again.'}), 403
    return None


# ---- Signed-out after being idle, checked on the server (the page's own timer can be edited) ----
# Turned off: Eschool no longer signs anyone out for being inactive (without "Remember me"
# the sign-in still ends when the browser is closed). Set e.g. timedelta(hours=12) to bring it back.
SERVER_IDLE_LIMIT = None


@app.before_request
def _server_idle_timeout():
    if SERVER_IDLE_LIMIT is None or 'user_id' not in session or session.permanent:
        return None
    now = datetime.now(timezone.utc)
    last = session.get('_seen')
    try:
        last = datetime.fromisoformat(last) if last else None
    except (TypeError, ValueError):
        last = None
    if last and now - last > SERVER_IDLE_LIMIT:
        session.clear()
        if request.path.startswith('/api/') or request.is_json:
            return jsonify({'success': False, 'logged_in': False, 'message': 'You were signed out after being away. Please sign in again.'}), 401
        return redirect('/Login')
    if not last or (now - last).total_seconds() > 60:    # don't rewrite the cookie on every request
        session['_seen'] = now.isoformat()
    return None

