def get_random_quote():
    """Get a random quote - changes on every page load"""
    return random.choice(QUOTES)

# Only short quotes go on the dashboard banner, so a long one never pushes the
# Active Courses / Avg. Progress / Module Streak numbers down.
QUOTE_MAX_CHARS = 75
SHORT_QUOTES = [q for q in QUOTES if len(q['text']) <= QUOTE_MAX_CHARS]


def get_daily_quote():
    """Today's quote: the same for the whole day (Nairobi time), a new one each day."""
    day = (datetime.now(timezone.utc) + timedelta(hours=3)).date().toordinal()
    return SHORT_QUOTES[day % len(SHORT_QUOTES)]

def get_user_quote(user_email):
    """
    Get a quote based on user's email hash - consistent per user
    Changes only when the user logs in again
    """
    hash_value = int(hashlib.md5(user_email.encode()).hexdigest(), 16)
    return QUOTES[hash_value % len(QUOTES)]

