def _gl_mix(hex1, hex2, t):
    a = [int(hex1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(hex2[i:i + 2], 16) for i in (1, 3, 5)]
    return '#' + ''.join(f'{round(x + (y - x) * t):02x}' for x, y in zip(a, b))

def _gl_badge(key):
    A, B, BACK = _GL_PALETTES[key]
    A2, B2, BACK2 = _gl_mix(A, '#000000', .25), _gl_mix(B, '#000000', .25), _gl_mix(BACK, '#ffffff', .12)
    A_hi, B_hi = _gl_mix(A, '#ffffff', .35), _gl_mix(B, '#ffffff', .45)
    g = _GL_GLYPHS[key]
    P1, PARCH, P3 = _GL_PANELS[key]
    def shapes(fill, dx=0, dy=0, op=1):
        t = f' transform="translate({dx} {dy})"' if dx or dy else ''
        out = ''.join(f'<path d="{d}" fill="{fill}"/>' for d in g['ink'] + g.get('ink2', []))
        out += ''.join(f'<path d="{d}" fill="none" stroke="{fill}" stroke-width="9" stroke-linejoin="round"/>' for d in g.get('stroke', []))
        return f'<g opacity="{op}"{t}>{out}</g>'
    def ink_layer():
        out = ''.join(f'<path d="{d}" fill="url(#gInk)"/>' for d in g['ink'])
        out += ''.join(f'<path d="{d}" fill="none" stroke="url(#gInk)" stroke-width="9" stroke-linejoin="round"/>' for d in g.get('stroke', []))
        out += ''.join(f'<path d="{d}" fill="{PARCH}"/>' for d in g['cut'])
        out += ''.join(f'<path d="{d}" fill="none" stroke="{PARCH}" stroke-width="3" stroke-linecap="round"/>' for d in g.get('cutline', []))
        out += ''.join(f'<path d="{d}" fill="url(#gInk)"/>' for d in g.get('ink2', []))
        out += ''.join(f'<path d="{d}" fill="{PARCH}"/>' for d in g.get('cut2', []))
        out += ''.join(f'<path d="{d}" fill="none" stroke="#000" stroke-width="1.4" stroke-linecap="round"/>' for d in g.get('hair', []))
        out += '<path d="M60 104 L64 99 L68 104 L64 109 Z M132 104 L136 99 L140 104 L136 109 Z" fill="#000"/>'   # calligraphy diamonds
        return out
    POS = 'translate(101 101) scale(.8) translate(-100 -100)'
    defs = f'''
<linearGradient id="gA" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{A_hi}"/><stop offset=".6" stop-color="{A}"/><stop offset="1" stop-color="{A2}"/></linearGradient>
<linearGradient id="gB" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{B_hi}"/><stop offset=".5" stop-color="{B}"/><stop offset="1" stop-color="{B2}"/></linearGradient>
<linearGradient id="gBack" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{BACK2}"/><stop offset="1" stop-color="{BACK}"/></linearGradient>
<radialGradient id="gParch" cx=".45" cy=".38" r=".8"><stop offset="0" stop-color="{P1}"/><stop offset=".6" stop-color="{PARCH}"/><stop offset="1" stop-color="{P3}"/></radialGradient>
<linearGradient id="gInk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1a1410"/><stop offset="1" stop-color="#000"/></linearGradient>
<filter id="paper" x="0" y="0" width="100%" height="100%">
  <feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="2" seed="7" result="n"/>
  <feColorMatrix in="n" type="matrix" values="0 0 0 0 .35  0 0 0 0 .22  0 0 0 0 .1  0 0 0 .22 0" result="na"/>
  <feComposite in="na" in2="SourceAlpha" operator="in" result="n2"/>
  <feBlend in="SourceGraphic" in2="n2" mode="multiply"/></filter>
<filter id="shadow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="2.5" stdDeviation="2.5" flood-color="#000" flood-opacity=".45"/></filter>
<filter id="neon" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
<clipPath id="panel"><path d="M58 38 L144 34 L146 164 L56 168 Z"/></clipPath>
<clipPath id="slice1"><rect x="0" y="86" width="200" height="6"/></clipPath>
<clipPath id="slice2"><rect x="0" y="122" width="200" height="4"/></clipPath>
<mask id="noSlices"><rect width="200" height="200" fill="#fff"/><rect x="0" y="86" width="200" height="6" fill="#000"/><rect x="0" y="122" width="200" height="4" fill="#000"/></mask>
'''
    back = (
        '<path d="M46 32 L150 22 L162 34 L164 172 L150 182 L42 176 L36 164 L38 40 Z" fill="url(#gBack)"/>'
        '<path d="M30 58 L40 52 L42 128 L32 136 Z" fill="url(#gBack)"/><path d="M166 66 L176 60 L174 150 L164 156 Z" fill="url(#gBack)"/>'
        '<path d="M88 14 L132 12 L124 20 L84 22 Z" fill="url(#gBack)"/><path d="M70 184 L118 182 L112 190 L66 191 Z" fill="url(#gBack)"/>'
    )
    frameA = (
        '<path fill-rule="evenodd" fill="url(#gA)" d="M44 30 L154 24 L158 172 L42 178 Z M54 39 L146 34 L149 164 L52 168 Z"/>'
        '<path d="M26 74 L44 66 L44 120 L22 132 Z" fill="url(#gA)"/><path d="M60 18 L118 14 L110 22 L54 25 Z" fill="url(#gA)"/>'
        '<path d="M156 92 L178 80 L176 128 L158 140 Z" fill="url(#gA)" opacity=".95"/><path d="M98 180 L150 176 L144 186 L92 188 Z" fill="url(#gA)"/>'
    )
    frameB = (
        '<path fill-rule="evenodd" fill="url(#gB)" d="M50 34 L152 30 L155 168 L48 172 Z M55.5 38.5 L147.5 35 L150 164.5 L53.5 167.5 Z"/>'
        '<path d="M148 20 L176 26 L160 32 L140 28 Z" fill="url(#gB)"/><path d="M30 140 L46 132 L46 170 L34 176 Z" fill="url(#gB)"/>'
        '<path d="M40 182 L96 178 L88 186 L34 189 Z" fill="url(#gB)"/><path d="M160 44 L172 38 L170 84 L160 90 Z" fill="url(#gB)"/>'
        '<path d="M34 42 L48 38 L46 60 L36 64 Z" fill="url(#gB)"/>'
    )
    flecks = ''.join(f'<path d="{d}" fill="{c}"/>' for d, c in (
        ('M22 98 L28 95 L27 108 Z', A), ('M180 104 L186 100 L184 116 Z', B), ('M70 8 L86 7 L80 11 Z', A),
        ('M126 194 L146 192 L138 196 Z', B), ('M178 152 L184 146 L184 160 Z', A), ('M16 150 L22 146 L20 160 Z', B),
        ('M150 8 L160 10 L154 14 Z', BACK), ('M38 192 L50 191 L44 196 Z', BACK)))
    panel = (
        '<path d="M58 38 L144 34 L146 164 L56 168 Z" fill="url(#gParch)" filter="url(#paper)"/>'
        '<g clip-path="url(#panel)">'
        f'<g transform="{POS}">'
        + shapes(B, -2.6, .4, .9) + shapes(A, 2.6, -.4, .9)
        + f'<g mask="url(#noSlices)"><g filter="url(#shadow)">{ink_layer()}</g></g>'
        + f'<g clip-path="url(#slice1)"><g transform="translate(5 0)">{ink_layer()}</g><g transform="translate(9 0)">{shapes(B, 0, 0, .5)}</g></g>'
        + f'<g clip-path="url(#slice2)"><g transform="translate(-4 0)">{ink_layer()}</g></g>'
        + '</g>'
        + ''.join(f'<rect x="50" y="{y}" width="100" height=".5" fill="#000" opacity=".045"/>' for y in range(40, 166, 5))
        + '</g>'
        '<path d="M58 38 L144 34 L146 164 L56 168 Z" fill="none" stroke="#fff" stroke-opacity=".85" stroke-width="1.2"/>'
    )
    label = _GL_NAMES[key]
    w = 22 + 7.2 * len(label)
    x = 100 - w / 2
    tag = (f'<g filter="url(#shadow)"><path d="M{x - 4} 160 L{x + w + 2} 157 L{x + w + 6} 171 L{x} 174 Z" fill="{BACK}" stroke="{B}" stroke-width="1.4"/>'
           f'<path d="M{x - 4} 160 L{x + 10} 159.4 L{x + 6} 173.6 L{x} 174 Z" fill="{A}"/>'
           f'<text x="{100 + 4}" y="169.5" text-anchor="middle" font-family="\'Courier New\',Consolas,monospace" font-weight="700" font-size="11" fill="#fff" letter-spacing="1">{label}</text></g>')
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><defs>{defs}</defs>
<g filter="url(#shadow)">{back}</g><g filter="url(#neon)">{frameA}{frameB}</g>{flecks}{panel}{tag}</svg>'''

