def _genesis_glitch_svg(number=None):
    """ESCHOOL GENESIS: a calligraphic (blackletter) E on warm parchment, inside a glitch frame of
    hot pink, electric cyan and deep navy shards. Every learner's first Legendary badge."""
    PINK, PINK2, CYAN, CYAN2, NAVY, NAVY2 = '#ff1f6b', '#c2185b', '#22e4f5', '#0bb5c9', '#0d1b3d', '#1b2c5e'
    # --- the calligraphic E (drawn for Eschool), about 70 x 104 around the middle of the badge
    E = (
        # lead-in curl at the top left
        'M66 67 C63 69 59 70 57 68 C55 66 57 62 61 63 C65 63.5 69 63 73 60 L76 63 Z '
        # top arm: thick at the stem, sweeping right and flicking up
        'M71 64 C78 57 85 53 92 51 L130 59 C136 60.5 140 57.5 142 52.5 C143.5 49.5 148 50 147.5 54 '
        'C145.5 63 138 71.5 127 71 L99 67 L96 69 C92 66 86 64.5 80 65.5 Z '
        # stem: thick, slightly waisted, cut at an angle at the top and bottom
        'M80 65 L97 60 C95.5 82 95.5 108 97.5 133 L81 140 C83 114 83 90 80 65 Z '
        # middle tongue: a sharp lozenge with a small flick
        'M97 100 C103 93.5 109 90.5 115.5 92 L125.5 95.5 C129 96.5 131.5 94.5 133 91.5 C135 89.5 137.5 91.5 136.5 94 '
        'C133.5 101 127.5 106.5 119 105.5 L97 104.5 Z '
        # bottom arm: from the foot of the stem, sweeping right and up
        'M81 139 L97 132 L131 145 C136.5 147 140 144 142 139 C143 136 147.5 136 146.5 140 '
        'C143.5 150.5 134.5 158.5 123.5 156.5 L93 146 Z '
        # foot: a hairline hook down to the left
        'M84 141 C78.5 143.5 74.5 149 74.5 155 C74.5 158 70.5 158 70.5 154.5 C70.5 147.5 75.5 141.5 82 138.5 Z '
        # a small diamond beside the stem, a classic calligraphy flourish
        'M70 102 L74.5 97 L79 102 L74.5 107 Z'
    )
    EPOS = 'translate(101 101) scale(.8) translate(-102 -104)'   # where the E sits in the panel
    hair = 'M100.5 67 C101.5 90 101.5 112 102.5 133'       # the thin hairline beside the stem
    nicks = ''.join(f'<path d="M{x} {y} l5 1.6 -5 1.6 Z" fill="#c9a06f"/>' for x, y in ((81.5, 88), (82, 118)))   # little pen cuts

    defs = f'''
<linearGradient id="gPink" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff4d8d"/><stop offset=".6" stop-color="{PINK}"/><stop offset="1" stop-color="{PINK2}"/></linearGradient>
<linearGradient id="gCyan" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#7ff3ff"/><stop offset=".5" stop-color="{CYAN}"/><stop offset="1" stop-color="{CYAN2}"/></linearGradient>
<linearGradient id="gNavy" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{NAVY2}"/><stop offset="1" stop-color="{NAVY}"/></linearGradient>
<radialGradient id="gParch" cx=".45" cy=".38" r=".8"><stop offset="0" stop-color="#e2bd8c"/><stop offset=".6" stop-color="#c99b68"/><stop offset="1" stop-color="#9e7247"/></radialGradient>
<linearGradient id="gInk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1a1410"/><stop offset="1" stop-color="#000"/></linearGradient>
<filter id="paper" x="0" y="0" width="100%" height="100%">
  <feTurbulence type="fractalNoise" baseFrequency=".9" numOctaves="2" seed="7" result="n"/>
  <feColorMatrix in="n" type="matrix" values="0 0 0 0 .35  0 0 0 0 .22  0 0 0 0 .1  0 0 0 .22 0" result="na"/>
  <feComposite in="na" in2="SourceAlpha" operator="in" result="n2"/>
  <feBlend in="SourceGraphic" in2="n2" mode="multiply"/></filter>
<filter id="shadow" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="2.5" stdDeviation="2.5" flood-color="#000" flood-opacity=".45"/></filter>
<filter id="neon" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
<clipPath id="panel"><path d="M58 38 L144 34 L146 164 L56 168 Z"/></clipPath>
<clipPath id="slice1"><rect x="0" y="88" width="200" height="6"/></clipPath>
<clipPath id="slice2"><rect x="0" y="121" width="200" height="4"/></clipPath>
<mask id="noSlices"><rect width="200" height="200" fill="#fff"/><rect x="0" y="88" width="200" height="6" fill="#000"/><rect x="0" y="121" width="200" height="4" fill="#000"/></mask>
'''
    # --- the frame, back to front: navy shards, pink frame, cyan frame, small flying shards
    navy = (
        '<path d="M46 32 L150 22 L162 34 L164 172 L150 182 L42 176 L36 164 L38 40 Z" fill="url(#gNavy)"/>'
        '<path d="M30 58 L40 52 L42 128 L32 136 Z" fill="url(#gNavy)"/>'            # left shard
        '<path d="M166 66 L176 60 L174 150 L164 156 Z" fill="url(#gNavy)"/>'        # right shard
        '<path d="M88 14 L132 12 L124 20 L84 22 Z" fill="url(#gNavy)"/>'            # top shard
        '<path d="M70 184 L118 182 L112 190 L66 191 Z" fill="url(#gNavy)"/>'        # bottom shard
    )
    pink = (
        # the main pink frame (tilted a little), a thick ring
        '<path fill-rule="evenodd" fill="url(#gPink)" d="M44 30 L154 24 L158 172 L42 178 Z M54 39 L146 34 L149 164 L52 168 Z"/>'
        '<path d="M26 74 L44 66 L44 120 L22 132 Z" fill="url(#gPink)"/>'           # left blade
        '<path d="M60 18 L118 14 L110 22 L54 25 Z" fill="url(#gPink)"/>'           # top blade
        '<path d="M156 92 L178 80 L176 128 L158 140 Z" fill="url(#gPink)" opacity=".95"/>'   # right blade
        '<path d="M98 180 L150 176 L144 186 L92 188 Z" fill="url(#gPink)"/>'       # bottom blade
    )
    cyan = (
        # a thinner cyan frame, shifted (the "glitch" split)
        '<path fill-rule="evenodd" fill="url(#gCyan)" d="M50 34 L152 30 L155 168 L48 172 Z M55.5 38.5 L147.5 35 L150 164.5 L53.5 167.5 Z"/>'
        '<path d="M148 20 L176 26 L160 32 L140 28 Z" fill="url(#gCyan)"/>'         # top right blade
        '<path d="M30 140 L46 132 L46 170 L34 176 Z" fill="url(#gCyan)"/>'         # bottom left blade
        '<path d="M40 182 L96 178 L88 186 L34 189 Z" fill="url(#gCyan)"/>'         # bottom blade
        '<path d="M160 44 L172 38 L170 84 L160 90 Z" fill="url(#gCyan)"/>'         # right blade
        '<path d="M34 42 L48 38 L46 60 L36 64 Z" fill="url(#gCyan)"/>'             # left top blade
    )
    flecks = ''.join(f'<path d="{d}" fill="{c}"/>' for d, c in (
        ('M22 98 L28 95 L27 108 Z', PINK), ('M180 104 L186 100 L184 116 Z', CYAN), ('M70 8 L86 7 L80 11 Z', PINK),
        ('M126 194 L146 192 L138 196 Z', CYAN), ('M178 152 L184 146 L184 160 Z', PINK), ('M16 150 L22 146 L20 160 Z', CYAN),
        ('M150 8 L160 10 L154 14 Z', NAVY), ('M38 192 L50 191 L44 196 Z', NAVY)))
    # --- the parchment panel with the E (with a pink / cyan split, like the frame)
    panel = (
        '<path d="M58 38 L144 34 L146 164 L56 168 Z" fill="url(#gParch)" filter="url(#paper)"/>'
        '<g clip-path="url(#panel)">'
        f'<g transform="{EPOS}">'
        f'<path d="{E}" fill="{CYAN}" opacity=".9" transform="translate(-2.4 .4)"/>'
        f'<path d="{E}" fill="{PINK}" opacity=".9" transform="translate(2.4 -.4)"/>'
        f'<g mask="url(#noSlices)"><g filter="url(#shadow)"><path d="{E}" fill="url(#gInk)"/>'
        f'<path d="{hair}" stroke="#000" stroke-width="1.6" fill="none" stroke-linecap="round"/></g>' + nicks + '</g>'
        # two thin glitch slices of the letter, knocked sideways
        f'<g clip-path="url(#slice1)"><path d="{E}" fill="#000" transform="translate(5 0)"/><path d="{E}" fill="{CYAN}" opacity=".5" transform="translate(9 0)"/></g>'
        f'<g clip-path="url(#slice2)"><path d="{E}" fill="#000" transform="translate(-4 0)"/></g>'
        '</g>'
        # faint scan lines
        + ''.join(f'<rect x="50" y="{y}" width="100" height=".5" fill="#000" opacity=".045"/>' for y in range(40, 166, 5))
        + '</g>'
        '<path d="M58 38 L144 34 L146 164 L56 168 Z" fill="none" stroke="#fff" stroke-opacity=".85" stroke-width="1.2"/>'
    )
    tag = ''
    if number:
        label = f'Gen. {number:,}'
        w = 22 + 7.2 * len(label)
        x = 100 - w / 2
        tag = (f'<g filter="url(#shadow)"><path d="M{x - 4} 160 L{x + w + 2} 157 L{x + w + 6} 171 L{x} 174 Z" fill="{NAVY}" stroke="{CYAN}" stroke-width="1.4"/>'
               f'<path d="M{x - 4} 160 L{x + 10} 159.4 L{x + 6} 173.6 L{x} 174 Z" fill="{PINK}"/>'
               f'<text x="{100 + 4}" y="169.5" text-anchor="middle" font-family="\'Courier New\',Consolas,monospace" font-weight="700" font-size="11" fill="#fff" letter-spacing="1">{label}</text></g>')
    return f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200">
<defs>{defs}</defs>
<g filter="url(#shadow)">{navy}</g>
<g filter="url(#neon)">{pink}{cyan}</g>
{flecks}
{panel}
{tag}
</svg>"""


def _badge_svg(theme, number=None):
    """A Legendary badge drawn exactly like its card on the Achievements page (same shape, rim,
    face, dotted ring, shine, clock ticks and sparkles), with its symbol drawn in white.
    Genesis has no design of its own on that page, so it looks like its card there too."""
    import math
    if theme in ('genesis', 'starter'):
        return _genesis_glitch_svg(number)     # Genesis has its own design: a calligraphic E in a glitch frame
    if theme in GLITCH_THEMES:
        return _gl_badge(GLITCH_THEMES[theme])  # every other Legendary badge, in the same style as Genesis
    look = 'prism' if theme in ('genesis', 'starter') else theme
    (c1, c2, c3, c4), shape, glyph = DP_THEMES.get(look) or DP_THEMES['prism']
    if theme in ('genesis', 'starter'):
        glyph = 'book'
    d = _dp_shape(shape)
    inner = 'translate(100 100) scale(.8) translate(-100 -100)'
    pt = lambda r, deg: (100 + r * math.cos(math.radians(deg)), 100 + r * math.sin(math.radians(deg)))
    ticks = ''
    if shape == 'clock':
        for i in range(12):
            (x1, y1), (x2, y2) = pt(78, i * 30), pt(70 if i % 3 else 64, i * 30)
            ticks += (f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="{c4}" '
                      f'stroke-width="{2 if i % 3 else 4}" stroke-linecap="round" opacity=".85"/>')
    sparkles = ''.join(
        f'<path d="M{x} {y - 6} L{x + 1.6} {y - 1.6} L{x + 6} {y} L{x + 1.6} {y + 1.6} L{x} {y + 6} '
        f'L{x - 1.6} {y + 1.6} L{x - 6} {y} L{x - 1.6} {y - 1.6} Z" fill="{c4}" opacity="{.9 - i * .15:.2f}"/>'
        for i, (x, y) in enumerate(((30, 40), (168, 52), (160, 160), (42, 158))))
    return f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200">
<defs>
<linearGradient id="r" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{c4}"/><stop offset=".35" stop-color="{c3}"/><stop offset=".55" stop-color="{c2}"/><stop offset=".75" stop-color="{c3}"/><stop offset="1" stop-color="{c4}"/></linearGradient>
<radialGradient id="f" cx=".38" cy=".3" r=".85"><stop offset="0" stop-color="{c3}"/><stop offset=".45" stop-color="{c2}"/><stop offset="1" stop-color="{c1}"/></radialGradient>
<linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".45"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></linearGradient>
<clipPath id="c"><path d="{d}" transform="{inner}"/></clipPath>
<filter id="glow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000" flood-opacity=".45"/><feDropShadow dx="0" dy="0" stdDeviation="6" flood-color="{c3}" flood-opacity=".9"/></filter>
</defs>
<path d="{d}" fill="url(#r)"/>
<path d="{d}" fill="none" stroke="{c1}" stroke-opacity=".55" stroke-width="2"/>
<path d="{d}" transform="{inner}" fill="url(#f)" stroke="{c4}" stroke-opacity=".7" stroke-width="2"/>
<g clip-path="url(#c)">
<circle cx="100" cy="100" r="58" fill="none" stroke="{c4}" stroke-opacity=".28" stroke-width="1.5" stroke-dasharray="2 6"/>
<circle cx="100" cy="100" r="46" fill="{c1}" fill-opacity=".35"/>
<ellipse cx="100" cy="46" rx="90" ry="54" fill="url(#g)"/>
</g>
{ticks}{sparkles}
<g filter="url(#glow)"><g transform="translate(100 100) scale(.6) translate(-100 -100)">{DP_GLYPHS[glyph]}</g></g>
</svg>"""


# ----- Top-3 crowns: this month's 1st, 2nd and 3rd on the leaderboard wear a gold, silver or bronze crown
# on their badge picture (their Legendary badge), fixed onto the badge with two clasps.
_CW_CX, _CW_CY, _CW_RX, _CW_RY, _CW_BH = 100, 80, 60, 12, 15     # the crown band: centre, ellipse radii, band height

_CW_DEFS = '''
<linearGradient id="bandG" x1="0" y1="0" x2="1" y2="0">
  <stop offset="0" stop-color="#5a3605"/><stop offset=".12" stop-color="#a8701a"/><stop offset=".3" stop-color="#ffe9a3"/>
  <stop offset=".42" stop-color="#d9a23a"/><stop offset=".55" stop-color="#fff2c4"/><stop offset=".7" stop-color="#c08a2a"/>
  <stop offset=".88" stop-color="#8a5a12"/><stop offset="1" stop-color="#4a2c04"/></linearGradient>
<linearGradient id="bandShade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".35"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".35"/></linearGradient>
<linearGradient id="ptG" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff3c6"/><stop offset=".35" stop-color="#e9b84a"/><stop offset=".7" stop-color="#a86f17"/><stop offset="1" stop-color="#5e3a06"/></linearGradient>
<linearGradient id="ptBack" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#c99434"/><stop offset="1" stop-color="#4a2c04"/></linearGradient>
<radialGradient id="velv" cx=".45" cy=".35" r=".75"><stop offset="0" stop-color="#e3344f"/><stop offset=".45" stop-color="#9b0f26"/><stop offset="1" stop-color="#3d0410"/></radialGradient>
<radialGradient id="rubyG" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="#ffe4ea"/><stop offset=".3" stop-color="#f43f5e"/><stop offset=".75" stop-color="#9f1239"/><stop offset="1" stop-color="#4c0519"/></radialGradient>
<radialGradient id="sapG" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="#e0f2fe"/><stop offset=".35" stop-color="#3b82f6"/><stop offset="1" stop-color="#172554"/></radialGradient>
<radialGradient id="emG" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="#ecfdf5"/><stop offset=".35" stop-color="#10b981"/><stop offset="1" stop-color="#022c22"/></radialGradient>
<radialGradient id="diaG" cx=".4" cy=".3" r=".8"><stop offset="0" stop-color="#ffffff"/><stop offset=".5" stop-color="#e0f2fe"/><stop offset="1" stop-color="#7dd3fc"/></radialGradient>
<radialGradient id="glowG" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#ffd76a" stop-opacity=".55"/><stop offset="1" stop-color="#ffd76a" stop-opacity="0"/></radialGradient>
<filter id="dsh" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="3" stdDeviation="3" flood-color="#000" flood-opacity=".55"/></filter>
<filter id="soft"><feGaussianBlur stdDeviation="1.2"/></filter>
'''

_CW_DEFS += '<radialGradient id="velvB" cx=".45" cy=".35" r=".75"><stop offset="0" stop-color="#4f86f7"/><stop offset=".5" stop-color="#1d4ed8"/><stop offset="1" stop-color="#0b1f5c"/></radialGradient>'

def _cw_ell(theta, dy=0):
    a = math.radians(theta)
    return _CW_CX + _CW_RX * math.cos(a), _CW_CY + dy + _CW_RY * math.sin(a)

def _cw_gem(x, y, rx, ry, kind):
    g = {'ruby': 'rubyG', 'sap': 'sapG', 'em': 'emG', 'dia': 'diaG'}[kind]
    return (f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="{rx + 1.2:.1f}" ry="{ry + 1.2:.1f}" fill="#5e3a06"/>'
            f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="{rx:.1f}" ry="{ry:.1f}" fill="url(#{g})"/>'
            f'<ellipse cx="{x - rx * .35:.1f}" cy="{y - ry * .4:.1f}" rx="{rx * .3:.1f}" ry="{ry * .22:.1f}" fill="#fff" opacity=".85"/>')

def _cw_point(x, y, s, front=True, tilt=0, centre=False):
    """One ornate point of the crown: a tall leaf with a gem and a pearl on top."""
    fill = 'url(#ptG)' if front else 'url(#ptBack)'
    out = f'<g transform="translate({x:.1f} {y:.1f}) rotate({tilt:.1f}) scale({s:.2f})">'
    if centre:   # the tallest point: a cross on an orb
        out += ('<path d="M-12 0 C-13 -10 -6 -14 -8 -24 C-4 -22 -2 -26 0 -34 C2 -26 4 -22 8 -24 C6 -14 13 -10 12 0 Z" fill="' + fill + '" stroke="#4a2c04" stroke-width=".9"/>'
                '<path d="M-7 -2 C-8 -10 -3 -14 -4 -20 M7 -2 C8 -10 3 -14 4 -20" stroke="#fff3c6" stroke-opacity=".6" stroke-width=".8" fill="none"/>'
                + (_cw_gem(0, -13, 4.2, 5.2, 'ruby') if front else '') +
                '<circle cx="0" cy="-38" r="5" fill="url(#ptG)" stroke="#4a2c04" stroke-width=".8"/>'
                '<path d="M-1.6 -52 H1.6 V-47 H6 V-43.6 H1.6 V-42 H-1.6 V-43.6 H-6 V-47 H-1.6 Z" fill="url(#ptG)" stroke="#4a2c04" stroke-width=".7"/>'
                '<circle cx="-1.6" cy="-39.6" r="1.4" fill="#fff" opacity=".8"/>')
    else:
        out += ('<path d="M-9 0 C-10 -8 -4 -11 -6 -19 C-3 -17 -1 -21 0 -27 C1 -21 3 -17 6 -19 C4 -11 10 -8 9 0 Z" fill="' + fill + '" stroke="#4a2c04" stroke-width=".9"/>'
                '<path d="M-5 -2 C-6 -8 -2 -11 -3 -15" stroke="#fff3c6" stroke-opacity=".55" stroke-width=".8" fill="none"/>'
                + (_cw_gem(0, -10, 3, 3.8, 'sap' if int(x) % 2 else 'em') if front else '') +
                '<circle cx="0" cy="-30" r="3.2" fill="#f8f4ea" stroke="#8a7f68" stroke-width=".4"/><circle cx="-1" cy="-31" r="1" fill="#fff"/>')
    return out + '</g>'

def _cw_crown(pro):
    parts = []
    if pro:
        for th in (215, 270, 325):                      # a few points at the back
            x, y = _cw_ell(th)
            parts.append(_cw_point(x, y + 2, .7, front=False))
        parts.append(f'<path d="M{_CW_CX - _CW_RX} {_CW_CY} A{_CW_RX} {_CW_RY} 0 0 1 {_CW_CX + _CW_RX} {_CW_CY} L{_CW_CX + _CW_RX} {_CW_CY + 4} A{_CW_RX} {_CW_RY} 0 0 0 {_CW_CX - _CW_RX} {_CW_CY + 4} Z" fill="#6b4208"/>')
        parts.append(f'<path d="M{_CW_CX - _CW_RX + 5} {_CW_CY + 2} C{_CW_CX - _CW_RX + 4} {_CW_CY - 32} {_CW_CX + _CW_RX - 4} {_CW_CY - 32} {_CW_CX + _CW_RX - 5} {_CW_CY + 2} Z" fill="url(#velv)"/>')
        parts.append(f'<path d="M{_CW_CX - 40} {_CW_CY + 4} C{_CW_CX - 36} {_CW_CY - 20} {_CW_CX - 14} {_CW_CY - 27} {_CW_CX} {_CW_CY - 27} C{_CW_CX + 14} {_CW_CY - 27} {_CW_CX + 36} {_CW_CY - 20} {_CW_CX + 40} {_CW_CY + 4}" stroke="url(#ptG)" stroke-width="2.8" fill="none"/>')
    else:   # Basic: a lower blue velvet cap (Basic's colour) inside the crown
        parts.append(f'<path d="M{_CW_CX - _CW_RX} {_CW_CY} A{_CW_RX} {_CW_RY} 0 0 1 {_CW_CX + _CW_RX} {_CW_CY} L{_CW_CX + _CW_RX} {_CW_CY + 4} A{_CW_RX} {_CW_RY} 0 0 0 {_CW_CX - _CW_RX} {_CW_CY + 4} Z" fill="#7a4d0b"/>')
        parts.append(f'<path d="M{_CW_CX - _CW_RX + 5} {_CW_CY + 2} C{_CW_CX - _CW_RX + 6} {_CW_CY - 22} {_CW_CX + _CW_RX - 6} {_CW_CY - 22} {_CW_CX + _CW_RX - 5} {_CW_CY + 2} Z" fill="url(#velvB)"/>')
        parts.append(f'<path d="M{_CW_CX - 26} {_CW_CY} C{_CW_CX - 24} {_CW_CY - 12} {_CW_CX - 12} {_CW_CY - 17} {_CW_CX} {_CW_CY - 17}" stroke="#bfdbfe" stroke-opacity=".3" stroke-width="2" fill="none"/>')
    band = f'M{_CW_CX - _CW_RX} {_CW_CY} A{_CW_RX} {_CW_RY} 0 0 0 {_CW_CX + _CW_RX} {_CW_CY} L{_CW_CX + _CW_RX} {_CW_CY + _CW_BH} A{_CW_RX} {_CW_RY} 0 0 1 {_CW_CX - _CW_RX} {_CW_CY + _CW_BH} Z'
    parts.append(f'<g filter="url(#dsh)"><path d="{band}" fill="url(#bandG)"/><path d="{band}" fill="url(#bandShade)"/><path d="{band}" fill="none" stroke="#4a2c04" stroke-width="1"/></g>')
    parts.append(f'<path d="M{_CW_CX - _CW_RX} {_CW_CY} A{_CW_RX} {_CW_RY} 0 0 0 {_CW_CX + _CW_RX} {_CW_CY}" stroke="#fff3c6" stroke-width="1.5" fill="none"/>')
    parts.append(f'<path d="M{_CW_CX - _CW_RX} {_CW_CY + _CW_BH} A{_CW_RX} {_CW_RY} 0 0 0 {_CW_CX + _CW_RX} {_CW_CY + _CW_BH}" stroke="#ffe39a" stroke-width="2.2" fill="none"/>')
    # jewels on the band
    jewels = ((150, 'em', .6), (120, 'dia', .8), (90, 'ruby', 1.1), (60, 'dia', .8), (30, 'em', .6)) if pro else \
             ((150, 'sap', .6), (120, 'dia', .7), (90, 'sap', 1.0), (60, 'dia', .7), (30, 'sap', .6))
    for th, kind, size in jewels:
        x, y = _cw_ell(th, _CW_BH / 2)
        sq = .45 + .55 * math.sin(math.radians(th))
        parts.append(_cw_gem(x, y, 4 * size * sq, 4.3 * size, kind))
    if pro:
        for i in range(18):
            th = 10 + i * (160 / 17); sq = math.sin(math.radians(th))
            for dy in (3, _CW_BH - 3):
                x, y = _cw_ell(th, dy)
                parts.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{.5 + .6 * sq:.2f}" fill="#fff8e6" opacity="{.5 + .5 * sq:.2f}"/>')
    # points on the front
    pts = ((165, False), (125, False), (90, True), (55, False), (15, False)) if pro else ((160, False), (122, False), (90, False), (58, False), (20, False))
    for th, cen in pts:
        x, y = _cw_ell(th)
        s = (.85 + .4 * math.sin(math.radians(th))) if pro else (.7 + .3 * math.sin(math.radians(th)))
        tilt = -math.cos(math.radians(th)) * 8
        parts.append(f'<g filter="url(#dsh)">{_cw_point(x, y + 1, s, True, tilt, cen)}</g>')
    if not pro:   # Basic's gems on the points: blue
        parts = [p.replace('url(#emG)', 'url(#sapG)') for p in parts]
    return ''.join(parts)



# gold / silver / bronze versions of the crown: (band stops, point stops, velvet)
_CROWN_METALS = {
    1: (('#5a3605', '#a8701a', '#ffe9a3', '#d9a23a', '#fff2c4', '#c08a2a', '#8a5a12', '#4a2c04'), ('#fff3c6', '#e9b84a', '#a86f17', '#5e3a06'),
        ('#e3344f', '#9b0f26', '#3d0410')),
    2: (('#3b4350', '#7d8796', '#ffffff', '#c3ccd8', '#f8fafc', '#a6b0bd', '#6b7584', '#2f3640'), ('#ffffff', '#d5dce5', '#8c97a6', '#454e5b'),
        ('#4f86f7', '#1d4ed8', '#0b1f5c')),
    3: (('#4a2408', '#8f4d1d', '#ffd2a6', '#c97b3c', '#ffe1c4', '#b06a32', '#7a3f14', '#3d1d05'), ('#ffe1c4', '#d68d4b', '#9a5a24', '#4a2408'),
        ('#34d399', '#047857', '#022c22')),
}


def _crown_defs(rank):
    """The crown's colours for 1st (gold, red velvet), 2nd (silver, blue velvet) or 3rd (bronze, green velvet)."""
    band, pt, velv = _CROWN_METALS[rank]
    d = _CW_DEFS
    d = re.sub(r'<linearGradient id="bandG".*?</linearGradient>', lambda m: '<linearGradient id="bandG" x1="0" y1="0" x2="1" y2="0">' + ''.join(
        f'<stop offset="{o}" stop-color="{c}"/>' for o, c in zip(('0', '.12', '.3', '.42', '.55', '.7', '.88', '1'), band)) + '</linearGradient>', d, flags=re.S)
    d = re.sub(r'<linearGradient id="ptG".*?</linearGradient>', lambda m: '<linearGradient id="ptG" x1="0" y1="0" x2="1" y2="1">' + ''.join(
        f'<stop offset="{o}" stop-color="{c}"/>' for o, c in zip(('0', '.35', '.7', '1'), pt)) + '</linearGradient>', d, flags=re.S)
    d = re.sub(r'<radialGradient id="velv".*?</radialGradient>', lambda m: (
        f'<radialGradient id="velv" cx=".45" cy=".35" r=".75"><stop offset="0" stop-color="{velv[0]}"/>'
        f'<stop offset=".45" stop-color="{velv[1]}"/><stop offset="1" stop-color="{velv[2]}"/></radialGradient>'), d, flags=re.S)
    return d


# Basic and Pro owners: a soft swirl of light around their badge picture (Basic: blue, Pro: gold)
_PLAN_SWIRL = {   # (outer arcs, main ring, warm glow, inner band), size
    'basic': (('#60a5fa', '#3b82f6', '#93c5fd', '#2563eb'), .82),
    'pro':   (('#f59e0b', '#fbbf24', '#fcd34d', '#d97706'), .9),
}


def _swirl_svg(plan, cx=100, cy=114):
    (outer, mid, inner, accent), k = _PLAN_SWIRL[plan]
    def arc(r, start, sweep, color, width, blur, op):
        r *= k
        c = 2 * math.pi * r
        return (f'<circle cx="{cx}" cy="{cy}" r="{r:.1f}" fill="none" stroke="{color}" stroke-width="{width}" stroke-linecap="round" '
                f'stroke-dasharray="{c * sweep / 360:.1f} {c:.1f}" transform="rotate({start} {cx} {cy})" opacity="{op}" filter="url(#swb{blur})"/>')
    defs = ''.join(f'<filter id="swb{b}" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="{b}"/></filter>' for b in (4, 7, 10))
    body = (arc(118, 150, 150, outer, 16, 10, .55) + arc(112, -60, 110, outer, 14, 10, .45) + arc(96, 40, 250, mid, 22, 7, .75)
            + arc(88, 70, 170, accent, 10, 4, .7) + arc(74, 20, 160, inner, 26, 7, .85) + arc(70, 200, 90, inner, 12, 10, .45))
    return defs, f'<g transform="rotate(-10 {cx} {cy})">{body}</g>'


def _crowned_svg(badge_svg, rank, plan=None):
    """The badge picture with its extras (square, so it fits every picture frame):
    a top-3 crown fixed on top (1 = gold, 2 = silver, 3 = bronze) and/or a swirl of light for Basic (blue) / Pro (gold)."""
    has_crown = rank in (1, 2, 3)
    swirl_defs, swirl = _swirl_svg(plan) if plan in _PLAN_SWIRL else ('', '')
    if not has_crown and not swirl:
        return badge_svg
    view = '-35 -30 270 270' if swirl else '-15 -30 230 230'      # a little more room for the swirl
    if not has_crown:
        uri = 'data:image/svg+xml;base64,' + base64.b64encode(badge_svg.encode()).decode()
        return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}"><defs>{swirl_defs}</defs>{swirl}'
                f'<image href="{uri}" x="14" y="28" width="172" height="172"/></svg>')
    uri = 'data:image/svg+xml;base64,' + base64.b64encode(badge_svg.encode()).decode()
    sc = .8                                        # the band is as wide as the badge's top edge
    bottom = _CW_CY + _CW_BH + _CW_RY              # lowest point of the band
    x, y = 100 - 100 * sc + 1, 64 - bottom * sc    # the band wraps over the top of the badge's frame
    dark = _CROWN_METALS[rank][1][3]
    clasps = ''.join(
        f'<path d="M{cx - 5} 56 h10 l-1.5 13 q-3.5 3 -7 0 Z" fill="url(#ptG)" stroke="{dark}" stroke-width=".8"/>'
        f'<circle cx="{cx}" cy="61" r="1.8" fill="#fff" stroke="{dark}" stroke-width=".5"/>' for cx in (56, 146))
    shadow = '<ellipse cx="101" cy="66" rx="46" ry="6" fill="#000" opacity=".35" filter="url(#soft)"/>'
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}"><defs>{_crown_defs(rank)}{swirl_defs}</defs>{swirl}'
            f'<image href="{uri}" x="14" y="28" width="172" height="172"/>{shadow}{clasps}'
            f'<g transform="translate({x:.1f} {y:.1f}) scale({sc})">{_cw_crown(True)}</g></svg>')


def _learner_plan(user_id):
    """'basic' or 'pro' while that plan is active, else None (for the swirl). Cached for the request."""
    from flask import g, has_request_context
    if not has_request_context() or not user_id:
        return None
    cache = g.__dict__.setdefault('_dp_plans', {})
    if user_id not in cache:
        key = None
        try:
            c = sqlite3.connect('users.db')
            try:
                r = c.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (user_id,)).fetchone()
            finally:
                c.close()
            if r:
                k = _current_plan(r[0], r[1], r[2])['key']
                key = k if k in ('basic', 'pro') else None
        except sqlite3.Error:
            key = None              # e.g. the plan columns don't exist yet
        cache[user_id] = key
    return cache[user_id]


def _learner_crown(user_id):
    """1, 2 or 3 if this learner is in the top 3 of this month's leaderboard right now, else None.
    Learners hidden from the leaderboard never get a crown (so their place isn't shown). Cached for the request."""
    from flask import g, has_request_context
    if not has_request_context() or not user_id:
        return None
    top = getattr(g, '_top3_crowns', None)
    if top is None:
        top = {}
        try:
            conn = _links_db()
            try:
                hidden = set(_users_with_privacy(conn, 'show_on_leaderboard', 0))
                ranked = _lb_ranked(conn, 'month', hidden)
            finally:
                conn.close()
            for t in ranked:
                if t[5]['score'] > 0 and t[0] <= 3:
                    top[t[1]] = t[0]          # equal EP share a place, so there can be two 2nds
        except Exception:
            top = {}
        g._top3_crowns = top
    return top.get(user_id)


@app.route('/badge-art/<theme>.svg')
def badge_art_image(theme):
    """The drawing of one Legendary badge (same one used for profile pictures). ?n=<number> for Genesis."""
    if theme not in DP_THEMES:
        abort(404)
    n = request.args.get('n', type=int) if theme == 'genesis' else None
    resp = Response(_badge_svg(theme, n if n and n > 0 else None), mimetype='image/svg+xml')
    resp.headers['Cache-Control'] = 'no-cache'   # always check for a newer drawing
    return resp


@app.route('/badge-dp/<int:uid>.svg')
def badge_dp_image(uid):
    """A learner's profile picture: the badge they show (starter or Legendary), drawn as an image."""
    theme, number = 'genesis', None
    if 'user_id' in session:
        conn = _links_db()
        try:
            dp = _badge_dp(conn, uid)
            b = dp.get('badge') or {}
            if b.get('key', '').startswith('legend_'):
                theme = next((d[4] for d in LEGENDARY_DEFS if 'legend_' + d[0] == b['key']), 'genesis')
            if theme == 'genesis':
                number = _genesis_number(conn, uid)
        except Exception:
            theme = 'genesis'
        finally:
            conn.close()
    svg = _badge_svg(theme, number)
    if 'user_id' in session:
        svg = _crowned_svg(svg, _learner_crown(uid), _learner_plan(uid))   # top-3 crown + Basic / Pro swirl
    resp = Response(svg, mimetype='image/svg+xml')
    resp.headers['Cache-Control'] = 'no-cache'   # the picture changes when a new Legendary is earned or a plan starts/ends
    return resp


@app.route('/api/profile/dp-badge', methods=['POST'])
def api_profile_dp_badge():
    """Learners: {"key": "<achievement key>"} makes that earned badge your profile picture."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please log in again.'}), 401
    if session.get('role', 'student') != 'student':
        return jsonify({'success': False, 'message': 'Only learners use a badge as their picture.'}), 403
    return jsonify({'success': False, 'message': 'Your picture changes by itself: it is always your newest Legendary badge.'}), 403
    key = str((request.get_json(silent=True) or {}).get('key') or '')[:60]
    uid = session['user_id']
    conn = _links_db()
    try:
        dp = _badge_dp(conn, uid, with_choices=True)
        if not any(a['key'] == key for a in dp['choices']):
            return jsonify({'success': False, 'message': "You haven't earned that badge yet."}), 400
        conn.execute('''INSERT INTO profile_dp (user_id, badge_key, updated_at) VALUES (?, ?, ?)
                        ON CONFLICT(user_id) DO UPDATE SET badge_key = excluded.badge_key, updated_at = excluded.updated_at''',
                     (uid, key, _iso(_utc_now())))
        conn.commit()
        return jsonify({'success': True, 'dp': _badge_dp(conn, uid)})
    finally:
        conn.close()


# ============ STRATEGY LIKES (Learning Strategies Hub) ============
# strategies.html defines each learning strategy statically in its own
# JavaScript (title, steps, tips, etc. never touch the database) — only
# the *like relationship* needs a server-side home, so likes survive a
# cleared browser and are visible from any device the person logs into,
# instead of only living in that one browser's localStorage.

def get_liked_strategy_ids(cursor, user_id):
    """Set of strategy ids (as numbered in strategies.html) the given user has liked."""
    if not user_id:
        return set()
    cursor.execute('SELECT strategy_id FROM strategy_likes WHERE user_id = ?', (user_id,))
    return {row[0] for row in cursor.fetchall()}


def get_strategy_like_counts(cursor):
    """Map of strategy_id -> like count, for every strategy with at least one like."""
    cursor.execute('SELECT strategy_id, COUNT(*) FROM strategy_likes GROUP BY strategy_id')
    return {row[0]: row[1] for row in cursor.fetchall()}


# ============ OPINIONS (Learning Strategies Hub — Community Opinions) ============
# Unlike the static strategy list above, opinions are entirely
# user-generated (the text, the tag, and the like count), so — unlike
# strategy_likes, which only tracks a relationship against a static id —
# opinions need their own table for the content itself, plus the same
# opinion_likes relationship table for per-user like tracking.

def get_liked_opinion_ids(cursor, user_id):
    """Set of opinion ids the given user has liked."""
    if not user_id:
        return set()
    cursor.execute('SELECT opinion_id FROM opinion_likes WHERE user_id = ?', (user_id,))
    return {row[0] for row in cursor.fetchall()}


def serialize_opinion(row, liked_by_current_user=False):
    """
    row layout (opinions joined with users, plus a like-count subquery):
      0 id, 1 user_id, 2 text, 3 tag, 4 created_at, 5 firstname, 6 lastname, 7 likes, [8 anonymous]
    Learners are children, so only a first name and last initial are shown
    ("Amina W."), or "Anonymous learner" if they chose to post without a name.
    """
    firstname = (row[5] or '').strip()
    lastname = (row[6] or '').strip()
    anonymous = bool(row[8]) if len(row) > 8 else False
    if anonymous or not firstname:
        author = 'Anonymous learner'
    else:
        author = firstname + (f' {lastname[0].upper()}.' if lastname else '')

    return {
        'id': row[0],
        'user_id': row[1],
        'text': row[2],
        'tag': row[3],
        'date': to_iso_utc(row[4]),
        'author': author,
        'anonymous': anonymous,
        'likes': row[7] or 0,
        'liked_by_current_user': liked_by_current_user
    }


OPINION_TAGS = {'reading', 'memorization', 'mastery', 'general'}
OPINION_HIDE_AT = 3          # a tip reported by this many different people is hidden until an admin looks at it
# phone numbers and links are not allowed in tips (children's community)
_OPINION_PHONE = re.compile(r'(?:\+?\d[\s().-]?){9,}')
_OPINION_LINK = re.compile(r'(https?://|www\.|\b[\w-]+\.(com|net|org|co\.ke|ke|io|me|info|xyz|ly|gg)\b|@[\w.]{3,}|wa\.me|t\.me)', re.I)


def _opinion_tables(conn):
    cols = {r[1] for r in conn.execute('PRAGMA table_info(opinions)').fetchall()}
    if cols and 'anonymous' not in cols:
        conn.execute('ALTER TABLE opinions ADD COLUMN anonymous INTEGER DEFAULT 0')
    conn.execute('''CREATE TABLE IF NOT EXISTS opinion_reports (
        opinion_id INTEGER NOT NULL, user_id INTEGER NOT NULL, reason TEXT, created_at TEXT,
        PRIMARY KEY (opinion_id, user_id))''')
    conn.commit()


def _opinion_moderator():
    return session.get('role') in ('admin', 'teacher')

