@app.route('/api/tutoring/<int:tid>/teacher-end', methods=['POST'])
def tutoring_teacher_end(tid):
    """Teacher stops teaching a family: {"reason": "..."}. Booked lessons are cancelled;
    sessions paid for but not taught are left for Eschool support to refund."""
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    reason = str((request.get_json(silent=True) or {}).get('reason') or '').strip()[:300]
    if len(reason) < 5:
        return jsonify({'success': False, 'message': 'Tell the parent why, in a sentence.'}), 400
    conn = _links_db()
    try:
        _tutor_tables(conn)
        r = _own_tutoring(conn, tid, 'teacher')
        if not r or r['status'] not in ('accepted', 'active'):
            return jsonify({'success': False, 'message': 'These lessons are already closed.'}), 404
        now = _iso(_utc_now())
        conn.execute("UPDATE tutoring SET status = 'ended', ended_at = ?, teacher_note = ? WHERE id = ?", (now, reason, tid))
        conn.execute("UPDATE tutoring_sessions SET status = 'cancelled', updated_at = ? WHERE tutoring_id = ? AND status = 'scheduled'", (now, tid))
        info = _tutoring_json(conn, conn.execute(TUTORING_SELECT + ' WHERE t.id = ?', (tid,)).fetchone(), with_detail=False)
        left = info['sessions_left']
        create_notification(conn, r['parent_id'], 'Teacher ended lessons',
                            f"{_full_name(r['t_first'], r['t_last'], 'The teacher')} ended {r['subject']} lessons for "
                            f"{_full_name(r['s_first'], r['s_last'], 'your child')}. Reason: {reason}"
                            + (f" You have {left} paid session{'s' if left != 1 else ''} not taught; contact Help & Support for a refund." if left else ''),
                            icon='fa-circle-xmark', color='red', category='tutoring')
        conn.commit()
        return jsonify({'success': True, 'unused_sessions': left})
    finally:
        conn.close()


@app.route('/teacher-settings')
def jsettings():
    """Settings for teacher accounts: profile, teaching, notifications, security,
    privacy, appearance and policies. Uses the shared account APIs
    (/api/profile/details, /api/settings, /api/account/*, /api/notification-prefs,
    /api/privacy) plus /api/tutor-profile for private-teaching details."""
    if 'user_id' not in session:
        return redirect(url_for('login'))
    if session.get('role') != 'teacher':
        return redirect('/settings')
    uid = session['user_id']
    conn = _links_db()
    stats = {'followers': 0, 'resources': 0, 'reviews': 0, 'rating': None, 'requests': 0}
    try:
        def one(sql, args=(uid,)):
            try:
                r = conn.execute(sql, args).fetchone()
                return r[0] if r and r[0] is not None else 0
            except sqlite3.Error:
                return 0
        stats['followers'] = teacher_learner_count(conn, uid)
        stats['resources'] = one('SELECT COUNT(*) FROM resources WHERE user_id = ?')
        _tutor_tables(conn)
        stats['reviews'] = one('SELECT COUNT(*) FROM teacher_ratings WHERE teacher_id = ?')
        rt = _rating_summary(conn, [uid])[uid]
        stats['rating'], stats['ratings'] = rt['avg'], rt['count']
        stats['requests'] = one("SELECT COUNT(*) FROM tutoring WHERE teacher_id = ? AND status = 'pending'")
    finally:
        conn.close()
    return render_template('Teacher/teacher-settings.html', stats=stats)

