def render_profile(ctx):
    """Renders the profile page inside the VIEWER's own menu. Parents used to get
    the teacher profile with the teacher menu, so its buttons (Messages, Settings ...)
    took them to teacher pages. For parents the same profile content is shown
    inside the parent layout (Parent/parent-body.html) instead."""
    template = profile_template_for_role(session.get('role'))
    if session.get('role') == 'parent':
        # the normal profile of whoever it belongs to: a child's learner profile, a teacher's teacher profile
        template = 'Teacher/teacher-profile.html' if ctx.get('profile_role') == 'teacher' else 'Learner/profile.html'
        try:
            src = app.jinja_loader.get_source(app.jinja_env, template)[0]
            if _EXTENDS_RE.search(src):
                src = _EXTENDS_RE.sub('{% extends "Parent/parent-body.html" %}', src, count=1)
                if '{% block allcontent %}' not in src and '{% block content %}' in src:
                    src = src.replace('{% block content %}', '{% block allcontent %}', 1)
                # the colours and fonts the learner layout gives this page, so it looks the same here
                src = src.replace('{% block allcontent %}', '{% block allcontent %}' + PROFILE_BASE_STYLE + PROFILE_PARENT_EXTRA.get(template, ''), 1)
                src = '</div>{% endblock %}'.join(src.rsplit('{% endblock %}', 1))
                return render_template_string(src, **ctx)
        except Exception as e:   # fall back to the normal page rather than failing
            app.logger.warning('parent profile layout skipped: %s', e)
    return render_template(template, **ctx)


# Learner pages that have their own version for other roles. Opening one of
# these from a shared page (a profile, a notification link) sends parents and
# teachers to THEIR page, so the menu never switches to another role's layout.
ROLE_PAGE = {
    'parent': {'/messages': '/parent-message', '/settings': '/parent-settings', '/support': '/parent-support',
               '/help': '/parent-support', '/dashboard': '/parent-dashboard'},
    'teacher': {'/messages': '/teacher-messages', '/settings': '/teacher-settings', '/support': '/teacher-support',
                '/help': '/teacher-support', '/schedule': '/teacher-schedule', '/live': '/teacher-live',
                '/resourses': '/teacher-rankings', '/dashboard': '/teacher-dashboard',
                '/progres': '/teacher-progress'},
}


@app.before_request
def _send_to_own_role_page():
    if request.method != 'GET' or 'user_id' not in session:
        return None
    target = ROLE_PAGE.get(session.get('role') or '', {}).get(request.path.rstrip('/') or '/')
    if target:
        qs = request.query_string.decode()
        return redirect(target + ('?' + qs if qs else ''))
    return None


@app.route('/profile/<int:user_id>')
def view_profile(user_id):
    """Anyone else's profile page — this is what the Follow button and
    live followers/following counts are actually for."""
    if 'user_id' not in session:
        return redirect(url_for('login'))

    # Viewing your own id through this route just sends you to the
    # canonical /profile instead of duplicating the same page.
    if user_id == session['user_id']:
        return redirect(url_for('profile'))

    ctx = build_profile_context(user_id)
    if ctx is None:
        abort(404)
    if (ctx.get('profile_role') or '') == 'parent' and session.get('role') != 'admin':
        name = f"{ctx.get('firstname') or ''} {ctx.get('lastname') or ''}".strip() or 'This parent'
        return render_template_string(NO_PARENT_PROFILE_PAGE, name=name)

    conn = sqlite3.connect('users.db')
    try:
        allowed = can_view_profile(conn, session['user_id'], session.get('role'), user_id)
    finally:
        conn.close()
    first = (ctx.get('firstname') or 'This learner').strip()
    if not allowed and session.get('role', 'student') == 'student' and (ctx.get('profile_role') or 'student') == 'student':
        # learner to learner: say exactly why, and only offer Add friend when it makes sense
        conn = _links_db()
        try:
            vis = get_privacy(conn, user_id)['profile_visibility']
            _friends_tables(conn)
            rel = relationship(conn, session['user_id'], session.get('role', 'student'), user_id)
            name = f"{ctx.get('firstname') or ''} {ctx.get('lastname') or ''}".strip() or 'This learner'
            if rel.get('state') == 'friends':          # already friends, but they limited their profile
                return render_template_string(PRIVATE_PROFILE_PAGE, name=name, first=first, mode='friends_limited', vis=vis), 403
            if vis == 'private':                       # only them: adding a friend wouldn't change anything
                return render_template_string(PRIVATE_PROFILE_PAGE, name=name, first=first, mode='only_me', vis=vis), 403
            if user_id not in deactivated_user_ids(conn):
                st = _learner_stats(conn.execute('SELECT ' + SUMMARY_COLS + ' FROM student_progress_summary WHERE student_id = ?',
                                                 (user_id,)).fetchone() if conn.execute("SELECT 1 FROM sqlite_master WHERE name='student_progress_summary'").fetchone() else None,
                                    _ep_totals(conn, [user_id]).get(user_id))
                key = _career_keys(conn, [user_id]).get(user_id)
                career = _career_public(CAREER_PATHS[key]) if key else None
                return render_template_string(PREVIEW_PROFILE_PAGE, uid=user_id,
                                              name=_short_name(ctx.get('firstname'), ctx.get('lastname')),
                                              first=(ctx.get('firstname') or 'this learner'),
                                              badge=get_avatar_url(user_id, None), level=st.get('level', 1),
                                              career=career, state=rel.get('state'), vis=vis)
        finally:
            conn.close()
    if not allowed:   # the person chose who can see their profile (Settings > Privacy)
        name = f"{ctx.get('firstname') or ''} {ctx.get('lastname') or ''}".strip() or 'This person'
        return render_template_string(PRIVATE_PROFILE_PAGE, name=name, first=first, mode='chosen', vis=None), 403

    return render_profile(ctx)
# PARENT ROUTES //////////////////////


@app.route('/parent-dashboard')
def parent_dashboard():
    """
    Parent home page. Everything comes from the database:
      children      - active parent_links + the summary each child's dashboard sends
                      + EP the server recorded (modules, quizzes, courses, streaks)
      activities    - what the children did, newest first
      calendar      - those completions plus live classes
      upcoming_live - the next live classes
      alerts        - things worth a parent's attention, worked out from the above
    Grades, progress and activity only show for links where the child allowed "grades".
    """
    if 'user_id' not in session:
        return redirect(url_for('login'))
    if session.get('role') != 'parent':
        return redirect(url_for(home_endpoint_for_role(session.get('role'))))

    parent_id = session['user_id']
    now = datetime.now(timezone.utc)
    today = _nairobi_today()
    today_d = datetime.strptime(today, '%Y-%m-%d')
    last7 = [(today_d - timedelta(days=i)).strftime('%Y-%m-%d') for i in range(6, -1, -1)]
    week_start = _week_start()

    def when(raw):
        try:
            d = datetime.fromisoformat(str(raw).replace('Z', '+00:00'))
        except (TypeError, ValueError):
            return None
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)

    def ago(d):
        if not d:
            return ''
        secs = max(0, int((now - d).total_seconds()))
        if secs < 120:
            return 'just now'
        if secs < 3600:
            return f'{secs // 60} minutes ago'
        if secs < 86400:
            h = secs // 3600
            return f"{h} hour{'s' if h != 1 else ''} ago"
        days = secs // 86400
        return 'yesterday' if days == 1 else f'{days} days ago'

    def letter_for(gpa):
        if gpa is None:
            return '-'
        for cut, letter in ((3.85, 'A'), (3.5, 'A-'), (3.15, 'B+'), (2.85, 'B'), (2.5, 'B-'),
                            (2.15, 'C+'), (1.85, 'C'), (1.5, 'C-'), (1.15, 'D+'), (0.85, 'D')):
            if gpa >= cut:
                return letter
        return 'F'

    kind_group = {'module': 'module', 'course': 'course', 'quiz': 'quiz', 'daily_quiz': 'quiz',
                  'module_streak': 'streak', 'quiz_streak': 'streak'}

    conn = _links_db()
    try:
        _progress_summary_table(conn)
        _ep_table(conn)
        _refresh_children_progress(conn, parent_id)
        me = conn.execute('SELECT avatar_filename FROM users WHERE id = ?', (parent_id,)).fetchone()
        cols = ', '.join('ps.' + c.strip() for c in SUMMARY_COLS.split(','))
        rows = conn.execute(f'''
            SELECT pl.student_id, pl.permissions, pl.relationship, pl.linked_at,
                   u.firstname, u.lastname, u.avatar_filename, {cols}
            FROM parent_links pl
            JOIN users u ON u.id = pl.student_id
            LEFT JOIN student_progress_summary ps ON ps.student_id = pl.student_id
            WHERE pl.parent_id = ? AND pl.status = 'active'
            ORDER BY u.firstname, u.lastname
        ''', (parent_id,)).fetchall()
        pending_count = conn.execute("SELECT COUNT(*) FROM parent_links WHERE parent_id = ? AND status = 'pending'",
                                     (parent_id,)).fetchone()[0]

        ids = [r['student_id'] for r in rows]
        totals = _ep_totals(conn, ids) if ids else {}
        ranks, ranked_total = {}, 0
        if rows:
            try:
                hidden = _users_with_privacy(conn, 'show_on_leaderboard', 0)
                ranked = _ranked_learners(conn, exclude_ids=hidden)
                ranks = {t[1]: t[0] for t in ranked if t[5]['ep_month'] > 0}   # 0 EP this month: no place yet
                ranked_total = len(ranked)
            except Exception:
                ranks = {}

        children, activities, calendar_events, alerts = [], [], [], []
        for r in rows:
            sid = r['student_id']
            try:
                perms = _clean_permissions(json.loads(r['permissions'] or '{}'))
            except ValueError:
                perms = _clean_permissions({})
            st = _learner_stats(r, totals.get(sid))
            courses = [c for c in st['courses'] if isinstance(c, dict)]
            first = (r['firstname'] or '').strip()
            last = (r['lastname'] or '').strip()
            full = _full_name(first, last, 'Student')
            levels = sorted({str(c.get('level')).strip() for c in courses if c.get('level')})
            can_see = perms.get('grades', False)
            has_summary = r['updated_at'] is not None
            has_data = can_see and has_summary
            gpa = st['gpa'] if has_data else None
            avg = int(st['avg_progress'] or 0) if has_data else 0
            pg = _progress_page_grade(conn, sid) if has_data else None      # same grade as the child's Progress page
            average = pg['percent'] if pg else 0

            child_activity, active_days, last_seen = [], set(), None
            if can_see:
                for e in conn.execute('SELECT kind, ref, ep, day, created_at FROM ep_events '
                                      'WHERE user_id = ? ORDER BY id DESC LIMIT 80', (sid,)).fetchall():
                    text, sub = _ep_event_label(e)
                    d = when(e['created_at'])
                    if e['day']:
                        active_days.add(e['day'])
                        last_seen = max(last_seen, d) if (last_seen and d) else (last_seen or d)
                    if not e['day']:
                        shown_ago = 'before tracking began'
                    elif d and (d + timedelta(hours=3)).strftime('%Y-%m-%d') == e['day']:
                        shown_ago = ago(d)
                    else:   # recorded later than the day it was done (e.g. synced from the browser)
                        gap = (today_d - datetime.strptime(e['day'], '%Y-%m-%d')).days
                        shown_ago = 'today' if gap <= 0 else 'yesterday' if gap == 1 else f'{gap} days ago'
                    item = {'kind': kind_group.get(e['kind'], 'module'), 'text': text, 'sub': sub,
                            'ep': e['ep'], 'child_id': sid, 'child_name': full, 'child_first': first or full,
                            'time_ago': shown_ago,
                            'at': d.isoformat() if (d and e['day']) else '', 'day': e['day'] or ''}
                    child_activity.append(item)
                    if e['day']:
                        calendar_events.append({'date': e['day'], 'kind': 'done',
                                                'title': f"{text}: {sub}" if sub else text,
                                                'child': first or full, 'time': ''})
            activities.extend(child_activity[:25])
            if not last_seen and has_summary:
                last_seen = when(r['updated_at'])
            idle_days = (now - last_seen).days if last_seen else None
            done_this_week = sum(1 for a in child_activity if a['day'] and a['day'] >= week_start)

            child = {
                'id': sid,
                'full_name': full,
                'first_name': first or full,
                'initials': ((first[:1] + last[:1]) or full[:1]).upper(),
                'photo_url': get_avatar_url(sid, r['avatar_filename']) if r['avatar_filename'] else None,
                'grade': (', '.join(_pretty_level(l) for l in levels) or 'Learner') if can_see else 'Learner',   # levels come from their courses
                'relationship': (r['relationship'] or '').capitalize(),
                'linked_since': _nice_date(r['linked_at']) or '',
                'can_see_grades': can_see,
                'has_summary': has_summary,
                'has_data': has_data,
                'gpa': gpa or 0,
                'has_gpa': pg is not None,          # kept for older templates: "has a grade"
                'has_grade': pg is not None,
                'letter': pg['letter'] if pg else '-',
                'score_pct': pg['percent'] if pg else None,
                'total_score': pg['total'] if pg else None,
                'total_possible': pg['possible'] if pg else 0,
                'band': _grade_band(pg['percent']) if pg else '',
                'average': average,
                'avg_progress': avg,
                'rank': ranks.get(sid),   # public: same as the leaderboard page
                'courses': [{'name': c.get('name') or 'Course', 'progress': int(c.get('progress') or 0),
                             'level': _pretty_level(str(c.get('level') or '')) if c.get('level') else ''}
                            for c in courses] if can_see else [],
                'assessments': st['assessments'] if can_see else 0,
                'modules_completed': st['modules_completed'] if can_see else 0,
                'quizzes_passed': st['quizzes_passed'] if can_see else 0,
                'courses_completed': st['courses_completed'] if can_see else 0,
                'quiz_streak': st['quiz_streak'] if can_see else 0,
                'module_streak': st['module_streak'] if can_see else 0,
                'ep_week': st['ep_week'] if can_see else 0,
                'ep_month': st['ep_month'],
                'ep_total': st['ep'],
                'level': st['level'],
                'level_progress': st['level_progress'] if can_see else 0,
                'total_days': st['active_days'] if can_see else 0,
                'week': [{'day': d, 'label': datetime.strptime(d, '%Y-%m-%d').strftime('%a')[:2],
                          'active': d in active_days} for d in last7],
                'done_this_week': done_this_week,
                'last_active': ago(last_seen) if (last_seen and can_see) else '',
                'idle_days': idle_days if can_see else None,
                'activity': child_activity[:5],
                'updated_ago': ago(when(r['updated_at'])) if has_data else '',
                'prog': None,
            }
            if has_data:
                # details for the Progress card: per-course modules, scores, last activity, EP by day
                sp = _server_progress(conn, sid)
                by_day = {d['day']: d['ep'] for d in conn.execute(
                    'SELECT day, SUM(ep) AS ep FROM ep_events WHERE user_id = ? AND day >= ? GROUP BY day',
                    (sid, (today_d - timedelta(days=13)).strftime('%Y-%m-%d'))).fetchall()}
                prev7 = [(today_d - timedelta(days=i)).strftime('%Y-%m-%d') for i in range(13, 6, -1)]
                course_rows = []
                for c in child['courses']:
                    key = next((k for k, v in sp['courses'].items() if v['name'] == c['name']), None)
                    sc = sp['courses'].get(key) if key else None
                    last = sc['last_day'] if sc else None
                    gap = (today_d - datetime.strptime(last, '%Y-%m-%d')).days if last else None
                    course_rows.append({
                        'name': c['name'], 'progress': c['progress'],
                        'passed': min(sc['passed'], sc['total']) if sc else None, 'total': sc['total'] if sc else None,
                        'score': sc['score'] if sc else None,
                        'grade': _grade_for_pct(sc['score'])[0] if (sc and sc['score'] is not None) else None,
                        'last': ('today' if gap == 0 else 'yesterday' if gap == 1 else f'{gap} days ago') if gap is not None else '',
                        'idle': gap is not None and gap >= 7 and c['progress'] < 100,
                    })
                scored = [x for x in course_rows if x['score'] is not None]
                open_courses = [x for x in course_rows if x['progress'] < 100]
                child['prog'] = {
                    'avg_score': sp['avg_score'],
                    'subjects': len(sp['subjects']),
                    'courses': course_rows,
                    'days': [{'label': datetime.strptime(d, '%Y-%m-%d').strftime('%a')[:2], 'day': d,
                              'ep': by_day.get(d, 0), 'today': d == today} for d in last7],
                    'ep_7': sum(by_day.get(d, 0) for d in last7),
                    'ep_prev7': sum(by_day.get(d, 0) for d in prev7),
                    'strongest': max(scored, key=lambda x: x['score']) if len(scored) > 1 else None,
                    'weakest': min(scored, key=lambda x: x['score']) if len(scored) > 1 else None,
                    'behind': min(open_courses, key=lambda x: x['progress']) if open_courses else None,
                }
                child['prog']['max_day'] = max([d['ep'] for d in child['prog']['days']] + [1])
                if sp['avg_score'] is not None:   # real average test score, not GPA scaled
                    child['average'] = sp['avg_score']
            children.append(child)

            # what needs the parent's attention
            name = child['first_name']
            if not can_see:
                alerts.append({'level': 'info', 'child': full, 'icon': 'fa-lock',
                               'text': f"{name} hasn't shared grades with you. They can turn it on in their Settings."})
            elif not has_summary:
                alerts.append({'level': 'info', 'child': full, 'icon': 'fa-seedling',
                               'text': f"{name} hasn't started learning yet. Progress appears here the moment they pass a module test or quiz."})
            else:
                if idle_days is not None and idle_days >= 3:
                    alerts.append({'level': 'warn', 'child': full, 'icon': 'fa-moon',
                                   'text': f"{name} hasn't studied for {idle_days} days."})
                low = [c for c in child['courses'] if c['progress'] < 25]
                if courses and avg < 30:
                    alerts.append({'level': 'warn', 'child': full, 'icon': 'fa-chart-line',
                                   'text': f"{name}'s course progress is low ({avg}%)."})
                elif low:
                    alerts.append({'level': 'warn', 'child': full, 'icon': 'fa-book-open',
                                   'text': f"{name} has barely started {low[0]['name']} ({low[0]['progress']}%)."})
                if child['quiz_streak'] >= 3:
                    alerts.append({'level': 'ok', 'child': full, 'icon': 'fa-fire',
                                   'text': f"{name} is on a {child['quiz_streak']}-day quiz streak."})
                if done_this_week >= 5:
                    alerts.append({'level': 'ok', 'child': full, 'icon': 'fa-star',
                                   'text': f"{name} finished {done_this_week} things this week."})

        activities.sort(key=lambda a: (a['day'], a['at']), reverse=True)
        activities = activities[:40]
        activity_today = sum(1 for a in activities if a['day'] == today)

        live_rows = conn.execute(LIVE_CLASS_SELECT + ' WHERE lc.start_time >= ? ORDER BY lc.start_time LIMIT 300',
                                 (_iso(now - timedelta(days=45)),)).fetchall()
        upcoming_live = []
        for lr in live_rows:
            lc = serialize_live_class(lr)
            d = when(lc['start'])
            if not d:
                continue
            local = d + timedelta(hours=3)   # Nairobi
            calendar_events.append({'date': local.strftime('%Y-%m-%d'), 'kind': 'live', 'title': lc['title'],
                                    'child': '', 'time': local.strftime('%H:%M')})
            end = d + timedelta(minutes=lc['durationMin'] or 60)
            if end > now and len(upcoming_live) < 5:
                upcoming_live.append({'title': lc['title'], 'subject': lc['subject'], 'teacher': lc['teacher'],
                                      'start': _iso(d), 'duration': lc['durationMin'] or 60,
                                      'live_now': d <= now < end})
    finally:
        conn.close()

    tconn = _links_db()
    try:     # teachers hired: private teachers who accepted, for any of this parent's children
        _tutor_tables(tconn)
        teachers_hired = tconn.execute("SELECT COUNT(DISTINCT teacher_id) FROM tutoring WHERE parent_id = ? AND status IN ('accepted', 'active')",
                                       (parent_id,)).fetchone()[0]
    finally:
        tconn.close()
    with_data = [c for c in children if c['has_data']]
    graded = [c for c in with_data if c['has_grade']]
    avg_pct = round(sum(c['score_pct'] for c in graded) / len(graded)) if graded else None
    performance = {
        'has_data': bool(graded),
        'overall_average': avg_pct or 0,
        'overall_letter': _grade_for_pct(avg_pct)[0] if avg_pct is not None else '-',
        'overall_band': _grade_band(avg_pct),
        'avg_progress': round(sum(c['avg_progress'] for c in with_data) / len(with_data)) if with_data else 0,
        'gpa': round(sum(c['gpa'] for c in graded) / len(graded), 2) if graded else 0,
        'ep_week': sum(c['ep_week'] for c in children),
        'ep_month': sum(c['ep_month'] for c in children),
    }
    ranked = [c['rank'] for c in children if c['rank']]
    order = {'warn': 0, 'info': 1, 'ok': 2}
    alerts.sort(key=lambda a: order[a['level']])

    return render_template(
        'Parent/parent-dashboard.html',
        parent={'first_name': session.get('firstname', ''),
                'full_name': _full_name(session.get('firstname'), session.get('lastname'), ''),
                'avatar_url': get_avatar_url(parent_id, me['avatar_filename']) if me else None},
        children=children,
        stats={'children_count': len(children), 'teachers_count': teachers_hired, 'recent_activity_count': activity_today,
               'best_rank': min(ranked) if ranked else None, 'ranked_total': ranked_total,
               'pending_count': pending_count},
        activities=activities,
        performance=performance,
        calendar_events=calendar_events,
        upcoming_live=upcoming_live,
        alerts=alerts,
        leaderboard=sorted(children, key=lambda c: (not c['has_data'], -c['average'])),
        today_key=today,
    )


@app.route('/api/parent/link', methods=['POST'])
def parent_quick_link():
    """
    The "Link a child" card on the parent dashboard: the child's email + the
    link code shown on the child's dashboard. Same checks as the full linking
    page (code must be unused and not expired). Access can be changed later
    on My Children.
    """
    guard = _parent_guard()
    if guard:
        return guard
    blocked = _link_tries_blocked()
    if blocked:
        return blocked
    data = request.get_json(silent=True) or {}
    email = (data.get('email') or '').strip().lower()
    raw = re.sub(r'[^A-Z0-9]', '', str(data.get('code') or '').upper())
    code = f"{raw[:3]}-{raw[3:6]}-{raw[6:]}" if len(raw) == 9 else raw   # codes look like ABC-DEF-GHJ
    relationship = (data.get('relationship') or '').strip().lower()
    if not email or not code:
        return jsonify({'success': False, 'message': 'Enter the email and the link code.'}), 400
    if relationship not in VALID_RELATIONSHIPS:
        return jsonify({'success': False, 'message': 'Choose how you are related to the child.'}), 400

    parent_id = session['user_id']
    parent_name = _full_name(session.get('firstname'), session.get('lastname'), 'A parent')
    conn = _links_db()
    try:
        student = conn.execute('''
            SELECT id, firstname, lastname FROM users
            WHERE LOWER(email) = ? AND COALESCE(role, 'student') = 'student'
        ''', (email,)).fetchone()
        if not student or student['id'] == parent_id:
            return jsonify({'success': False, 'message': 'No learner account uses that email.'}), 404

        existing = conn.execute('SELECT id, status FROM parent_links WHERE parent_id = ? AND student_id = ?',
                                (parent_id, student['id'])).fetchone()
        if existing and existing['status'] == 'active':
            return jsonify({'success': False, 'message': 'This child is already linked to you.'}), 409

        now = _utc_now()
        code_row = conn.execute('''
            SELECT id, expires_at FROM link_codes
            WHERE student_id = ? AND code = ? AND used = 0
            ORDER BY id DESC LIMIT 1
        ''', (student['id'], code)).fetchone()
        if not code_row:
            return jsonify({'success': False, 'message': 'That code is not right. Ask your child for the code on their dashboard.'}), 404
        if code_row['expires_at'] < _iso(now):
            return jsonify({'success': False, 'message': 'That code has expired. Ask your child to make a new one.'}), 410
        conn.execute('UPDATE link_codes SET used = 1 WHERE id = ?', (code_row['id'],))

        perms = json.dumps({k: k != 'messages' for k in PARENT_PERM_KEYS})   # reading messages is turned on separately
        if existing:
            conn.execute('''UPDATE parent_links SET relationship = ?, method = 'code', status = 'active',
                            permissions = ?, requested_at = ?, linked_at = ?, expires_at = NULL,
                            last_resent_at = NULL WHERE id = ?''',
                         (relationship, perms, _iso(now), _iso(now), existing['id']))
        else:
            conn.execute('''INSERT INTO parent_links (parent_id, student_id, relationship, method, status,
                            permissions, requested_at, linked_at) VALUES (?, ?, ?, 'code', 'active', ?, ?, ?)''',
                         (parent_id, student['id'], relationship, perms, _iso(now), _iso(now)))

        student_name = _full_name(student['firstname'], student['lastname'], 'The student')
        create_notification(conn, user_id=student['id'], title='Parent account linked',
                            message=f"{parent_name} ({relationship}) is now linked to your account.",
                            icon='fa-user-shield', color='green')
        create_notification(conn, user_id=parent_id, title='Account linked',
                            message=f"{student_name} is now linked to your account.",
                            icon='fa-user-shield', color='green')
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()

@app.route('/Parent-messages')
def Psettings():
    return render_template('Parent/parent-messages.html')

@app.route('/parent-children')
def Pchildren():
    """
    My Children: one card per ACTIVE link of this parent, with real data:
      - name, photo, relationship, linked date            (users + parent_links)
      - GPA, overall grade, course progress, streaks       (student_progress_summary,
        sent by the student's own dashboard; only shown if the link allows "grades")
      - grade level                                        (from the levels of their enrolled courses)
      - teachers                                           (teachers the student follows)
    """
    if 'user_id' not in session:
        return redirect(url_for('login'))
    if session.get('role') != 'parent':
        return redirect(url_for(home_endpoint_for_role(session.get('role'))))

    parent_id = session['user_id']
    conn = _links_db()
    try:
        _progress_summary_table(conn)
        _ensure_plan_columns(conn)
        _access_tables(conn)
        _refresh_children_progress(conn, parent_id)
        rows = conn.execute('''
            SELECT pl.id AS link_id, pl.student_id, pl.relationship, pl.linked_at, pl.permissions, pl.perm_requests,
                   u.firstname, u.lastname, u.avatar_filename,
                   u.plan, u.plan_started_at, u.plan_expires_at,
                   ps.gpa, ps.overall_grade, ps.avg_progress, ps.courses, ps.modules_completed,
                   ps.assessments, ps.quiz_streak, ps.module_streak, ps.updated_at
            FROM parent_links pl
            JOIN users u ON u.id = pl.student_id
            LEFT JOIN student_progress_summary ps ON ps.student_id = pl.student_id
            WHERE pl.parent_id = ? AND pl.status = 'active'
            ORDER BY u.firstname, u.lastname
        ''', (parent_id,)).fetchall()

        pending_count = conn.execute(
            "SELECT COUNT(*) FROM parent_links WHERE parent_id = ? AND status = 'pending'", (parent_id,)
        ).fetchone()[0]

        children = []
        ids = [r['student_id'] for r in rows]
        totals = _ep_totals(conn, ids) if ids else {}
        ranks, ranked_total = {}, 0
        if ids:
            try:
                hidden = _users_with_privacy(conn, 'show_on_leaderboard', 0)
                ranked = _ranked_learners(conn, exclude_ids=hidden)
                ranks, ranked_total = {t[1]: t[0] for t in ranked if t[5]['ep_month'] > 0}, len(ranked)   # 0 EP: no place yet
            except Exception:
                ranks = {}
        for r in rows:
            extra = conn.execute('SELECT ' + SUMMARY_COLS + ' FROM student_progress_summary WHERE student_id = ?',
                                 (r['student_id'],)).fetchone()
            st = _learner_stats(extra, totals.get(r['student_id']))
            try:
                perms = _clean_permissions(json.loads(r['permissions'] or '{}'))
            except ValueError:
                perms = _clean_permissions({})
            try:
                courses = json.loads(r['courses'] or '[]')
                if not isinstance(courses, list):
                    courses = []
            except ValueError:
                courses = []

            teacher_rows = conn.execute('''
                SELECT u.firstname, u.lastname FROM follows f
                JOIN users u ON u.id = f.following_id
                WHERE f.follower_id = ? AND u.role = 'teacher'
                ORDER BY u.firstname, u.lastname
            ''', (r['student_id'],)).fetchall()
            teachers = [_full_name(t['firstname'], t['lastname'], 'Teacher') for t in teacher_rows]

            levels = sorted({str(c.get('level')).strip() for c in courses
                             if isinstance(c, dict) and c.get('level')})
            grade_level = ', '.join(_pretty_level(l) for l in levels) or None

            plan = _current_plan(r['plan'], r['plan_started_at'], r['plan_expires_at'])
            has_summary = r['updated_at'] is not None
            can_see_grades = perms.get('grades', False)
            children.append({
                'id': r['student_id'],
                'link_id': r['link_id'],
                'plan': plan,
                'permissions': perms,
                'pending_perms': _perm_requests(r['perm_requests']),
                'access_log': _access_history(conn, r['link_id'], 5),
                'name': _full_name(r['firstname'], r['lastname'], 'Student'),
                'avatar_url': get_avatar_url(r['student_id'], r['avatar_filename']),
                'relationship': (r['relationship'] or '').capitalize() or None,
                'linked_at': _nice_date(r['linked_at']),
                'can_see_grades': can_see_grades,
                'has_summary': has_summary,
                'gpa': r['gpa'] if (can_see_grades and has_summary) else None,
                'overall_grade': r['overall_grade'] if (can_see_grades and has_summary) else None,
                # the grade exactly as the child's Progress page shows it
                'score': (_progress_page_grade(conn, r['student_id']) if (can_see_grades and has_summary) else None),
                'avg_progress': r['avg_progress'] if (can_see_grades and has_summary) else None,
                'courses': courses if can_see_grades else [],
                # only what the child shares: nothing about their learning when "grades" is off
                'modules_completed': (r['modules_completed'] or 0) if can_see_grades else 0,
                'assessments': (r['assessments'] or 0) if can_see_grades else 0,
                'grade': grade_level if can_see_grades else None,
                'teachers': teachers if can_see_grades else [],
                'updated': _time_ago(r['updated_at']) if (has_summary and can_see_grades) else None,
                'first_name': (r['firstname'] or '').strip() or 'Your child',
                'rank': ranks.get(r['student_id']),
                'ranked_total': ranked_total,
                'ep_total': st['ep'], 'ep_week': st['ep_week'] if can_see_grades else 0, 'ep_month': st['ep_month'], 'level': st['level'],
                'quiz_streak': st['quiz_streak'] if can_see_grades else 0, 'module_streak': st['module_streak'] if can_see_grades else 0,
                'quizzes_passed': st['quizzes_passed'] if can_see_grades else 0,
                'courses_completed': st['courses_completed'] if can_see_grades else 0,
            })
    finally:
        conn.close()

    return render_template('Parent/parent-children.html', children=children, pending_count=pending_count,
                           payment_options=_payment_options())


# ============ SUBSCRIPTION PLANS ============
PLAN_NAMES = {'free': 'Free', 'basic': 'Basic', 'pro': 'Pro'}


def _ensure_plan_columns(conn):
    """Adds the plan columns if init_db hasn't run since this update."""
    for col in ("plan TEXT DEFAULT 'free'", "plan_started_at TEXT", "plan_expires_at TEXT"):
        try:
            conn.execute(f'ALTER TABLE users ADD COLUMN {col}')
        except sqlite3.OperationalError:
            pass


def _parse_iso(value):
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return None


def _current_plan(plan, started_at, expires_at):
    """
    The plan the user is on RIGHT NOW. A Basic/Pro plan whose end date has
    passed (or has no end date) counts as Free.
    Returns {key, name, expires_on, days_left, time_left, percent_left, ending_soon}.
    """
    key = (plan or 'free').strip().lower()
    expires = _parse_iso(expires_at)
    now = _utc_now()
    if key not in ('basic', 'pro') or not expires or expires <= now:
        return {'key': 'free', 'name': 'Free', 'expired_plan': PLAN_NAMES.get(key) if key in ('basic', 'pro') and expires else None,
                'expires_on': None, 'days_left': None, 'time_left': None, 'percent_left': None, 'ending_soon': False}

    seconds_left = (expires - now).total_seconds()
    # round UP, so a plan bought for 30 days shows "30 days left", not 29
    days_left = math.ceil(seconds_left / 86400) if seconds_left >= 86400 else 0
    hours_left = math.ceil(seconds_left / 3600)
    if days_left >= 1:
        time_left = f"{days_left} day{'s' if days_left != 1 else ''} left"
    elif hours_left >= 1:
        time_left = f"{hours_left} hour{'s' if hours_left != 1 else ''} left"
    else:
        time_left = 'Less than an hour left'

    started = _parse_iso(started_at)
    total = (expires - started).total_seconds() if started and started < expires else None
    percent_left = max(0, min(100, round(seconds_left / total * 100))) if total else None

    return {'key': key, 'name': PLAN_NAMES[key], 'expired_plan': None,
            'expires_on': expires.strftime('%b %d, %Y'),
            'days_left': days_left, 'time_left': time_left,
            'percent_left': percent_left, 'ending_soon': days_left < 7}


@app.route('/api/admin/users/<int:user_id>/plan', methods=['POST'])
def admin_set_user_plan(user_id):
    """
    Admin sets a learner's plan, e.g. after a payment is confirmed.
    JSON: {"plan": "basic"|"pro"|"free", "days": 30}
    Adding days to the SAME plan that is still running extends it from its
    current end date, so nobody loses paid time.
    """
    if 'user_id' not in session or session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403

    data = request.get_json(silent=True) or {}
    plan = (data.get('plan') or '').strip().lower()
    if plan not in PLAN_NAMES:
        return jsonify({'success': False, 'message': 'Plan must be free, basic or pro'}), 400

    conn = _links_db()
    try:
        _ensure_plan_columns(conn)
        row = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?',
                           (user_id,)).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'User not found'}), 404

        now = _utc_now()
        if plan == 'free':
            conn.execute("UPDATE users SET plan = 'free', plan_started_at = NULL, plan_expires_at = NULL WHERE id = ?",
                         (user_id,))
        else:
            try:
                days = int(data.get('days'))
            except (TypeError, ValueError):
                return jsonify({'success': False, 'message': 'Give the number of days, e.g. 30'}), 400
            if not 1 <= days <= 3660:
                return jsonify({'success': False, 'message': 'Days must be between 1 and 3660'}), 400

            _extend_plan(conn, user_id, plan, days)
        conn.commit()

        updated = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?',
                               (user_id,)).fetchone()
        return jsonify({'success': True,
                        'plan': _current_plan(updated['plan'], updated['plan_started_at'], updated['plan_expires_at'])})
    finally:
        conn.close()


# ============ PLAN PAYMENTS (parents pay for a child's Basic / Pro plan) ============
# How it works (no money is taken by this code):
#   1. On My Children the parent picks a child, a plan and how long, pays
#      with M-Pesa using the details below, and types the M-Pesa code.
#   2. That creates a PENDING payment and notifies every admin.
#   3. An admin checks the code in the M-Pesa statement and confirms or
#      rejects it (POST /api/admin/payments/<id>). Confirming starts or
#      extends the child's plan straight away; parent and child are told.
#
# >>> Put your own prices and M-Pesa details here (or set the environment
#     variables). Until a Paybill or Till number is set, the page shows
#     "Payments are not set up yet" and nobody can submit a payment.

# What each plan opens. Free learners get the free courses only; Basic adds live classes;
# Pro adds every course. Add a course id to PRO_ONLY_COURSES to make it Pro-only
# (e.g. a science course when it is added).
PLAN_FEATURES = {
    'free':  {'live': False, 'all_courses': False, 'ads': True},     # Free shows ads
    'basic': {'live': True,  'all_courses': False, 'ads': False},
    'pro':   {'live': True,  'all_courses': True,  'ads': False},
}
PRO_ONLY_COURSES = {'math'}


def _plan_key_of(conn, uid):
    """'free' | 'basic' | 'pro' for this account right now (an ended plan counts as free)."""
    try:
        _ensure_plan_columns(conn)
        r = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (uid,)).fetchone()
    except sqlite3.Error:
        return 'free'
    return _current_plan(r[0], r[1], r[2])['key'] if r else 'free'


def _course_open(plan_key, course_id):
    return PLAN_FEATURES.get(plan_key, PLAN_FEATURES['free'])['all_courses'] or course_id not in PRO_ONLY_COURSES


@app.route('/api/my-plan/access')
def api_my_plan_access():
    """What the signed-in learner's plan opens: live classes and which courses."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _links_db()
    try:
        key = _plan_key_of(conn, session['user_id']) if session.get('role', 'student') == 'student' else 'pro'
    finally:
        conn.close()
    return jsonify({'success': True, 'plan': key, 'plan_name': PLAN_NAMES.get(key, 'Free'),
                    'live': PLAN_FEATURES[key]['live'], 'ads': PLAN_FEATURES[key]['ads'],
                    'courses': {c: _course_open(key, c) for c in EP_COURSE_MODULES},
                    'pro_only_courses': sorted(PRO_ONLY_COURSES)})


# ============ MONEY: one currency for the whole site ============
# Every price, payment, lesson rate and payout is in SITE_CURRENCY (payments.env), e.g. KES, USD, EUR, GBP, NGN.
# Choose it before the first real payment and don't change it afterwards: amounts already saved don't convert.
SITE_CURRENCY = (os.environ.get('SITE_CURRENCY') or 'KES').strip().upper()[:3]
ZERO_DECIMAL_CURRENCIES = {'BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'}
# what a teacher may charge for one lesson, in SITE_CURRENCY
LESSON_PRICE_MIN = float(os.environ.get('LESSON_PRICE_MIN') or (50 if SITE_CURRENCY == 'KES' else 1))
LESSON_PRICE_MAX = float(os.environ.get('LESSON_PRICE_MAX') or (100000 if SITE_CURRENCY == 'KES' else 10000))


def _money(n, cur=None):
    """'KES 1,200' / 'USD 4.99': an amount in the site currency, written for people."""
    try:
        v = float(n or 0)
    except (TypeError, ValueError):
        v = 0.0
    return f"{cur or SITE_CURRENCY} {v:,.0f}" if v.is_integer() else f"{cur or SITE_CURRENCY} {v:,.2f}"


def _round_money(v):
    """Whole units for currencies without cents (KES, UGX ...), cents otherwise."""
    if SITE_CURRENCY in ZERO_DECIMAL_CURRENCIES or SITE_CURRENCY == 'KES':
        return int(round(v))
    x = round(float(v), 2)
    return int(x) if x.is_integer() else x


def _parse_amount(v, lo, hi):
    """A price someone typed: a number with at most 2 decimals between lo and hi, else None."""
    try:
        x = round(float(str(v).replace(',', '').strip()), 0 if SITE_CURRENCY in ZERO_DECIMAL_CURRENCIES else 2)
    except (TypeError, ValueError):
        return None
    if x != x or not lo <= x <= hi:
        return None
    return int(x) if float(x).is_integer() else x


@app.context_processor
def _currency_context():
    g = lambda v: int(v) if float(v).is_integer() else v
    return {'CURRENCY': SITE_CURRENCY, 'LESSON_MIN': g(LESSON_PRICE_MIN), 'LESSON_MAX': g(LESSON_PRICE_MAX),
            'LESSON_STEP': 50 if SITE_CURRENCY == 'KES' else (1 if SITE_CURRENCY in ZERO_DECIMAL_CURRENCIES else 0.01)}


PLAN_PRICES = {            # in SITE_CURRENCY, for each length (days). Change them with PLAN_PRICES_JSON in payments.env
    'basic': {30: 300, 90: 800, 365: 3000},
    'pro':   {30: 600, 90: 1600, 365: 6000},
}
try:    # e.g. PLAN_PRICES_JSON={"basic": {"30": 4.99, "90": 12.99, "365": 45}, "pro": {"30": 9.99, "90": 25, "365": 90}}
    _pp = json.loads(os.environ.get('PLAN_PRICES_JSON') or 'null')
    if isinstance(_pp, dict):
        for _k in ('basic', 'pro'):
            if isinstance(_pp.get(_k), dict):
                _new = {int(d): (int(a) if float(a).is_integer() else round(float(a), 2)) for d, a in _pp[_k].items() if float(a) > 0}
                if _new:
                    PLAN_PRICES[_k] = _new
except (ValueError, TypeError) as _e:
    print(f'PLAN_PRICES_JSON ignored: {_e}')
PLAN_INFO = {              # shown on the Plans page, edit freely. "missing" shows what the plan doesn't have.
    'free':  {'name': 'Free', 'tagline': 'Start learning at no cost',
              'features': ['Courses except Mathematics', 'Daily Quiz Test and course quizzes',
                           'My Goals and your progress', 'Private teachers (paid per lesson)'],
              'missing': ['Live classes', 'Mathematics'], 'ads': True},
    'basic': {'name': 'Basic', 'tagline': 'For steady everyday learning',
              'features': ['Everything in Free', 'Live classes with Eschool teachers', 'No ads'],
              'missing': ['Mathematics']},
    'pro':   {'name': 'Pro', 'tagline': 'Everything, for exam-focused learners',
              'features': ['Everything in Basic', 'Every course, including Mathematics',
                           'Priority help from teachers', 'No ads'],
              'missing': []},
}
PAYMENT_SETTINGS = {
    'paybill': os.environ.get('MPESA_PAYBILL', ''),          # e.g. '247247'
    'till': os.environ.get('MPESA_TILL', ''),                # use this OR paybill
    'account_name': os.environ.get('MPESA_ACCOUNT_NAME', 'Eschool'),
    'confirm_time': os.environ.get('PAYMENT_CONFIRM_TIME', 'within 24 hours'),
}
MPESA_CODE_RE = re.compile(r'^[A-Z0-9]{10}$')   # M-Pesa codes look like SJK3H7XQ2P


def _payments_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS plan_payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER NOT NULL,
            student_id INTEGER NOT NULL,
            plan TEXT NOT NULL,
            days INTEGER NOT NULL,
            amount INTEGER NOT NULL,
            method TEXT NOT NULL DEFAULT 'mpesa',
            reference TEXT NOT NULL,
            phone TEXT,
            status TEXT NOT NULL DEFAULT 'pending',   -- pending | confirmed | rejected | cancelled
            note TEXT,
            created_at TEXT NOT NULL,
            decided_at TEXT,
            decided_by INTEGER,
            FOREIGN KEY (parent_id) REFERENCES users (id),
            FOREIGN KEY (student_id) REFERENCES users (id)
        )
    ''')
    conn.execute('CREATE UNIQUE INDEX IF NOT EXISTS idx_plan_payments_ref ON plan_payments (reference)')


def _payments_ready():
    return bool(PAYMENT_SETTINGS['paybill'] or PAYMENT_SETTINGS['till'])


def _payment_options():
    """What the payment window needs: plans, prices and how to pay."""
    plans = []
    for key in ('basic', 'pro'):
        info = PLAN_INFO[key]
        plans.append({'key': key, 'name': info['name'], 'tagline': info['tagline'], 'features': info['features'],
                      'missing': info.get('missing', []),
                      'prices': [{'days': d, 'amount': a} for d, a in sorted(PLAN_PRICES[key].items())]})
    f = PLAN_INFO['free']
    return {'ready': _payments_ready(), 'currency': SITE_CURRENCY, 'plans': plans,
            'any_ready': _payments_ready() or _stripe_ready(),
            'free_plan': {'key': 'free', 'name': f['name'], 'tagline': f['tagline'], 'features': f['features'], 'missing': f['missing'], 'ads': True},
            'paybill': PAYMENT_SETTINGS['paybill'], 'till': PAYMENT_SETTINGS['till'],
            'account_name': PAYMENT_SETTINGS['account_name'], 'confirm_time': PAYMENT_SETTINGS['confirm_time'],
            'card': _stripe_ready(), 'mpesa_prompt': _stk_ready(), 'mpesa': _payments_ready() or _stk_ready()}


def _extend_plan(conn, user_id, plan, days):
    """Starts or extends a plan. The same plan still running is extended
    from its end date, so nobody loses paid time."""
    _ensure_plan_columns(conn)
    row = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (user_id,)).fetchone()
    if not row:
        return None
    now = _utc_now()
    current_end = _parse_iso(row['plan_expires_at'])
    same_plan_running = (row['plan'] or '').lower() == plan and current_end and current_end > now
    start = _parse_iso(row['plan_started_at']) if same_plan_running else now
    end = (current_end if same_plan_running else now) + timedelta(days=days)
    if (row['plan'] or '').lower() == 'basic' and plan == 'pro' and current_end and current_end > now:
        # upgrade: the Basic time left isn't lost, it becomes Pro time of the same value (Basic costs half, so half the days)
        rate = PLAN_PRICES['basic'][30] / PLAN_PRICES['pro'][30]
        end += (current_end - now) * rate
    conn.execute('UPDATE users SET plan = ?, plan_started_at = ?, plan_expires_at = ? WHERE id = ?',
                 (plan, _iso(start or now), _iso(end), user_id))
    return end


def _serialize_payment(r):
    method = (r['method'] if 'method' in r.keys() else None) or 'mpesa'
    return {
        'id': r['id'], 'student_id': r['student_id'], 'parent_id': r['parent_id'],
        'student_name': _full_name(r['firstname'], r['lastname'], 'Student'),
        'plan': r['plan'], 'plan_name': PLAN_NAMES.get(r['plan'], r['plan']),
        'days': r['days'], 'amount': r['amount'], 'reference': r['reference'], 'phone': r['phone'] or '',
        'method': method, 'method_label': 'Card' if method == 'stripe' else 'M-Pesa',
        # what to show as "paid with": the M-Pesa code, or "Card" (Stripe's own ids mean nothing to families)
        'paid_with': 'Card' if method == 'stripe' else r['reference'],
        'status': r['status'], 'note': r['note'] or '',
        'created_at': r['created_at'], 'decided_at': r['decided_at'],
    }


def _plan_pay_columns(conn):
    cols = {r[1] for r in conn.execute('PRAGMA table_info(plan_payments)').fetchall()}
    if 'receipt' not in cols:
        conn.execute('ALTER TABLE plan_payments ADD COLUMN receipt TEXT')


def _plan_pay_check(conn, payer_id, data):
    """Shared checks for paying a plan (M-Pesa code or card). Returns (student_id, plan, days, amount, learner row)
    or raises ValueError(message, http status)."""
    plan = (data.get('plan') or '').strip().lower()
    if session.get('role') == 'student':
        data['student_id'] = payer_id           # a learner without a parent pays for their own plan
    try:
        student_id = int(data.get('student_id'))
        days = int(data.get('days'))
    except (TypeError, ValueError):
        raise ValueError('Choose a child and how long.', 400)
    if plan not in PLAN_PRICES or days not in PLAN_PRICES[plan]:
        raise ValueError('Choose Basic or Pro and how long.', 400)
    _ensure_plan_columns(conn)
    if session.get('role') == 'student':
        link = conn.execute('SELECT firstname, lastname, plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (student_id,)).fetchone()
    else:
        link = conn.execute('''SELECT u.firstname, u.lastname, u.plan, u.plan_started_at, u.plan_expires_at
                               FROM parent_links pl JOIN users u ON u.id = pl.student_id
                               WHERE pl.parent_id = ? AND pl.student_id = ? AND pl.status = 'active' ''', (payer_id, student_id)).fetchone()
    if not link:
        raise ValueError('That child is not linked to you.', 404)
    current = _current_plan(link['plan'], link['plan_started_at'], link['plan_expires_at'])
    if current['key'] == 'pro' and plan == 'basic':      # Basic -> Pro is an upgrade; Pro -> Basic waits for Pro to end
        first = (link['firstname'] or 'Your child').strip()
        raise ValueError(f"{first} is on Pro until {current['expires_on']}. Renew Pro, or pay for Basic after Pro ends.", 409)
    return student_id, plan, days, PLAN_PRICES[plan][days], link


def _confirm_plan_payment(conn, p, by=None, note=None, receipt=None):
    """Start or extend the plan for one plan payment and tell the family. Safe to call twice (only the first counts).
    p: a PAYMENT_SELECT row. Returns the plan's new end, or None."""
    cur = conn.execute('''UPDATE plan_payments SET status = 'confirmed', note = COALESCE(?, note), receipt = COALESCE(?, receipt),
                          decided_at = ?, decided_by = ? WHERE id = ? AND status IN ('pending', 'started')''',
                       (note, receipt, _iso(_utc_now()), by, p['id']))
    if not cur.rowcount:
        return None
    end = _extend_plan(conn, p['student_id'], p['plan'], p['days'])
    if end is None:
        return None
    plan_name = PLAN_NAMES.get(p['plan'], p['plan'])
    child = _full_name(p['firstname'], p['lastname'], 'Your child')
    ends = end.strftime('%b %d, %Y')
    if p['parent_id'] == p['student_id']:       # a learner paid for their own plan
        create_notification(conn, p['student_id'], 'Payment confirmed',
                            f"Your payment is confirmed. You're on Eschool {plan_name} until {ends}.", icon='fa-crown', color='green')
    else:
        create_notification(conn, p['parent_id'], 'Payment confirmed',
                            f"{child} is now on Eschool {plan_name} until {ends}.", icon='fa-circle-check', color='green')
        create_notification(conn, p['student_id'], f'Eschool {plan_name} is on',
                            f"Your parent paid for Eschool {plan_name}. It runs until {ends}.", icon='fa-crown', color='green')
    return end


def _plan_stripe_sync(conn, p):
    """Ask Stripe how a plan card payment went and record it."""
    cs = _stripe('GET', '/checkout/sessions/' + p['reference'])
    if cs.get('payment_status') in ('paid', 'no_payment_required'):
        _confirm_plan_payment(conn, p, receipt=cs.get('payment_intent'))
    elif cs.get('status') == 'expired':
        conn.execute("UPDATE plan_payments SET status = 'failed', note = 'Card payment not finished', decided_at = ? WHERE id = ? AND status = 'started'",
                     (_iso(_utc_now()), p['id']))


PAYMENT_SELECT = '''
    SELECT p.*, u.firstname, u.lastname FROM plan_payments p
    LEFT JOIN users u ON u.id = p.student_id
'''


@app.route('/api/parent/payments', methods=['GET', 'POST'])
def parent_payments():
    guard = _payer_guard()
    if guard:
        return guard
    parent_id = session['user_id']
    conn = _links_db()
    try:
        _payments_table(conn)
        try:
            conn.execute('CREATE UNIQUE INDEX IF NOT EXISTS idx_plan_payments_reference ON plan_payments (reference)')
        except sqlite3.Error:
            pass        # older duplicate codes: the check below still blocks new ones
        if request.method == 'GET':
            rows = conn.execute(PAYMENT_SELECT + " WHERE p.parent_id = ? AND p.status NOT IN ('started', 'failed') ORDER BY p.id DESC LIMIT 50",
                                (parent_id,)).fetchall()
            return jsonify({'payments': [_serialize_payment(r) for r in rows], 'options': _payment_options()})

        if not _payments_ready():
            return jsonify({'success': False, 'message': 'Paying with an M-Pesa code is not set up. Pay by card instead, or contact Eschool support.'}), 503
        data = request.get_json(silent=True) or {}
        reference = re.sub(r'\s+', '', str(data.get('reference') or '')).upper()
        phone = re.sub(r'[^\d+]', '', str(data.get('phone') or ''))[:15] or None
        try:
            student_id, plan, days, amount, link = _plan_pay_check(conn, parent_id, data)
        except ValueError as e:
            return jsonify({'success': False, 'message': e.args[0]}), e.args[1]
        if not MPESA_CODE_RE.match(reference):
            return jsonify({'success': False, 'message': 'The M-Pesa code has 10 letters and numbers, like SJK3H7XQ2P.'}), 400
        if phone and not re.fullmatch(r'\+?\d{9,15}', phone):
            return jsonify({'success': False, 'message': 'Enter the phone number you paid from, e.g. 0712 345 678 or +254 712 345 678.'}), 400
        if conn.execute('SELECT 1 FROM plan_payments WHERE reference = ?', (reference,)).fetchone():
            return jsonify({'success': False, 'message': 'This M-Pesa code has already been used.'}), 409
        if conn.execute("SELECT COUNT(*) FROM plan_payments WHERE parent_id = ? AND status = 'pending'",
                        (parent_id,)).fetchone()[0] >= 3:
            return jsonify({'success': False, 'message': 'You have 3 payments waiting to be checked. Please wait for them first.'}), 429

        cur = conn.execute('''INSERT INTO plan_payments (parent_id, student_id, plan, days, amount, reference, phone, created_at)
                              VALUES (?, ?, ?, ?, ?, ?, ?, ?)''',
                           (parent_id, student_id, plan, days, amount, reference, phone, _iso(_utc_now())))
        parent_name = _full_name(session.get('firstname'), session.get('lastname'), 'A parent')
        child_name = _full_name(link['firstname'], link['lastname'], 'a learner')
        for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
            create_notification(conn, admin_id, 'Payment to check',
                                f"{parent_name} paid {_money(amount)} for {PLAN_NAMES[plan]} ({days} days) for {child_name}. "
                                f"M-Pesa code {reference}.", icon='fa-money-bill-wave', color='#f59e0b')
        conn.commit()
        row = conn.execute(PAYMENT_SELECT + ' WHERE p.id = ?', (cur.lastrowid,)).fetchone()
        return jsonify({'success': True, 'payment': _serialize_payment(row)})
    finally:
        conn.close()


@app.route('/api/parent/payments/online', methods=['POST'])
def parent_payments_online():
    """{"student_id", "plan", "days", "method": "card"} -> {"redirect": Stripe Checkout page}.
    The plan starts as soon as Stripe says it is paid (webhook, or the page asking /api/parent/payments/<id>/status)."""
    guard = _payer_guard()
    if guard:
        return guard
    if not _stripe_ready():
        return jsonify({'success': False, 'message': 'Card payments are not set up yet.'}), 503
    payer = session['user_id']
    data = request.get_json(silent=True) or {}
    conn = _links_db()
    try:
        _payments_table(conn)
        _plan_pay_columns(conn)
        try:
            student_id, plan, days, amount, link = _plan_pay_check(conn, payer, data)
        except ValueError as e:
            return jsonify({'success': False, 'message': e.args[0]}), e.args[1]
        recent = conn.execute("SELECT COUNT(*) FROM plan_payments WHERE parent_id = ? AND method = 'stripe' AND created_at > ?",
                              (payer, _iso(_utc_now() - timedelta(minutes=10)))).fetchone()[0]
        if recent >= 5:
            return jsonify({'success': False, 'message': 'You started several card payments just now. Please wait a few minutes.'}), 429
        temp = 'NEW-' + uuid.uuid4().hex
        cur = conn.execute('''INSERT INTO plan_payments (parent_id, student_id, plan, days, amount, method, reference, status, created_at)
                              VALUES (?, ?, ?, ?, ?, 'stripe', ?, 'started', ?)''', (payer, student_id, plan, days, amount, temp, _iso(_utc_now())))
        pid = cur.lastrowid
        conn.commit()
        child = _full_name(link['firstname'], link['lastname'], 'your child')
        back = '/plans' if session.get('role') == 'student' else '/parent-children'
        base = _site_url()
        length = '1 year' if days == 365 else f'{days} days'
        try:
            cs = _stripe('POST', '/checkout/sessions', {
                'mode': 'payment',
                'success_url': f'{base}{back}?paid={pid}',
                'cancel_url': f'{base}{back}?unpaid={pid}',
                'client_reference_id': str(pid),
                'customer_email': session.get('email') or None,
                'line_items[0][quantity]': 1,
                'line_items[0][price_data][currency]': ONLINE_PAY['stripe_currency'],
                'line_items[0][price_data][unit_amount]': _stripe_amount(amount),
                'line_items[0][price_data][product_data][name]': f'Eschool {PLAN_NAMES[plan]} · {length}',
                'line_items[0][price_data][product_data][description]': 'For ' + child,
                'metadata[kind]': 'plan', 'metadata[payment_id]': pid,
                'payment_intent_data[metadata][kind]': 'plan', 'payment_intent_data[metadata][payment_id]': pid,
                'expires_at': int(_ptime.time()) + 60 * 60,
            }, idem=f'eschool-plan-{pid}')
        except (ValueError, _rq.RequestException) as e:
            conn.execute("UPDATE plan_payments SET status = 'failed', note = ? WHERE id = ?", (str(e)[:200], pid))
            conn.commit()
            return jsonify({'success': False, 'message': str(e) if isinstance(e, ValueError) else 'The card payment service is not answering. Try again in a minute.'}), 502
        conn.execute('UPDATE plan_payments SET reference = ? WHERE id = ?', (cs['id'], pid))
        conn.commit()
        return jsonify({'success': True, 'payment_id': pid, 'redirect': cs['url']})
    finally:
        conn.close()


@app.route('/api/parent/payments/<int:payment_id>/status')
def parent_payment_status(payment_id):
    """The page asks this after coming back from Stripe, until the plan is confirmed."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _payments_table(conn)
        _plan_pay_columns(conn)
        p = conn.execute(PAYMENT_SELECT + ' WHERE p.id = ? AND p.parent_id = ?', (payment_id, session['user_id'])).fetchone()
        if not p:
            return jsonify({'success': False, 'message': 'Payment not found.'}), 404
        if p['status'] == 'started' and p['method'] == 'stripe' and not p['reference'].startswith('NEW-') and _stripe_ready():
            try:
                _plan_stripe_sync(conn, p)
                conn.commit()
            except (ValueError, _rq.RequestException):
                pass        # asked again on the next check
            p = conn.execute(PAYMENT_SELECT + ' WHERE p.id = ?', (payment_id,)).fetchone()
        out = _serialize_payment(p)
        _ensure_plan_columns(conn)
        u = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (p['student_id'],)).fetchone()
        current = _current_plan(u['plan'], u['plan_started_at'], u['plan_expires_at']) if u else None
        return jsonify({'success': True, 'payment': out, 'current': current})
    finally:
        conn.close()


@app.route('/api/parent/payments/<int:payment_id>', methods=['DELETE'])
def parent_cancel_payment(payment_id):
    """A parent can withdraw a payment that hasn't been checked yet (e.g. a typo in the code)."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _payments_table(conn)
        cur = conn.execute("""UPDATE plan_payments SET status = 'cancelled', decided_at = ?
                              WHERE id = ? AND parent_id = ? AND status = 'pending'""",
                           (_iso(_utc_now()), payment_id, session['user_id']))
        conn.commit()
        if not cur.rowcount:
            return jsonify({'success': False, 'message': 'Only payments that are still waiting can be withdrawn.'}), 404
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/admin/payments', methods=['GET'])
def admin_list_payments():
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    status = request.args.get('status', 'pending')
    conn = _links_db()
    try:
        _payments_table(conn)
        sql, args = PAYMENT_SELECT, ()
        if status in ('pending', 'confirmed', 'rejected', 'cancelled'):
            sql += ' WHERE p.status = ?'
            args = (status,)
        rows = conn.execute(sql + ' ORDER BY p.id DESC LIMIT 200', args).fetchall()
        out = []
        for r in rows:
            item = _serialize_payment(r)
            parent = conn.execute('SELECT firstname, lastname, email FROM users WHERE id = ?', (r['parent_id'],)).fetchone()
            item['parent_name'] = _full_name(parent['firstname'], parent['lastname'], 'Parent') if parent else 'Parent'
            item['parent_email'] = parent['email'] if parent else ''
            out.append(item)
        return jsonify({'payments': out})
    finally:
        conn.close()


@app.route('/api/admin/payments/<int:payment_id>', methods=['POST'])
def admin_decide_payment(payment_id):
    """JSON: {"action": "confirm" | "reject", "note": "optional reason"}"""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    data = request.get_json(silent=True) or {}
    action = data.get('action')
    note = str(data.get('note') or '').strip()[:300] or None
    if action not in ('confirm', 'reject'):
        return jsonify({'success': False, 'message': 'action must be confirm or reject'}), 400
    conn = _links_db()
    try:
        _payments_table(conn)
        p = conn.execute(PAYMENT_SELECT + " WHERE p.id = ? AND p.status = 'pending'", (payment_id,)).fetchone()
        if not p:
            return jsonify({'success': False, 'message': 'No waiting payment with that id'}), 404
        plan_name = PLAN_NAMES.get(p['plan'], p['plan'])
        child = _full_name(p['firstname'], p['lastname'], 'Your child')
        if action == 'confirm':
            if not conn.execute('SELECT 1 FROM users WHERE id = ?', (p['student_id'],)).fetchone():
                return jsonify({'success': False, 'message': 'The learner account no longer exists'}), 404
            _plan_pay_columns(conn)
            _confirm_plan_payment(conn, p, by=session['user_id'], note=note)
        else:
            create_notification(conn, p['parent_id'], 'Payment not confirmed',
                                f"We couldn't confirm M-Pesa code {p['reference']} for {child}." + (f" {note}" if note else ''),
                                icon='fa-triangle-exclamation', color='red')
        if action == 'reject':
            conn.execute("UPDATE plan_payments SET status = 'rejected', note = ?, decided_at = ?, decided_by = ? WHERE id = ?",
                         (note, _iso(_utc_now()), session['user_id'], payment_id))
        admin_log(conn, 'Confirmed plan payment' if action == 'confirm' else 'Rejected plan payment', 'payment', payment_id,
                  f"{p['reference']} · {_money(p['amount'])} · {plan_name} for {child}" + (f" · {note}" if note else ''))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


# ============ PRIVATE TEACHING (parents hire a teacher for their child) ============
# Flow:
#   1. A parent finds a teacher (ranked for each child), sends a request:
#      child, subject, lesson mode, sessions a week, preferred times, message.
#   2. The teacher accepts (setting the price per session if their tutor
#      profile has none) or declines.
#   3. The parent pays for a number of sessions with M-Pesa, checked by an
#      admin exactly like plan payments (PAYMENT_SETTINGS above). Eschool
#      holds the money and pays the teacher. Confirmed payment = sessions
#      the teacher can schedule.
#   4. The teacher schedules sessions and records how each went (attended,
#      notes, homework). The parent sees every session, rates them, can
#      report a problem, and sees the messages and calls between the
#      teacher and the child. The child is told their parent can see them.
#
# Teachers fill in their tutor profile with POST /api/tutor-profile
# (headline, bio, subjects, rate, mode ...). Until they do, they are still
# listed, with subjects taken from their live classes, and they set a price
# when they accept a request.

TUTOR_SUBJECTS = ['Mathematics', 'English', 'Kiswahili', 'CSL', 'Physics', 'Chemistry',
                  'Biology', 'Business', 'Computer Studies', 'Other']
COURSE_SUBJECT = {'math': 'Mathematics', 'english': 'English', 'kiswahili': 'Kiswahili', 'csl': 'CSL'}
TUTOR_MODES = {'online': 'Online', 'in-person': 'In person', 'both': 'Online & in person'}
# Private lessons only happen on Eschool (an Eschool call), so every lesson is online.
LESSON_MODE_LABEL = 'Online, in an Eschool call'


def _user_joined(conn, uid):
    """When this person joined Eschool (UTC datetime). Stored in users.joined_at; for accounts made
    before that column existed it is worked out once from their earliest activity and then saved."""
    try:
        conn.execute('ALTER TABLE users ADD COLUMN joined_at TEXT')
    except sqlite3.OperationalError:
        pass
    r = conn.execute('SELECT joined_at FROM users WHERE id = ?', (uid,)).fetchone()
    d = _parse_any(r[0]) if r and r[0] else None
    if d:
        return d
    found = []
    for q in ('SELECT MIN(created_at) FROM notifications WHERE user_id = ?',
              'SELECT MIN(timestamp) FROM messages WHERE sender_id = ? OR receiver_id = ?',
              'SELECT MIN(created_at) FROM tutoring WHERE teacher_id = ? OR parent_id = ? OR student_id = ?',
              'SELECT MIN(start_time) FROM live_classes WHERE teacher_id = ?',
              'SELECT MIN(upload_date) FROM resources WHERE user_id = ?',
              'SELECT MIN(updated_at) FROM tutor_profiles WHERE teacher_id = ?',
              'SELECT MIN(created_at) FROM ep_events WHERE user_id = ?'):
        try:
            v = conn.execute(q, (uid,) * q.count('?')).fetchone()[0]
        except sqlite3.Error:
            continue
        v = _parse_any(v) if v else None
        if v:
            found.append(v.astimezone(timezone.utc) if v.tzinfo else v.replace(tzinfo=timezone.utc))
    d = min(found) if found else _utc_now()
    d = min(d, _utc_now())
    try:
        conn.execute('UPDATE users SET joined_at = ? WHERE id = ?', (_iso(d), uid))
        conn.commit()
    except sqlite3.Error:
        pass
    return d


def _mark_joined(conn, uid):
    """Records the day a new account was made (used for 'time on Eschool')."""
    try:
        try:
            conn.execute('ALTER TABLE users ADD COLUMN joined_at TEXT')
        except sqlite3.OperationalError:
            pass
        conn.execute('UPDATE users SET joined_at = ? WHERE id = ? AND joined_at IS NULL', (_iso(_utc_now()), uid))
        conn.commit()
    except sqlite3.Error as e:
        print(f'joined_at not saved: {e}')


def _time_on_eschool(joined):
    """(whole years, plain label) since joining, e.g. (2, '2 years'), (0, '5 months'), (0, 'New this month')."""
    days = max(0, (_utc_now() - joined).days)
    years = days // 365
    if years:
        return years, f"{years} year{'s' if years != 1 else ''}"
    months = days // 30
    return 0, (f"{months} month{'s' if months != 1 else ''}" if months else 'New this month')
TUTOR_PACKS = [1, 4, 8, 12]          # sessions a parent can pay for at once


def _tutor_tables(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS teacher_ratings (
        id INTEGER PRIMARY KEY AUTOINCREMENT, teacher_id INTEGER NOT NULL, reviewer_id INTEGER NOT NULL,
        stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5), comment TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE (teacher_id, reviewer_id))''')
    conn.execute('''CREATE TABLE IF NOT EXISTS tutor_profiles (
        teacher_id INTEGER PRIMARY KEY,
        headline TEXT, bio TEXT, subjects TEXT, levels TEXT,
        rate INTEGER, session_minutes INTEGER DEFAULT 60,
        mode TEXT DEFAULT 'online', location TEXT, experience_years INTEGER,
        qualifications TEXT, availability TEXT, accepting INTEGER DEFAULT 1,
        updated_at TEXT)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS tutoring (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        parent_id INTEGER NOT NULL, teacher_id INTEGER NOT NULL, student_id INTEGER NOT NULL,
        subject TEXT NOT NULL, mode TEXT NOT NULL, sessions_per_week INTEGER DEFAULT 1,
        preferred_times TEXT, start_date TEXT, goals TEXT, message TEXT,
        rate INTEGER, session_minutes INTEGER DEFAULT 60,
        status TEXT NOT NULL DEFAULT 'pending',      -- pending | accepted | declined | cancelled | active | ended
        teacher_note TEXT, sessions_paid INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL, responded_at TEXT, ended_at TEXT)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS tutoring_payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tutoring_id INTEGER NOT NULL, parent_id INTEGER NOT NULL,
        sessions INTEGER NOT NULL, amount INTEGER NOT NULL,
        reference TEXT NOT NULL, phone TEXT,
        status TEXT NOT NULL DEFAULT 'pending',      -- pending | confirmed | rejected | cancelled
        note TEXT, created_at TEXT NOT NULL, decided_at TEXT, decided_by INTEGER)''')
    conn.execute('CREATE UNIQUE INDEX IF NOT EXISTS idx_tutoring_payments_ref ON tutoring_payments (reference)')
    conn.execute('''CREATE TABLE IF NOT EXISTS tutoring_sessions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tutoring_id INTEGER NOT NULL,
        starts_at TEXT NOT NULL, minutes INTEGER NOT NULL DEFAULT 60,
        topic TEXT, link TEXT,
        status TEXT NOT NULL DEFAULT 'scheduled',    -- scheduled | completed | missed | cancelled
        child_attended INTEGER, teacher_notes TEXT, homework TEXT,
        parent_rating INTEGER, parent_comment TEXT, parent_report TEXT,
        created_at TEXT NOT NULL, updated_at TEXT)''')
    _pay_columns(conn)   # method (mpesa_code | mpesa_stk | stripe) and receipt, added for online payments
    _lesson_columns(conn)   # proof of each lesson, reminders, admin decisions


def _jlist(v):
    try:
        x = json.loads(v or '[]')
        return [str(i).strip() for i in x if str(i).strip()] if isinstance(x, list) else []
    except (TypeError, ValueError):
        return []


def _clean_list(v, limit=12, size=60):
    if isinstance(v, str):
        v = v.split(',')
    if not isinstance(v, list):
        return []
    out = []
    for i in v:
        s = str(i).strip()[:size]
        if s and s not in out:
            out.append(s)
    return out[:limit]


def _child_subjects(conn, student_id):
    """[(subject, progress)] from the child's own progress summary."""
    _progress_summary_table(conn)
    row = conn.execute('SELECT courses FROM student_progress_summary WHERE student_id = ?', (student_id,)).fetchone()
    out = []
    for c in _jlist_dicts(row['courses'] if row else None):
        name = COURSE_SUBJECT.get(str(c.get('id') or '').lower())
        if not name:
            raw = str(c.get('name') or '')
            name = next((s for s in TUTOR_SUBJECTS if s.lower() in raw.lower()), None)
        if name:
            out.append((name, int(c.get('progress') or 0), str(c.get('level') or '')))
    return out


def _jlist_dicts(v):
    try:
        x = json.loads(v or '[]')
        return [i for i in x if isinstance(i, dict)] if isinstance(x, list) else []
    except (TypeError, ValueError):
        return []


def _teacher_cards(conn, teacher_ids=None):
    """Every teacher with what a parent needs to choose one."""
    _tutor_tables(conn)
    sql = '''SELECT u.id, u.firstname, u.lastname, u.avatar_filename, u.country,
                    tp.headline, tp.bio, tp.subjects, tp.levels, tp.rate, tp.session_minutes, tp.mode,
                    tp.location, tp.experience_years, tp.qualifications, tp.availability, tp.accepting, tp.updated_at
             FROM users u LEFT JOIN tutor_profiles tp ON tp.teacher_id = u.id
             WHERE u.role = 'teacher' AND TRIM(COALESCE(u.firstname, '') || COALESCE(u.lastname, '')) != '' '''
    args = []
    if teacher_ids is not None:
        ids = list(teacher_ids) or [-1]
        sql += f" AND u.id IN ({','.join('?' for _ in ids)})"
        args = ids
    rows = conn.execute(sql, args).fetchall()
    ids = [r['id'] for r in rows] or [-1]
    marks = ','.join('?' for _ in ids)

    def grouped(q):
        return {r[0]: r for r in conn.execute(q.format(marks=marks), ids).fetchall()}

    ratings = grouped('SELECT teacher_id, COUNT(*), AVG(stars) FROM teacher_ratings WHERE teacher_id IN ({marks}) GROUP BY teacher_id')
    try:
        class_ratings = grouped('SELECT teacher_id, COUNT(*), AVG(stars) FROM live_ratings WHERE teacher_id IN ({marks}) GROUP BY teacher_id')
    except sqlite3.Error:
        class_ratings = {}
    live = {}
    for r in conn.execute(f'SELECT teacher_id, subject, COUNT(*) FROM live_classes WHERE teacher_id IN ({marks}) GROUP BY teacher_id, subject', ids).fetchall():
        live.setdefault(r[0], []).append((r[1], r[2]))
    res = grouped("SELECT user_id, COUNT(*) FROM resources WHERE user_id IN ({marks}) AND COALESCE(privacy, 'public') = 'public' GROUP BY user_id")
    followers = grouped('SELECT following_id, COUNT(*) FROM follows WHERE following_id IN ({marks}) GROUP BY following_id')
    students = grouped("SELECT teacher_id, COUNT(DISTINCT student_id) FROM tutoring WHERE teacher_id IN ({marks}) AND status IN ('active', 'ended') GROUP BY teacher_id")
    done = grouped('''SELECT t.teacher_id, SUM(CASE WHEN s.status = 'completed' THEN 1 ELSE 0 END),
                             SUM(CASE WHEN s.status IN ('completed', 'missed') THEN 1 ELSE 0 END), AVG(s.parent_rating), COUNT(s.parent_rating)
                      FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                      WHERE t.teacher_id IN ({marks}) GROUP BY t.teacher_id''')

    overall = _rating_summary(conn, [r['id'] for r in rows])
    out = []
    for r in rows:
        tid = r['id']
        joined = _user_joined(conn, tid)
        years, exp_label = _time_on_eschool(joined)
        has_profile = r['updated_at'] is not None
        subjects = _jlist(r['subjects'])
        if not subjects:   # fall back to what they teach in live classes
            subjects = [COURSE_SUBJECT.get(s.lower(), s.title()) for s, _ in sorted(live.get(tid, []), key=lambda x: -x[1]) if s][:5]
        rc = ratings.get(tid)
        dn = done.get(tid)
        out.append({
            'id': tid,
            'name': _full_name(r['firstname'], r['lastname'], 'Teacher'),
            'initials': (((r['firstname'] or '')[:1] + (r['lastname'] or '')[:1]) or 'T').upper(),
            'avatar_url': get_avatar_url(tid, r['avatar_filename']),
            'has_profile': has_profile,
            'headline': r['headline'] or ('Teacher on Eschool' + (f" · {subjects[0]}" if subjects else '')),
            'bio': r['bio'] or '',
            'subjects': subjects,
            'levels': _jlist(r['levels']),
            'rate': r['rate'],
            'session_minutes': r['session_minutes'] or 60,
            'mode': 'online',                       # lessons only happen on Eschool
            'mode_label': LESSON_MODE_LABEL,
            'location': r['location'] or '',
            # experience = how long they have been teaching on Eschool, worked out, not typed in
            'experience_years': years,
            'experience_label': exp_label,
            'joined_at': _iso(joined),
            'qualifications': _jlist(r['qualifications']),
            'availability': r['availability'] or '',
            'accepting': bool(r['accepting']) if has_profile else True,
            # the one rating (all sources, 1-5 stars): see _rating_summary
            'rating_count': overall[tid]['count'],
            'rating': overall[tid],
            'review_count': rc[1] if rc else 0,
            # learners rate every live class they join (1-5, shown out of 10)
            'class_rating_count': class_ratings[tid][1] if tid in class_ratings else 0,
            'class_rating_avg': round(class_ratings[tid][2], 2) if tid in class_ratings and class_ratings[tid][2] else None,
            'rating_avg': overall[tid]['avg'],
            'review_avg': round(rc[2], 2) if rc and rc[2] else 0,
            'live_classes': sum(n for _, n in live.get(tid, [])),
            'resources': res[tid][1] if tid in res else 0,
            'followers': followers[tid][1] if tid in followers else 0,
            'students': students[tid][1] if tid in students else 0,
            'sessions_done': (dn[1] or 0) if dn else 0,
            'attendance_rate': round((dn[1] or 0) / dn[2] * 100) if dn and dn[2] else None,
            'lessons_booked': (dn[2] or 0) if dn else 0,
            'session_rating': round(dn[3], 1) if dn and dn[3] else None,
        })
        out[-1].update(_teacher_score(overall[tid], dn, years, joined))
    return out


# ============ TEACHER RANKINGS AND BADGES (Teacher/teacher-rankings.html) ============
# Every teacher is ranked by the Eschool score (see _teacher_score). Badges come in five tiers
# and get much harder as they go up: the numbers grow steeply, and the top tiers also need a
# high Eschool score, so they can't be reached by volume alone. A badge, once earned, is kept.
TEACHER_TIERS = [
    {'key': 'bronze',   'label': 'Bronze',   'color': '#b45309', 'points': 1, 'min_score': 0},
    {'key': 'silver',   'label': 'Silver',   'color': '#64748b', 'points': 2, 'min_score': 6.5},
    {'key': 'gold',     'label': 'Gold',     'color': '#d97706', 'points': 3, 'min_score': 7.5},
    {'key': 'platinum', 'label': 'Platinum', 'color': '#0891b2', 'points': 4, 'min_score': 8.3},
    {'key': 'diamond',  'label': 'Diamond',  'color': '#7c3aed', 'points': 5, 'min_score': 9.0},
]
# key, name, icon, what it measures, unit, thresholds per tier (bronze .. diamond), extra per tier
TEACHER_BADGES = [
    ('mentor',   'Mentor',             'fa-user-graduate',     'Different learners you have taught',           'learners',         [3, 10, 30, 75, 150],     None),
    ('lessons',  'Dedicated',          'fa-chalkboard-user',   'Private lessons taught (proved by the call)',  'lessons',          [10, 50, 150, 400, 1000], None),
    ('veteran',  'Veteran',            'fa-hourglass-half',    'Time teaching on Eschool',                     'days',             [182, 365, 730, 1460, 2190], None),
    ('trusted',  'Trusted by families','fa-heart',             'Reviews from parents, with a high average',    'parent reviews',   [3, 10, 25, 60, 120],     [4.0, 4.2, 4.4, 4.6, 4.8]),
    ('reliable', 'Reliable',           'fa-calendar-check',    'Booked lessons held, over many lessons',       '% held',           [85, 90, 94, 97, 99],     [10, 40, 100, 250, 500]),
    ('host',     'Live host',          'fa-tower-broadcast',   'Live classes taught, rated well by learners',  'live classes',     [3, 10, 30, 75, 150],     [None, 3.8, 4.2, 4.5, 4.7]),
    ('loyal',    'Families come back', 'fa-rotate',            'Families who paid for lessons again',          'families',         [1, 5, 15, 40, 80],       None),
]
TEACHER_LEVELS = [   # name, badge points needed, Eschool score needed
    ('Newcomer', 0, 0), ('Rising', 5, 0), ('Established', 12, 7.0), ('Distinguished', 20, 8.0),
    ('Master', 28, 8.6), ('Legend', 33, 9.2),
]


def _teacher_badges_table(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS teacher_badges (
        teacher_id INTEGER NOT NULL, badge TEXT NOT NULL, tier INTEGER NOT NULL, earned_at TEXT NOT NULL,
        PRIMARY KEY (teacher_id, badge, tier))""")


def _teacher_extra_metrics(conn, ids):
    """What the badges need that the teacher cards don't have: parent reviews, live classes held
    and how they were rated, and families who paid again."""
    marks = ','.join('?' for _ in ids) or 'NULL'
    out = {i: {'parent_reviews': 0, 'parent_avg': None, 'live_held': 0, 'live_rating': None, 'loyal': 0} for i in ids}
    try:
        for r in conn.execute(f"""SELECT tr.teacher_id, COUNT(*), AVG(tr.stars) FROM teacher_ratings tr JOIN users u ON u.id = tr.reviewer_id
                                  WHERE tr.teacher_id IN ({marks}) AND u.role = 'parent' GROUP BY tr.teacher_id""", ids).fetchall():
            out[r[0]].update(parent_reviews=r[1], parent_avg=r[2])
    except sqlite3.Error:
        pass
    try:
        for r in conn.execute(f"""SELECT teacher_id, COUNT(*) FROM live_classes WHERE teacher_id IN ({marks}) AND state = 'ended' GROUP BY teacher_id""", ids).fetchall():
            out[r[0]]['live_held'] = r[1]
        for r in conn.execute(f"""SELECT teacher_id, AVG(stars) FROM live_ratings WHERE teacher_id IN ({marks}) GROUP BY teacher_id""", ids).fetchall():
            out[r[0]]['live_rating'] = r[1]
    except sqlite3.Error:
        pass
    try:
        for r in conn.execute(f"""SELECT t.teacher_id, COUNT(*) FROM (
                                    SELECT t.teacher_id, t.parent_id FROM tutoring_payments p JOIN tutoring t ON t.id = p.tutoring_id
                                    WHERE t.teacher_id IN ({marks}) AND p.status = 'confirmed'
                                    GROUP BY t.teacher_id, t.parent_id HAVING COUNT(*) >= 2) t GROUP BY t.teacher_id""", ids).fetchall():
            out[r[0]]['loyal'] = r[1]
    except sqlite3.Error:
        pass
    return out


def _badge_value(key, card, ex):
    days = max(0, (_utc_now() - (_parse_any(card.get('joined_at')) or _utc_now())).days)
    return {'mentor': card.get('students', 0), 'lessons': card.get('sessions_done', 0), 'veteran': days,
            'trusted': ex['parent_reviews'], 'reliable': card.get('attendance_rate') or 0, 'host': ex['live_held'],
            'loyal': ex['loyal']}[key]


def _teacher_badges(card, ex, kept=None):
    """Each badge: the tier reached (0 = none, 1..5), progress to the next tier and what's still missing."""
    kept = kept or {}
    score = card.get('score') or 0
    out = []
    for key, name, icon, what, unit, need, extra in TEACHER_BADGES:
        value = _badge_value(key, card, ex)
        reached = 0
        for i, n in enumerate(need):
            tier = TEACHER_TIERS[i]
            ok = value >= n and score >= tier['min_score']
            if key == 'trusted':
                ok = ok and (ex['parent_avg'] or 0) >= extra[i]
            if key == 'reliable':
                ok = ok and card.get('lessons_booked', 0) >= extra[i]
            if key == 'host' and extra[i] is not None:
                ok = ok and (ex['live_rating'] or 0) >= extra[i]
            if not ok:
                break
            reached = i + 1
        reached = max(reached, kept.get(key, 0))          # a badge once earned is kept
        nxt = None
        if reached < 5:
            i, tier = reached, TEACHER_TIERS[reached]
            missing = []
            if value < need[i]:
                left = need[i] - value
                missing.append(f"{round(left / 30)} more months on Eschool" if key == 'veteran' and left >= 60 else
                               f"{left} more days on Eschool" if key == 'veteran' else
                               f"{need[i]}% of lessons held (now {value}%)" if key == 'reliable' else f"{left} more {unit}")
            if key == 'trusted' and (ex['parent_avg'] or 0) < extra[i]:
                missing.append(f"parent reviews averaging {extra[i]:g} stars" + (f" (now {ex['parent_avg']:.1f})" if ex['parent_avg'] else ''))
            if key == 'reliable' and card.get('lessons_booked', 0) < extra[i]:
                missing.append(f"{extra[i] - card.get('lessons_booked', 0)} more booked lessons")
            if key == 'host' and extra[i] is not None and (ex['live_rating'] or 0) < extra[i]:
                missing.append(f"live classes rated {extra[i]:g} stars on average" + (f" (now {ex['live_rating']:.1f})" if ex['live_rating'] else ''))
            if score < tier['min_score']:
                missing.append(f"an Eschool score of {tier['min_score']} (now {score})")
            nxt = {'tier': tier['key'], 'label': tier['label'], 'need': need[i], 'percent': max(0, min(100, round(value / need[i] * 100))) if need[i] else 100,
                   'missing': missing}
        out.append({'key': key, 'name': name, 'icon': icon, 'what': what, 'unit': unit, 'value': value,
                    'tier': reached, 'tier_key': TEACHER_TIERS[reached - 1]['key'] if reached else None,
                    'tier_label': TEACHER_TIERS[reached - 1]['label'] if reached else None,
                    'tier_color': TEACHER_TIERS[reached - 1]['color'] if reached else None,
                    'ladder': need, 'next': nxt})
    return out


def _teacher_level(badges, score):
    points = sum(TEACHER_TIERS[b['tier'] - 1]['points'] for b in badges if b['tier'])
    level = 0
    for i, (name, pts, sc) in enumerate(TEACHER_LEVELS):
        if points >= pts and (score or 0) >= sc:
            level = i
    nxt = TEACHER_LEVELS[level + 1] if level + 1 < len(TEACHER_LEVELS) else None
    return {'index': level, 'name': TEACHER_LEVELS[level][0], 'points': points,
            'next': {'name': nxt[0], 'points': nxt[1], 'score': nxt[2],
                     'percent': min(100, round(points / nxt[1] * 100)) if nxt[1] else 100} if nxt else None}


# ----- teacher Legend drawings (metal emblems) -----
import math as _tl_math
def _tl_pt(r, deg): return f"{100 + r*_tl_math.cos(_tl_math.radians(deg)):.1f} {100 + r*_tl_math.sin(_tl_math.radians(deg)):.1f}"
_TL_POLY = lambda n, r, rot: 'M' + ' L'.join(_tl_pt(r, rot + i*360/n) for i in range(n)) + ' Z'
_TL_STAR = lambda n, R, r: 'M' + ' L'.join(_tl_pt(r if i % 2 else R, -90 + i*180/n) for i in range(n*2)) + ' Z'
TL_SHAPE = {'shield': 'M100 6 L184 36 V98 C184 150 148 182 100 196 C52 182 16 150 16 98 V36 Z',
         'hex': _TL_POLY(6, 96, -90), 'star8': _TL_STAR(8, 98, 74), 'oct': _TL_POLY(8, 96, 22.5),
         'spark': _TL_STAR(4, 99, 52), 'star12': _TL_STAR(12, 98, 82), 'clock': 'M100 4 A96 96 0 1 1 99.9 4 Z',
         'circle': 'M100 4 A96 96 0 1 1 99.9 4 Z'}
def _tl_laurel():
    s = ''
    for side in (1, -1):
        for i in range(8):
            a = 90 + side*(30 + i*17)
            x, y = 100 + 44*_tl_math.cos(_tl_math.radians(a)), 100 + 44*_tl_math.sin(_tl_math.radians(a))
            s += f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="11" ry="4.6" transform="rotate({a + 90 + side*40:.1f} {x:.1f} {y:.1f})" fill="#fff"/>'
    return s + '<path d="M100 72 l8 17 19 2 -14 13 4 19 -17 -10 -17 10 4 -19 -14 -13 19 -2 Z" fill="#fde68a"/>'
TL_GLYPH = {
 'bookpen': '<path d="M42 78 C62 66 86 68 100 82 C114 68 138 66 158 78 V146 C138 134 114 136 100 150 C86 136 62 134 42 146 Z" fill="#fff"/><path d="M100 82 V150" stroke="#a16207" stroke-width="5"/><path d="M58 92 C70 88 82 89 90 94 M58 106 C70 102 82 103 90 108 M58 120 C70 116 82 117 90 122" stroke="#d4a937" stroke-width="3.5" fill="none" stroke-linecap="round"/><g transform="rotate(40 128 76)"><rect x="121" y="34" width="14" height="62" rx="3" fill="#fde68a"/><rect x="121" y="34" width="14" height="10" rx="3" fill="#a16207"/><path d="M121 96 L128 112 L135 96 Z" fill="#fff7d6"/><path d="M126 107 L128 112 L130 107 Z" fill="#0f172a"/></g>',
 'anchor': '<circle cx="100" cy="60" r="11" fill="none" stroke="#fff" stroke-width="7"/><path d="M100 71 V144" stroke="#fff" stroke-width="10" stroke-linecap="round"/><path d="M76 90 H124" stroke="#fff" stroke-width="9" stroke-linecap="round"/><path d="M60 116 C64 138 84 148 100 148 C116 148 136 138 140 116" stroke="#fff" stroke-width="9" fill="none" stroke-linecap="round"/><path d="M48 122 L60 102 L72 122 Z M152 122 L140 102 L128 122 Z" fill="#fff"/><circle cx="100" cy="60" r="4" fill="#fde68a"/>',
 'cap': '<path d="M100 56 L160 84 L100 112 L40 84 Z" fill="#fff"/><path d="M66 98 V124 C66 138 134 138 134 124 V98 L100 114 Z" fill="#fff"/><path d="M152 88 V122" stroke="#fde68a" stroke-width="5" stroke-linecap="round"/><circle cx="152" cy="128" r="7" fill="#fde68a"/>',
 'lantern': '<path d="M88 56 C88 38 112 38 112 56" stroke="#fff" stroke-width="7" fill="none"/><path d="M80 58 H120 L126 70 H74 Z" fill="#fff"/><path d="M78 74 H122 L128 132 H72 Z" fill="#fff"/><rect x="66" y="134" width="68" height="14" rx="5" fill="#fff"/><path d="M100 84 C111 98 116 105 116 114 C116 123 109 128 100 128 C91 128 84 123 84 114 C84 105 89 98 100 84 Z" fill="#fbbf24"/><path d="M100 102 C105 109 107 112 107 117 C107 121 104 124 100 124 C96 124 93 121 93 117 C93 112 95 109 100 102 Z" fill="#fff7d6"/>',
 'atom': '<g fill="none" stroke="#fff" stroke-width="7"><ellipse cx="100" cy="100" rx="52" ry="19"/><ellipse cx="100" cy="100" rx="52" ry="19" transform="rotate(60 100 100)"/><ellipse cx="100" cy="100" rx="52" ry="19" transform="rotate(-60 100 100)"/></g><circle cx="100" cy="100" r="12" fill="#67e8f9"/><circle cx="152" cy="100" r="6" fill="#fff"/>',
 'apple': '<path d="M100 76 C88 64 58 64 56 98 C54 128 76 150 92 148 C96 147 98 145 100 145 C102 145 104 147 108 148 C124 150 146 128 144 98 C142 64 112 64 100 76 Z" fill="#fff"/><path d="M100 76 C100 62 104 54 112 48" stroke="#fff" stroke-width="6" fill="none" stroke-linecap="round"/><path d="M107 62 C118 46 138 48 142 55 C131 66 116 68 107 62 Z" fill="#facc15"/><path d="M72 92 C74 82 80 78 86 78" stroke="#facc15" stroke-width="6" fill="none" stroke-linecap="round"/>',
 'tree': '<path d="M100 44 C126 44 142 62 140 84 C156 90 158 116 140 124 C132 136 112 136 104 130 H96 C88 136 68 136 60 124 C42 116 44 90 60 84 C58 62 74 44 100 44 Z" fill="#fff"/><path d="M100 112 V152" stroke="#fff" stroke-width="11" stroke-linecap="round"/><path d="M100 132 L84 120 M100 124 L116 112" stroke="#fff" stroke-width="7" stroke-linecap="round"/><circle cx="84" cy="84" r="5" fill="#4ade80"/><circle cx="112" cy="76" r="5" fill="#4ade80"/><circle cx="120" cy="104" r="5" fill="#4ade80"/>',
 'laurel': _tl_laurel(),
}
def _tl_svg(key, c, shape, glyph, earned=True, size=None, ribbon=None):
    c1, c2, c3, c4 = c if earned else ['#1e2530', '#3b4352', '#6b7280', '#cbd5e1']
    d = TL_SHAPE[shape]; inner = 'translate(100 100) scale(.8) translate(-100 -100)'
    ticks = ''
    if shape == 'clock':
        for i in range(12):
            a = i*30
            ticks += f'<line x1="{_tl_pt(78,a).split()[0]}" y1="{_tl_pt(78,a).split()[1]}" x2="{_tl_pt(70 if i%3 else 64,a).split()[0]}" y2="{_tl_pt(70 if i%3 else 64,a).split()[1]}" stroke="{c4}" stroke-width="{2 if i%3 else 4}" stroke-linecap="round" opacity=".85"/>'
    sp = ''.join(f'<path d="M{x} {y-6} L{x+1.6} {y-1.6} L{x+6} {y} L{x+1.6} {y+1.6} L{x} {y+6} L{x-1.6} {y+1.6} L{x-6} {y} L{x-1.6} {y-1.6} Z" fill="{c4}" opacity="{.9-i*.15:.2f}"/>' for i,(x,y) in enumerate(((30,40),(168,52),(160,160),(42,158)))) if earned else ''
    k = key
    g = TL_GLYPH[glyph] if earned else f'<g opacity=".55">{TL_GLYPH[glyph]}</g>'
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><defs>
<linearGradient id="r{k}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{c4}"/><stop offset=".35" stop-color="{c3}"/><stop offset=".55" stop-color="{c2}"/><stop offset=".75" stop-color="{c3}"/><stop offset="1" stop-color="{c4}"/></linearGradient>
<radialGradient id="f{k}" cx=".38" cy=".3" r=".85"><stop offset="0" stop-color="{c3}"/><stop offset=".45" stop-color="{c2}"/><stop offset="1" stop-color="{c1}"/></radialGradient>
<linearGradient id="g{k}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".45"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></linearGradient>
<clipPath id="c{k}"><path d="{d}" transform="{inner}"/></clipPath>
<filter id="w{k}" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000" flood-opacity=".45"/><feDropShadow dx="0" dy="0" stdDeviation="{6 if earned else 0}" flood-color="{c3}" flood-opacity=".9"/></filter></defs>
<path d="{d}" fill="url(#r{k})"/><path d="{d}" fill="none" stroke="{c1}" stroke-opacity=".55" stroke-width="2"/>
<path d="{d}" transform="{inner}" fill="url(#f{k})" stroke="{c4}" stroke-opacity=".7" stroke-width="2"/>
<g clip-path="url(#c{k})"><circle cx="100" cy="100" r="58" fill="none" stroke="{c4}" stroke-opacity=".28" stroke-width="1.5" stroke-dasharray="2 6"/><circle cx="100" cy="100" r="46" fill="{c1}" fill-opacity=".35"/><ellipse cx="100" cy="46" rx="90" ry="54" fill="url(#g{k})"/></g>
{ticks}{sp}<g filter="url(#w{k})"><g transform="translate(100 100) scale(.6) translate(-100 -100)">{g}</g></g>{_tl_ribbon(ribbon, c) if ribbon else ''}</svg>'''


def _tl_ribbon(text, c):
    w = 30 + 8.2 * len(text)
    x = 100 - w / 2
    return (f'<path d="M{x - 12:.1f} 152 H{x + w + 12:.1f} L{x + w + 4:.1f} 165 L{x + w + 12:.1f} 178 H{x - 12:.1f} L{x - 4:.1f} 165 Z" fill="{c[1]}" stroke="{c[3]}" stroke-width="2.5"/>'
            f'<text x="100" y="170.5" text-anchor="middle" font-family="Poppins,Segoe UI,Arial,sans-serif" font-weight="800" font-size="14" fill="#fff" letter-spacing="1">{text}</text>')



