@app.route('/api/tutoring/teachers/<int:teacher_id>')
def tutoring_teacher(teacher_id):
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        cards = _teacher_cards(conn, [teacher_id])
        if not cards:
            return jsonify({'success': False, 'message': 'Teacher not found'}), 404
        t = cards[0]
        t['upcoming_live'] = [{'title': r['title'], 'subject': r['subject'], 'start': r['start_time']} for r in conn.execute(
            'SELECT title, subject, start_time FROM live_classes WHERE teacher_id = ? AND start_time >= ? ORDER BY start_time LIMIT 3',
            (teacher_id, _iso(_utc_now()))).fetchall()]
        t['recent_resources'] = [{'id': r['id'], 'title': r['title'], 'type': r['file_category'] or 'file'} for r in conn.execute(
            "SELECT id, title, file_category FROM resources WHERE user_id = ? AND COALESCE(privacy, 'public') = 'public' ORDER BY id DESC LIMIT 4",
            (teacher_id,)).fetchall()]
        t['hired'] = bool(conn.execute("SELECT 1 FROM tutoring WHERE teacher_id = ? AND parent_id = ? AND status IN ('active', 'ended')",
                                       (teacher_id, session['user_id'])).fetchone())
        # How quickly they answer parents, and how many families keep paying for more lessons
        waits = []
        for r in conn.execute('SELECT created_at, responded_at FROM tutoring WHERE teacher_id = ? AND responded_at IS NOT NULL', (teacher_id,)).fetchall():
            a, b = _parse_any(r['created_at']), _parse_any(r['responded_at'])
            if a and b and b >= a:
                waits.append((b - a).total_seconds() / 3600)
        waits.sort()
        t['response_hours'] = round(waits[len(waits) // 2], 1) if waits else None
        t['answered'] = len(waits)
        t['families'] = conn.execute("SELECT COUNT(DISTINCT parent_id) FROM tutoring WHERE teacher_id = ? AND status IN ('active', 'ended')", (teacher_id,)).fetchone()[0]
        paid = conn.execute('''SELECT COUNT(*), SUM(CASE WHEN n > 1 THEN 1 ELSE 0 END) FROM
                               (SELECT p.tutoring_id, COUNT(*) AS n FROM tutoring_payments p JOIN tutoring t ON t.id = p.tutoring_id
                                WHERE t.teacher_id = ? AND p.status = 'confirmed' GROUP BY p.tutoring_id)''', (teacher_id,)).fetchone()
        t['rebook_rate'] = round((paid[1] or 0) / paid[0] * 100) if paid and paid[0] else None
        t['subject_lessons'] = [{'subject': r[0], 'lessons': r[1]} for r in conn.execute(
            '''SELECT t.subject, COUNT(*) FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
               WHERE t.teacher_id = ? AND s.status = 'completed' GROUP BY t.subject ORDER BY 2 DESC LIMIT 6''', (teacher_id,)).fetchall()]
        return jsonify({'teacher': t})
    finally:
        conn.close()


def _tutoring_json(conn, r, with_detail=True):
    sessions = [dict(s) for s in conn.execute('SELECT * FROM tutoring_sessions WHERE tutoring_id = ? ORDER BY starts_at DESC', (r['id'],)).fetchall()]
    used = sum(1 for s in sessions if s['status'] in ('completed', 'missed', 'review'))
    booked = sum(1 for s in sessions if s['status'] == 'scheduled')
    out = {
        'id': r['id'], 'status': r['status'], 'subject': r['subject'], 'mode': r['mode'],
        'mode_label': TUTOR_MODES.get(r['mode'], r['mode']),
        'sessions_per_week': r['sessions_per_week'], 'preferred_times': r['preferred_times'] or '',
        'start_date': r['start_date'] or '', 'goals': r['goals'] or '', 'message': r['message'] or '',
        'rate': r['rate'], 'session_minutes': r['session_minutes'] or 60, 'teacher_note': r['teacher_note'] or '',
        'created_at': r['created_at'], 'responded_at': r['responded_at'], 'ended_at': r['ended_at'],
        'sessions_paid': r['sessions_paid'] or 0, 'sessions_used': used, 'sessions_booked': booked,
        'sessions_left': max(0, (r['sessions_paid'] or 0) - used - booked),
        'teacher': {'id': r['teacher_id'], 'name': _full_name(r['t_first'], r['t_last'], 'Teacher'),
                    'avatar_url': get_avatar_url(r['teacher_id'], r['t_avatar'])},
        'child': {'id': r['student_id'], 'name': _full_name(r['s_first'], r['s_last'], 'Child'),
                  'first_name': (r['s_first'] or '').strip() or 'Child'},
        'parent': {'id': r['parent_id'], 'name': _full_name(r['p_first'], r['p_last'], 'Parent')},
        'self_paid': r['parent_id'] == r['student_id'],      # a learner paying for their own lessons
    }
    if with_detail:
        out['sessions'] = sessions
        out['payments'] = [dict(p) for p in conn.execute("SELECT id, sessions, amount, reference, status, note, created_at, decided_at, method, receipt FROM tutoring_payments WHERE tutoring_id = ? AND (status NOT IN ('started', 'failed') OR ?) ORDER BY id DESC", (r['id'], 1 if session.get('role') in ('parent', 'student') else 0)).fetchall()]
        rated = [s['parent_rating'] for s in sessions if s['parent_rating']]
        out['avg_session_rating'] = round(sum(rated) / len(rated), 1) if rated else None
        out['attended'] = sum(1 for s in sessions if s['status'] == 'completed' and s['child_attended'] != 0)
        # how the teacher and the child have been in touch since the request
        since = (r['created_at'] or '')[:19].replace('T', ' ')
        a, b = r['teacher_id'], r['student_id']
        m = conn.execute('''SELECT COUNT(*), SUM(CASE WHEN sender_id = ? THEN 1 ELSE 0 END), MAX(timestamp) FROM messages
                            WHERE ((sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?)) AND timestamp >= ?''',
                         (a, a, b, b, a, since)).fetchone()
        calls = {'count': 0, 'minutes': 0, 'last': None}
        try:
            for c in conn.execute('''SELECT answered_at, ended_at, created_at FROM calls
                                     WHERE ((caller_id = ? AND callee_id = ?) OR (caller_id = ? AND callee_id = ?)) AND created_at >= ?''',
                                  (a, b, b, a, since)).fetchall():
                calls['count'] += 1
                calls['last'] = max(calls['last'] or '', c['created_at'] or '')
                st, en = _parse_any(c['answered_at']), _parse_any(c['ended_at'])
                if st and en and en > st:
                    calls['minutes'] += int((en - st).total_seconds() // 60)
        except sqlite3.OperationalError:
            pass   # calls table not created yet
        out['interaction'] = {'messages': m[0] or 0, 'from_teacher': m[1] or 0, 'from_child': (m[0] or 0) - (m[1] or 0),
                              'last_message': to_iso_utc(m[2]) if m[2] else None, 'calls': calls}
        out['grade_change'] = _tutoring_grade_change(conn, r)
    return out


def _subject_course(subject):
    """The Eschool course a lesson subject is about ('Maths' -> 'math'), or None."""
    s = re.sub(r'[^a-z ]', '', str(subject or '').lower()).strip()
    if not s:
        return None
    if s in ('math', 'maths', 'mathematics') or s.startswith('math'):
        return 'math' if 'math' in EP_COURSE_MODULES else None
    for key in EP_COURSE_MODULES:
        name = EP_COURSE_NAMES.get(key, key).lower()
        if s == key or s in name or name.replace('grade 10 ', '') in s:
            return key
    return None


def _course_score_from_events(conn, sid, course, before=None):
    """A course's score from Eschool module tests and quizzes (30% tests, 70% quizzes, like the Progress page),
    counting only results before a time when one is given. None when there are no results."""
    q = "SELECT kind, pct FROM ep_events WHERE user_id = ? AND kind IN ('module', 'quiz') AND ref LIKE ? AND pct IS NOT NULL"
    args = [sid, course + ':%']
    if before:
        q += ' AND created_at < ?'
        args.append(before)
    rows = conn.execute(q, args).fetchall()
    m = [r[1] for r in rows if r[0] == 'module']
    z = [r[1] for r in rows if r[0] == 'quiz']
    ma = sum(m) / len(m) if m else None
    za = sum(z) / len(z) if z else None
    score = (ma * SCORE_MODULE_WEIGHT + za * SCORE_QUIZ_WEIGHT) if (ma is not None and za is not None) else (ma if ma is not None else za)
    return round(score) if score is not None else None


def _tutoring_grade_change(conn, r):
    """The child's grade in the lesson subject before the lessons started and now (only for subjects that are Eschool courses)."""
    course = _subject_course(r['subject'])
    if not course:
        return None
    try:
        _ep_table(conn)
        start = _iso(_parse_any(r['responded_at'] or r['created_at']) or _utc_now())
        before = _course_score_from_events(conn, r['student_id'], course, start)
        now = _course_score_from_events(conn, r['student_id'], course)
    except sqlite3.Error:
        return None
    pack = lambda v: {'percent': v, 'letter': _grade_for_pct(v)[0]} if v is not None else None
    return {'course': course, 'name': re.sub(r'^Grade \d+\s+', '', EP_COURSE_NAMES.get(course, course)), 'since': start,
            'before': pack(before), 'now': pack(now), 'change': (now - before) if (now is not None and before is not None) else None}


def _parse_any(v):
    if not v:
        return None
    try:
        d = datetime.fromisoformat(str(v).replace('Z', '+00:00').replace(' ', 'T'))
    except ValueError:
        return None
    return d if d.tzinfo else d.replace(tzinfo=timezone.utc)


TUTORING_SELECT = '''
    SELECT t.*, tu.firstname AS t_first, tu.lastname AS t_last, tu.avatar_filename AS t_avatar,
           su.firstname AS s_first, su.lastname AS s_last, pu.firstname AS p_first, pu.lastname AS p_last
    FROM tutoring t
    LEFT JOIN users tu ON tu.id = t.teacher_id
    LEFT JOIN users su ON su.id = t.student_id
    LEFT JOIN users pu ON pu.id = t.parent_id
'''


@app.route('/api/tutoring', methods=['GET', 'POST'])
def tutoring_parent():
    guard = _payer_guard()
    if guard:
        return guard
    pid = session['user_id']
    conn = _links_db()
    try:
        _tutor_tables(conn)
        if request.method == 'GET':
            rows = conn.execute(TUTORING_SELECT + ' WHERE t.parent_id = ? ORDER BY t.id DESC', (pid,)).fetchall()
            events = []
            try:
                today = _d(_nairobi_today())
                pairs = {(r['teacher_id'], r['student_id']) for r in rows if r['status'] in ('active', 'accepted', 'ended')}
                events = _shared_events(conn, sorted(pairs), today - timedelta(days=35), today + timedelta(days=120))
            except sqlite3.OperationalError:
                pass
            return jsonify({'engagements': [_tutoring_json(conn, r) for r in rows], 'events': events,
                            'payment': _payment_options(), 'packs': TUTOR_PACKS})

        d = request.get_json(silent=True) or {}
        try:
            teacher_id, student_id = int(d.get('teacher_id')), int(d.get('child_id'))
            per_week = max(1, min(7, int(d.get('sessions_per_week') or 1)))
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Choose a teacher and a child.'}), 400
        subject = str(d.get('subject') or '').strip()[:60]
        mode = 'online'     # lessons only happen on Eschool, in an Eschool call
        times = str(d.get('preferred_times') or '').strip()[:160]
        goals = str(d.get('goals') or '').strip()[:300]
        message = str(d.get('message') or '').strip()[:800]
        start = str(d.get('start_date') or '')[:10]
        if not subject:
            return jsonify({'success': False, 'message': 'Choose a subject.'}), 400
        if not times:
            return jsonify({'success': False, 'message': 'Say when lessons suit you, e.g. weekdays 5-6pm.'}), 400
        if start and not re.match(r'^\d{4}-\d{2}-\d{2}$', start):
            start = ''
        self_pay = session.get('role') == 'student'
        if self_pay:
            student_id = pid                     # a learner without a parent hires a teacher for themselves
        elif not conn.execute("SELECT 1 FROM parent_links WHERE parent_id = ? AND student_id = ? AND status = 'active'", (pid, student_id)).fetchone():
            return jsonify({'success': False, 'message': 'That child is not linked to you.'}), 404
        t = _teacher_cards(conn, [teacher_id])
        if not t:
            return jsonify({'success': False, 'message': 'Teacher not found.'}), 404
        t = t[0]
        if not t['accepting']:
            return jsonify({'success': False, 'message': f"{t['name']} is not taking new students right now."}), 409
        if conn.execute("""SELECT 1 FROM tutoring WHERE parent_id = ? AND teacher_id = ? AND student_id = ? AND subject = ?
                           AND status IN ('pending', 'accepted', 'active')""", (pid, teacher_id, student_id, subject)).fetchone():
            return jsonify({'success': False, 'message': 'You already have an open request with this teacher for this child and subject.'}), 409
        cur = conn.execute('''INSERT INTO tutoring (parent_id, teacher_id, student_id, subject, mode, sessions_per_week,
                              preferred_times, start_date, goals, message, rate, session_minutes, created_at)
                              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                           (pid, teacher_id, student_id, subject, mode, per_week, times, start or None, goals, message,
                            t['rate'], t['session_minutes'], _iso(_utc_now())))
        child = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (student_id,)).fetchone()
        parent_name = _full_name(session.get('firstname'), session.get('lastname'), 'A parent')
        create_notification(conn, teacher_id, 'New teaching request',
                            (f"{parent_name}, a learner, wants you to teach them " if self_pay else
                             f"{parent_name} wants you to teach {_full_name(child['firstname'], child['lastname'], 'their child')} ")
                            + f"{subject} ({per_week} session{'s' if per_week != 1 else ''} a week).",
                            icon='fa-chalkboard-user', color='#4361ee')
        conn.commit()
        row = conn.execute(TUTORING_SELECT + ' WHERE t.id = ?', (cur.lastrowid,)).fetchone()
        return jsonify({'success': True, 'engagement': _tutoring_json(conn, row)})
    finally:
        conn.close()


def _own_tutoring(conn, tid, role):
    col = 'parent_id' if role == 'parent' else 'teacher_id'
    return conn.execute(TUTORING_SELECT + f' WHERE t.id = ? AND t.{col} = ?', (tid, session.get('user_id'))).fetchone()


# ----- refunds: a family can end lessons at any time; the teacher keeps the money for lessons
# that were taught and Eschool sends back the money for paid lessons that were not -----
def _refunds_table(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS tutoring_refunds (
        id INTEGER PRIMARY KEY AUTOINCREMENT, tutoring_id INTEGER NOT NULL, parent_id INTEGER NOT NULL,
        teacher_id INTEGER NOT NULL, student_id INTEGER NOT NULL, sessions INTEGER NOT NULL, amount INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'owed',          -- owed | refunded
        note TEXT, created_at TEXT NOT NULL, decided_at TEXT, decided_by INTEGER)''')
    cols = {r[1] for r in conn.execute('PRAGMA table_info(tutoring_refunds)').fetchall()}
    if 'kind' not in cols:      # 'lesson' = one missed lesson paid back while lessons go on; 'end' = when lessons end
        conn.execute("ALTER TABLE tutoring_refunds ADD COLUMN kind TEXT DEFAULT 'end'")
        conn.execute("ALTER TABLE tutoring_refunds ADD COLUMN session_id INTEGER")


def _unused_lessons(conn, r):
    """(paid lessons not taught, money for them) for one arrangement. A lesson counts as used once it is over:
    taught, the learner missed it (the teacher waited), or being checked."""
    used = conn.execute("SELECT COUNT(*) FROM tutoring_sessions WHERE tutoring_id = ? AND status IN ('completed', 'missed', 'review')",
                        (r['id'],)).fetchone()[0]
    _refunds_table(conn)
    # a single missed lesson paid back ('lesson') already took one lesson off sessions_paid, so it isn't counted again
    already = conn.execute("SELECT COALESCE(SUM(sessions), 0) FROM tutoring_refunds WHERE tutoring_id = ? AND COALESCE(kind, 'end') = 'end'", (r['id'],)).fetchone()[0]
    unused = max(0, (r['sessions_paid'] or 0) - used - already)
    # money: what was really paid per lesson (the confirmed payments), not the price today
    paid = conn.execute("SELECT COALESCE(SUM(amount), 0), COALESCE(SUM(sessions), 0) FROM tutoring_payments WHERE tutoring_id = ? AND status = 'confirmed'",
                        (r['id'],)).fetchone()
    per = (paid[0] / paid[1]) if paid[1] else (r['rate'] or 0)
    return unused, _round_money(unused * per)


@app.route('/api/tutoring/<int:tid>/end-preview')
def tutoring_end_preview(tid):
    """What ending lessons now means: lessons taught (the teacher's), lessons not taught (refunded)."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _tutor_tables(conn)
        _refunds_table(conn)
        r = _own_tutoring(conn, tid, 'parent')
        if not r:
            return jsonify({'success': False, 'message': 'Not found.'}), 404
        booked = conn.execute("SELECT COUNT(*) FROM tutoring_sessions WHERE tutoring_id = ? AND status = 'scheduled'", (tid,)).fetchone()[0]
        taught = conn.execute("SELECT COUNT(*) FROM tutoring_sessions WHERE tutoring_id = ? AND status IN ('completed', 'missed', 'review')", (tid,)).fetchone()[0]
        unused, amount = _unused_lessons(conn, r)
        return jsonify({'success': True, 'paid': r['sessions_paid'] or 0, 'taught': taught, 'booked': booked,
                        'refund_lessons': unused, 'refund_amount': amount})
    finally:
        conn.close()


@app.route('/api/tutoring/sessions/<int:sid>/cancel', methods=['POST'])
def tutoring_family_cancel_lesson(sid):
    """The family cancels one booked lesson (at least LESSON_CANCEL_HOURS before it starts).
    The lesson goes back to 'to book', so nothing is lost."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _tutor_tables(conn)
        s = conn.execute('''SELECT s.id, s.status, s.starts_at, t.teacher_id, t.subject, t.student_id, t.parent_id
                            FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id WHERE s.id = ? AND t.parent_id = ?''',
                         (sid, session['user_id'])).fetchone()
        if not s or s['status'] != 'scheduled':
            return jsonify({'success': False, 'message': 'Only booked lessons that have not happened can be cancelled.'}), 404
        start = _parse_any(s['starts_at'])
        if start and start - _utc_now() < timedelta(hours=LESSON_CANCEL_HOURS):
            return jsonify({'success': False, 'message': f'Lessons can be cancelled up to {LESSON_CANCEL_HOURS} hours before they start. '
                                                         'Message the teacher if something came up.'}), 409
        now = _iso(_utc_now())
        conn.execute("UPDATE tutoring_sessions SET status = 'cancelled', outcome = 'cancelled', updated_at = ? WHERE id = ?", (now, sid))
        when = _when_for(s['teacher_id'], start) if start else 'the booked time'
        who = _full_name(session.get('firstname'), session.get('lastname'), 'The family')
        create_notification(conn, s['teacher_id'], 'Lesson cancelled',
                            f"{who} cancelled the {s['subject']} lesson on {when}. It goes back to the lessons to book.",
                            icon='fa-calendar-xmark', color='orange', category='tutoring')
        conn.commit()
        return jsonify({'success': True, 'message': 'Lesson cancelled. It goes back to your lessons to book.'})
    finally:
        conn.close()


def _card_refundable(conn, tutoring_id):
    """How much of this arrangement's card payments can still go back to the card."""
    if not _stripe_ready():
        return 0
    _pay_columns(conn)
    r = conn.execute('''SELECT COALESCE(SUM(amount - COALESCE(refunded, 0)), 0) FROM tutoring_payments
                        WHERE tutoring_id = ? AND method = 'stripe' AND status = 'confirmed' AND receipt LIKE 'pi_%' ''', (tutoring_id,)).fetchone()
    return r[0] or 0


def _refund_to_card(conn, f):
    """Sends one owed refund back to the card(s) it was paid with, newest payment first. Returns the Stripe refund ids."""
    left = float(f['amount'])
    if _card_refundable(conn, f['tutoring_id']) + 0.001 < left:
        raise ValueError('Not enough of this family\'s card payments is left to refund. Send it another way.')
    ids = []
    for p in conn.execute('''SELECT id, amount, COALESCE(refunded, 0) AS refunded, receipt FROM tutoring_payments
                             WHERE tutoring_id = ? AND method = 'stripe' AND status = 'confirmed' AND receipt LIKE 'pi_%' ORDER BY id DESC''',
                          (f['tutoring_id'],)).fetchall():
        take = min(float(p['amount']) - float(p['refunded']), left)
        if take <= 0.001:
            continue
        rf = _stripe('POST', '/refunds', {'payment_intent': p['receipt'], 'amount': _stripe_amount(take),
                                          'metadata[refund_id]': f['id'], 'metadata[tutoring_id]': f['tutoring_id']},
                     idem=f"eschool-refund-{f['id']}-{p['id']}")
        conn.execute('UPDATE tutoring_payments SET refunded = COALESCE(refunded, 0) + ? WHERE id = ?', (_round_money(take), p['id']))
        ids.append(rf.get('id'))
        left -= take
        if left <= 0.001:
            break
    return ids


@app.route('/api/admin/refunds', methods=['GET'])
def admin_refunds():
    """Money to send back to families for paid lessons that were not taught. ?status=owed|refunded|all"""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    st = request.args.get('status', 'owed')
    conn = _links_db()
    try:
        _refunds_table(conn)
        sql = '''SELECT f.*, t.subject, p.firstname AS p_first, p.lastname AS p_last, p.email AS p_email,
                        s.firstname AS s_first, s.lastname AS s_last, te.firstname AS t_first, te.lastname AS t_last
                 FROM tutoring_refunds f JOIN tutoring t ON t.id = f.tutoring_id
                 LEFT JOIN users p ON p.id = f.parent_id LEFT JOIN users s ON s.id = f.student_id LEFT JOIN users te ON te.id = f.teacher_id'''
        args = ()
        if st in ('owed', 'refunded'):
            sql += ' WHERE f.status = ?'
            args = (st,)
        rows = conn.execute(sql + ' ORDER BY f.id DESC LIMIT 200', args).fetchall()
        return jsonify({'success': True, 'refunds': [{
            'id': r['id'], 'amount': r['amount'], 'sessions': r['sessions'], 'status': r['status'], 'note': r['note'] or '',
            'subject': r['subject'], 'payer': _full_name(r['p_first'], r['p_last'], 'Family'), 'payer_email': r['p_email'] or '',
            'learner': _full_name(r['s_first'], r['s_last'], 'Learner'), 'teacher': _full_name(r['t_first'], r['t_last'], 'Teacher'),
            'self_paid': r['parent_id'] == r['student_id'], 'created_at': r['created_at'], 'decided_at': r['decided_at'],
            'card': r['status'] == 'owed' and _card_refundable(conn, r['tutoring_id']) + 0.001 >= float(r['amount'] or 0)} for r in rows]})
    finally:
        conn.close()


@app.route('/api/admin/refunds/<int:rid>', methods=['POST'])
def admin_mark_refunded(rid):
    """{"note": "M-Pesa reversal QWE..."}: the money was sent back by hand.
    {"method": "card"}: Eschool sends it back to the card it was paid with, through Stripe."""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    body = request.get_json(silent=True) or {}
    note = str(body.get('note') or '').strip()[:300] or None
    conn = _links_db()
    try:
        _refunds_table(conn)
        f = conn.execute("SELECT * FROM tutoring_refunds WHERE id = ? AND status = 'owed'", (rid,)).fetchone()
        if not f:
            return jsonify({'success': False, 'message': 'No refund waiting with that id.'}), 404
        if body.get('method') == 'card':
            try:
                ids = _refund_to_card(conn, f)
            except (ValueError, _rq.RequestException) as e:
                conn.commit()      # keep any part that did go back
                return jsonify({'success': False, 'message': str(e) if isinstance(e, ValueError) else 'Stripe is not answering. Try again in a minute.'}), 502
            note = 'Back to the card it was paid with (Stripe ' + ', '.join(i for i in ids if i) + '). Banks take 5 to 10 days to show it.'
        conn.execute("UPDATE tutoring_refunds SET status = 'refunded', note = ?, decided_at = ?, decided_by = ? WHERE id = ?",
                     (note, _iso(_utc_now()), session['user_id'], rid))
        create_notification(conn, f['parent_id'], 'Refund sent',
                            f"Eschool sent back {_money(f['amount'])} for {f['sessions']} lesson{'s' if f['sessions'] != 1 else ''} that were not taught."
                            + (f" {note}" if note else ''), icon='fa-rotate-left', color='green', category='tutoring')
        admin_log(conn, 'Refund sent', 'refund', rid, f"{_money(f['amount'])} · {f['sessions']} lessons" + (f" · {note}" if note else ''))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/tutoring/<int:tid>/cancel', methods=['POST'])
def tutoring_cancel(tid):
    """Parent withdraws a request (before paying) or ends an active arrangement. Ending: booked lessons are
    cancelled, the teacher keeps the money for lessons taught, and paid lessons not taught are refunded by Eschool."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _tutor_tables(conn)
        r = _own_tutoring(conn, tid, 'parent')
        if not r or r['status'] not in ('pending', 'accepted', 'active'):
            return jsonify({'success': False, 'message': 'This request is already closed.'}), 404
        new = 'ended' if r['status'] == 'active' else 'cancelled'
        conn.execute('UPDATE tutoring SET status = ?, ended_at = ? WHERE id = ?', (new, _iso(_utc_now()), tid))
        refund = (0, 0)
        if new == 'ended':
            conn.execute("UPDATE tutoring_sessions SET status = 'cancelled', updated_at = ? WHERE tutoring_id = ? AND status = 'scheduled'",
                         (_iso(_utc_now()), tid))
            _refunds_table(conn)
            refund = _unused_lessons(conn, r)
            if refund[0]:
                conn.execute('''INSERT INTO tutoring_refunds (tutoring_id, parent_id, teacher_id, student_id, sessions, amount, created_at)
                                VALUES (?, ?, ?, ?, ?, ?, ?)''', (tid, r['parent_id'], r['teacher_id'], r['student_id'], refund[0], refund[1], _iso(_utc_now())))
                payer = _full_name(r['p_first'], r['p_last'], 'A family')
                for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
                    create_notification(conn, admin_id, 'Refund to send',
                                        f"{payer} ended {r['subject']} lessons. Send back {_money(refund[1])} for {refund[0]} paid lesson"
                                        f"{'s' if refund[0] != 1 else ''} that were not taught.", icon='fa-rotate-left', color='#f59e0b')
                create_notification(conn, r['parent_id'], 'Refund on its way',
                                    f"You'll get back {_money(refund[1])} for {refund[0]} paid {r['subject']} lesson{'s' if refund[0] != 1 else ''} "
                                    "that were not taught. Eschool sends it back and tells you when it's done.",
                                    icon='fa-rotate-left', color='blue', category='tutoring')
        create_notification(conn, r['teacher_id'], 'Teaching ended' if new == 'ended' else 'Request withdrawn',
                            f"{_full_name(r['p_first'], r['p_last'], 'The parent')} {'ended' if new == 'ended' else 'withdrew'} "
                            f"{r['subject']} lessons for {_full_name(r['s_first'], r['s_last'], 'their child')}.",
                            icon='fa-circle-xmark', color='#64748b')
        conn.commit()
        return jsonify({'success': True, 'status': new, 'refund_lessons': refund[0], 'refund_amount': refund[1]})
    finally:
        conn.close()


@app.route('/api/tutoring/<int:tid>/pay', methods=['POST'])
def tutoring_pay(tid):
    guard = _payer_guard()
    if guard:
        return guard
    if not _payments_ready():
        return jsonify({'success': False, 'message': 'Payments are not set up yet. Please contact the school.'}), 503
    d = request.get_json(silent=True) or {}
    reference = re.sub(r'\s+', '', str(d.get('reference') or '')).upper()
    phone = re.sub(r'[^\d+]', '', str(d.get('phone') or ''))[:15] or None
    try:
        sessions = int(d.get('sessions'))
    except (TypeError, ValueError):
        sessions = 0
    if sessions not in TUTOR_PACKS:
        return jsonify({'success': False, 'message': 'Choose how many sessions to pay for.'}), 400
    if not MPESA_CODE_RE.match(reference):
        return jsonify({'success': False, 'message': 'The M-Pesa code has 10 letters and numbers, like SJK3H7XQ2P.'}), 400
    conn = _links_db()
    try:
        _tutor_tables(conn)
        _payments_table(conn)
        r = _own_tutoring(conn, tid, 'parent')
        if not r or r['status'] not in ('accepted', 'active'):
            return jsonify({'success': False, 'message': 'You can pay once the teacher has accepted.'}), 409
        if not r['rate']:
            return jsonify({'success': False, 'message': 'The teacher has not set a price yet.'}), 409
        used = conn.execute('SELECT 1 FROM tutoring_payments WHERE reference = ? OR receipt = ? UNION SELECT 1 FROM plan_payments WHERE reference = ?',
                            (reference, reference, reference)).fetchone()
        if used:
            return jsonify({'success': False, 'message': 'This M-Pesa code has already been used.'}), 409
        amount = r['rate'] * sessions
        cur = conn.execute('''INSERT INTO tutoring_payments (tutoring_id, parent_id, sessions, amount, reference, phone, created_at)
                              VALUES (?, ?, ?, ?, ?, ?, ?)''', (tid, session['user_id'], sessions, amount, reference, phone, _iso(_utc_now())))
        for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
            create_notification(conn, admin_id, 'Teaching payment to check',
                                f"{_full_name(r['p_first'], r['p_last'], 'A parent')} paid {_money(amount)} for {sessions} {r['subject']} "
                                f"session{'s' if sessions != 1 else ''} with {_full_name(r['t_first'], r['t_last'], 'a teacher')}. M-Pesa code {reference}.",
                                icon='fa-money-bill-wave', color='#f59e0b')
        conn.commit()
        return jsonify({'success': True, 'payment_id': cur.lastrowid, 'amount': amount})
    finally:
        conn.close()


@app.route('/api/tutoring/sessions/<int:sid>/feedback', methods=['POST'])
def tutoring_session_feedback(sid):
    """Parent rates a finished session, or reports a problem with any session."""
    guard = _payer_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    conn = _links_db()
    try:
        _tutor_tables(conn)
        s = conn.execute('''SELECT s.*, t.parent_id, t.teacher_id, t.subject FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                            WHERE s.id = ? AND t.parent_id = ?''', (sid, session['user_id'])).fetchone()
        if not s:
            return jsonify({'success': False, 'message': 'Session not found.'}), 404
        now = _iso(_utc_now())
        if d.get('report'):
            text = str(d.get('report')).strip()[:600]
            conn.execute('UPDATE tutoring_sessions SET parent_report = ?, updated_at = ? WHERE id = ?', (text, now, sid))
            for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
                create_notification(conn, admin_id, 'Parent reported a teaching session',
                                    f"{_full_name(session.get('firstname'), session.get('lastname'), 'A parent')} reported a {s['subject']} session: {text[:140]}",
                                    icon='fa-flag', color='#ef4444')
            conn.commit()
            return jsonify({'success': True})
        try:
            stars = int(d.get('rating'))
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Pick 1 to 5 stars.'}), 400
        if not 1 <= stars <= 5:
            return jsonify({'success': False, 'message': 'Pick 1 to 5 stars.'}), 400
        if s['status'] != 'completed':
            return jsonify({'success': False, 'message': 'You can rate a session once it has taken place.'}), 409
        conn.execute('UPDATE tutoring_sessions SET parent_rating = ?, parent_comment = ?, updated_at = ? WHERE id = ?',
                     (stars, str(d.get('comment') or '').strip()[:400] or None, now, sid))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/tutoring/<int:tid>/interactions')
def tutoring_interactions(tid):
    """Messages and calls between the hired teacher and the child, since the request."""
    guard = _payer_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _tutor_tables(conn)
        r = _own_tutoring(conn, tid, 'parent')
        if not r or r['status'] not in ('active', 'ended', 'accepted'):
            return jsonify({'success': False, 'message': 'Available once the teacher has accepted.'}), 404
        a, b = r['teacher_id'], r['student_id']
        since = (r['created_at'] or '')[:19].replace('T', ' ')
        items = [{'type': 'message', 'from': 'teacher' if m['sender_id'] == a else 'child', 'text': m['text'],
                  'at': to_iso_utc(m['timestamp'])}
                 for m in conn.execute('''SELECT sender_id, text, timestamp FROM messages
                                          WHERE ((sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?)) AND timestamp >= ?
                                          ORDER BY id DESC LIMIT 150''', (a, b, b, a, since)).fetchall()]
        try:
            for c in conn.execute('''SELECT caller_id, kind, status, created_at, answered_at, ended_at FROM calls
                                     WHERE ((caller_id = ? AND callee_id = ?) OR (caller_id = ? AND callee_id = ?)) AND created_at >= ?
                                     ORDER BY id DESC LIMIT 50''', (a, b, b, a, since)).fetchall():
                st, en = _parse_any(c['answered_at']), _parse_any(c['ended_at'])
                items.append({'type': 'call', 'from': 'teacher' if c['caller_id'] == a else 'child', 'kind': c['kind'],
                              'answered': bool(st), 'minutes': int((en - st).total_seconds() // 60) if st and en and en > st else 0,
                              'at': c['created_at']})
        except sqlite3.OperationalError:
            pass
        items.sort(key=lambda x: x['at'] or '', reverse=True)
        return jsonify({'items': items[:200]})
    finally:
        conn.close()


