@app.route('/api/tutoring/<int:tid>/respond', methods=['POST'])
def tutoring_respond(tid):
    """Teacher: {"action": "accept" | "decline", "rate": 800, "session_minutes": 60, "note": "..."}"""
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    d = request.get_json(silent=True) or {}
    conn = _links_db()
    try:
        _tutor_tables(conn)
        r = _own_tutoring(conn, tid, 'teacher')
        if not r or r['status'] != 'pending':
            return jsonify({'success': False, 'message': 'This request is no longer waiting.'}), 404
        note = str(d.get('note') or '').strip()[:400] or None
        child = _full_name(r['s_first'], r['s_last'], 'your child')
        teacher = _full_name(r['t_first'], r['t_last'], 'The teacher')
        if d.get('action') == 'accept':
            try:
                rate = _parse_amount(d.get('rate') or r['rate'] or 0, LESSON_PRICE_MIN, LESSON_PRICE_MAX) or 0
                minutes = int(d.get('session_minutes') or r['session_minutes'] or 60)
            except (TypeError, ValueError):
                rate, minutes = 0, 60
            if not rate:
                return jsonify({'success': False, 'message': f'Set your price per lesson ({SITE_CURRENCY} {LESSON_PRICE_MIN:g} to {LESSON_PRICE_MAX:,.0f}).'}), 400
            conn.execute("UPDATE tutoring SET status = 'accepted', rate = ?, session_minutes = ?, teacher_note = ?, responded_at = ? WHERE id = ?",
                         (rate, max(30, min(180, minutes)), note, _iso(_utc_now()), tid))
            create_notification(conn, r['parent_id'], 'Teacher accepted',
                                f"{teacher} accepted to teach {child} {r['subject']} at {_money(rate)} a session. Pay for sessions to start.",
                                icon='fa-circle-check', color='green', category='tutoring')
        elif d.get('action') == 'decline':
            conn.execute("UPDATE tutoring SET status = 'declined', teacher_note = ?, responded_at = ? WHERE id = ?", (note, _iso(_utc_now()), tid))
            create_notification(conn, r['parent_id'], 'Teacher declined',
                                f"{teacher} can't teach {child} {r['subject']} right now." + (f" {note}" if note else ''),
                                icon='fa-circle-xmark', color='red', category='tutoring')
        else:
            return jsonify({'success': False, 'message': 'action must be accept or decline'}), 400
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/tutoring/<int:tid>/sessions', methods=['POST'])
def tutoring_add_session(tid):
    """Teacher books a paid session: {"starts_at": ISO, "minutes": 60, "topic": "...", "link": "https://..."}"""
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    d = request.get_json(silent=True) or {}
    start = _parse_any(d.get('starts_at'))
    if not start:
        return jsonify({'success': False, 'message': 'Choose the date and time.'}), 400
    conn = _links_db()
    try:
        _tutor_tables(conn)
        r = _own_tutoring(conn, tid, 'teacher')
        if not r or r['status'] != 'active':
            return jsonify({'success': False, 'message': 'Sessions can be booked once the parent has paid.'}), 409
        info = _tutoring_json(conn, r, with_detail=False)
        if info['sessions_left'] <= 0:
            return jsonify({'success': False, 'message': 'All paid sessions are booked. The parent needs to pay for more.'}), 409
        link = ''   # lessons happen in an Eschool call, so attendance can be proved (no Zoom / Meet links)
        try:
            minutes = max(15, min(240, int(d.get('minutes') or r['session_minutes'] or 60)))
        except (TypeError, ValueError):
            minutes = 60
        topic = str(d.get('topic') or '').strip()[:160]
        start_utc = start.astimezone(timezone.utc)
        if start_utc < _utc_now() + timedelta(minutes=5):
            return jsonify({'success': False, 'message': 'Choose a time in the future.'}), 400
        end_utc = start_utc + timedelta(minutes=minutes)
        for o in conn.execute('''SELECT s.starts_at, s.minutes, t.subject FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                                 WHERE t.teacher_id = ? AND s.status = 'scheduled' ''', (session['user_id'],)).fetchall():
            o_start = _parse_any(o['starts_at'])
            if o_start and o_start < end_utc and start_utc < o_start + timedelta(minutes=int(o['minutes'] or 60)):
                return jsonify({'success': False, 'message': f"You already have a {o['subject']} lesson at that time. Choose another time."}), 409
        conn.execute('INSERT INTO tutoring_sessions (tutoring_id, starts_at, minutes, topic, link, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                     (tid, _iso(start.astimezone(timezone.utc)), minutes, topic or None, link or None, _iso(_utc_now())))
        for uid in dict.fromkeys((r['parent_id'], r['student_id'])):
            create_notification(conn, uid, 'Lesson booked', f"{r['subject']} with {_full_name(r['t_first'], r['t_last'], 'your teacher')} "
                                f"on {_when_for(uid, start_utc)}. The teacher calls on Eschool at lesson time."
                                + (f" Topic: {topic}." if topic else ''), icon='fa-calendar-check', color='#06b6d4', category='tutoring')
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/tutoring/sessions/<int:sid>', methods=['PATCH'])
def tutoring_update_session(sid):
    """Teacher records a session: {"status": "completed"|"missed"|"cancelled", "child_attended": true, "teacher_notes": "...", "homework": "..."}"""
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    d = request.get_json(silent=True) or {}
    status = d.get('status')
    if status not in ('completed', 'missed', 'cancelled', 'scheduled', None):
        return jsonify({'success': False, 'message': 'status must be completed, missed, cancelled or scheduled'}), 400
    conn = _links_db()
    try:
        _tutor_tables(conn)
        s = conn.execute('''SELECT s.id, s.status, s.starts_at, t.parent_id, t.student_id, t.subject FROM tutoring_sessions s
                            JOIN tutoring t ON t.id = s.tutoring_id WHERE s.id = ? AND t.teacher_id = ?''',
                         (sid, session['user_id'])).fetchone()
        if not s:
            return jsonify({'success': False, 'message': 'Session not found'}), 404
        now = _iso(_utc_now())
        # notes and homework can always be written; only what was sent changes
        if 'teacher_notes' in d:
            conn.execute('UPDATE tutoring_sessions SET teacher_notes = ?, updated_at = ? WHERE id = ?',
                         (str(d.get('teacher_notes') or '').strip()[:1000] or None, now, sid))
        if 'homework' in d:
            conn.execute('UPDATE tutoring_sessions SET homework = ?, updated_at = ? WHERE id = ?',
                         (str(d.get('homework') or '').strip()[:500] or None, now, sid))
        message = 'Saved.'
        if status == 'cancelled' and s['status'] == 'scheduled':
            start = _parse_any(s['starts_at'])
            if start and start <= _utc_now():
                conn.commit()
                return jsonify({'success': False, 'message': 'A lesson that has started can no longer be cancelled.'}), 409
            conn.execute("UPDATE tutoring_sessions SET status = 'cancelled', outcome = 'cancelled', updated_at = ? WHERE id = ?", (now, sid))
            for uid in dict.fromkeys((s['parent_id'], s['student_id'])):
                create_notification(conn, uid, 'Lesson cancelled', f"A {s['subject']} lesson was cancelled by the teacher. It goes back to your lessons to book.",
                                    icon='fa-calendar-xmark', color='orange', category='tutoring')
            message = 'Lesson cancelled. It goes back to the parent to book again.'
        elif status in ('completed', 'missed'):
            # whether a lesson took place is proved by the Eschool call, not typed in
            message = ('Notes saved. Eschool marks the lesson as taught by itself once the lesson call is over '
                       '(you and the learner on an Eschool call for most of the lesson).')
        conn.commit()
        return jsonify({'success': True, 'message': message})
    finally:
        conn.close()


# ============ TIME ZONES: times in messages are shown in each person's own time ============
# Every signed-in page tells the server the browser's time zone once (see add_call_script_to_pages);
# without it, the country's zone is used, then Nairobi. The school day (streaks, daily quiz, the
# monthly leaderboard) stays on one clock for everyone so nobody gets an unfair extra day.
COUNTRY_TZ = {'KE': 'Africa/Nairobi', 'UG': 'Africa/Kampala', 'TZ': 'Africa/Dar_es_Salaam', 'RW': 'Africa/Kigali',
              'ET': 'Africa/Addis_Ababa', 'NG': 'Africa/Lagos', 'GH': 'Africa/Accra', 'ZA': 'Africa/Johannesburg',
              'ZM': 'Africa/Lusaka', 'ZW': 'Africa/Harare', 'EG': 'Africa/Cairo', 'IN': 'Asia/Kolkata',
              'GB': 'Europe/London', 'US': 'America/New_York', 'CA': 'America/Toronto', 'AE': 'Asia/Dubai'}
DEFAULT_TZ = 'Africa/Nairobi'


def _tz_column(conn):
    if 'timezone' not in {r[1] for r in conn.execute('PRAGMA table_info(users)').fetchall()}:
        conn.execute('ALTER TABLE users ADD COLUMN timezone TEXT')


def _zone_of(uid):
    from zoneinfo import ZoneInfo
    name = DEFAULT_TZ
    try:
        c = sqlite3.connect('users.db')
        try:
            _tz_column(c)
            r = c.execute('SELECT timezone, country FROM users WHERE id = ?', (uid,)).fetchone()
        finally:
            c.close()
        if r:
            name = r[0] or COUNTRY_TZ.get((r[1] or '').upper(), DEFAULT_TZ)
        return ZoneInfo(name)
    except Exception:
        return ZoneInfo(DEFAULT_TZ)


def _when_for(uid, dt, fmt='%a %b %d, %H:%M'):
    """A UTC time written in this person's own time zone, with the zone's short name (e.g. 'Tue Nov 17, 10:00 EAT')."""
    if not dt:
        return ''
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    local = dt.astimezone(_zone_of(uid))
    abbr = local.strftime('%Z')
    return local.strftime(fmt) + (f' {abbr}' if abbr and not abbr.startswith(('+', '-')) else f" (UTC{local.strftime('%z')[:3]})")


@app.route('/api/me/timezone', methods=['POST'])
def api_me_timezone():
    if 'user_id' not in session:
        return jsonify({'success': False}), 401
    name = str((request.get_json(silent=True) or {}).get('tz') or '')[:64]
    try:
        from zoneinfo import ZoneInfo
        ZoneInfo(name)
    except Exception:
        return jsonify({'success': False, 'message': 'Unknown time zone'}), 400
    conn = sqlite3.connect('users.db')
    try:
        _tz_column(conn)
        conn.execute('UPDATE users SET timezone = ? WHERE id = ?', (name, session['user_id']))
        conn.commit()
    finally:
        conn.close()
    session['tz_seen'] = name
    return jsonify({'success': True})


TZ_SCRIPT = ('<script>try{(function(){var z=Intl.DateTimeFormat().resolvedOptions().timeZone;if(z)'
             'fetch("/api/me/timezone",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},'
             'body:JSON.stringify({tz:z})})})()}catch(e){}</script>')


# ============ LESSONS: REMINDERS AND PROOF THAT A LESSON TOOK PLACE ============
# A teacher can't simply say a lesson happened. Online lessons happen in an
# Eschool call (no outside links), and the server checks the call record:
#   taught          teacher and learner were on an Eschool call together for
#                   at least LESSON_PROOF_SHARE of the lesson time.
#   learner_absent  no call connected, but the teacher called the learner at
#                   the start and kept trying for LESSON_WAIT_MINUTES. Counts as
#                   a lesson used (the teacher was there).
#   review          anything else (no call, a call that was too short, an
#                   in-person lesson). An admin looks at the evidence and decides
#                   "taught" or "not taught"; "not taught" gives the lesson back.
# Learners, parents and teachers get a reminder about a day before and 15
# minutes before every lesson. Lessons show on the learner's Schedule page.
# Monthly report with the evidence: /api/tutoring/lesson-report?month=YYYY-MM

LESSON_PROOF_SHARE = 0.75        # share of the lesson both must be on the call
LESSON_CANCEL_HOURS = 2          # a family can cancel a booked lesson up to this long before it starts
LESSON_WAIT_MINUTES = 15         # how long a teacher keeps trying if the learner doesn't come
LESSON_EARLY_MINUTES = 15        # a lesson call may start this early
LESSON_GRACE_MINUTES = 30        # wait this long after the lesson end before deciding
LESSON_TICK_SECONDS = 60
_LESSON_LAST_TICK = {'at': 0.0}
LESSON_OUTCOME_TEXT = {
    'taught': 'Taught (proved by the Eschool call)',
    'learner_absent': 'Learner absent (teacher waited)',
    'review': 'Being checked by Eschool',
    'not_taught': 'Not taught (lesson given back)',
    'cancelled': 'Cancelled',
    'scheduled': 'Upcoming',
}


def _lesson_columns(conn):
    cols = {r[1] for r in conn.execute('PRAGMA table_info(tutoring_sessions)').fetchall()}
    for col, typ in (('outcome', 'TEXT'), ('proof', 'TEXT'), ('together_seconds', 'INTEGER'),
                     ('reminded_day', 'INTEGER NOT NULL DEFAULT 0'), ('reminded_soon', 'INTEGER NOT NULL DEFAULT 0'),
                     ('decided_by', 'INTEGER'), ('decided_at', 'TEXT'), ('decision_note', 'TEXT')):
        if col not in cols:
            conn.execute(f'ALTER TABLE tutoring_sessions ADD COLUMN {col} {typ}')


def _lesson_evidence(conn, s):
    """Looks at the Eschool calls between the teacher and the learner around one lesson.
    Returns (outcome, together_seconds, proof dict)."""
    _calls_tables(conn)
    start = _parse_any(s['starts_at'])
    minutes = int(s['minutes'] or 60)
    end = start + timedelta(minutes=minutes)
    w0, w1 = start - timedelta(minutes=LESSON_EARLY_MINUTES), end + timedelta(minutes=LESSON_GRACE_MINUTES)
    now = _utc_now()
    teacher, learner = s['teacher_id'], s['student_id']
    rows = conn.execute('''SELECT caller_id, callee_id, kind, status, created_at, answered_at, ended_at FROM calls
                           WHERE (caller_id = ? AND callee_id = ?) OR (caller_id = ? AND callee_id = ?)
                           ORDER BY id DESC LIMIT 300''', (teacher, learner, learner, teacher)).fetchall()
    together, connected, tries, learner_tries = 0, 0, [], 0
    for c in rows:
        made = _parse_any(c['created_at'])
        if not made or made < w0 - timedelta(hours=2) or made > w1:
            continue
        answered = _parse_any(c['answered_at'])
        if answered:
            a = max(answered, w0)
            ended = _parse_any(c['ended_at']) or min(now, answered + timedelta(minutes=minutes))
            b = min(ended, w1, now)
            if b > a:
                together += int((b - a).total_seconds())
                connected += 1
        elif c['caller_id'] == teacher and start - timedelta(minutes=5) <= made <= start + timedelta(minutes=45):
            tries.append(made)
        elif c['caller_id'] == learner and w0 <= made <= w1:
            learner_tries += 1
    needed = int(minutes * 60 * LESSON_PROOF_SHARE)
    proof = {'together_minutes': round(together / 60), 'lesson_minutes': minutes, 'calls_connected': connected,
             'teacher_tries': len(tries), 'learner_tries': learner_tries}
    if tries:
        proof['first_try'], proof['last_try'] = _iso(min(tries)), _iso(max(tries))
    if together >= needed:
        proof['why'] = f"Teacher and learner were on an Eschool call together for {round(together / 60)} of {minutes} minutes."
        return 'taught', together, proof
    if not connected and tries and min(tries) <= start + timedelta(minutes=10) \
            and (max(tries) - min(tries)) >= timedelta(minutes=LESSON_WAIT_MINUTES - 1):
        proof['why'] = (f"The teacher called {len(tries)} times from the start of the lesson for "
                        f"{round((max(tries) - min(tries)).total_seconds() / 60)} minutes; the learner didn't answer.")
        return 'learner_absent', together, proof
    if (s['mode'] or '') == 'in-person':
        proof['why'] = 'In-person lesson: an Eschool call can\'t prove it, so Eschool checks it.'
    elif connected:
        proof['why'] = f"The call was only {round(together / 60)} of {minutes} minutes."
    elif tries:
        proof['why'] = "The teacher called but didn't keep trying for the whole waiting time."
    elif learner_tries:
        proof['why'] = "The learner called the teacher, but the teacher didn't answer."
    else:
        proof['why'] = 'There was no Eschool call between the teacher and the learner.'
    return 'review', together, proof


def _lesson_rows(conn, where, args):
    return conn.execute(f'''SELECT s.*, t.teacher_id, t.student_id, t.parent_id, t.subject, t.mode,
                               tu.firstname AS t_first, tu.lastname AS t_last, su.firstname AS s_first, su.lastname AS s_last
                               FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                               LEFT JOIN users tu ON tu.id = t.teacher_id LEFT JOIN users su ON su.id = t.student_id
                               WHERE {where} ORDER BY s.starts_at''', args).fetchall()


def _lessons_check(conn):
    """Reminders for upcoming lessons, and a decision for every lesson that is over."""
    _tutor_tables(conn)
    now = _utc_now()
    for s in _lesson_rows(conn, "s.status = 'scheduled'", ()):
        start = _parse_any(s['starts_at'])
        if not start:
            continue
        teacher = _full_name(s['t_first'], s['t_last'], 'your teacher')
        learner = _full_name(s['s_first'], s['s_last'], 'your learner')
        left = start - now
        if timedelta(minutes=16) < left <= timedelta(hours=24) and not s['reminded_day']:
            for uid in dict.fromkeys((s['student_id'], s['parent_id'])):
                create_notification(conn, uid, 'Lesson coming up',
                                    f"{s['subject']} lesson with {teacher} within the next day. See the time on the Schedule page.",
                                    icon='fa-calendar-day', color='#06b6d4', category='tutoring')
            create_notification(conn, s['teacher_id'], 'Lesson coming up',
                                f"{s['subject']} lesson with {learner} within the next day.",
                                icon='fa-calendar-day', color='#06b6d4', category='tutoring')
            conn.execute('UPDATE tutoring_sessions SET reminded_day = 1 WHERE id = ?', (s['id'],))
        elif timedelta(minutes=-5) < left <= timedelta(minutes=16) and not s['reminded_soon']:
            create_notification(conn, s['student_id'], 'Your lesson starts soon',
                                f"{s['subject']} with {teacher} starts in about 15 minutes. Keep Eschool open: your teacher will call you here.",
                                icon='fa-bell', color='#f59e0b', category='tutoring')
            if s['parent_id'] != s['student_id']:
                create_notification(conn, s['parent_id'], 'Lesson starts soon',
                                    f"{learner}'s {s['subject']} lesson with {teacher} starts in about 15 minutes.",
                                    icon='fa-bell', color='#f59e0b', category='tutoring')
            create_notification(conn, s['teacher_id'], 'Your lesson starts soon',
                                f"{s['subject']} with {learner} starts in about 15 minutes. Call the learner on Eschool "
                                "(video or voice) at the start: the call is what proves the lesson took place.",
                                icon='fa-bell', color='#f59e0b', category='tutoring')
            conn.execute('UPDATE tutoring_sessions SET reminded_day = 1, reminded_soon = 1 WHERE id = ?', (s['id'],))
        elif now > start + timedelta(minutes=int(s['minutes'] or 60) + LESSON_GRACE_MINUTES):
            outcome, together, proof = _lesson_evidence(conn, s)
            status = {'taught': 'completed', 'learner_absent': 'missed'}.get(outcome, 'review')
            conn.execute('''UPDATE tutoring_sessions SET status = ?, outcome = ?, together_seconds = ?, proof = ?,
                            child_attended = ?, updated_at = ? WHERE id = ? AND status = 'scheduled' ''',
                         (status, outcome, together, json.dumps(proof), 1 if outcome == 'taught' else (0 if outcome == 'learner_absent' else None),
                          _iso(now), s['id']))
            if now - start > timedelta(days=3):
                continue   # an old lesson from before this check existed: decided quietly
            if outcome == 'taught':
                create_notification(conn, s['parent_id'], 'Lesson taught',
                                    f"{learner}'s {s['subject']} lesson with {teacher} took place. {proof['why']}",
                                    icon='fa-clipboard-check', color='green', category='tutoring')
            elif outcome == 'learner_absent':
                for uid in dict.fromkeys((s['parent_id'], s['student_id'])):
                    create_notification(conn, uid, 'Lesson missed by the learner',
                                        f"{s['subject']} with {teacher}: {proof['why']}",
                                        icon='fa-triangle-exclamation', color='red', category='tutoring')
            else:
                create_notification(conn, s['parent_id'], 'Lesson being checked',
                                    f"We couldn't confirm {learner}'s {s['subject']} lesson with {teacher}. {proof['why']} "
                                    "Eschool will check it; if it wasn't taught, the lesson goes back to you.",
                                    icon='fa-magnifying-glass', color='orange', category='tutoring')
                create_notification(conn, s['teacher_id'], 'Lesson not confirmed',
                                    f"Your {s['subject']} lesson with {learner} couldn't be confirmed: {proof['why']} An admin will check it.",
                                    icon='fa-magnifying-glass', color='orange', category='tutoring')
                for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
                    create_notification(conn, admin_id, 'Lesson to check',
                                        f"{s['subject']}: {teacher} with {learner}. {proof['why']}",
                                        icon='fa-magnifying-glass', color='orange')


@app.before_request
def _lessons_tick():
    """Runs the lesson check at most once a minute, while anyone uses Eschool."""
    if request.endpoint in (None, 'static'):
        return None
    now = _clock.time()
    if now - _LESSON_LAST_TICK['at'] < LESSON_TICK_SECONDS:
        return None
    _LESSON_LAST_TICK['at'] = now
    try:
        conn = _links_db()
        try:
            _lessons_check(conn)
            _goal_reminders(conn)
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        print(f"lesson check skipped: {e}")
    return None


def _lesson_json(s, for_role):
    start = _parse_any(s['starts_at'])
    outcome = s['outcome'] or ('scheduled' if s['status'] == 'scheduled' else s['status'])
    try:
        proof = json.loads(s['proof']) if s['proof'] else None
    except (TypeError, ValueError):
        proof = None
    out = {'id': s['id'], 'subject': s['subject'], 'topic': s['topic'] or '', 'mode': s['mode'],
           'starts_at': _iso(start) if start else s['starts_at'], 'minutes': s['minutes'],
           'status': s['status'], 'outcome': outcome, 'outcome_text': LESSON_OUTCOME_TEXT.get(outcome, outcome),
           'teacher': _full_name(s['t_first'], s['t_last'], 'Teacher'), 'teacher_id': s['teacher_id'],
           'learner': _full_name(s['s_first'], s['s_last'], 'Learner'), 'learner_id': s['student_id'],
           'homework': s['homework'] or '', 'together_minutes': round((s['together_seconds'] or 0) / 60),
           'evidence': (proof or {}).get('why', ''), 'decision_note': s['decision_note'] or ''}
    if for_role in ('parent', 'admin', 'teacher'):
        out['proof'] = proof
        out['teacher_notes'] = s['teacher_notes'] or ''
        out['parent_report'] = s['parent_report'] or ''
    return out


@app.route('/api/tutoring/my-lessons')
def api_my_lessons():
    """A learner's private lessons (60 days back, and everything ahead), for the Schedule page."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    conn = _links_db()
    try:
        _tutor_tables(conn)
        since = _iso(_utc_now() - timedelta(days=60))
        role = session.get('role')
        who = {'teacher': 't.teacher_id', 'parent': 't.parent_id'}.get(role, 't.student_id')
        rows = _lesson_rows(conn, f"{who} = ? AND s.starts_at >= ?", (session['user_id'], since))
        return jsonify({'success': True, 'lessons': [_lesson_json(r, role) for r in rows]})
    finally:
        conn.close()


@app.route('/api/tutoring/lesson-report')
def api_lesson_report():
    """Month report with the evidence for every lesson: ?month=YYYY-MM (parent: own children,
    teacher: own lessons, admin: everyone, or ?teacher_id= / ?parent_id=)."""
    role = session.get('role')
    if 'user_id' not in session or role not in ('parent', 'teacher', 'admin'):
        return jsonify({'success': False, 'message': 'Not available'}), 403
    month = (request.args.get('month') or _utc_now().strftime('%Y-%m'))[:7]
    try:
        first = datetime.strptime(month + '-01', '%Y-%m-%d').replace(tzinfo=timezone.utc)
    except ValueError:
        return jsonify({'success': False, 'message': 'month must look like 2026-10'}), 400
    nxt = (first + timedelta(days=32)).replace(day=1)
    where, args = 's.starts_at >= ? AND s.starts_at < ?', [_iso(first - timedelta(days=1)), _iso(nxt + timedelta(days=1))]
    if role == 'parent':
        where += ' AND t.parent_id = ?'; args.append(session['user_id'])
    elif role == 'teacher':
        where += ' AND t.teacher_id = ?'; args.append(session['user_id'])
    else:
        for key, col in (('teacher_id', 't.teacher_id'), ('parent_id', 't.parent_id')):
            if request.args.get(key, '').isdigit():
                where += f' AND {col} = ?'; args.append(int(request.args[key]))
    conn = _links_db()
    try:
        _tutor_tables(conn)
        rows = [r for r in _lesson_rows(conn, where, tuple(args))
                if (_parse_any(r['starts_at']) or first).strftime('%Y-%m') == month]
        lessons = [_lesson_json(r, role) for r in rows]
        count = lambda o: sum(1 for x in lessons if x['outcome'] == o)
        totals = {o: count(o) for o in ('taught', 'learner_absent', 'review', 'not_taught', 'cancelled', 'scheduled')}
        totals['to_pay_teacher'] = totals['taught'] + totals['learner_absent']
        return jsonify({'success': True, 'month': month, 'totals': totals, 'lessons': lessons})
    finally:
        conn.close()


@app.route('/api/admin/lessons/<int:sid>/decide', methods=['POST'])
def api_admin_decide_lesson(sid):
    """{"outcome": "taught" | "not_taught", "note": "..."}. "not_taught" gives the lesson back to the parent."""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    d = request.get_json(silent=True) or {}
    outcome = d.get('outcome')
    if outcome not in ('taught', 'not_taught'):
        return jsonify({'success': False, 'message': 'outcome must be taught or not_taught'}), 400
    note = str(d.get('note') or '').strip()[:400]
    conn = _links_db()
    try:
        _tutor_tables(conn)
        rows = _lesson_rows(conn, 's.id = ?', (sid,))
        if not rows:
            return jsonify({'success': False, 'message': 'Lesson not found'}), 404
        s = rows[0]
        if s['status'] in ('scheduled', 'cancelled') and s['outcome'] != 'not_taught':
            return jsonify({'success': False, 'message': 'Only lessons that are over can be decided.'}), 409
        status = 'completed' if outcome == 'taught' else 'cancelled'
        conn.execute('''UPDATE tutoring_sessions SET status = ?, outcome = ?, decided_by = ?, decided_at = ?, decision_note = ?,
                        updated_at = ? WHERE id = ?''', (status, outcome, session['user_id'], _iso(_utc_now()), note or None,
                                                         _iso(_utc_now()), sid))
        learner = _full_name(s['s_first'], s['s_last'], 'your child')
        text = (f"Eschool checked {learner}'s {s['subject']} lesson: " +
                ('it was taught.' if outcome == 'taught' else "it wasn't taught, so the lesson goes back to you to book again.")
                + (f" Note: {note}" if note else ''))
        create_notification(conn, s['parent_id'], 'Lesson checked', text, icon='fa-scale-balanced', color='blue', category='tutoring')
        create_notification(conn, s['teacher_id'], 'Lesson checked',
                            f"An admin decided your {s['subject']} lesson with {learner} was " +
                            ('taught.' if outcome == 'taught' else 'not taught.') + (f" Note: {note}" if note else ''),
                            icon='fa-scale-balanced', color='blue', category='tutoring')
        if outcome == 'not_taught':
            r = conn.execute(TUTORING_SELECT + ' WHERE t.id = (SELECT tutoring_id FROM tutoring_sessions WHERE id = ?)', (sid,)).fetchone()
            if r and r['status'] == 'ended':     # lessons already ended: nothing to book again, so the money goes back
                _refunds_table(conn)
                n, amount = _unused_lessons(conn, r)
                if n:
                    conn.execute('''INSERT INTO tutoring_refunds (tutoring_id, parent_id, teacher_id, student_id, sessions, amount, created_at)
                                    VALUES (?, ?, ?, ?, ?, ?, ?)''', (r['id'], r['parent_id'], r['teacher_id'], r['student_id'], n, amount, _iso(_utc_now())))
        admin_log(conn, 'Decided lesson', 'lesson', sid, f"{s['subject']}: {outcome}")
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


