@app.route('/api/admin/tutoring-payments/<int:pay_id>', methods=['POST'])
def admin_decide_tutoring_payment(pay_id):
    """{"action": "confirm" | "reject", "note": "..."}"""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    d = request.get_json(silent=True) or {}
    if d.get('action') not in ('confirm', 'reject'):
        return jsonify({'success': False, 'message': 'action must be confirm or reject'}), 400
    note = str(d.get('note') or '').strip()[:300] or None
    conn = _links_db()
    try:
        _tutor_tables(conn)
        p = conn.execute("SELECT * FROM tutoring_payments WHERE id = ? AND status = 'pending'", (pay_id,)).fetchone()
        if not p:
            return jsonify({'success': False, 'message': 'No waiting payment with that id'}), 404
        r = conn.execute(TUTORING_SELECT + ' WHERE t.id = ?', (p['tutoring_id'],)).fetchone()
        now = _iso(_utc_now())
        if d['action'] == 'confirm':
            _confirm_tutoring_payment(conn, p, by=session['user_id'], note=note)
        else:
            create_notification(conn, r['parent_id'], 'Teaching payment not confirmed',
                                f"We couldn't confirm M-Pesa code {p['reference']}." + (f" {note}" if note else ''), icon='fa-triangle-exclamation', color='red')
        conn.execute('UPDATE tutoring_payments SET status = ?, note = ?, decided_at = ?, decided_by = ? WHERE id = ?',
                     ('confirmed' if d['action'] == 'confirm' else 'rejected', note, now, session['user_id'], pay_id))
        admin_log(conn, 'Confirmed teaching payment' if d['action'] == 'confirm' else 'Rejected teaching payment', 'payment', pay_id,
                  f"{p['reference']} · {_money(p['amount'])} · {r['subject']}" + (f" · {note}" if note else ''))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


# ============ PARENT: LEARNER PROGRESS (parent-progress.html) ============
# Everything comes from what Eschool already records for the child:
#   - student_progress_summary : GPA, grade, course progress, streaks (sent by the child's dashboard)
#   - ep_events                : every module test, quiz, Daily Quiz and course finished, with day and score
#   - achievements             : the same list the child sees
#   - tutoring_sessions        : private lessons (attendance, teacher notes, homework)
# Parts follow what the child allowed when linking: grades -> results and progress,
# attendance -> lesson attendance, schedule -> upcoming lessons.

PROGRESS_COURSE_STYLE = {
    'math': ('#7c3aed', 'fa-calculator'), 'english': ('#2563eb', 'fa-book-open'),
    'kiswahili': ('#16a34a', 'fa-language'), 'csl': ('#d97706', 'fa-hands-helping'),
}


def _linked_child(conn, parent_id, student_id):
    return conn.execute('''SELECT pl.permissions, pl.relationship, pl.linked_at, u.id, u.firstname, u.lastname, u.avatar_filename,
                                  u.plan, u.plan_started_at, u.plan_expires_at
                           FROM parent_links pl JOIN users u ON u.id = pl.student_id
                           WHERE pl.parent_id = ? AND pl.student_id = ? AND pl.status = 'active' ''',
                        (parent_id, student_id)).fetchone()


@app.route('/api/parent/children')
def api_parent_children():
    guard = _parent_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _ensure_plan_columns(conn)
        _progress_summary_table(conn)
        _refresh_children_progress(conn, session['user_id'])
        rows = conn.execute('''SELECT pl.id AS link_id, pl.permissions, pl.relationship, pl.linked_at,
                                      u.id, u.firstname, u.lastname, u.avatar_filename, ps.courses
                               FROM parent_links pl JOIN users u ON u.id = pl.student_id
                               LEFT JOIN student_progress_summary ps ON ps.student_id = u.id
                               WHERE pl.parent_id = ? AND pl.status = 'active' ORDER BY u.firstname''',
                            (session['user_id'],)).fetchall()
        out = []
        for r in rows:
            try:
                perms = _clean_permissions(json.loads(r['permissions'] or '{}'))
            except ValueError:
                perms = _clean_permissions({})
            levels = sorted({_pretty_level(str(c.get('level'))) for c in _jlist_dicts(r['courses']) if c.get('level')})
            out.append({'id': r['id'], 'name': _full_name(r['firstname'], r['lastname'], 'Child'),
                        'first_name': (r['firstname'] or '').strip() or 'Child',
                        'avatar_url': get_avatar_url(r['id'], r['avatar_filename']) if r['avatar_filename'] else None,
                        'grade': ', '.join(levels), 'permissions': perms,
                        'link_id': r['link_id'], 'relationship': (r['relationship'] or '').capitalize(),
                        'linked_since': _nice_date(r['linked_at']) or ''})
        return jsonify({'children': out, 'permission_labels': PARENT_PERM_LABELS})
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/progress')
def api_parent_child_progress(child_id):
    guard = _parent_guard()
    if guard:
        return guard
    rng = request.args.get('range', 'term')
    today = datetime.strptime(_nairobi_today(), '%Y-%m-%d')
    if rng == '30d':
        start, prev_start = today - timedelta(days=29), today - timedelta(days=59)
    elif rng == 'year':
        start = today.replace(month=1, day=1)
        prev_start = start.replace(year=start.year - 1)
    elif rng == 'all':
        start = prev_start = datetime(2000, 1, 1)
    else:   # term = about the last 3 months
        rng = 'term'
        start, prev_start = today - timedelta(days=89), today - timedelta(days=179)
    start_s, prev_s = start.strftime('%Y-%m-%d'), prev_start.strftime('%Y-%m-%d')

    conn = _links_db()
    try:
        _progress_summary_table(conn)
        _ep_table(conn)
        _ensure_plan_columns(conn)
        _refresh_children_progress(conn, session['user_id'])
        link = _linked_child(conn, session['user_id'], child_id)
        if not link:
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        try:
            perms = _clean_permissions(json.loads(link['permissions'] or '{}'))
        except ValueError:
            perms = _clean_permissions({})
        row = conn.execute('SELECT ' + SUMMARY_COLS + ' FROM student_progress_summary WHERE student_id = ?', (child_id,)).fetchone()
        totals = _ep_totals(conn, [child_id])
        st = _learner_stats(row, totals.get(child_id))
        goal = conn.execute('SELECT weekly_goal FROM ep_goals WHERE user_id = ?', (child_id,)).fetchone()
        rank, ranked_total = None, 0
        try:
            hidden = _users_with_privacy(conn, 'show_on_leaderboard', 0)
            ranked = _ranked_learners(conn, exclude_ids=hidden)
            ranked_total = len(ranked)
            rank = next((t[0] for t in ranked if t[1] == child_id), None)
        except Exception:
            pass
        plan = _current_plan(link['plan'], link['plan_started_at'], link['plan_expires_at'])
        events = [dict(e) for e in conn.execute('SELECT kind, ref, ep, day, created_at, pct FROM ep_events WHERE user_id = ? ORDER BY COALESCE(day, created_at)',
                                                 (child_id,)).fetchall()]

        out = {
            'range': rng, 'from': start_s, 'permissions': perms,
            'updated_at': st['updated_at'], 'has_summary': row is not None and st['updated_at'] is not None,
            'child': {'id': child_id, 'name': _full_name(link['firstname'], link['lastname'], 'Child'),
                      'first_name': (link['firstname'] or '').strip() or 'Child',
                      'relationship': (link['relationship'] or '').capitalize(), 'linked_since': _nice_date(link['linked_at'])},
            'plan': plan,
            'points': {'ep_total': st['ep'], 'ep_week': st['ep_week'], 'ep_month': st['ep_month'], 'level': st['level'], 'level_progress': st['level_progress'],
                       'ep_to_next': st['ep_to_next'], 'weekly_goal': goal['weekly_goal'] if goal else None,
                       'rank': rank, 'ranked_total': ranked_total},
        }

        if perms['grades']:
            def in_range(e, a, b=None):
                d = e['day'] or ''
                return d and d >= a and (b is None or d < b)
            scored = [e for e in events if e['pct'] is not None and e['kind'] in ('module', 'quiz', 'daily_quiz')]
            cur = [e['pct'] for e in scored if in_range(e, start_s)]
            prev = [e['pct'] for e in scored if in_range(e, prev_s, start_s)] if rng != 'all' else []
            done_period = [e for e in events if in_range(e, start_s) and e['kind'] in ('module', 'quiz', 'daily_quiz', 'course')]
            courses = []
            course_grades = _progress_page_course_grades(conn, child_id)
            for c in st['courses']:
                if not isinstance(c, dict):
                    continue
                cid = str(c.get('id') or '').lower()
                mine = [e for e in events if (e['ref'] or '').split(':')[0] == cid or (e['kind'] == 'course' and e['ref'] == cid)]
                mods = [e for e in mine if e['kind'] == 'module']
                pcts = [e['pct'] for e in mine if e['pct'] is not None]
                color, icon = PROGRESS_COURSE_STYLE.get(cid, ('#4361ee', 'fa-book'))
                total = EP_COURSE_MODULES.get(cid)
                last = max((e['created_at'] for e in mine if e['day']), default=None)
                courses.append({
                    'id': cid, 'name': c.get('name') or EP_COURSE_NAMES.get(cid, 'Course'),
                    'level': _pretty_level(str(c.get('level'))) if c.get('level') else '',
                    'color': color, 'icon': icon, 'progress': int(c.get('progress') or 0),
                    'modules_completed': len(mods), 'modules_total': total,
                    'quizzes_passed': sum(1 for e in mine if e['kind'] == 'quiz'),
                    'finished': any(e['kind'] == 'course' for e in mine) or int(c.get('progress') or 0) >= 100,
                    'avg_score': round(sum(pcts) / len(pcts)) if pcts else None,
                    'best_score': max(pcts) if pcts else None,
                    'last_activity': last,
                    # the course's grade the way the child's Progress page works it out (30% module tests, 70% quizzes)
                    'grade': course_grades.get(cid),
                })
            grades = []
            for e in reversed(events):
                if e['kind'] not in ('module', 'quiz', 'daily_quiz', 'course'):
                    continue
                if rng != 'all' and not in_range(e, start_s):
                    continue
                text, sub = _ep_event_label(e)
                grades.append({'type': {'module': 'module', 'quiz': 'quiz', 'daily_quiz': 'daily', 'course': 'course'}[e['kind']],
                               'assignment': text, 'course': sub or ('Daily Quiz' if e['kind'] == 'daily_quiz' else ''),
                               'percentage': e['pct'], 'ep': e['ep'], 'date': e['day']})
            # average score by week (8 weeks) or by month (longer ranges)
            trend = []
            if rng == '30d':
                for i in range(4, -1, -1):
                    a = today - timedelta(days=today.weekday() + 7 * i)
                    b = a + timedelta(days=7)
                    vals = [e['pct'] for e in scored if in_range(e, a.strftime('%Y-%m-%d'), b.strftime('%Y-%m-%d'))]
                    trend.append({'label': a.strftime('%d %b'), 'avg': round(sum(vals) / len(vals)) if vals else None, 'count': len(vals)})
            else:
                months = 12 if rng in ('year', 'all') else 4
                y, m = today.year, today.month
                keys = []
                for _ in range(months):
                    keys.append((y, m)); m -= 1
                    if m == 0:
                        y, m = y - 1, 12
                for y, m in reversed(keys):
                    pre = f'{y:04d}-{m:02d}'
                    vals = [e['pct'] for e in scored if (e['day'] or '').startswith(pre)]
                    trend.append({'label': datetime(y, m, 1).strftime('%b'), 'avg': round(sum(vals) / len(vals)) if vals else None, 'count': len(vals)})
            days = 30 if rng != '30d' else 30
            daily = []
            for i in range(days - 1, -1, -1):
                d = (today - timedelta(days=i)).strftime('%Y-%m-%d')
                evs = [e for e in events if e['day'] == d]
                daily.append({'date': d, 'count': len(evs), 'ep': sum(e['ep'] for e in evs)})
            out.update({
                'summary': {
                    'overall_progress': st['avg_progress'], 'gpa': st['gpa'], 'overall_grade': st['overall_grade'],
                    'progress_grade': _progress_page_grade(conn, child_id),
                    'modules_completed': st['modules_completed'],
                    'modules_total': sum(EP_COURSE_MODULES.get(c['id'], 0) for c in courses) or None,
                    'quizzes_passed': st['quizzes_passed'], 'courses_completed': st['courses_completed'],
                    'courses_enrolled': len(courses), 'assessments': st['assessments'],
                    'quiz_streak': st['quiz_streak'], 'best_quiz_streak': st['best_quiz_streak'],
                    'module_streak': st['module_streak'], 'best_module_streak': st['best_module_streak'],
                    'active_days': st['active_days'],
                    'avg_score': round(sum(cur) / len(cur)) if cur else None,
                    'avg_score_change': (round(sum(cur) / len(cur) - sum(prev) / len(prev)) if cur and prev else None),
                    'done_in_period': len(done_period),
                    'active_days_in_period': len({e['day'] for e in done_period}),
                    'ep_in_period': sum(e['ep'] for e in done_period),
                },
                'courses': courses, 'grades': grades, 'score_trend': trend, 'daily': daily,
            })
            try:
                ach = _achievements_list(conn, child_id)
                out['achievements'] = [{k: a[k] for k in ('title', 'description', 'icon', 'color', 'tier_label', 'tier_color',
                                                          'badge', 'unlocked', 'unlocked_at', 'percent', 'progress', 'target', 'category')}
                                       for a in ach]
            except Exception:
                out['achievements'] = []

        # private lessons with teachers this parent hired (any teacher if attendance is shared)
        try:
            _tutor_tables(conn)
            sess = conn.execute('''SELECT s.*, t.subject, t.parent_id, u.firstname AS tf, u.lastname AS tl FROM tutoring_sessions s
                                   JOIN tutoring t ON t.id = s.tutoring_id LEFT JOIN users u ON u.id = t.teacher_id
                                   WHERE t.student_id = ? ORDER BY s.starts_at DESC''', (child_id,)).fetchall()
        except sqlite3.OperationalError:
            sess = []
        own = [s for s in sess if s['parent_id'] == session['user_id']]
        visible = sess if perms['attendance'] else own
        if visible:
            held = [s for s in visible if s['status'] in ('completed', 'missed')]
            attended = sum(1 for s in held if s['status'] == 'completed' and s['child_attended'] != 0)
            now_iso = _iso(_utc_now())
            out['lessons'] = {
                'held': len(held), 'attended': attended, 'missed': len(held) - attended,
                'rate': round(attended / len(held) * 100) if held else None,
                'upcoming': [{'subject': s['subject'], 'teacher': _full_name(s['tf'], s['tl'], 'Teacher'), 'starts_at': s['starts_at'],
                              'minutes': s['minutes'], 'topic': s['topic'] or ''}
                             for s in reversed(visible) if s['status'] == 'scheduled' and s['starts_at'] >= now_iso][:5]
                            if (perms['schedule'] or own) else [],
                'recent': [{'subject': s['subject'], 'teacher': _full_name(s['tf'], s['tl'], 'Teacher'), 'starts_at': s['starts_at'],
                            'status': 'attended' if s['status'] == 'completed' and s['child_attended'] != 0 else 'missed'}
                           for s in held[:20]],
            }
            out['teacher_notes'] = [{'teacher': _full_name(s['tf'], s['tl'], 'Teacher'), 'course': s['subject'],
                                     'text': s['teacher_notes'], 'homework': s['homework'] or '', 'created_at': s['updated_at'] or s['starts_at']}
                                    for s in own if s['teacher_notes'] or s['homework']][:20]
        return jsonify(out)
    finally:
        conn.close()


# ============ PARENTAL CONTROLS (parent-controls.html) ============
# Rules a linked parent sets for their child, ENFORCED ON THE SERVER:
#   - Screen time: a daily limit per weekday, quiet hours, pause now, extra time today.
#     Time is measured on the server while the child has Eschool open (every page
#     checks in with the server at least every 15 seconds). When a rule applies,
#     pages show a "Paused by your parent" screen instead, and messaging/calls stop.
#   - Who the child can talk to: everyone / teachers only / approved people only / nobody,
#     plus a blocked list. Applies to messages AND calls, both directions. When someone
#     new is held back, the parent gets a request to approve.
#   - Features: messaging, calls, following people, posting tips, uploading files.
#   - The parent sees every person the child talks to (counts, calls, last contact) and,
#     with the "Messages" access turned on, can read those conversations.
# Linked parents can always message and call their child. The child is notified when
# rules change and sees the reason whenever something is blocked.

CONTROL_DAYS = ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun')
CONTROL_FEATURES = ('messaging', 'calls', 'following', 'posting', 'uploads')
CONTACT_MODES = ('everyone', 'teachers', 'approved', 'nobody')
# Screen time (daily limits, quiet hours, extra time) is switched off: Eschool doesn't limit or count
# a child's time. Pause still works. Set True to bring screen time back (the saved rules are kept).
SCREEN_TIME_ENABLED = False
USAGE_GAP_SECONDS = 90          # a gap longer than this between requests is not counted as time on Eschool
FEATURE_TEXT = {'messaging': 'messaging', 'calls': 'calls', 'following': 'following people',
                'posting': 'posting tips', 'uploads': 'uploading files'}


def _controls_tables(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS parental_controls (
        student_id INTEGER PRIMARY KEY, data TEXT NOT NULL, updated_at TEXT, updated_by INTEGER)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS child_usage (
        student_id INTEGER NOT NULL, day TEXT NOT NULL, seconds INTEGER NOT NULL DEFAULT 0,
        last_seen TEXT, limit_alerted INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (student_id, day))''')
    conn.execute('''CREATE TABLE IF NOT EXISTS child_bonus (
        student_id INTEGER NOT NULL, day TEXT NOT NULL, minutes INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (student_id, day))''')
    conn.execute('''CREATE TABLE IF NOT EXISTS child_pause (
        student_id INTEGER PRIMARY KEY, until TEXT, message TEXT, parent_id INTEGER, created_at TEXT)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS contact_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL, other_id INTEGER NOT NULL,
        from_child INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending',
        note TEXT, created_at TEXT NOT NULL, decided_at TEXT, decided_by INTEGER)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS controls_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL, parent_id INTEGER,
        text TEXT NOT NULL, created_at TEXT NOT NULL)''')


def _default_controls():
    return {
        'screen_time': {'daily_limit_minutes': {d: 0 for d in CONTROL_DAYS},
                        'quiet_hours': {'enabled': False, 'start': '21:00', 'end': '06:00'}},
        'features': {f: True for f in CONTROL_FEATURES},
        'contacts': {'mode': 'everyone', 'allowed': [], 'blocked': []},
        'alerts': {'limit_reached': True, 'contact_requests': True},
    }


def _clean_controls(raw):
    c = _default_controls()
    raw = raw if isinstance(raw, dict) else {}
    st = raw.get('screen_time') or {}
    lim = st.get('daily_limit_minutes') or {}
    for d in CONTROL_DAYS:
        try:
            c['screen_time']['daily_limit_minutes'][d] = max(0, min(1440, int(lim.get(d) or 0)))
        except (TypeError, ValueError):
            pass
    q = st.get('quiet_hours') or {}
    c['screen_time']['quiet_hours']['enabled'] = bool(q.get('enabled'))
    for k in ('start', 'end'):
        if isinstance(q.get(k), str) and re.match(r'^([01]\d|2[0-3]):[0-5]\d$', q[k]):
            c['screen_time']['quiet_hours'][k] = q[k]
    feats = raw.get('features') or {}
    for f in CONTROL_FEATURES:
        if f in feats:
            c['features'][f] = bool(feats[f])
    ct = raw.get('contacts') or {}
    if ct.get('mode') in CONTACT_MODES:
        c['contacts']['mode'] = ct['mode']
    for k in ('allowed', 'blocked'):
        ids = []
        for v in (ct.get(k) or [])[:500]:
            try:
                ids.append(int(v['id'] if isinstance(v, dict) else v))
            except (TypeError, ValueError, KeyError):
                pass
        c['contacts'][k] = sorted(set(ids))
    al = raw.get('alerts') or {}
    for k in c['alerts']:
        if k in al:
            c['alerts'][k] = bool(al[k])
    return c


def _get_controls(conn, student_id):
    _controls_tables(conn)
    r = conn.execute('SELECT data FROM parental_controls WHERE student_id = ?', (student_id,)).fetchone()
    if not r:
        return None
    try:
        return _clean_controls(json.loads(r[0]))
    except ValueError:
        return None


def _child_parents(conn, student_id):
    try:
        return [r[0] for r in conn.execute("SELECT parent_id FROM parent_links WHERE student_id = ? AND status = 'active'",
                                           (student_id,)).fetchall()]
    except sqlite3.Error:
        return []


def _nairobi_dt():
    return datetime.now(timezone.utc) + timedelta(hours=3)


def _in_quiet_hours(q, now_local):
    if not q.get('enabled'):
        return False
    cur = now_local.strftime('%H:%M')
    s, e = q['start'], q['end']
    return (s <= cur < e) if s < e else (cur >= s or cur < e)


def _control_state(conn, student_id, controls=None):
    """What applies to the child right now: {blocked, reason, until, message, used_s, limit_min, bonus}."""
    controls = controls or _get_controls(conn, student_id)
    now_local = _nairobi_dt()
    day = now_local.strftime('%Y-%m-%d')
    used = conn.execute('SELECT seconds FROM child_usage WHERE student_id = ? AND day = ?', (student_id, day)).fetchone()
    used_s = used[0] if used else 0
    bonus = conn.execute('SELECT minutes FROM child_bonus WHERE student_id = ? AND day = ?', (student_id, day)).fetchone()
    bonus = bonus[0] if bonus else 0
    out = {'blocked': False, 'reason': None, 'until': None, 'message': '', 'used_s': used_s, 'limit_min': 0, 'bonus': bonus}
    p = conn.execute('SELECT until, message FROM child_pause WHERE student_id = ?', (student_id,)).fetchone()
    if p:
        until = _parse_iso(p[0]) if p[0] else None
        if until and until <= datetime.now(timezone.utc):
            conn.execute('DELETE FROM child_pause WHERE student_id = ?', (student_id,))
            conn.commit()
        else:
            out.update(blocked=True, reason='paused', until=p[0], message=p[1] or '')
            return out
    if not controls or not SCREEN_TIME_ENABLED:
        return out
    lim = controls['screen_time']['daily_limit_minutes'][CONTROL_DAYS[now_local.weekday()]]
    out['limit_min'] = lim
    if _in_quiet_hours(controls['screen_time']['quiet_hours'], now_local):
        out.update(blocked=True, reason='quiet', until=controls['screen_time']['quiet_hours']['end'])
        return out
    if lim and used_s >= (lim + bonus) * 60:
        out.update(blocked=True, reason='limit')
    return out


def parental_contact_check(conn, a_id, b_id, kind='message'):
    """(allowed, reason) for a message or call between a and b, from the parental
    controls of whichever of them is a controlled child. Creates an approval request
    when a new person is held back."""
    try:
        _controls_tables(conn)
        rows = conn.execute('SELECT id, role, firstname, lastname FROM users WHERE id IN (?, ?)', (a_id, b_id)).fetchall()
    except sqlite3.Error:
        return True, ''
    info = {r[0]: r for r in rows}
    for child, other in ((a_id, b_id), (b_id, a_id)):
        ch = info.get(child)
        if not ch or (ch[1] or 'student') != 'student':
            continue
        c = _get_controls(conn, child)
        state = _control_state(conn, child, c)
        if other in _child_parents(conn, child):
            continue    # parents can always reach their child
        try:            # ... and so can a teacher the parent hired (lessons happen in Eschool calls)
            if conn.execute("SELECT 1 FROM tutoring WHERE student_id = ? AND teacher_id = ? AND status = 'active' LIMIT 1",
                            (child, other)).fetchone():
                continue
        except sqlite3.Error:
            pass
        child_is_sender = child == a_id
        if state['blocked'] and child_is_sender:
            return False, 'Your parent has paused Eschool for now.'
        if not c:
            continue
        feat = 'calls' if kind == 'call' else 'messaging'
        if not c['features'][feat]:
            return False, (f"Your parent has turned off {FEATURE_TEXT[feat]}." if child_is_sender
                           else f"This learner can't receive {FEATURE_TEXT[feat]} right now.")
        ct = c['contacts']
        if other in ct['blocked']:
            return False, ("Your parent has blocked this person." if child_is_sender
                           else "You can't contact this learner.")
        o = info.get(other)
        mode = ct['mode']
        ok = (mode == 'everyone' or other in ct['allowed']
              or (mode == 'teachers' and o is not None and o[1] == 'teacher'))
        if mode == 'nobody' and other not in ct['allowed']:
            ok = False
        if ok:
            continue
        # held back: ask the parent (once per pair while waiting)
        if mode != 'nobody' and not conn.execute("SELECT 1 FROM contact_requests WHERE student_id = ? AND other_id = ? AND status = 'pending'",
                                                 (child, other)).fetchone():
            conn.execute('INSERT INTO contact_requests (student_id, other_id, from_child, created_at) VALUES (?, ?, ?, ?)',
                         (child, other, 1 if child_is_sender else 0, _iso(_utc_now())))
            cname = _full_name(ch[2], ch[3], 'Your child')
            oname = _full_name(o[2], o[3], 'Someone') if o else 'Someone'
            for pid in _child_parents(conn, child):
                if c['alerts'].get('contact_requests', True):
                    create_notification(conn, pid, 'Contact request',
                                        (f"{cname} wants to talk to {oname}." if child_is_sender else f"{oname} wants to talk to {cname}.")
                                        + ' Approve or decline it on Parental controls.', icon='fa-user-shield', color='#f59e0b')
            conn.commit()
        return False, ("Your parent needs to approve this person first. We've asked them." if child_is_sender
                       else "This learner can only talk to people their parent has approved.")
    return True, ''


def _feature_off(conn, uid, feature):
    """Reason text if a parent switched this feature off for the signed-in child, else None."""
    if session.get('role', 'student') != 'student':
        return None
    try:
        c = _get_controls(conn, uid)
    except sqlite3.Error:
        return None
    if c and not c['features'].get(feature, True):
        return f"Your parent has turned off {FEATURE_TEXT[feature]}."
    return None


CHILD_LOCK_PAGE = '''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta http-equiv="refresh" content="60"><title>Paused - Eschool</title>
<style>
 body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f1f5f9;font-family:Inter,"Segoe UI",sans-serif;color:#1e293b;padding:20px;box-sizing:border-box}
 .box{background:#fff;border-radius:20px;padding:36px 28px;max-width:440px;width:100%;text-align:center;box-shadow:0 10px 30px rgba(15,23,42,.08)}
 .ic{width:76px;height:76px;border-radius:50%;margin:0 auto 18px;display:flex;align-items:center;justify-content:center;background:#eef2ff;color:#4361ee;font-size:34px}
 h1{font-size:1.35rem;margin:0 0 10px} p{color:#64748b;line-height:1.6;margin:0 0 14px}
 .msg{background:#f8fafc;border-radius:12px;padding:12px 14px;color:#1e293b;font-style:italic}
 a{display:inline-block;margin-top:8px;color:#64748b;font-size:.9rem}
 @media (prefers-color-scheme: dark){body{background:#0f172a;color:#e5e7eb}.box{background:#111827}.msg{background:#1e293b;color:#e5e7eb}p{color:#94a3b8}}
</style></head><body><main class="box">
 <div class="ic" aria-hidden="true">{{ icon }}</div>
 <h1>{{ title }}</h1>
 <p>{{ text }}</p>
 {% if message %}<p class="msg">"{{ message }}"</p>{% endif %}
 <p style="font-size:.85rem;">This page checks again every minute. Your work and progress are saved.</p>
 <a href="/logout">Log out</a>
</main></body></html>'''

LOCK_FREE_PATHS = ('/logout', '/api/whoami', '/eschool-calls.js', '/Login', '/login')


@app.before_request
def _apply_parental_controls():
    """Counts the child's time on Eschool and applies pause, quiet hours and daily limits."""
    uid = session.get('user_id')
    if not uid or session.get('role', 'student') != 'student' or request.endpoint in (None, 'static'):
        return None
    if request.path.startswith(LOCK_FREE_PATHS) or request.path.startswith('/uploads/'):
        return None
    conn = sqlite3.connect('users.db', timeout=10)
    try:
        try:
            linked = conn.execute("SELECT 1 FROM parent_links WHERE student_id = ? AND status = 'active' LIMIT 1", (uid,)).fetchone()
        except sqlite3.OperationalError:
            linked = None          # no parent has linked to anyone yet (table not created yet)
        if not linked:
            return None
        _controls_tables(conn)
        controls = _get_controls(conn, uid)
        state = _control_state(conn, uid, controls)
        if not state['blocked'] and not SCREEN_TIME_ENABLED:
            return None             # nothing to count when screen time is off
        if not state['blocked']:
            # count time: the gap since the last request, if it was short (the page was open)
            now = datetime.now(timezone.utc)
            day = _nairobi_dt().strftime('%Y-%m-%d')
            row = conn.execute('SELECT seconds, last_seen, limit_alerted FROM child_usage WHERE student_id = ? AND day = ?', (uid, day)).fetchone()
            last = _parse_iso(row[1]) if row and row[1] else None
            add = int((now - last).total_seconds()) if last else 0
            add = add if 0 < add <= USAGE_GAP_SECONDS else 0
            if row:
                conn.execute('UPDATE child_usage SET seconds = seconds + ?, last_seen = ? WHERE student_id = ? AND day = ?', (add, _iso(now), uid, day))
            else:
                conn.execute('INSERT INTO child_usage (student_id, day, seconds, last_seen) VALUES (?, ?, 0, ?)', (uid, day, _iso(now)))
            seconds = (row[0] if row else 0) + add
            lim = state['limit_min']
            if lim and seconds >= (lim + state['bonus']) * 60 and not (row and row[2]):
                conn.execute('UPDATE child_usage SET limit_alerted = 1 WHERE student_id = ? AND day = ?', (uid, day))
                name = _full_name(session.get('firstname'), session.get('lastname'), 'Your child')
                if controls and controls['alerts'].get('limit_reached', True):
                    for pid in _child_parents(conn, uid):
                        create_notification(conn, pid, 'Daily limit reached', f"{name} has used today's {lim} minutes on Eschool.",
                                            icon='fa-hourglass-end', color='#f59e0b')
                create_notification(conn, uid, 'Time is up for today', f"You've used your {lim} minutes on Eschool today. See you tomorrow!",
                                    icon='fa-hourglass-end', color='#f59e0b')
            conn.commit()
            return None
        # blocked: pages show the lock screen; messaging and calls are refused
        wants_page = request.method == 'GET' and not request.path.startswith('/api/') \
            and 'text/html' in (request.headers.get('Accept') or '') \
            and request.path not in ('/notifications',) and not request.path.startswith('/messages/')
        blocked_api = request.path.startswith(('/messages/send', '/api/calls/start'))
        if not (wants_page or blocked_api):
            return None
        if state['reason'] == 'paused':
            until = _parse_iso(state['until']) if state['until'] else None
            title, icon = 'Your parent has paused Eschool', '⏸'
            text = ('It opens again at ' + _when_for(session.get('user_id'), until, '%H:%M on %a %d %b') + '.') if until else 'It opens again when your parent turns it back on.'
        elif state['reason'] == 'quiet':
            title, icon = 'Quiet hours', '\U0001F319'
            text = f"Your parent set quiet hours. Eschool opens again at {state['until']}."
        else:
            title, icon = "That's all for today", '⌛'
            text = f"You've used today's {state['limit_min'] + state['bonus']} minutes. Eschool opens again tomorrow."
        if blocked_api:
            return jsonify({'success': False, 'message': f'{title}. {text}'}), 423
        return render_template_string(CHILD_LOCK_PAGE, title=title, text=text, icon=icon, message=state['message']), 423
    finally:
        conn.close()


def _parent_child_or_404(conn, child_id):
    if not _is_linked_parent(conn, session['user_id'], child_id):
        return None
    return conn.execute('SELECT id, firstname, lastname, avatar_filename FROM users WHERE id = ?', (child_id,)).fetchone()


def _log_control(conn, child_id, text):
    conn.execute('INSERT INTO controls_log (student_id, parent_id, text, created_at) VALUES (?, ?, ?, ?)',
                 (child_id, session.get('user_id'), text[:300], _iso(_utc_now())))


def _usage_week(conn, child_id):
    today = _nairobi_dt()
    out = []
    for i in range(6, -1, -1):
        d = (today - timedelta(days=i)).strftime('%Y-%m-%d')
        r = conn.execute('SELECT seconds FROM child_usage WHERE student_id = ? AND day = ?', (child_id, d)).fetchone()
        out.append({'date': d, 'seconds': r[0] if r else 0})
    return out


@app.route('/api/parent/children/<int:child_id>/controls', methods=['GET', 'PUT'])
def api_child_controls(child_id):
    guard = _parent_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _controls_tables(conn)
        ch = _parent_child_or_404(conn, child_id)
        if not ch:
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        current = _get_controls(conn, child_id) or _default_controls()
        if request.method == 'PUT':
            new = _clean_controls((request.get_json(silent=True) or {}).get('controls'))
            q = new['screen_time']['quiet_hours']
            if q['enabled'] and q['start'] == q['end']:
                return jsonify({'success': False, 'message': "Quiet hours can't start and end at the same time."}), 400
            changes = []
            if new['screen_time'] != current['screen_time']:
                changes.append('screen time')
            if new['features'] != current['features']:
                off = [FEATURE_TEXT[f] for f in CONTROL_FEATURES if not new['features'][f]]
                changes.append('features' + (f" (off: {', '.join(off)})" if off else ''))
            if new['contacts'] != current['contacts']:
                changes.append('who you can talk to')
            conn.execute('''INSERT INTO parental_controls (student_id, data, updated_at, updated_by) VALUES (?, ?, ?, ?)
                            ON CONFLICT(student_id) DO UPDATE SET data = excluded.data, updated_at = excluded.updated_at,
                            updated_by = excluded.updated_by''', (child_id, json.dumps(new), _iso(_utc_now()), session['user_id']))
            if changes:
                _log_control(conn, child_id, 'Changed ' + ', '.join(changes))
                create_notification(conn, child_id, 'Your parent updated your Eschool rules',
                                    'Changed: ' + ', '.join(changes) + '.', icon='fa-user-shield', color='#4361ee')
            conn.commit()
            current = new
        state = _control_state(conn, child_id, current)
        names = {r[0]: (_full_name(r[1], r[2], 'User'), r[3] or 'student') for r in conn.execute(
            f"SELECT id, firstname, lastname, role FROM users WHERE id IN ({','.join('?' for _ in (current['contacts']['allowed'] + current['contacts']['blocked'] + [-1]))})",
            current['contacts']['allowed'] + current['contacts']['blocked'] + [-1]).fetchall()}
        pending = conn.execute("SELECT COUNT(*) FROM contact_requests WHERE student_id = ? AND status = 'pending'", (child_id,)).fetchone()[0]
        _access_tables(conn)
        link = conn.execute("SELECT id, permissions, perm_requests FROM parent_links WHERE parent_id = ? AND student_id = ? AND status = 'active'",
                            (session['user_id'], child_id)).fetchone()
        try:
            perms = _clean_permissions(json.loads(link['permissions'] or '{}'))
        except ValueError:
            perms = _clean_permissions({})
        out = dict(current)
        out['contacts'] = dict(current['contacts'])
        for k in ('allowed', 'blocked'):
            out['contacts'][k] = [{'id': i, 'name': names.get(i, ('User', ''))[0], 'role': names.get(i, ('', 'student'))[1]} for i in current['contacts'][k]]
        p = conn.execute('SELECT until, message, created_at FROM child_pause WHERE student_id = ?', (child_id,)).fetchone()
        return jsonify({
            'controls': out, 'link_id': link['id'], 'permissions': perms, 'pending': _perm_requests(link['perm_requests']), 'screen_time': SCREEN_TIME_ENABLED,
            'usage': {'today_seconds': state['used_s'], 'limit_minutes': state['limit_min'], 'bonus_minutes': state['bonus'],
                      'week': _usage_week(conn, child_id)},
            'state': {'blocked': state['blocked'], 'reason': state['reason'], 'until': state['until']},
            'pause': {'active': state['reason'] == 'paused', 'until': p['until'] if p and state['reason'] == 'paused' else None,
                      'message': p['message'] if p and state['reason'] == 'paused' else ''},
            'pending_requests': pending,
        })
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/pause', methods=['POST', 'DELETE'])
def api_child_pause(child_id):
    guard = _parent_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _controls_tables(conn)
        if not _parent_child_or_404(conn, child_id):
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        if request.method == 'DELETE':
            conn.execute('DELETE FROM child_pause WHERE student_id = ?', (child_id,))
            _log_control(conn, child_id, 'Resumed access')
            create_notification(conn, child_id, 'Eschool is open again', 'Your parent ended the pause.', icon='fa-play', color='green')
            conn.commit()
            return jsonify({'success': True, 'pause': {'active': False}})
        d = request.get_json(silent=True) or {}
        msg = str(d.get('message') or '').strip()[:140]
        until = None
        if d.get('until_tomorrow'):
            nxt = (_nairobi_dt() + timedelta(days=1)).replace(hour=6, minute=0, second=0, microsecond=0)
            until = _iso(nxt - timedelta(hours=3))
        elif d.get('minutes'):
            try:
                mins = max(5, min(1440, int(d['minutes'])))
            except (TypeError, ValueError):
                return jsonify({'success': False, 'message': 'Choose how long.'}), 400
            until = _iso(_utc_now() + timedelta(minutes=mins))
        conn.execute('''INSERT INTO child_pause (student_id, until, message, parent_id, created_at) VALUES (?, ?, ?, ?, ?)
                        ON CONFLICT(student_id) DO UPDATE SET until = excluded.until, message = excluded.message,
                        parent_id = excluded.parent_id, created_at = excluded.created_at''',
                     (child_id, until, msg or None, session['user_id'], _iso(_utc_now())))
        when = _when_for(child_id, _parse_iso(until), '%H:%M %a') if until else 'until your parent turns it back on'
        _log_control(conn, child_id, f'Paused access ({when})')
        create_notification(conn, child_id, 'Eschool is paused', f"Your parent paused Eschool ({when})." + (f' "{msg}"' if msg else ''),
                            icon='fa-circle-pause', color='red')
        conn.commit()
        return jsonify({'success': True, 'pause': {'active': True, 'until': until, 'message': msg}})
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/bonus-time', methods=['POST'])
def api_child_bonus(child_id):
    guard = _parent_guard()
    if guard:
        return guard
    if not SCREEN_TIME_ENABLED:
        return jsonify({'success': False, 'message': 'Screen time is switched off on Eschool.'}), 410
    try:
        minutes = int((request.get_json(silent=True) or {}).get('minutes'))
    except (TypeError, ValueError):
        minutes = 0
    if minutes not in (15, 30, 60, 120):
        return jsonify({'success': False, 'message': 'Choose 15, 30, 60 or 120 minutes.'}), 400
    conn = _links_db()
    try:
        _controls_tables(conn)
        if not _parent_child_or_404(conn, child_id):
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        day = _nairobi_dt().strftime('%Y-%m-%d')
        conn.execute('''INSERT INTO child_bonus (student_id, day, minutes) VALUES (?, ?, ?)
                        ON CONFLICT(student_id, day) DO UPDATE SET minutes = minutes + excluded.minutes''', (child_id, day, minutes))
        conn.execute('UPDATE child_usage SET limit_alerted = 0 WHERE student_id = ? AND day = ?', (child_id, day))
        _log_control(conn, child_id, f'Added {minutes} minutes for today')
        create_notification(conn, child_id, 'Extra time', f'Your parent gave you {minutes} more minutes today.', icon='fa-hourglass-half', color='green')
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/contacts')
def api_child_contacts(child_id):
    """Everyone the child has messaged, called or followed, with counts."""
    guard = _parent_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _controls_tables(conn)
        if not _parent_child_or_404(conn, child_id):
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        parents = set(_child_parents(conn, child_id))
        ppl = {}

        def person(oid):
            return ppl.setdefault(oid, {'id': oid, 'sent': 0, 'received': 0, 'last_message_at': None, 'first_contact': None,
                                        'calls': 0, 'call_minutes': 0, 'last_call_at': None, 'child_follows': False})
        for r in conn.execute('''SELECT CASE WHEN sender_id = ? THEN receiver_id ELSE sender_id END AS other,
                                        SUM(CASE WHEN sender_id = ? THEN 1 ELSE 0 END), SUM(CASE WHEN receiver_id = ? THEN 1 ELSE 0 END),
                                        MAX(timestamp), MIN(timestamp)
                                 FROM messages WHERE (sender_id = ? OR receiver_id = ?) AND COALESCE(is_broadcast, 0) = 0
                                 GROUP BY other''', (child_id, child_id, child_id, child_id, child_id)).fetchall():
            p = person(r[0]); p.update(sent=r[1] or 0, received=r[2] or 0, last_message_at=to_iso_utc(r[3]), first_contact=to_iso_utc(r[4]))
        try:
            for r in conn.execute('''SELECT CASE WHEN caller_id = ? THEN callee_id ELSE caller_id END AS other, created_at, answered_at, ended_at
                                     FROM calls WHERE caller_id = ? OR callee_id = ?''', (child_id, child_id, child_id)).fetchall():
                p = person(r[0]); p['calls'] += 1
                st, en = _parse_any(r[2]), _parse_any(r[3])
                if st and en and en > st:
                    p['call_minutes'] += int((en - st).total_seconds() // 60)
                ca = to_iso_utc(r[1])
                p['last_call_at'] = max(p['last_call_at'] or '', ca or '') or None
        except sqlite3.OperationalError:
            pass
        for r in conn.execute('SELECT following_id FROM follows WHERE follower_id = ?', (child_id,)).fetchall():
            person(r[0])['child_follows'] = True
        for pid in parents:
            ppl.pop(pid, None)
        ppl.pop(child_id, None)
        ids = list(ppl) or [-1]
        users = {r[0]: r for r in conn.execute(f"SELECT id, firstname, lastname, role, avatar_filename FROM users WHERE id IN ({','.join('?' for _ in ids)})", ids).fetchall()}
        c = _get_controls(conn, child_id) or _default_controls()
        week_ago = _iso(_utc_now() - timedelta(days=7)).replace('T', ' ').rstrip('Z')
        out = []
        for oid, p in ppl.items():
            u = users.get(oid)
            if not u:
                continue
            recent = conn.execute('''SELECT COUNT(*) FROM messages WHERE ((sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?)) AND timestamp >= ?''',
                                  (child_id, oid, oid, child_id, week_ago)).fetchone()[0]
            p.update(name=_full_name(u[1], u[2], 'User'), role=u[3] or 'student', avatar_url=get_avatar_url(oid, u[4]) if u[4] else None,
                     messages_week=recent,
                     status='blocked' if oid in c['contacts']['blocked'] else 'approved' if oid in c['contacts']['allowed'] else 'allowed')
            p['last_contact_at'] = max(p['last_message_at'] or '', p['last_call_at'] or '') or None
            out.append(p)
        out.sort(key=lambda x: x['last_contact_at'] or '', reverse=True)
        return jsonify({'contacts': out})
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/contacts/<int:other_id>/messages')
def api_child_conversation(child_id, other_id):
    """The conversation between the child and one person. Needs the 'messages' access."""
