@app.route('/api/parent/contact-requests/<int:req_id>', methods=['POST'])
def api_contact_request_decision(req_id):
    """{"decision": "approve" | "deny", "note": "..."}"""
    guard = _parent_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    if d.get('decision') not in ('approve', 'deny'):
        return jsonify({'success': False, 'message': 'decision must be approve or deny'}), 400
    note = str(d.get('note') or '').strip()[:200] or None
    conn = _links_db()
    try:
        _controls_tables(conn)
        r = conn.execute("SELECT * FROM contact_requests WHERE id = ? AND status = 'pending'", (req_id,)).fetchone()
        if not r or not _is_linked_parent(conn, session['user_id'], r['student_id']):
            return jsonify({'success': False, 'message': 'This request was already answered.'}), 404
        c = _get_controls(conn, r['student_id']) or _default_controls()
        other = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (r['other_id'],)).fetchone()
        name = _full_name(other['firstname'], other['lastname'], 'this person') if other else 'this person'
        if d['decision'] == 'approve':
            c['contacts']['allowed'] = sorted(set(c['contacts']['allowed']) | {r['other_id']})
            c['contacts']['blocked'] = [i for i in c['contacts']['blocked'] if i != r['other_id']]
            conn.execute('''INSERT INTO parental_controls (student_id, data, updated_at, updated_by) VALUES (?, ?, ?, ?)
                            ON CONFLICT(student_id) DO UPDATE SET data = excluded.data, updated_at = excluded.updated_at, updated_by = excluded.updated_by''',
                         (r['student_id'], json.dumps(c), _iso(_utc_now()), session['user_id']))
            create_notification(conn, r['student_id'], 'Contact approved', f'You can now talk to {name}.' + (f' "{note}"' if note else ''),
                                icon='fa-user-check', color='green')
        else:
            create_notification(conn, r['student_id'], 'Contact not approved', f"Your parent didn't approve talking to {name}." + (f' "{note}"' if note else ''),
                                icon='fa-user-slash', color='red')
        conn.execute('UPDATE contact_requests SET status = ?, note = ?, decided_at = ?, decided_by = ? WHERE id = ?',
                     ('approved' if d['decision'] == 'approve' else 'denied', note, _iso(_utc_now()), session['user_id'], req_id))
        _log_control(conn, r['student_id'], f"{'Approved' if d['decision'] == 'approve' else 'Declined'} contact with {name}")
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/parent/children/<int:child_id>/people')
def api_child_people_search(child_id):
    """Find a teacher or learner to approve or block ahead of time. ?q="""
