@app.route('/api/parent/children/<int:child_id>/activity')
def api_child_activity(child_id):
    """A timeline from what Eschool records: learning, messages, calls, follows, posts, uploads, rules."""
    guard = _parent_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _controls_tables(conn)
        _ep_table(conn)
        if not _parent_child_or_404(conn, child_id):
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        since = _utc_now() - timedelta(days=30)
        since_iso, since_sql = _iso(since), since.strftime('%Y-%m-%d %H:%M:%S')
        items = []
        for e in conn.execute('SELECT kind, ref, ep, day, created_at FROM ep_events WHERE user_id = ? AND day IS NOT NULL AND created_at >= ? ORDER BY id DESC LIMIT 150',
                              (child_id, since.isoformat())).fetchall():
            text, sub = _ep_event_label(e)
            items.append({'category': 'learning', 'icon': 'fa-graduation-cap', 'text': f"{text}" + (f" · {sub}" if sub else '') + f" (+{e['ep']} EP)", 'at': e['created_at']})
        names = {}

        def nm(uid):
            if uid not in names:
                u = conn.execute('SELECT firstname, lastname, role FROM users WHERE id = ?', (uid,)).fetchone()
                names[uid] = (_full_name(u[0], u[1], 'Someone') + (' (teacher)' if u and u[2] == 'teacher' else ' (parent)' if u and u[2] == 'parent' else '')) if u else 'Someone'
            return names[uid]
        for r in conn.execute('''SELECT DATE(timestamp) AS d, CASE WHEN sender_id = ? THEN receiver_id ELSE sender_id END AS other,
                                        SUM(CASE WHEN sender_id = ? THEN 1 ELSE 0 END), SUM(CASE WHEN receiver_id = ? THEN 1 ELSE 0 END), MAX(timestamp)
                                 FROM messages WHERE (sender_id = ? OR receiver_id = ?) AND COALESCE(is_broadcast, 0) = 0 AND timestamp >= ?
                                 GROUP BY d, other ORDER BY MAX(timestamp) DESC LIMIT 150''',
                              (child_id, child_id, child_id, child_id, child_id, since_sql)).fetchall():
            parts = []
            if r[2]:
                parts.append(f"sent {r[2]}")
            if r[3]:
                parts.append(f"received {r[3]}")
            items.append({'category': 'social', 'icon': 'fa-comments', 'text': f"Messages with {nm(r[1])}: " + ' and '.join(parts), 'at': to_iso_utc(r[4]), 'other_id': r[1]})
        try:
            for r in conn.execute('SELECT caller_id, callee_id, kind, created_at, answered_at, ended_at FROM calls WHERE (caller_id = ? OR callee_id = ?) AND created_at >= ? ORDER BY id DESC LIMIT 60',
                                  (child_id, child_id, since_sql)).fetchall():
                other = r[1] if r[0] == child_id else r[0]
                st, en = _parse_any(r[4]), _parse_any(r[5])
                mins = int((en - st).total_seconds() // 60) if st and en and en > st else None
                way = 'Called' if r[0] == child_id else 'Got a call from'
                items.append({'category': 'social', 'icon': 'fa-video' if r[2] == 'video' else 'fa-phone',
                              'text': f"{way} {nm(other)} ({r[2]})" + (f", {mins} min" if mins is not None else ', not answered'), 'at': to_iso_utc(r[3])})
        except sqlite3.OperationalError:
            pass
        for r in conn.execute('SELECT following_id, created_at FROM follows WHERE follower_id = ? AND created_at >= ?', (child_id, since_sql)).fetchall():
            items.append({'category': 'social', 'icon': 'fa-user-plus', 'text': f"Started following {nm(r[0])}", 'at': to_iso_utc(r[1])})
        for r in conn.execute('SELECT text, created_at FROM opinions WHERE user_id = ? AND created_at >= ?', (child_id, since_sql)).fetchall():
            items.append({'category': 'posts', 'icon': 'fa-lightbulb', 'text': 'Posted a study tip: "' + (r[0] or '')[:90] + '"', 'at': to_iso_utc(r[1])})
        for r in conn.execute('SELECT title, upload_date FROM resources WHERE user_id = ? AND upload_date >= ?', (child_id, since_sql)).fetchall():
            items.append({'category': 'posts', 'icon': 'fa-cloud-arrow-up', 'text': f'Uploaded "{r[0]}"', 'at': to_iso_utc(r[1])})
        for r in conn.execute('''SELECT rs.title, rv.created_at FROM resource_views rv JOIN resources rs ON rs.id = rv.resource_id
                                 WHERE rv.user_id = ? AND rv.created_at >= ? ORDER BY rv.id DESC LIMIT 60''', (child_id, since_sql)).fetchall():
            items.append({'category': 'learning', 'icon': 'fa-book-open', 'text': f'Opened "{r[0]}"', 'at': to_iso_utc(r[1])})
        for r in conn.execute('''SELECT l.text, l.created_at, u.firstname, u.lastname FROM controls_log l LEFT JOIN users u ON u.id = l.parent_id
                                 WHERE l.student_id = ? AND l.created_at >= ? ORDER BY l.id DESC LIMIT 60''', (child_id, since_iso)).fetchall():
            items.append({'category': 'rules', 'icon': 'fa-user-shield', 'text': f"{_full_name(r[2], r[3], 'A parent')}: {r[0]}", 'at': r[1]})
        for r in conn.execute('''SELECT r.from_child, r.status, r.created_at, u.firstname, u.lastname FROM contact_requests r
                                 LEFT JOIN users u ON u.id = r.other_id WHERE r.student_id = ? AND r.created_at >= ?''', (child_id, since_iso)).fetchall():
            who = _full_name(r[3], r[4], 'someone')
            items.append({'category': 'rules', 'icon': 'fa-hand', 'text': (f"Tried to contact {who}" if r[0] else f"{who} tried to make contact") + f" (request {r[1]})", 'at': r[2]})

        def key(i):
            d = _parse_any(i['at'])
            return d.isoformat() if d else ''
        items.sort(key=key, reverse=True)
        for i in items:
            d = _parse_any(i['at'])
            i['at'] = _iso(d) if d else None
        return jsonify({'activity': items[:300]})
    finally:
        conn.close()


# ============ STUDENT PROGRESS SUMMARY (so linked parents can see it) ============
# Grades, GPA, course progress and streaks are worked out in the student's own
# browser. The student's dashboard sends a small summary here whenever it
# changes, and the parent's "My Children" page reads it.

def _progress_summary_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS student_progress_summary (
            student_id INTEGER PRIMARY KEY,
            gpa REAL,
            overall_grade TEXT,
            avg_progress INTEGER,
            courses TEXT,
            modules_completed INTEGER,
            assessments INTEGER,
            quiz_streak INTEGER,
            module_streak INTEGER,
            updated_at TEXT,
            FOREIGN KEY (student_id) REFERENCES users (id)
        )
    ''')
    # columns added for the learner profile (achievements + leaderboard)
    for col in ('quizzes_passed INTEGER', 'courses_completed INTEGER',
                'best_quiz_streak INTEGER', 'best_module_streak INTEGER',
                'quiz_last_date TEXT', 'module_last_date TEXT', 'active_days INTEGER',
                'score_grades TEXT'):   # Progress page Grades: overall grade + total score (JSON)
        try:
            conn.execute(f'ALTER TABLE student_progress_summary ADD COLUMN {col}')
        except sqlite3.OperationalError:
            pass   # already there


def _pretty_level(level):
    """'grade-10' -> 'Grade 10'"""
    return level.replace('-', ' ').replace('_', ' ').strip().title()


def _nice_date(iso):
    if not iso:
        return None
    try:
        return datetime.strptime(iso[:10], '%Y-%m-%d').strftime('%b %d, %Y')
    except ValueError:
        return None


def _time_ago(iso):
    try:
        then = datetime.strptime(iso, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except (TypeError, ValueError):
        return None
    secs = max(0, int((_utc_now() - then).total_seconds()))
    if secs < 120:
        return 'just now'
    if secs < 3600:
        return f'{secs // 60} minutes ago'
    if secs < 86400:
        hours = secs // 3600
        return f"{hours} hour{'s' if hours != 1 else ''} ago"
    days = secs // 86400
    return 'yesterday' if days == 1 else f'{days} days ago'


def _num(value, lo, hi, cast=float):
    """A number clamped to [lo, hi], or None if it isn't a number."""
    try:
        v = cast(value)
    except (TypeError, ValueError):
        return None
    if v != v:   # NaN
        return None
    return max(lo, min(hi, v))


@app.route('/api/student/progress-summary', methods=['POST'])
def student_progress_summary():
    guard = _student_guard()
    if guard:
        return guard

    data = request.get_json(silent=True) or {}
    courses = []
    for c in (data.get('courses') or [])[:20]:
        if not isinstance(c, dict):
            continue
        courses.append({
            'id': str(c.get('id') or '')[:30],
            'name': str(c.get('name') or '')[:80],
            'level': str(c.get('level') or '')[:30],
            'progress': _num(c.get('progress'), 0, 100, int) or 0
        })

    gpa = _num(data.get('gpa'), 0.0, 4.0)
    grade = str(data.get('overall_grade') or '')[:3] or None
    if grade not in {'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D+', 'D', 'F'}:
        grade, gpa = None, None   # "N/A" = no graded work yet

    conn = _links_db()
    try:
        _progress_summary_table(conn)
        def day(v):
            v = str(v or '')[:10]
            return v if re.match(r'^\d{4}-\d{2}-\d{2}$', v) else None

        values = {
            'gpa': gpa, 'overall_grade': grade,
            'avg_progress': _num(data.get('avg_progress'), 0, 100, int),
            'courses': json.dumps(courses),
            'modules_completed': _num(data.get('modules_completed'), 0, 10000, int) or 0,
            'assessments': _num(data.get('assessments'), 0, 10000, int) or 0,
            'quiz_streak': _num(data.get('quiz_streak'), 0, 10000, int) or 0,
            'module_streak': _num(data.get('module_streak'), 0, 10000, int) or 0,
            'quizzes_passed': _num(data.get('quizzes_passed'), 0, 10000, int) or 0,
            'courses_completed': _num(data.get('courses_completed'), 0, 1000, int) or 0,
            'best_quiz_streak': _num(data.get('best_quiz_streak'), 0, 10000, int) or 0,
            'best_module_streak': _num(data.get('best_module_streak'), 0, 10000, int) or 0,
            'quiz_last_date': day(data.get('quiz_last_date')),
            'module_last_date': day(data.get('module_last_date')),
            'active_days': _num(data.get('active_days'), 0, 100000, int) or 0,
            'updated_at': _iso(_utc_now()),
        }
        cols = list(values)
        conn.execute(
            f"INSERT INTO student_progress_summary (student_id, {', '.join(cols)}) "
            f"VALUES (?, {', '.join('?' for _ in cols)}) "
            f"ON CONFLICT(student_id) DO UPDATE SET "
            + ', '.join(f'{c} = excluded.{c}' for c in cols),
            [session['user_id']] + [values[c] for c in cols]
        )
        _rebuild_progress_summary(conn, session['user_id'])   # merge in what the server recorded (scores, streaks)
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()

# ============ LIVE PROGRESS (server-side, no waiting for the child's dashboard) ============
# The summary above used to be written only by the child's dashboard, so a
# parent saw nothing until the child opened it. Now the server keeps it up to
# date itself from what it already records:
#   - every module test, quiz, Daily Quiz Test and finished course (ep_events)
#   - the full course state the Courses/Progress pages send to /api/ep/sync
# _rebuild_progress_summary() runs after every /api/ep/sync and whenever a
# parent page finds a child's summary older than their latest work.
# The child's dashboard can still send its own summary; the values merge.

GRADE_POINTS = ((90, 'A', 4.0), (85, 'A-', 3.7), (80, 'B+', 3.3), (75, 'B', 3.0), (70, 'B-', 2.7), (65, 'C+', 2.3),
                (60, 'C', 2.0), (55, 'C-', 1.7), (50, 'D+', 1.3), (40, 'D', 1.0), (0, 'F', 0.0))
SCORE_MODULE_WEIGHT, SCORE_QUIZ_WEIGHT = 0.3, 0.7     # same weights as the Progress page


def _grade_for_pct(pct):
    for cut, letter, gp in GRADE_POINTS:
        if pct >= cut:
            return letter, gp
    return 'F', 0.0


def _letter_for_gpa(gpa):
    """Same cut-offs as the learner dashboard's overall grade."""
    for cut, letter in ((3.7, 'A'), (3.3, 'A-'), (3.0, 'B'), (2.7, 'B-'), (2.3, 'C+'), (2.0, 'C'),
                        (1.7, 'C-'), (1.3, 'D+'), (1.0, 'D')):
        if gpa >= cut:
            return letter
    return 'F'


def _day_streak(days):
    """(length, last_day) of the run of consecutive days ending at the most recent day."""
    ds = sorted({d for d in days if d}, reverse=True)
    if not ds:
        return 0, None
    run, prev = 1, datetime.strptime(ds[0], '%Y-%m-%d')
    for d in ds[1:]:
        cur = datetime.strptime(d, '%Y-%m-%d')
        if (prev - cur).days == 1:
            run, prev = run + 1, cur
        else:
            break
    return run, ds[0]


def _server_progress(conn, sid):
    """Everything the server can say about a learner's progress from ep_events."""
    _ep_table(conn)
    rows = conn.execute('SELECT kind, ref, ep, day, pct, created_at FROM ep_events WHERE user_id = ?', (sid,)).fetchall()
    courses = {}
    for key, total in EP_COURSE_MODULES.items():
        courses[key] = {'id': key, 'name': EP_COURSE_NAMES.get(key, key), 'total': total, 'passed': 0, 'finished': False,
                        'module_pcts': [], 'quiz_pcts': [], 'quizzes': 0, 'last_day': None}
    daily_pcts, quiz_days, module_days, all_days = [], [], [], set()
    quizzes = assessments = 0
    last_at = None
    for r in rows:
        course, _, rest = (r['ref'] or '').partition(':')
        c = courses.get(course) if r['kind'] in ('module', 'quiz') else courses.get(r['ref']) if r['kind'] == 'course' else None
        if r['day']:
            all_days.add(r['day'])
        if r['created_at'] and (last_at is None or r['created_at'] > last_at):
            last_at = r['created_at']
        if r['kind'] == 'module' and c:
            c['passed'] += 1
            if r['pct'] is not None:
                c['module_pcts'].append(r['pct'])
                assessments += 1
            module_days.append(r['day'])
        elif r['kind'] == 'quiz' and c:
            c['quizzes'] += 1
            quizzes += 1
            assessments += 1
            if r['pct'] is not None:
                c['quiz_pcts'].append(r['pct'])
            quiz_days.append(r['day'])
        elif r['kind'] == 'daily_quiz':
            quizzes += 1
            assessments += 1
            if r['pct'] is not None:
                daily_pcts.append(r['pct'])
            quiz_days.append(r['day'])
        elif r['kind'] == 'course' and c:
            c['finished'] = True
        if c and r['day'] and (c['last_day'] is None or r['day'] > c['last_day']):
            c['last_day'] = r['day']

    subjects = []   # (name, score) used for GPA, like the Progress page
    for c in courses.values():
        m = sum(c['module_pcts']) / len(c['module_pcts']) if c['module_pcts'] else None
        q = sum(c['quiz_pcts']) / len(c['quiz_pcts']) if c['quiz_pcts'] else None
        score = (m * SCORE_MODULE_WEIGHT + q * SCORE_QUIZ_WEIGHT) if (m is not None and q is not None) else (m if m is not None else q)
        c['score'] = round(score) if score is not None else None
        c['progress'] = 100 if c['finished'] else min(99, round(c['passed'] / c['total'] * 100)) if c['total'] else 0
        c['started'] = bool(c['passed'] or c['quizzes'] or c['finished'])
        if c['score'] is not None:
            subjects.append((c['name'], c['score']))
    if daily_pcts:
        subjects.append(('Daily Quiz Test', round(sum(daily_pcts) / len(daily_pcts))))
    gpa = round(sum(_grade_for_pct(s)[1] for _, s in subjects) / len(subjects), 2) if subjects else None
    qs, q_last = _day_streak(quiz_days)
    ms, m_last = _day_streak(module_days)
    return {
        'courses': courses, 'subjects': subjects, 'gpa': gpa,
        # the letter comes from the average score, exactly like the learner's Progress page (not from GPA)
        'grade': _grade_for_pct(round(sum(s for _, s in subjects) / len(subjects)))[0] if subjects else None,
        'avg_score': round(sum(s for _, s in subjects) / len(subjects)) if subjects else None,
        'quizzes': quizzes, 'assessments': assessments, 'active_days': len(all_days),
        'quiz_streak': qs, 'quiz_last': q_last, 'module_streak': ms, 'module_last': m_last,
        'has_events': bool(rows), 'last_at': last_at,
    }


_GRADE_LETTERS = {'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D+', 'D', 'F', 'N/A'}


def _progress_page_grade(conn, sid):
    """The learner's grade exactly as their Progress page (Grades tab) shows it:
    {'letter', 'percent', 'total', 'possible', 'subjects'}, or None when there are no grades yet.
    The page sends its numbers with every sync; if the learner did more work since, the same
    sum is done here from the server's record of that work."""
    try:
        row = conn.execute('SELECT score_grades FROM student_progress_summary WHERE student_id = ?', (sid,)).fetchone()
        g = json.loads(row[0] or 'null') or {} if row else {}
    except (TypeError, ValueError, sqlite3.Error):
        g = {}
    fresh = bool(g) and g.get('subjects', 0) > 0 and g.get('grade') not in (None, 'N/A') and g.get('percent') is not None
    if fresh and g.get('at'):
        try:
            last_ep = conn.execute('SELECT MAX(created_at) FROM ep_events WHERE user_id = ?', (sid,)).fetchone()[0]
        except sqlite3.Error:
            last_ep = None
        ga, la = _parse_any(g.get('at')), _parse_any(last_ep) if last_ep else None
        if ga and la and la > ga + timedelta(seconds=30):
            fresh = False
    if fresh:
        return {'letter': g['grade'], 'percent': int(g['percent']), 'total': g.get('total'),
                'possible': g.get('possible') or g['subjects'] * 100, 'subjects': g['subjects']}
    sp = _server_progress(conn, sid)
    if not sp['subjects']:
        return None
    total = sum(sc for _, sc in sp['subjects'])
    return {'letter': sp['grade'], 'percent': sp['avg_score'], 'total': total,
            'possible': len(sp['subjects']) * 100, 'subjects': len(sp['subjects'])}


def _progress_page_course_grades(conn, sid):
    """{course id: {'percent', 'letter'}}: each course's grade as the child's Progress page shows it (Grades tab),
    or worked out here the same way when the page's numbers are older than their latest work."""
    try:
        row = conn.execute('SELECT score_grades FROM student_progress_summary WHERE student_id = ?', (sid,)).fetchone()
        g = (json.loads(row[0] or 'null') or {}) if row else {}
    except (TypeError, ValueError, sqlite3.Error):
        g = {}
    fresh = bool(g) and isinstance(g.get('courses'), dict)
    if fresh and g.get('at'):
        try:
            last_ep = conn.execute('SELECT MAX(created_at) FROM ep_events WHERE user_id = ?', (sid,)).fetchone()[0]
        except sqlite3.Error:
            last_ep = None
        ga, la = _parse_any(g.get('at')), _parse_any(last_ep) if last_ep else None
        if ga and la and la > ga + timedelta(seconds=30):
            fresh = False
    out = {}
    if fresh:
        for cid, c in g['courses'].items():
            if isinstance(c, dict) and isinstance(c.get('avg'), (int, float)):
                out[cid] = {'percent': int(round(c['avg'])), 'letter': _grade_for_pct(round(c['avg']))[0]}
        return out
    for cid in EP_COURSE_MODULES:
        v = _course_score_from_events(conn, sid, cid)
        if v is not None:
            out[cid] = {'percent': v, 'letter': _grade_for_pct(v)[0]}
    return out


def _grade_band(pct):
    """Colour band for a score: same cut-offs as the grade letters (A/A- excellent, B good, C average, below the pass mark poor)."""
    if pct is None:
        return ''
    return 'excellent' if pct >= 85 else 'good' if pct >= 70 else 'average' if pct >= 60 else 'poor'


def _save_score_grades(conn, sid, g):
    """Keeps the Overall grade and Total score exactly as the learner's Progress page
    (Grades tab) works them out, so the profile shows the same numbers. Those come from
    every test and quiz attempt kept on the learner's device, which the server doesn't
    have, so the page sends its result with each /api/ep/sync."""
    if not isinstance(g, dict):
        return
    def num(v, hi):
        return int(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and 0 <= v <= hi else None
    grade = g.get('grade') if g.get('grade') in _GRADE_LETTERS else None
    subjects = num(g.get('subjects'), 50)
    if grade is None or subjects is None:
        return
    percent = num(g.get('percent'), 100)
    if percent is not None:      # the letter always matches the percentage (same scale as the Progress page)
        grade = next(l for cut, l in ((90, 'A'), (85, 'A-'), (80, 'B+'), (75, 'B'), (70, 'B-'), (65, 'C+'), (60, 'C'),
                                      (55, 'C-'), (50, 'D+'), (40, 'D'), (0, 'F')) if percent >= cut) if grade != 'N/A' else grade
    total = num(g.get('total'), subjects * 100)
    clean = {'grade': grade, 'percent': percent, 'total': total,
             'possible': subjects * 100, 'subjects': subjects, 'graded': num(g.get('graded'), 50),
             'at': _iso(_utc_now())}
    # each course's score from every attempt, passed or not (the Career page uses it)
    per = {}
    for c in (g.get('courses') if isinstance(g.get('courses'), list) else [])[:50]:
        if isinstance(c, dict) and c.get('id') in EP_COURSE_MODULES:
            avg, tests, quizzes = num(c.get('avg'), 100), num(c.get('tests'), 1000), num(c.get('quizzes'), 5000)
            if avg is not None:
                per[c['id']] = {'avg': avg, 'tests': tests or 0, 'quizzes': quizzes or 0}
    clean['courses'] = per
    _progress_summary_table(conn)
    conn.execute('INSERT OR IGNORE INTO student_progress_summary (student_id, updated_at) VALUES (?, ?)', (sid, clean['at']))
    conn.execute('UPDATE student_progress_summary SET score_grades = ? WHERE student_id = ?', (json.dumps(clean), sid))


def _rebuild_progress_summary(conn, sid, sync_courses=None, streaks=None):
    """Brings student_progress_summary up to date from server data (and, after
    /api/ep/sync, the course state the learner's browser just sent)."""
    _progress_summary_table(conn)
    sp = _server_progress(conn, sid)
    old = conn.execute('SELECT ' + SUMMARY_COLS + ' FROM student_progress_summary WHERE student_id = ?', (sid,)).fetchone()
    old = dict(old) if old else {}
    if not sp['has_events'] and not sync_courses and not old:
        return False
    sync = {}
    for c in (sync_courses or []):
        if isinstance(c, dict) and str(c.get('id') or '') in EP_COURSE_MODULES:
            done = c.get('completed') if isinstance(c.get('completed'), list) else []
            n = len({i for i in done if isinstance(i, int) and not isinstance(i, bool)
                     and 0 <= i < EP_COURSE_MODULES[str(c['id'])]})
            sync[str(c['id'])] = {'done': n, 'finished': bool(c.get('finished')) and n >= EP_COURSE_MODULES[str(c['id'])]}

    by_id = {}
    for c in _jlist_dicts(old.get('courses')):
        cid = str(c.get('id') or '')
        if cid:
            by_id[cid] = dict(c)
    for cid, sc in sp['courses'].items():
        if not (sc['started'] or cid in sync or cid in by_id):
            continue
        c = by_id.setdefault(cid, {'id': cid, 'name': sc['name'], 'level': 'grade-10', 'progress': 0})
        if cid in sync:   # the browser just told us exactly where the learner is
            s = sync[cid]
            c['progress'] = 100 if s['finished'] else min(99, round(s['done'] / sc['total'] * 100))
        else:
            c['progress'] = max(int(c.get('progress') or 0), sc['progress'])
        c['name'] = c.get('name') or sc['name']
        c['level'] = c.get('level') or 'grade-10'
    courses = list(by_id.values())
    progresses = [int(c.get('progress') or 0) for c in courses]
    if sync:
        modules = sum(s['done'] for s in sync.values())
    else:
        modules = max(int(old.get('modules_completed') or 0), sum(c['passed'] for c in sp['courses'].values()))

    today = _nairobi_today()
    q_streak, q_last = sp['quiz_streak'], sp['quiz_last']
    m_streak, m_last = sp['module_streak'], sp['module_last']
    if isinstance(streaks, dict):   # the Courses page knows the exact live streaks
        if isinstance(streaks.get('quiz'), int) and streaks['quiz'] >= 0:
            q_streak = streaks['quiz']
            q_last = today if q_streak else q_last
        if isinstance(streaks.get('module'), int) and streaks['module'] >= 0:
            m_streak = streaks['module']
            m_last = today if m_streak else m_last
    elif old.get('quiz_last_date') and (not q_last or old['quiz_last_date'] > q_last):
        q_streak, q_last = old.get('quiz_streak') or 0, old['quiz_last_date']
    if not isinstance(streaks, dict) and old.get('module_last_date') and (not m_last or old['module_last_date'] > m_last):
        m_streak, m_last = old.get('module_streak') or 0, old['module_last_date']

    # GPA from test scores the server recorded (same method as the Progress page:
    # 30% module tests + 70% course quizzes per course, Daily Quiz Test on its own)
    gpa, grade = old.get('gpa'), old.get('overall_grade')
    if sp['gpa'] is not None:
        gpa, grade = sp['gpa'], sp['grade']
    values = {
        'gpa': gpa, 'overall_grade': grade,
        'avg_progress': round(sum(progresses) / len(progresses)) if progresses else 0,
        'courses': json.dumps(courses),
        'modules_completed': modules,
        'assessments': max(int(old.get('assessments') or 0), sp['assessments']),
        'quiz_streak': q_streak, 'module_streak': m_streak,
        'quizzes_passed': max(int(old.get('quizzes_passed') or 0), sp['quizzes']),
        'courses_completed': sum(1 for p in progresses if p >= 100),
        'best_quiz_streak': max(int(old.get('best_quiz_streak') or 0), q_streak),
        'best_module_streak': max(int(old.get('best_module_streak') or 0), m_streak),
        'quiz_last_date': q_last, 'module_last_date': m_last,
        'active_days': max(int(old.get('active_days') or 0), sp['active_days']),
        'updated_at': _iso(_utc_now()),
    }
    cols = list(values)
    conn.execute(f"INSERT INTO student_progress_summary (student_id, {', '.join(cols)}) VALUES (?, {', '.join('?' for _ in cols)}) "
                 "ON CONFLICT(student_id) DO UPDATE SET " + ', '.join(f'{c} = excluded.{c}' for c in cols),
                 [sid] + [values[c] for c in cols])
    return True


def _refresh_learner_progress(conn, sid):
    """Rebuilds one learner's summary if it is missing or older than their latest recorded work."""
    _progress_summary_table(conn)
    _ep_table(conn)
    r = conn.execute('''SELECT (SELECT updated_at FROM student_progress_summary WHERE student_id = ?) AS upd,
                               (SELECT MAX(created_at) FROM ep_events WHERE user_id = ?) AS last_ep''', (sid, sid)).fetchone()
    if not r or not r['last_ep']:
        return False
    upd = _parse_any(r['upd']) if r['upd'] else None
    last = _parse_any(r['last_ep'])
    if upd is None or (last and last > upd):
        if _rebuild_progress_summary(conn, sid):
            conn.commit()
            return True
    return False


def _refresh_children_progress(conn, parent_id):
    """Rebuilds each linked child's summary if it is missing or older than their latest work."""
    _progress_summary_table(conn)
    _ep_table(conn)
    rows = conn.execute('''SELECT pl.student_id, ps.updated_at,
                                  (SELECT MAX(created_at) FROM ep_events e WHERE e.user_id = pl.student_id) AS last_ep
                           FROM parent_links pl LEFT JOIN student_progress_summary ps ON ps.student_id = pl.student_id
                           WHERE pl.parent_id = ? AND pl.status = 'active' ''', (parent_id,)).fetchall()
    changed = False
    for r in rows:
        if not r['last_ep']:
            continue
        upd = _parse_iso(r['updated_at']) if r['updated_at'] else None
        try:
            last = datetime.fromisoformat(str(r['last_ep']).replace('Z', '+00:00'))
            last = last if last.tzinfo else last.replace(tzinfo=timezone.utc)
        except ValueError:
            last = None
        if upd is None or (last and last > upd):
            changed = _rebuild_progress_summary(conn, r['student_id']) or changed
    conn.commit()   # always: an open write here made every other connection wait 10 s (slow parent pages)


