@app.route('/api/parent/quick-contacts')
def api_parent_quick_contacts():
    """People a parent most often needs to message: their linked children, the
    teachers those children follow, and teachers hired on the Teachers page."""
    guard = _parent_guard()
    if guard:
        return guard
    pid = session['user_id']
    conn = _links_db()
    try:
        kids = conn.execute('''SELECT u.id, u.firstname, u.lastname, u.avatar_filename FROM parent_links pl
                               JOIN users u ON u.id = pl.student_id WHERE pl.parent_id = ? AND pl.status = 'active'
                               ORDER BY u.firstname''', (pid,)).fetchall()
        out, seen = [], set()
        for k in kids:
            seen.add(k['id'])
            out.append({'id': k['id'], 'name': _full_name(k['firstname'], k['lastname'], 'Child'), 'group': 'child',
                        'note': 'Your child', 'avatar_url': get_avatar_url(k['id'], k['avatar_filename']) if k['avatar_filename'] else None})
        teachers = {}
        kid_names = {k['id']: (k['firstname'] or '').strip() or 'your child' for k in kids}
        try:
            _tutor_tables(conn)
            for r in conn.execute('''SELECT t.teacher_id, t.student_id, t.subject FROM tutoring t
                                     WHERE t.parent_id = ? AND t.status IN ('accepted', 'active', 'ended') ORDER BY t.id DESC''', (pid,)).fetchall():
                teachers.setdefault(r['teacher_id'], f"Teaches {kid_names.get(r['student_id'], 'your child')} {r['subject']}")
        except sqlite3.Error:
            pass
        for k in kids:
            for r in conn.execute('''SELECT u.id FROM follows f JOIN users u ON u.id = f.following_id
                                     WHERE f.follower_id = ? AND u.role = 'teacher' ''', (k['id'],)).fetchall():
                teachers.setdefault(r['id'], f"{kid_names[k['id']]}'s teacher")
        for tid, note in teachers.items():
            if tid in seen:
                continue
            u = conn.execute('SELECT firstname, lastname, avatar_filename FROM users WHERE id = ?', (tid,)).fetchone()
            if u:
                out.append({'id': tid, 'name': _full_name(u['firstname'], u['lastname'], 'Teacher'), 'group': 'teacher', 'note': note,
                            'avatar_url': get_avatar_url(tid, u['avatar_filename']) if u['avatar_filename'] else None})
        return jsonify({'contacts': out})
    finally:
        conn.close()

# ============ PARENT: GOALS & REWARDS ============
# A parent sets a goal for a linked child ("Pass 5 quizzes by Sunday") and a
# reward for reaching it. Progress is measured by the server from what the
# child actually does on Eschool (ep_events, child_usage, the quiz streak and
# the monthly leaderboard), so the child can't tick a goal off by hand.
#   active   -> achieved (target reached before the end date)  -> rewarded (parent gave the reward)
#   active   -> missed   (end date passed first)
#   active   -> cancelled (parent removed it)
# The reward is something the parent gives themselves (e.g. "Movie night").

GOAL_TYPES = {
    'points':      {'label': 'Earn Eschool Points', 'unit': 'EP', 'min': 10, 'max': 5000, 'default': 100,
                    'icon': 'fa-star', 'course': 'none',
                    'help': 'EP the child earns from module tests, quizzes, finished courses and streak bonuses.'},
    'quizzes':     {'label': 'Pass quizzes', 'unit': 'quizzes', 'min': 1, 'max': 100, 'default': 5,
                    'icon': 'fa-clipboard-check', 'course': 'none',
                    'help': 'Course quizzes and the Daily Quiz Test both count.'},
    'modules':     {'label': 'Pass module tests', 'unit': 'module tests', 'min': 1, 'max': 100, 'default': 3,
                    'icon': 'fa-layer-group', 'course': 'optional',
                    'help': 'Each module test passed (60% or more). Pick a course or leave it open.'},
    'course':      {'label': 'Finish a course', 'unit': 'modules', 'min': 1, 'max': 100, 'default': 0,
                    'icon': 'fa-flag-checkered', 'course': 'required',
                    'help': 'Done when every module in the course is passed.'},
    'active_days': {'label': 'Learn on different days', 'unit': 'days', 'min': 1, 'max': 60, 'default': 5,
                    'icon': 'fa-calendar-check', 'course': 'none',
                    'help': 'A day counts when the child passes at least one module test or quiz.'},
    'study_time':  {'label': 'Time learning on Eschool', 'unit': 'hours', 'min': 1, 'max': 200, 'default': 5,
                    'icon': 'fa-clock', 'course': 'none',
                    'help': 'Time the child spends with Eschool open (the same count as Screen time).'},
    'quiz_streak': {'label': 'Reach a quiz streak', 'unit': 'days in a row', 'min': 2, 'max': 365, 'default': 7,
                    'icon': 'fa-fire', 'course': 'none',
                    'help': 'Days in a row with a quiz passed. Done the moment the streak reaches the target.'},
    'rank':        {'label': 'Monthly leaderboard place', 'unit': 'place', 'min': 1, 'max': 100, 'default': 10,
                    'icon': 'fa-ranking-star', 'course': 'none',
                    'help': 'Done when the child is at this place or higher on this month\'s leaderboard.'},
    'score':       {'label': 'Average test score', 'unit': '%', 'min': 40, 'max': 100, 'default': 75,
                    'icon': 'fa-bullseye', 'course': 'optional',
                    'help': 'Average of the module tests passed in the goal period. Needs at least 3 tests.'},
}
GOAL_SCORE_MIN_TESTS = 3
GOAL_MAX_ACTIVE = 10            # active goals per child
GOAL_MAX_DAYS = 120             # longest goal period
GOAL_REWARD_IDEAS = ['Movie night', 'Favourite meal', 'Pocket money', 'A day out', 'New book',
                     'Airtime', 'Stay up 30 min later', 'Pick the weekend activity']
GOAL_TICK_SECONDS = 45          # how often a learner's own visits re-check their goals
_GOAL_LAST_TICK = {}
import time as _time
REL_LABEL = {'mother': 'Mum', 'father': 'Dad', 'grandparent': 'Grandparent', 'guardian': 'Your guardian'}


def _goals_table(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS child_goals (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id INTEGER NOT NULL,
        parent_id INTEGER NOT NULL,
        type TEXT NOT NULL,
        target INTEGER NOT NULL,
        course TEXT,
        start_day TEXT NOT NULL,          -- Nairobi dates, inclusive
        due_day TEXT NOT NULL,
        reward TEXT,
        bonus_points INTEGER NOT NULL DEFAULT 0,
        bonus_minutes INTEGER NOT NULL DEFAULT 0,
        note TEXT,
        status TEXT NOT NULL DEFAULT 'active',
        value REAL NOT NULL DEFAULT 0,
        pct INTEGER NOT NULL DEFAULT 0,
        progress_text TEXT,
        near_alerted INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL,
        checked_at TEXT,
        achieved_at TEXT,
        missed_at TEXT,
        cancelled_at TEXT,
        rewarded_at TEXT,
        rewarded_by INTEGER,
        reward_message TEXT,
        retry_of INTEGER)''')
    conn.execute('CREATE INDEX IF NOT EXISTS idx_child_goals_student ON child_goals (student_id, status)')
    _goal_detail_columns(conn)


def _goal_course_name(course):
    return EP_COURSE_NAMES.get(course or '', course or '')


def _goal_title(gtype, target, course):
    cname = _goal_course_name(course)
    if gtype == 'points':
        return f'Earn {target} EP'
    if gtype == 'quizzes':
        return f"Pass {target} quiz{'zes' if target != 1 else ''}"
    if gtype == 'modules':
        return f"Pass {target} {cname + ' ' if cname else ''}module test{'s' if target != 1 else ''}"
    if gtype == 'course':
        return f'Finish {cname}'
    if gtype == 'active_days':
        return f"Learn on {target} different day{'s' if target != 1 else ''}"
    if gtype == 'study_time':
        return f"Spend {target} hour{'s' if target != 1 else ''} learning on Eschool"
    if gtype == 'quiz_streak':
        return f'Reach a {target}-day quiz streak'
    if gtype == 'rank':
        return 'Reach 1st on the monthly leaderboard' if target == 1 else f'Reach the monthly top {target}'
    if gtype == 'score':
        return f"Average {target}% or more in {cname + ' ' if cname else ''}module tests"
    return 'Goal'


def _goal_child_rank(conn, child_id):
    """(rank, total, ep_month) on this month's leaderboard; rank None if not ranked."""
    try:
        hidden = set(_users_with_privacy(conn, 'show_on_leaderboard', 0)) - {child_id}
        ranked = _ranked_learners(conn, exclude_ids=hidden)
    except sqlite3.Error:
        return None, 0, 0
    for t in ranked:
        if t[1] == child_id:
            return t[0], len(ranked), t[5]['ep_month']
    return None, len(ranked), 0


def _goal_measure(conn, g):
    """(value, pct 0-100, done, text) for a goal, from the child's real activity."""
    gtype, target, sid = g['type'], g['target'], g['student_id']
    a, b, course = g['start_day'], g['due_day'], g['course']
    in_window = 'user_id = ? AND day IS NOT NULL AND day >= ? AND day <= ?'
    args = [sid, a, b]

    def count_pct(v):
        return min(100, round(v / target * 100)) if target else 0

    if gtype == 'points':
        v = conn.execute(f'SELECT COALESCE(SUM(ep), 0) FROM ep_events WHERE {in_window}', args).fetchone()[0]
        return v, count_pct(v), v >= target, f'{v} of {target} EP'
    if gtype == 'quizzes':
        v = conn.execute(f"SELECT COUNT(*) FROM ep_events WHERE {in_window} AND kind IN ('quiz', 'daily_quiz')", args).fetchone()[0]
        return v, count_pct(v), v >= target, f'{v} of {target} quizzes passed'
    if gtype == 'modules':
        sql = f"SELECT COUNT(*) FROM ep_events WHERE {in_window} AND kind = 'module'"
        if course:
            sql += ' AND ref LIKE ?'
            args = args + [course + ':%']
        v = conn.execute(sql, args).fetchone()[0]
        return v, count_pct(v), v >= target, f'{v} of {target} module tests passed'
    if gtype == 'course':
        total = EP_COURSE_MODULES.get(course, target)
        done = conn.execute("SELECT 1 FROM ep_events WHERE user_id = ? AND kind = 'course' AND ref = ?", (sid, course)).fetchone()
        v = conn.execute("SELECT COUNT(*) FROM ep_events WHERE user_id = ? AND kind = 'module' AND ref LIKE ?",
                         (sid, course + ':%')).fetchone()[0]
        v = min(v, total)
        finished = bool(done) or v >= total
        return v, 100 if finished else min(99, round(v / total * 100)), finished, f'{v} of {total} modules passed'
    if gtype == 'active_days':
        v = conn.execute(f'SELECT COUNT(DISTINCT day) FROM ep_events WHERE {in_window}', args).fetchone()[0]
        return v, count_pct(v), v >= target, f"{v} of {target} day{'s' if target != 1 else ''}"
    if gtype == 'study_time':
        _controls_tables(conn)
        secs = conn.execute('SELECT COALESCE(SUM(seconds), 0) FROM child_usage WHERE student_id = ? AND day >= ? AND day <= ?',
                            (sid, a, b)).fetchone()[0]
        hours = round(secs / 3600, 1)
        mins = secs // 60
        shown = f'{mins // 60} h {mins % 60} min' if mins >= 60 else f'{mins} min'
        return hours, min(100, round(secs / (target * 3600) * 100)), secs >= target * 3600, f'{shown} of {target} h'
    if gtype == 'quiz_streak':
        _progress_summary_table(conn)
        row = conn.execute('SELECT quiz_streak, quiz_last_date FROM student_progress_summary WHERE student_id = ?', (sid,)).fetchone()
        v = _live_streak(row['quiz_streak'], row['quiz_last_date']) if row else 0
        return v, count_pct(v), v >= target, f"{v}-day streak now (target {target})"
    if gtype == 'rank':
        rank, total, ep_month = _goal_child_rank(conn, sid)
        if rank is None:
            return 0, 0, False, 'Not on the leaderboard yet'
        done = rank <= target and ep_month > 0
        pct = 100 if done else (0 if not ep_month else min(99, round(target / rank * 100)))
        return rank, pct, done, f'#{rank} of {total} this month' + ('' if ep_month else ' (no EP yet this month)')
    if gtype == 'score':
        sql = f"SELECT COUNT(*), AVG(pct) FROM ep_events WHERE {in_window} AND kind = 'module' AND pct IS NOT NULL"
        if course:
            sql += ' AND ref LIKE ?'
            args = args + [course + ':%']
        n, avg = conn.execute(sql, args).fetchone()
        avg = round(avg or 0)
        if n == 0:
            return 0, 0, False, f'No tests yet (needs {GOAL_SCORE_MIN_TESTS})'
        done = n >= GOAL_SCORE_MIN_TESTS and avg >= target
        if done:
            pct = 100
        elif n < GOAL_SCORE_MIN_TESTS:
            pct = round(n / GOAL_SCORE_MIN_TESTS * 60)
        else:
            pct = min(99, round(avg / target * 100))
        need = '' if n >= GOAL_SCORE_MIN_TESTS else f', needs {GOAL_SCORE_MIN_TESTS}'
        return avg, pct, done, f"{avg}% average over {n} test{'s' if n != 1 else ''}{need}"
    return 0, 0, False, ''


def _goal_value_text(gtype, value):
    if gtype == 'rank':
        return f'#{int(value)}' if value else '-'
    if gtype == 'score':
        return f'{int(value)}%'
    if gtype == 'study_time':
        return f'{value:g} h'
    return str(int(value))


def _goal_setter_label(conn, goal_parent_id, student_id):
    """What the child calls the parent who set a goal: Mum, Dad, or their first name."""
    r = conn.execute('''SELECT pl.relationship, u.firstname FROM users u
                        LEFT JOIN parent_links pl ON pl.parent_id = u.id AND pl.student_id = ?
                        WHERE u.id = ?''', (student_id, goal_parent_id)).fetchone()
    if not r:
        return 'Your parent'
    return REL_LABEL.get((r['relationship'] or '').lower()) or (r['firstname'] or '').strip() or 'Your parent'


def _goal_notify_parents(conn, student_id, title, message, icon='fa-bullseye', color='#8b5cf6'):
    for pid in _child_parents(conn, student_id):
        create_notification(conn, pid, title, message, icon=icon, color=color, category='goals')


def _goals_refresh(conn, student_id, notify=True):
    """Re-measures a child's active goals; marks them achieved or missed and sends the notices."""
    _goals_table(conn)
    _ep_table(conn)
    today = _nairobi_today()
    tomorrow = (datetime.strptime(today, '%Y-%m-%d') + timedelta(days=1)).strftime('%Y-%m-%d')
    rows = conn.execute("SELECT * FROM child_goals WHERE student_id = ? AND status = 'active'", (student_id,)).fetchall()
    if not rows:
        return
    child = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (student_id,)).fetchone()
    first = ((child['firstname'] if child else '') or '').strip() or 'Your child'
    now = _iso(_utc_now())
    for g in rows:
        value, pct, done, text = _goal_measure(conn, g)
        title = _goal_title(g['type'], g['target'], g['course'])
        own = g['parent_id'] == g['student_id']     # a goal the learner set for themselves
        if own and g['milestones']:
            _check_milestones(conn, g, 100 if done else pct, today, notify)
        if done and own:
            conn.execute("""UPDATE child_goals SET status = 'achieved', value = ?, pct = 100, progress_text = ?,
                            achieved_at = ?, checked_at = ? WHERE id = ?""", (value, text, now, now, g['id']))
            if notify:
                reward = (g['reward'] or '').strip()
                create_notification(conn, student_id, 'You reached your goal!',
                                    f'"{title}" is done ({text}).' + (f' Time for your reward: {reward}.' if reward else ' Well done!'),
                                    icon='fa-trophy', color='#10b981')
        elif today > g['due_day'] and own:
            conn.execute("""UPDATE child_goals SET status = 'missed', value = ?, pct = ?, progress_text = ?,
                            missed_at = ?, checked_at = ? WHERE id = ?""", (value, pct, text, now, now, g['id']))
            if notify:
                create_notification(conn, student_id, 'Goal ended',
                                    f'Your goal "{title}" ended with {text} ({pct}% of the way). See My goals for what to try next.',
                                    icon='fa-flag', color='#f59e0b')
        elif done:
            conn.execute("""UPDATE child_goals SET status = 'achieved', value = ?, pct = 100, progress_text = ?,
                            achieved_at = ?, checked_at = ? WHERE id = ?""", (value, text, now, now, g['id']))
            if notify:
                reward = (g['reward'] or '').strip()
                _goal_notify_parents(conn, student_id, f'{first} reached a goal',
                                     f'"{title}" is done ({text}).' + (f' Reward: {reward}. Mark it given on Goals & rewards.' if reward else ''),
                                     icon='fa-trophy', color='#10b981')
                who = _goal_setter_label(conn, g['parent_id'], student_id)
                create_notification(conn, student_id, 'Goal complete!',
                                    f'You reached "{title}".' + (f' {who} will give you your reward: {reward}.' if reward else ' Well done!'),
                                    icon='fa-trophy', color='#10b981')
        elif today > g['due_day']:
            conn.execute("""UPDATE child_goals SET status = 'missed', value = ?, pct = ?, progress_text = ?,
                            missed_at = ?, checked_at = ? WHERE id = ?""", (value, pct, text, now, now, g['id']))
            if notify:
                _goal_notify_parents(conn, student_id, f'{first} missed a goal',
                                     f'"{title}" ended with {text}. You can try it again with a new date.',
                                     icon='fa-flag', color='#f59e0b')
                create_notification(conn, student_id, 'Goal ended',
                                    f'"{title}" ended with {text}. Keep going, you were {pct}% of the way there.',
                                    icon='fa-flag', color='#f59e0b')
        else:
            near = 0
            if notify and not g['near_alerted'] and g['due_day'] in (today, tomorrow):
                when = 'today' if g['due_day'] == today else 'tomorrow'
                create_notification(conn, student_id, 'Goal ends ' + when,
                                    f'"{title}": {text}. It ends {when}.' + (f" Reward: {g['reward']}." if g['reward'] else ''),
                                    icon='fa-hourglass-half', color='#f59e0b')
                near = 1
            conn.execute('''UPDATE child_goals SET value = ?, pct = ?, progress_text = ?, checked_at = ?,
                            near_alerted = MAX(near_alerted, ?) WHERE id = ?''', (value, pct, text, now, near, g['id']))
    conn.commit()


def _goal_json(conn, g, viewer_id=None, names=None):
    t = GOAL_TYPES.get(g['type'], {})
    today = _nairobi_today()
    try:
        days_left = (datetime.strptime(g['due_day'], '%Y-%m-%d') - datetime.strptime(today, '%Y-%m-%d')).days
    except ValueError:
        days_left = 0
    names = names if names is not None else {}
    if g['parent_id'] not in names:
        r = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (g['parent_id'],)).fetchone()
        names[g['parent_id']] = _full_name(r['firstname'], r['lastname'], 'A parent') if r else 'A parent'
    rewarded_by = None
    if g['rewarded_by']:
        if g['rewarded_by'] not in names:
            r = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (g['rewarded_by'],)).fetchone()
            names[g['rewarded_by']] = _full_name(r['firstname'], r['lastname'], 'A parent') if r else 'A parent'
        rewarded_by = names[g['rewarded_by']]
    target = g['target']
    if g['type'] == 'course':
        target = EP_COURSE_MODULES.get(g['course'], target)
    return {
        'id': g['id'], 'child_id': g['student_id'], 'type': g['type'], 'type_label': t.get('label', g['type']),
        'icon': t.get('icon', 'fa-bullseye'), 'unit': t.get('unit', ''), 'target': target,
        'course': g['course'], 'course_name': _goal_course_name(g['course']) or None,
        'title': _goal_title(g['type'], g['target'], g['course']),
        'start_day': g['start_day'], 'due_day': g['due_day'], 'days_left': days_left,
        'days_total': max(1, (datetime.strptime(g['due_day'], '%Y-%m-%d') - datetime.strptime(g['start_day'], '%Y-%m-%d')).days + 1),
        'status': g['status'], 'value': g['value'], 'value_text': _goal_value_text(g['type'], g['value']),
        'pct': g['pct'], 'progress_text': g['progress_text'] or '',
        'reward': g['reward'] or '', 'bonus_points': g['bonus_points'] or 0, 'bonus_minutes': g['bonus_minutes'] or 0,
        'note': g['note'] or '', 'reward_message': g['reward_message'] or '',
        'created_at': g['created_at'], 'achieved_at': g['achieved_at'], 'missed_at': g['missed_at'],
        'cancelled_at': g['cancelled_at'], 'rewarded_at': g['rewarded_at'], 'rewarded_by': rewarded_by,
        'checked_at': g['checked_at'], 'retry_of': g['retry_of'],
        'set_by': {'id': g['parent_id'], 'name': names[g['parent_id']], 'you': viewer_id == g['parent_id']},
    }


def _goal_stats(goals):
    by = {}
    for g in goals:
        by[g['status']] = by.get(g['status'], 0) + 1
    reached = by.get('achieved', 0) + by.get('rewarded', 0)
    finished = reached + by.get('missed', 0)
    best = None
    per_type = {}
    for g in goals:
        if g['status'] in ('achieved', 'rewarded', 'missed'):
            d = per_type.setdefault(g['type'], [0, 0])
            d[1] += 1
            d[0] += g['status'] != 'missed'
    ranked = sorted(((v[0] / v[1], v[1], k) for k, v in per_type.items() if v[1] >= 2), reverse=True)
    if ranked:
        best = {'type': ranked[0][2], 'label': GOAL_TYPES[ranked[0][2]]['label'], 'rate': round(ranked[0][0] * 100), 'count': ranked[0][1]}
    return {
        'active': by.get('active', 0), 'waiting': by.get('achieved', 0), 'rewarded': by.get('rewarded', 0),
        'reached': reached, 'missed': by.get('missed', 0), 'cancelled': by.get('cancelled', 0),
        'hit_rate': round(reached / finished * 100) if finished else None, 'finished': finished,
        'best_type': best,
    }


def _goal_end_of_week(today=None):
    """Sunday of this week; if fewer than 2 days are left, Sunday of next week."""
    d = datetime.strptime(today or _nairobi_today(), '%Y-%m-%d')
    sunday = d + timedelta(days=6 - d.weekday())
    if (sunday - d).days < 2:
        sunday += timedelta(days=7)
    return sunday.strftime('%Y-%m-%d')


def _goal_suggestions(conn, child_id, first):
    """A few goals worth setting, each with the real numbers behind it."""
    _ep_table(conn)
    _progress_summary_table(conn)
    today = _nairobi_today()
    d_today = datetime.strptime(today, '%Y-%m-%d')
    week_end = _goal_end_of_week(today)
    out = []

    # 1. the course with the lowest share of modules passed (started, not finished)
    best = None
    for course, total in EP_COURSE_MODULES.items():
        n = conn.execute("SELECT COUNT(*) FROM ep_events WHERE user_id = ? AND kind = 'module' AND ref LIKE ?",
                         (child_id, course + ':%')).fetchone()[0]
        finished = conn.execute("SELECT 1 FROM ep_events WHERE user_id = ? AND kind = 'course' AND ref = ?", (child_id, course)).fetchone()
        if n and not finished and n < total and (best is None or n / total < best[1] / best[2]):
            best = (course, n, total)
    if best:
        course, n, total = best
        target = min(3, total - n)
        out.append({'type': 'modules', 'target': target, 'course': course, 'due': week_end,
                    'title': _goal_title('modules', target, course),
                    'why': f'{first} has passed {n} of {total} {EP_COURSE_NAMES[course]} modules ({round(n / total * 100)}%), the least of the courses started.'})

    # 2. quiz streak
    row = conn.execute('SELECT quiz_streak, quiz_last_date FROM student_progress_summary WHERE student_id = ?', (child_id,)).fetchone()
    streak = _live_streak(row['quiz_streak'], row['quiz_last_date']) if row else 0
    target = max(3, streak + 3)
    if target <= 30:
        out.append({'type': 'quiz_streak', 'target': target, 'course': None,
                    'due': (d_today + timedelta(days=target + 1)).strftime('%Y-%m-%d'),
                    'title': _goal_title('quiz_streak', target, None),
                    'why': f"{first}'s quiz streak is {streak} day{'s' if streak != 1 else ''} right now."})

    # 3. EP this week vs the last 4 weeks
    four_weeks_ago = (datetime.strptime(_week_start(), '%Y-%m-%d') - timedelta(days=28)).strftime('%Y-%m-%d')
    past = conn.execute('SELECT COALESCE(SUM(ep), 0) FROM ep_events WHERE user_id = ? AND day >= ? AND day < ?',
                        (child_id, four_weeks_ago, _week_start())).fetchone()[0]
    avg = past / 4
    target = max(50, int(round(avg * 1.2 / 10.0)) * 10)
    out.append({'type': 'points', 'target': target, 'course': None, 'due': week_end,
                'title': _goal_title('points', target, None),
                'why': (f'{first} averaged {round(avg)} EP a week over the last 4 weeks; this is about 20% more.'
                        if avg * 1.2 >= 50 else
                        f'{first} averaged {round(avg)} EP a week over the last 4 weeks; 50 EP is about 5 module tests.')})

    # 4. average score in the last 30 days
    n, avg_pct = conn.execute("""SELECT COUNT(*), AVG(pct) FROM ep_events WHERE user_id = ? AND kind = 'module'
                                 AND pct IS NOT NULL AND day >= ?""",
                              (child_id, (d_today - timedelta(days=30)).strftime('%Y-%m-%d'))).fetchone()
    if n and n >= 3 and avg_pct is not None and avg_pct < 90:
        target = min(100, int(-(-(avg_pct + 5) // 5) * 5))
        out.append({'type': 'score', 'target': target, 'course': None,
                    'due': (d_today + timedelta(days=13)).strftime('%Y-%m-%d'),
                    'title': _goal_title('score', target, None),
                    'why': f'{first} averaged {round(avg_pct)}% over {n} module tests in the last 30 days.'})

    # 5. active days in the last 7
    days = conn.execute('SELECT COUNT(DISTINCT day) FROM ep_events WHERE user_id = ? AND day >= ?',
                        (child_id, (d_today - timedelta(days=6)).strftime('%Y-%m-%d'))).fetchone()[0]
    if days < 6:
        target = min(6, days + 2)
        out.append({'type': 'active_days', 'target': target, 'course': None, 'due': week_end,
                    'title': _goal_title('active_days', target, None),
                    'why': f"{first} passed a test or quiz on {days} of the last 7 days."})

    # 6. monthly leaderboard
    rank, total, _ = _goal_child_rank(conn, child_id)
    if rank and rank > 3 and total > 5:
        target = max(3, (rank // 2) // 5 * 5 or 3)
        out.append({'type': 'rank', 'target': target, 'course': None, 'due': _month_end(),
                    'title': _goal_title('rank', target, None),
                    'why': f'{first} is #{rank} of {total} on this month\'s leaderboard.'})
    return out[:5]


def _goal_validate(conn, child_id, d, existing=None):
    """Cleans a create/edit body. Returns (fields, error)."""
    today = _nairobi_today()
    gtype = existing['type'] if existing else d.get('type')
    if gtype not in GOAL_TYPES:
        return None, 'Choose what the goal is about.'
    t = GOAL_TYPES[gtype]
    out = {'type': gtype}
    if not existing:
        course = (d.get('course') or '').strip() or None
        if t['course'] == 'none':
            course = None
        elif course and course not in EP_COURSE_MODULES:
            return None, 'Choose one of the courses in the list.'
        elif t['course'] == 'required' and not course:
            return None, 'Choose the course to finish.'
        out['course'] = course
        if gtype == 'course':
            target = EP_COURSE_MODULES[course]
        else:
            try:
                target = int(d.get('target'))
            except (TypeError, ValueError):
                return None, f"Enter a number for the target ({t['min']} to {t['max']})."
            if not t['min'] <= target <= t['max']:
                return None, f"The target must be between {t['min']} and {t['max']} {t['unit']}."
        out['target'] = target
    due = str(d.get('due') or (existing['due_day'] if existing else '')).strip()[:10]
    try:
        due_dt = datetime.strptime(due, '%Y-%m-%d')
    except ValueError:
        return None, 'Choose an end date.'
    start = existing['start_day'] if existing else today
    if due < today:
        return None, 'The end date must be today or later.'
    if (due_dt - datetime.strptime(start, '%Y-%m-%d')).days > GOAL_MAX_DAYS:
        return None, f'A goal can last at most {GOAL_MAX_DAYS} days.'
    out['due_day'] = due
    def pick(key, col):
        v = d.get(key) if key in d else (existing[col] if existing else None)
        return '' if v is None else v
    reward = re.sub(r'\s+', ' ', str(pick('reward', 'reward'))).strip()
    if len(reward) > 120:
        return None, 'Keep the reward under 120 characters.'
    out['reward'] = reward
    if not reward:
        return None, 'Write the reward your child will get.'
    out['bonus_points'], out['bonus_minutes'] = 0, 0     # no longer offered; columns kept for old rows
    note = str(pick('note', 'note')).strip()
    if len(note) > 300:
        return None, 'Keep the note to the child under 300 characters.'
    out['note'] = note
    return out, None


def _goal_owned(conn, goal_id):
    """The goal row if it belongs to one of this parent's linked children, else None."""
    _goals_table(conn)
    g = conn.execute('SELECT * FROM child_goals WHERE id = ?', (goal_id,)).fetchone()
    if not g or g['parent_id'] == g['student_id'] or not _is_linked_parent(conn, session['user_id'], g['student_id']):
        return None
    return g


