@app.route('/api/parent/goals')
def api_parent_goals():
    guard = _parent_guard()
    if guard:
        return guard
    pid = session['user_id']
    conn = _links_db()
    try:
        _goals_table(conn)
        kids = _parent_children(conn, pid)
        ids = [k['id'] for k in kids]
        for cid in ids:
            _goals_refresh(conn, cid)
        rows = []
        if ids:
            rows = conn.execute(f"""SELECT * FROM child_goals WHERE student_id IN ({','.join('?' for _ in ids)})
                                    AND parent_id != student_id
                                    ORDER BY CASE status WHEN 'achieved' THEN 0 WHEN 'active' THEN 1 ELSE 2 END,
                                             CASE WHEN status = 'active' THEN due_day END, id DESC LIMIT 400""", ids).fetchall()
        names = {}
        goals = [_goal_json(conn, g, pid, names) for g in rows]
        for k in kids:
            k['stats'] = _goal_stats([g for g in goals if g['child_id'] == k['id']])
            k.pop('subjects', None)
        types = [{'key': k, **{x: v[x] for x in ('label', 'unit', 'min', 'max', 'default', 'icon', 'course', 'help')}}
                 for k, v in GOAL_TYPES.items()]
        return jsonify({
            'success': True, 'children': kids, 'goals': goals, 'types': types,
            'courses': [{'key': k, 'name': EP_COURSE_NAMES[k], 'modules': v} for k, v in EP_COURSE_MODULES.items()],
            'reward_ideas': GOAL_REWARD_IDEAS,
            'limits': {'max_active': GOAL_MAX_ACTIVE, 'max_days': GOAL_MAX_DAYS, 'score_min_tests': GOAL_SCORE_MIN_TESTS},
            'today': _nairobi_today(), 'week_end': _goal_end_of_week(),
        })
    finally:
        conn.close()


