@app.route('/api/parent/goals', methods=['POST'])
def api_parent_goal_create():
    guard = _parent_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    try:
        child_id = int(d.get('child_id'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Choose which child the goal is for.'}), 400
    conn = _links_db()
    try:
        _goals_table(conn)
        child = _linked_child(conn, session['user_id'], child_id)
        if not child:
            return jsonify({'success': False, 'message': 'This child is not linked to you.'}), 404
        first = (child['firstname'] or '').strip() or 'Your child'
        active = conn.execute("SELECT COUNT(*) FROM child_goals WHERE student_id = ? AND status = 'active'", (child_id,)).fetchone()[0]
        if active >= GOAL_MAX_ACTIVE:
            return jsonify({'success': False, 'message': f'{first} already has {GOAL_MAX_ACTIVE} goals running. Let one finish or remove one first.'}), 400
        f, err = _goal_validate(conn, child_id, d)
        if err:
            return jsonify({'success': False, 'message': err}), 400
        if f['type'] == 'course' and conn.execute("SELECT 1 FROM ep_events WHERE user_id = ? AND kind = 'course' AND ref = ?",
                                                  (child_id, f['course'])).fetchone():
            return jsonify({'success': False, 'message': f"{first} has already finished {_goal_course_name(f['course'])}."}), 400
        today = _nairobi_today()
        probe = {'type': f['type'], 'target': f['target'], 'student_id': child_id, 'start_day': today,
                 'due_day': f['due_day'], 'course': f['course']}
        value, pct, done, text = _goal_measure(conn, probe)
        if done:
            return jsonify({'success': False, 'message': f'{first} has already reached this ({text}). Set a bigger target.'}), 400
        retry_of = None
        try:
            retry_of = int(d['retry_of']) if d.get('retry_of') else None
        except (TypeError, ValueError):
            retry_of = None
        if retry_of and not _goal_owned(conn, retry_of):
            retry_of = None
        now = _iso(_utc_now())
        cur = conn.execute('''INSERT INTO child_goals (student_id, parent_id, type, target, course, start_day, due_day,
                                  reward, bonus_points, bonus_minutes, note, status, value, pct, progress_text,
                                  created_at, checked_at, retry_of)
                              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?)''',
                           (child_id, session['user_id'], f['type'], f['target'], f['course'], today, f['due_day'],
                            f['reward'], f['bonus_points'], f['bonus_minutes'], f['note'], value, pct, text, now, now, retry_of))
        gid = cur.lastrowid
        title = _goal_title(f['type'], f['target'], f['course'])
        who = _goal_setter_label(conn, session['user_id'], child_id)
        due_txt = datetime.strptime(f['due_day'], '%Y-%m-%d').strftime('%a %d %b')
        create_notification(conn, child_id, f'New goal from {who}',
                            f'"{title}" by {due_txt}. Reward: {f["reward"]}.' + (f' {who} says: {f["note"]}' if f['note'] else ''),
                            icon='fa-bullseye', color='#8b5cf6')
        conn.commit()
        g = conn.execute('SELECT * FROM child_goals WHERE id = ?', (gid,)).fetchone()
        return jsonify({'success': True, 'goal': _goal_json(conn, g, session['user_id'])})
    finally:
        conn.close()


@app.route('/api/parent/goals/<int:goal_id>', methods=['PATCH'])
def api_parent_goal_edit(goal_id):
    """Change the end date, reward or note of a running goal (or the reward of a reached one)."""
    guard = _parent_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    conn = _links_db()
    try:
        g = _goal_owned(conn, goal_id)
        if not g:
            return jsonify({'success': False, 'message': 'Goal not found.'}), 404
        if g['status'] not in ('active', 'achieved'):
            return jsonify({'success': False, 'message': 'Only running goals, or reached goals still waiting for their reward, can be changed.'}), 400
        if g['status'] == 'achieved':   # only the reward can change; the end date is kept
            d = {k: v for k, v in d.items() if k in ('reward', 'note')}
            d['due'] = _nairobi_today()
        f, err = _goal_validate(conn, g['student_id'], d, existing=g)
        if err:
            return jsonify({'success': False, 'message': err}), 400
        if g['status'] == 'achieved':
            f['due_day'] = g['due_day']
        changes = []
        if f['due_day'] != g['due_day']:
            changes.append('the end date to ' + datetime.strptime(f['due_day'], '%Y-%m-%d').strftime('%a %d %b'))
        if f['reward'] != (g['reward'] or ''):
            changes.append('the reward')
        conn.execute('''UPDATE child_goals SET due_day = ?, reward = ?, bonus_points = ?, bonus_minutes = ?, note = ?,
                        near_alerted = CASE WHEN ? != due_day THEN 0 ELSE near_alerted END WHERE id = ?''',
                     (f['due_day'], f['reward'], f['bonus_points'], f['bonus_minutes'], f['note'], f['due_day'], goal_id))
        if changes:
            who = _goal_setter_label(conn, session['user_id'], g['student_id'])
            create_notification(conn, g['student_id'], 'Goal updated',
                                f'{who} changed {" and ".join(changes)} for "{_goal_title(g["type"], g["target"], g["course"])}".',
                                icon='fa-bullseye', color='#8b5cf6')
        conn.commit()
        g = conn.execute('SELECT * FROM child_goals WHERE id = ?', (goal_id,)).fetchone()
        return jsonify({'success': True, 'goal': _goal_json(conn, g, session['user_id'])})
    finally:
        conn.close()


