@app.route('/api/parent/goals/<int:goal_id>/reward', methods=['POST'])
def api_parent_goal_reward(goal_id):
    """The parent has given the reward: the goal is marked rewarded and the child is told."""
    guard = _parent_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    message = re.sub(r'\s+', ' ', str(d.get('message') or '')).strip()
    if len(message) > 300:
        return jsonify({'success': False, 'message': 'Keep the message under 300 characters.'}), 400
    conn = _links_db()
    try:
        g = _goal_owned(conn, goal_id)
        if not g:
            return jsonify({'success': False, 'message': 'Goal not found.'}), 404
        if g['status'] == 'rewarded':
            return jsonify({'success': False, 'message': 'This reward was already marked as given.'}), 409
        if g['status'] != 'achieved':
            return jsonify({'success': False, 'message': 'Rewards are given once the goal is reached.'}), 400
        now = _iso(_utc_now())
        cur = conn.execute("""UPDATE child_goals SET status = 'rewarded', rewarded_at = ?, rewarded_by = ?, reward_message = ?
                              WHERE id = ? AND status = 'achieved'""", (now, session['user_id'], message, goal_id))
        if cur.rowcount == 0:
            return jsonify({'success': False, 'message': 'This reward was already marked as given.'}), 409
        sid = g['student_id']
        who = _goal_setter_label(conn, session['user_id'], sid)
        create_notification(conn, sid, 'Your reward is here!',
                            f'{who} gave you your reward for "{_goal_title(g["type"], g["target"], g["course"])}": {(g["reward"] or "").strip() or "well done"}.'
                            + (f' "{message}"' if message else ''), icon='fa-gift', color='#ec4899')
        conn.commit()
        g = conn.execute('SELECT * FROM child_goals WHERE id = ?', (goal_id,)).fetchone()
        return jsonify({'success': True, 'goal': _goal_json(conn, g, session['user_id'])})
    finally:
        conn.close()


