@app.route('/api/learner/plans', methods=['GET', 'POST'])
def api_learner_plans():
    if 'user_id' not in session or session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Plans are for learners.'}), 403
    uid = session['user_id']
    conn = _links_db()
    try:
        _sched_tables(conn)
        if request.method == 'POST':
            d = request.get_json(silent=True) or {}
            name = re.sub(r'\s+', ' ', str(d.get('name') or '')).strip()[:50]
            if not name:
                return jsonify({'success': False, 'message': 'Give your plan a name.'}), 400
            if conn.execute('SELECT COUNT(*) FROM study_plans WHERE user_id = ?', (uid,)).fetchone()[0] >= 12:
                return jsonify({'success': False, 'message': 'You can have up to 12 plans.'}), 400
            color = d.get('color') if d.get('color') in PLAN_COLORS else PLAN_COLORS[
                conn.execute('SELECT COUNT(*) FROM study_plans WHERE user_id = ?', (uid,)).fetchone()[0] % len(PLAN_COLORS)]
            cur = conn.execute('INSERT INTO study_plans (user_id, name, color, created_at) VALUES (?, ?, ?, ?)',
                               (uid, name, color, _iso(_utc_now())))
            conn.commit()
            return jsonify({'success': True, 'id': cur.lastrowid})
        return jsonify({'success': True, 'plans': [dict(r) for r in conn.execute(
            'SELECT id, name, color FROM study_plans WHERE user_id = ? ORDER BY id', (uid,)).fetchall()], 'colors': PLAN_COLORS})
    finally:
        conn.close()


@app.route('/api/learner/plans/<int:plan_id>', methods=['PATCH', 'DELETE'])
def api_learner_plan(plan_id):
    if 'user_id' not in session or session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Plans are for learners.'}), 403
    uid = session['user_id']
    conn = _links_db()
    try:
        _sched_tables(conn)
        _goals_table(conn)
        if not conn.execute('SELECT 1 FROM study_plans WHERE id = ? AND user_id = ?', (plan_id, uid)).fetchone():
            return jsonify({'success': False, 'message': 'Plan not found.'}), 404
        if request.method == 'DELETE':
            # the plan's events and goals stay; they just move to "No plan"
            conn.execute('UPDATE teacher_events SET plan_id = NULL WHERE plan_id = ? AND teacher_id = ?', (plan_id, uid))
            conn.execute('UPDATE child_goals SET plan_id = NULL WHERE plan_id = ? AND student_id = ?', (plan_id, uid))
            conn.execute('DELETE FROM study_plans WHERE id = ?', (plan_id,))
            conn.commit()
            return jsonify({'success': True, 'message': 'Plan removed. Its events and goals are kept.'})
        d = request.get_json(silent=True) or {}
        name = re.sub(r'\s+', ' ', str(d.get('name') or '')).strip()[:50]
        if not name:
            return jsonify({'success': False, 'message': 'Give your plan a name.'}), 400
        color = d.get('color') if d.get('color') in PLAN_COLORS else None
        conn.execute('UPDATE study_plans SET name = ?, color = COALESCE(?, color) WHERE id = ?', (name, color, plan_id))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


def _set_event_plan(conn, eid, d):
    """Learners: put an event in one of their plans (or none)."""
    if session.get('role') != 'student' or 'plan_id' not in d:
        return
    plan = d.get('plan_id')
    try:
        plan = int(plan) if plan not in (None, '', 0, '0') else None
    except (TypeError, ValueError):
        plan = None
    if plan and not conn.execute('SELECT 1 FROM study_plans WHERE id = ? AND user_id = ?', (plan, session['user_id'])).fetchone():
        plan = None
    conn.execute('UPDATE teacher_events SET plan_id = ? WHERE id = ?', (plan, eid))


@app.route('/api/learner/goals/<int:goal_id>', methods=['PATCH'])
def api_learner_goal_edit(goal_id):
    """Change a running goal's details: why, priority, study days/time, milestones, reminder, plan, end date."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please log in again.'}), 401
    uid = session['user_id']
    conn = _links_db()
    try:
        _goals_table(conn)
        _sched_tables(conn)
        g = conn.execute("SELECT * FROM child_goals WHERE id = ? AND student_id = ? AND parent_id = ? AND status = 'active'",
                         (goal_id, uid, uid)).fetchone()
        if not g:
            return jsonify({'success': False, 'message': 'Only running goals can be changed.'}), 404
        d = request.get_json(silent=True) or {}
        due = g['due_day']
        if d.get('due') and d['due'] != g['due_day']:
            f, err = _goal_validate(conn, uid, {'due': d['due'], 'reward': 'x', 'note': ''}, existing=g)
            if err:
                return jsonify({'success': False, 'message': err}), 400
            due = f['due_day']
        det, err = _clean_goal_details(conn, uid, d, g['start_day'], due)
        if err:
            return jsonify({'success': False, 'message': err}), 400
        old = {(m['pct'], m['day']): m for m in _milestones(g['milestones'])}
        if det['milestones']:      # keep what was already reached
            det['milestones'] = json.dumps([old.get((m['pct'], m['day']), m) for m in json.loads(det['milestones'])])
        reward = re.sub(r'\s+', ' ', str(d.get('reward', g['reward']) or '')).strip()[:120] or None
        conn.execute("""UPDATE child_goals SET due_day = ?, why = ?, priority = ?, study_days = ?, study_time = ?, study_minutes = ?,
                        milestones = ?, reminder = ?, plan_id = ?, reward = ? WHERE id = ?""",
                     (due, det['why'], det['priority'], det['study_days'], det['study_time'], det['study_minutes'],
                      det['milestones'], det['reminder'], det['plan_id'], reward, goal_id))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/learner/goals', methods=['GET', 'POST'])
def api_learner_goals():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please log in again.'}), 401
    if session.get('role', 'student') != 'student':
        return jsonify({'success': False, 'message': 'Goals are for learners.'}), 403
    uid = session['user_id']
    conn = _links_db()
    try:
        _goals_table(conn)
        _ep_table(conn)
        if request.method == 'POST':
            d = request.get_json(silent=True) or {}
            active = conn.execute("SELECT COUNT(*) FROM child_goals WHERE student_id = ? AND parent_id = student_id AND status = 'active'",
                                  (uid,)).fetchone()[0]
            if active >= GOAL_MAX_ACTIVE:
                return jsonify({'success': False, 'message': f'You already have {GOAL_MAX_ACTIVE} goals running. Finish or remove one first.'}), 400
            reward = re.sub(r'\s+', ' ', str(d.get('reward') or '')).strip()[:120]
            f, err = _goal_validate(conn, uid, {**d, 'reward': reward or 'personal goal', 'note': str(d.get('note') or '')[:300]})
            if err:
                return jsonify({'success': False, 'message': err.replace('your child', 'you').replace('the child', 'you')}), 400
            if f['type'] == 'course' and conn.execute("SELECT 1 FROM ep_events WHERE user_id = ? AND kind = 'course' AND ref = ?",
                                                      (uid, f['course'])).fetchone():
                return jsonify({'success': False, 'message': f"You have already finished {_goal_course_name(f['course'])}."}), 400
            today = _nairobi_today()
            probe = {'type': f['type'], 'target': f['target'], 'student_id': uid, 'start_day': today,
                     'due_day': f['due_day'], 'course': f['course']}
            value, pct, done, text = _goal_measure(conn, probe)
            if done:
                return jsonify({'success': False, 'message': f'You have already reached this ({text}). Set a bigger target.'}), 400
            _sched_tables(conn)
            det, err = _clean_goal_details(conn, uid, d, today, f['due_day'])
            if err:
                return jsonify({'success': False, 'message': err}), 400
            now = _iso(_utc_now())
            conn.execute('''INSERT INTO child_goals (student_id, parent_id, type, target, course, start_day, due_day,
                                reward, note, status, value, pct, progress_text, created_at, checked_at,
                                why, priority, study_days, study_time, study_minutes, milestones, reminder, plan_id)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                         (uid, uid, f['type'], f['target'], f['course'], today, f['due_day'], reward or None,
                          f['note'] or None, value, pct, text, now, now,
                          det['why'], det['priority'], det['study_days'], det['study_time'], det['study_minutes'],
                          det['milestones'], det['reminder'], det['plan_id']))
            conn.commit()
        _goals_refresh(conn, uid)
        rows = conn.execute("""SELECT * FROM child_goals WHERE student_id = ? AND parent_id = student_id
                               ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, due_day, id DESC LIMIT 200""",
                            (uid,)).fetchall()
        goals = []
        for g in rows:
            j = _goal_json(conn, g, uid)
            j.pop('set_by', None)
            j['analysis'] = _my_goal_analysis(j)
            goals.append(_my_goal_extra(g, j))
        types = [{'key': k, 'help': MY_GOAL_HELP.get(k, ''),
                  **{x: v[x] for x in ('label', 'unit', 'min', 'max', 'default', 'icon', 'course')}}
                 for k, v in GOAL_TYPES.items()]
        courses = [{'key': k, 'name': EP_COURSE_NAMES.get(k, k), 'modules': n} for k, n in EP_COURSE_MODULES.items()]
        _sched_tables(conn)
        plans = [dict(r) for r in conn.execute('SELECT id, name, color FROM study_plans WHERE user_id = ? ORDER BY id', (uid,)).fetchall()]
        return jsonify({'success': True, 'goals': goals, 'overview': _my_goals_overview(goals),
                        'habits': _learner_habits(conn, uid), 'plans': plans,
                        'types': types, 'courses': courses, 'today': _nairobi_today(), 'max_days': GOAL_MAX_DAYS})
    finally:
        conn.close()


@app.route('/api/learner/goals/<int:goal_id>', methods=['DELETE'])
def api_learner_goal_remove(goal_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please log in again.'}), 401
    uid = session['user_id']
    conn = _links_db()
    try:
        _goals_table(conn)
        g = conn.execute('SELECT * FROM child_goals WHERE id = ? AND student_id = ? AND parent_id = ?', (goal_id, uid, uid)).fetchone()
        if not g:
            return jsonify({'success': False, 'message': 'Goal not found.'}), 404
        if g['status'] == 'active':
            conn.execute("UPDATE child_goals SET status = 'cancelled', cancelled_at = ? WHERE id = ?", (_iso(_utc_now()), goal_id))
        else:
            conn.execute('DELETE FROM child_goals WHERE id = ?', (goal_id,))   # clear a finished one from the list
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.before_request
def _goals_tick():
    """While a learner uses Eschool, re-check their goals now and then, so a
    goal is marked reached (and parents told) soon after it happens."""
    uid = session.get('user_id')
    if not uid or session.get('role', 'student') != 'student' or request.endpoint in (None, 'static'):
        return None
    now = _time.time()
    if now - _GOAL_LAST_TICK.get(uid, 0) < GOAL_TICK_SECONDS:
        return None
    _GOAL_LAST_TICK[uid] = now
    try:
        conn = _links_db()
        try:
            _goals_table(conn)
            if conn.execute("SELECT 1 FROM child_goals WHERE student_id = ? AND status = 'active' LIMIT 1", (uid,)).fetchone():
                _goals_refresh(conn, uid)
        finally:
            conn.close()
    except sqlite3.Error:
        pass
    return None


