def _student_guard():
    if 'user_id' not in session:
        return jsonify({'success': False, 'code': 'not_logged_in',
                        'message': 'Please log in again.'}), 401
    if (session.get('role') or 'student') != 'student':
        return jsonify({'success': False, 'code': 'wrong_account',
                        'message': 'You are signed in as a different account. Please log in as the learner.'}), 403
    return None


@app.route('/api/student/link-code', methods=['POST'])
def student_generate_link_code():
    """The student generates a one-time code (ESK-XXX-XXX style) for a parent."""
    guard = _student_guard()
    if guard:
        return guard

    conn = _links_db()
    try:
        # only one live code per student at a time
        conn.execute('UPDATE link_codes SET used = 1 WHERE student_id = ? AND used = 0', (session['user_id'],))
        raw = ''.join(secrets.choice(CODE_ALPHABET) for _ in range(9))
        code = f"{raw[:3]}-{raw[3:6]}-{raw[6:]}"
        expires = _utc_now() + timedelta(minutes=LINK_CODE_MINUTES)
        conn.execute(
            'INSERT INTO link_codes (student_id, code, expires_at) VALUES (?, ?, ?)',
            (session['user_id'], code, _iso(expires))
        )
        conn.commit()
        return jsonify({'success': True, 'code': code, 'expires_at': _iso(expires)})
    finally:
        conn.close()


@app.route('/api/student/parent-requests', methods=['GET'])
def student_parent_requests():
    """Pending requests waiting for this student, plus the parents already linked."""
    guard = _student_guard()
    if guard:
        return guard

    conn = _links_db()
    try:
        now = _iso(_utc_now())
        conn.execute('''
            UPDATE parent_links SET status = 'expired'
            WHERE student_id = ? AND status = 'pending' AND expires_at < ?
        ''', (session['user_id'], now))
        conn.commit()

        rows = conn.execute('''
            SELECT pl.id, pl.relationship, pl.status, pl.requested_at, pl.linked_at, pl.expires_at,
                   u.firstname, u.lastname
            FROM parent_links pl
            LEFT JOIN users u ON u.id = pl.parent_id
            WHERE pl.student_id = ? AND pl.status IN ('pending', 'active')
            ORDER BY pl.id DESC
        ''', (session['user_id'],)).fetchall()

        items = [{
            'id': r['id'],
            'parent_name': _full_name(r['firstname'], r['lastname'], 'Parent'),
            'relationship': r['relationship'],
            'status': r['status'],
            'requested_at': r['requested_at'],
            'linked_at': r['linked_at'],
            'expires_at': r['expires_at']
        } for r in rows]
        return jsonify({
            'requests': [i for i in items if i['status'] == 'pending'],
            'linked': [i for i in items if i['status'] == 'active']
        })
    finally:
        conn.close()


@app.route('/api/student/parent-requests/<int:link_id>/respond', methods=['POST'])
def student_respond_parent_request(link_id):
    """Student accepts or declines a parent's request; the parent is notified."""
    guard = _student_guard()
    if guard:
        return guard

    action = ((request.get_json(silent=True) or {}).get('action') or '').strip().lower()
    if action not in ('accept', 'decline'):
        return jsonify({'success': False, 'message': 'Action must be accept or decline'}), 400

    student_name = _full_name(session.get('firstname'), session.get('lastname'), 'Your child')
    conn = _links_db()
    try:
        row = conn.execute('''
            SELECT parent_id, status, expires_at FROM parent_links
            WHERE id = ? AND student_id = ?
        ''', (link_id, session['user_id'])).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Request not found'}), 404
        if row['status'] != 'pending':
            return jsonify({'success': False, 'message': 'This request is no longer pending'}), 409
        if row['expires_at'] and row['expires_at'] < _iso(_utc_now()):
            conn.execute("UPDATE parent_links SET status = 'expired' WHERE id = ?", (link_id,))
            conn.commit()
            return jsonify({'success': False, 'message': 'This request has expired'}), 410

        if action == 'accept':
            conn.execute(
                "UPDATE parent_links SET status = 'active', linked_at = ?, expires_at = NULL WHERE id = ?",
                (_iso(_utc_now()), link_id)
            )
            create_notification(
                conn, user_id=row['parent_id'],
                title='Link request accepted',
                message=f"{student_name} accepted your request. You can now view their progress.",
                icon='fa-circle-check', color='green'
            )
        else:
            conn.execute("UPDATE parent_links SET status = 'declined' WHERE id = ?", (link_id,))
            create_notification(
                conn, user_id=row['parent_id'],
                title='Link request declined',
                message=f"{student_name} declined your link request.",
                icon='fa-ban', color='red'
            )
        conn.commit()
        return jsonify({'success': True, 'status': 'active' if action == 'accept' else 'declined'})
    finally:
        conn.close()


# ============ PARENT: SEND A LINK CODE TO THE STUDENT'S NOTIFICATIONS ============
# Paste this block into backen.py ABOVE the line:
#     if __name__ == '__main__':
# (right after student_respond_parent_request is a good place).
# It reuses _links_db, _find_student, _parent_guard, _full_name, _iso, _utc_now,
# CODE_ALPHABET, LINK_CODE_MINUTES and create_notification from the links block.

@app.route('/api/parent/links/send-code', methods=['POST'])
def parent_send_link_code():
    """
    The parent picked "Use a link code" for a child. We generate a one-time
    code and put it in the CHILD's notifications (the bell). The child then
    reads it out to the parent, who types it in. The parent never sees the code
    on their own screen, so the child is always involved.
    """
    guard = _parent_guard()
    if guard:
        return guard

    data = request.get_json(silent=True) or {}
    try:
        student_id = int(data.get('student_id'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Please select a student first'}), 400

    parent_id = session['user_id']
    parent_name = _full_name(session.get('firstname'), session.get('lastname'), 'A parent')

    conn = _links_db()
    try:
        student = _find_student(conn, student_id)
        if not student or student_id == parent_id:
            return jsonify({'success': False, 'message': 'Student not found'}), 404

        existing = conn.execute(
            'SELECT status FROM parent_links WHERE parent_id = ? AND student_id = ?',
            (parent_id, student_id)
        ).fetchone()
        if existing and existing['status'] in ('active', 'pending'):
            return jsonify({'success': False, 'message': 'Already linked or pending'}), 409

        # at most one new code per student per minute (stops notification spam)
        recent = conn.execute('''
            SELECT 1 FROM link_codes
            WHERE student_id = ? AND created_at > datetime('now', '-60 seconds')
            LIMIT 1
        ''', (student_id,)).fetchone()
        if recent:
            return jsonify({'success': False, 'message': 'A code was just sent. Please wait a minute.'}), 429

        # only one live code per student at a time
        conn.execute('UPDATE link_codes SET used = 1 WHERE student_id = ? AND used = 0', (student_id,))
        raw = ''.join(secrets.choice(CODE_ALPHABET) for _ in range(9))
        code = f"{raw[:3]}-{raw[3:6]}-{raw[6:]}"
        expires = _utc_now() + timedelta(minutes=LINK_CODE_MINUTES)
        conn.execute(
            'INSERT INTO link_codes (student_id, code, expires_at) VALUES (?, ?, ?)',
            (student_id, code, _iso(expires))
        )

        # the notification the student sees in the bell
        create_notification(
            conn, user_id=student_id,
            title=f'Link code: {code}',
            message=f"{parent_name} wants to link to your account. Give them this code only if you "
                    f"know them. It expires in {LINK_CODE_MINUTES} minutes.",
            icon='fa-key', color='blue'
        )

        conn.commit()
        return jsonify({'success': True, 'expires_at': _iso(expires)})
    finally:
        conn.close()


# ============ PARENT: EMAIL APPROVAL (Yes / No) ============
# Flow:
#   1. Parent taps "Send approval email"  -> POST /api/parent/links/email-request
#      We email the student "Do you want to link your account to <parent>?"
#      with Yes / No buttons.
#   2. The buttons open /link-approval/<token> on this site. The student
#      confirms there (a real button press, so email scanners that open
#      links automatically can't approve anything by accident).
#   3. The parent's page polls GET /api/parent/links/email-request/<id>
#      every few seconds and unlocks "Continue" once the status is "approved".
#   4. The parent finishes the wizard; POST /api/parent/links checks the
#      request was approved and creates the link as active.
# Only a hash of the email token is stored, so a leaked database can't be
# used to approve requests.

import hashlib as _hashlib
from flask import render_template_string

LINK_EMAIL_HOURS = 24          # the Yes/No email works for 24 hours
LINK_EMAIL_RESEND_SECONDS = 60 # at most one email per parent+student per minute


def _email_requests_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS link_email_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER NOT NULL,
            student_id INTEGER NOT NULL,
            token_hash TEXT NOT NULL UNIQUE,
            status TEXT NOT NULL DEFAULT 'pending',   -- pending | approved | declined | expired | cancelled | used
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            responded_at TEXT,
            FOREIGN KEY (parent_id) REFERENCES users (id),
            FOREIGN KEY (student_id) REFERENCES users (id)
        )
    ''')


def _hash_token(token):
    return _hashlib.sha256(token.encode('utf-8')).hexdigest()


def _expire_if_needed(conn, row):
    """Marks a pending request expired once its time is up. Returns the current status."""
    if row['status'] == 'pending' and row['expires_at'] < _iso(_utc_now()):
        conn.execute("UPDATE link_email_requests SET status = 'expired' WHERE id = ?", (row['id'],))
        conn.commit()
        return 'expired'
    return row['status']


def _send_approval_email(to_email, student_first, parent_name, yes_url, no_url):
    """Sends the Yes/No email. Raises on failure so the caller can report it."""
    safe_parent = parent_name.replace('<', '&lt;').replace('>', '&gt;')
    safe_student = (student_first or 'there').replace('<', '&lt;').replace('>', '&gt;')
    html = f"""
    <div style="font-family:Arial,Helvetica,sans-serif;max-width:520px;margin:0 auto;padding:24px;color:#1e293b;">
      <h2 style="color:#4361ee;margin:0 0 16px;">Eschool – Parent link request</h2>
      <p>Hi {safe_student},</p>
      <p><strong>{safe_parent}</strong> wants to link their parent account to your Eschool account,
         so they can follow your learning progress.</p>
      <p style="font-size:18px;font-weight:bold;margin:24px 0 12px;">Do you want to link your account to {safe_parent}?</p>
      <table role="presentation" cellspacing="0" cellpadding="0"><tr>
        <td style="padding-right:12px;">
          <a href="{yes_url}" style="display:inline-block;background:#10b981;color:#ffffff;text-decoration:none;
             padding:14px 34px;border-radius:8px;font-weight:bold;font-size:16px;">Yes</a>
        </td>
        <td>
          <a href="{no_url}" style="display:inline-block;background:#ef4444;color:#ffffff;text-decoration:none;
             padding:14px 34px;border-radius:8px;font-weight:bold;font-size:16px;">No</a>
        </td>
      </tr></table>
      <p style="color:#6b7280;font-size:13px;margin-top:24px;">
        Only tap Yes if you know this person. This request expires in {LINK_EMAIL_HOURS} hours.
        If you didn't expect this email, tap No or simply ignore it.
      </p>
    </div>
    """
    text = (
        f"Hi {student_first or 'there'},\n\n"
        f"{parent_name} wants to link their parent account to your Eschool account.\n\n"
        f"Do you want to link your account to {parent_name}?\n\n"
        f"YES: {yes_url}\n"
        f"NO:  {no_url}\n\n"
        f"Only answer Yes if you know this person. This request expires in {LINK_EMAIL_HOURS} hours."
    )
    msg = Message(
        subject=f"{parent_name} wants to link to your Eschool account",
        recipients=[to_email],
        body=text,
        html=html
    )
    mail.send(msg)


@app.route('/api/parent/links/email-request', methods=['POST'])
def parent_send_email_request():
    guard = _parent_guard()
    if guard:
        return guard

    if not app.config['MAIL_USERNAME'] or not app.config['MAIL_PASSWORD']:
        print("Parent link email error: MAIL_USERNAME / MAIL_PASSWORD are not set")
        return jsonify({'success': False,
                        'message': 'Email is not set up on the server yet. Please use the link code method.'}), 503

    data = request.get_json(silent=True) or {}
    try:
        student_id = int(data.get('student_id'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Please select a student first'}), 400

    parent_id = session['user_id']
    parent_name = _full_name(session.get('firstname'), session.get('lastname'), 'A parent')

    conn = _links_db()
    try:
        _email_requests_table(conn)
        student = _find_student(conn, student_id)
        if not student or student_id == parent_id:
            return jsonify({'success': False, 'message': 'Student not found'}), 404
        if not student['email']:
            return jsonify({'success': False,
                            'message': "This student has no email address. Please use the link code method."}), 400

        existing = conn.execute(
            'SELECT status FROM parent_links WHERE parent_id = ? AND student_id = ?',
            (parent_id, student_id)
        ).fetchone()
        if existing and existing['status'] in ('active', 'pending'):
            return jsonify({'success': False, 'message': 'Already linked or pending'}), 409

        now = _utc_now()
        recent = conn.execute('''
            SELECT 1 FROM link_email_requests
            WHERE parent_id = ? AND student_id = ? AND created_at > ?
            LIMIT 1
        ''', (parent_id, student_id, _iso(now - timedelta(seconds=LINK_EMAIL_RESEND_SECONDS)))).fetchone()
        if recent:
            return jsonify({'success': False, 'message': 'An email was just sent. Please wait a minute.'}), 429

        # A new email replaces any older request still waiting for an answer
        conn.execute('''
            UPDATE link_email_requests SET status = 'cancelled'
            WHERE parent_id = ? AND student_id = ? AND status = 'pending'
        ''', (parent_id, student_id))

        token = secrets.token_urlsafe(32)
        expires = now + timedelta(hours=LINK_EMAIL_HOURS)
        cur = conn.execute('''
            INSERT INTO link_email_requests (parent_id, student_id, token_hash, status, created_at, expires_at)
            VALUES (?, ?, ?, 'pending', ?, ?)
        ''', (parent_id, student_id, _hash_token(token), _iso(now), _iso(expires)))
        request_id = cur.lastrowid

        yes_url = url_for('link_approval_page', token=token, answer='yes', _external=True)
        no_url = url_for('link_approval_page', token=token, answer='no', _external=True)
        try:
            _send_approval_email(student['email'], student['firstname'], parent_name, yes_url, no_url)
        except Exception as e:
            conn.rollback()   # don't keep a request the student never received
            print(f"Parent link email error: {e}")
            return jsonify({'success': False,
                            'message': "Couldn't send the email right now. Please try again in a moment."}), 502

        # also show it in the student's bell, in case they check Eschool first
        create_notification(
            conn, user_id=student_id,
            title='Parent link request',
            message=f"{parent_name} wants to link to your account. Check your email and tap Yes or No.",
            icon='fa-envelope', color='blue'
        )
        conn.commit()
        return jsonify({'request': {'id': request_id, 'status': 'pending', 'expires_at': _iso(expires)}})
    finally:
        conn.close()


@app.route('/api/parent/links/email-request/<int:request_id>', methods=['GET', 'DELETE'])
def parent_email_request_status(request_id):
    guard = _parent_guard()
    if guard:
        return guard

    conn = _links_db()
    try:
        _email_requests_table(conn)
        row = conn.execute(
            'SELECT * FROM link_email_requests WHERE id = ? AND parent_id = ?',
            (request_id, session['user_id'])
        ).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Request not found'}), 404

        if request.method == 'DELETE':
            if row['status'] == 'pending':
                conn.execute("UPDATE link_email_requests SET status = 'cancelled' WHERE id = ?", (request_id,))
                conn.commit()
            return jsonify({'success': True})

        status = _expire_if_needed(conn, row)
        if status == 'cancelled':
            status = 'expired'   # the page treats a replaced request like an expired one
        return jsonify({'request': {'id': row['id'], 'status': status,
                                    'expires_at': row['expires_at'], 'responded_at': row['responded_at']}})
    finally:
        conn.close()


