@app.route('/link-approval/<token>', methods=['GET', 'POST'])
def link_approval_page(token):
    """
    Opened from the Yes/No buttons in the email. No login needed: the secret
    token in the link proves the person has access to the student's inbox.
    GET only shows the question; the answer is saved on POST, when the
    student actually presses a button.
    """
    conn = _links_db()
    try:
        _email_requests_table(conn)
        row = conn.execute('''
            SELECT r.*, p.firstname AS p_first, p.lastname AS p_last,
                   s.firstname AS s_first, s.lastname AS s_last
            FROM link_email_requests r
            LEFT JOIN users p ON p.id = r.parent_id
            LEFT JOIN users s ON s.id = r.student_id
            WHERE r.token_hash = ?
        ''', (_hash_token(token),)).fetchone()

        if not row:
            return render_template_string(APPROVAL_PAGE, state='invalid'), 404

        parent_name = _full_name(row['p_first'], row['p_last'], 'A parent')
        student_name = _full_name(row['s_first'], row['s_last'], 'you')
        status = _expire_if_needed(conn, row)

        if status in ('expired', 'cancelled'):
            return render_template_string(APPROVAL_PAGE, state='expired' if status == 'expired' else 'invalid',
                                          parent_name=parent_name)
        if status != 'pending':
            return render_template_string(APPROVAL_PAGE, state='answered', parent_name=parent_name)

        if request.method == 'GET':
            answer = (request.args.get('answer') or '').lower()
            return render_template_string(APPROVAL_PAGE, state='ask', answer=answer,
                                          parent_name=parent_name, student_name=student_name)

        answer = (request.form.get('answer') or '').lower()
        if answer not in ('yes', 'no'):
            return render_template_string(APPROVAL_PAGE, state='ask', answer='',
                                          parent_name=parent_name, student_name=student_name), 400

        new_status = 'approved' if answer == 'yes' else 'declined'
        cur = conn.execute('''
            UPDATE link_email_requests SET status = ?, responded_at = ?
            WHERE id = ? AND status = 'pending'
        ''', (new_status, _iso(_utc_now()), row['id']))
        if cur.rowcount == 0:   # answered in another tab a moment ago
            return render_template_string(APPROVAL_PAGE, state='answered', parent_name=parent_name)

        create_notification(
            conn, user_id=row['parent_id'],
            title='Link request approved' if answer == 'yes' else 'Link request declined',
            message=(f"{student_name} tapped Yes. You can now finish linking their account."
                     if answer == 'yes' else f"{student_name} tapped No, so the accounts were not linked."),
            icon='fa-circle-check' if answer == 'yes' else 'fa-ban',
            color='green' if answer == 'yes' else 'red'
        )
        conn.commit()
        return render_template_string(APPROVAL_PAGE, state=new_status, parent_name=parent_name)
    finally:
        conn.close()


