@app.route('/Login', methods=['GET', 'POST'])
def login():
    # Support a message passed either from the POST form-handling below,
    # or via a redirect query string (e.g. redirect(url_for('login',
    # message='...')) from the Google OAuth callback on failure).
    message = request.args.get('message', '')

        # Already signed in in this browser (all tabs share one login):
    # show that account's page instead of the login form.
    already_name = f"{session.get('firstname', '')} {session.get('lastname', '')}".strip()

    if request.method == 'GET' and 'user_id' in session:
        return redirect(url_for(home_endpoint_for_role(session.get('role'))))

    if request.method == 'POST':
        email = (request.form.get('email') or '').strip()
        password = request.form.get('password') or ''
        remember = bool(request.form.get('remember'))

        # Already signed in as a DIFFERENT account? Refuse instead of overwriting.
        if 'user_id' in session and email.strip().lower() != (session.get('email') or '').lower():
            return render_template(
                'Home/Login.html',
                message=f"You're already signed in as {already_name} in this browser. "
                        f"Log out first, or use a private window for a second account."
            )

        wait = login_wait_minutes(email)
        if wait:
            return render_template('Home/Login.html', message=too_many_attempts_message(wait),
                                   message_ok=False, google_ready=google_configured())

        conn = sqlite3.connect('users.db')
        cursor = conn.cursor()

        cursor.execute("""
            SELECT id, firstname, lastname, email, role, country, password
            FROM users 
            WHERE lower(email) = lower(?) AND password IS NOT NULL
        """, (email,))

        user = next((r for r in cursor.fetchall() if password_matches(r[6], password)), None)
        conn.close()

        if user:
            login_succeeded(email)
            # Save user info in session
            session.permanent = remember          # "Remember me": stay signed in for 30 days
            session['user_id'] = user[0]
            session['firstname'] = user[1]
            session['lastname'] = user[2]
            session['email'] = user[3]
            session['role'] = user[4] or 'student'
            session['country'] = user[5]
            account_on_login(user[0], notify=True)   # session check + 'new sign-in' notice
            try:
                _c = sqlite3.connect('users.db')
                note_password(_c, user[0], password, email=user[3], name=user[1])    # only the strength, never the password
                _c.commit(); _c.close()
            except sqlite3.Error:
                pass
            
            # Store a quote for this user session
            quote = get_daily_quote()
            session['quote_text'] = quote['text']
            session['quote_author'] = quote['author']

            # Admins land on the admin dashboard, everyone else on the regular student dashboard
                        # Each role lands on its own page: admin, teacher or learner
            return redirect(url_for(home_endpoint_for_role(session['role'])))
        else:
            login_failed(email)
            account_failed_password(email)
            message = "Invalid email or password."

    return render_template('Home/Login.html', message=message,
                           message_ok=request.args.get('ok') == '1',
                           google_ready=google_configured())


# ============ GOOGLE OAUTH ROUTES ============

@app.route('/login/google')
def google_login():
    """Kicks off the Google OAuth flow. This is what the 'Continue with
    Google' button on Login.html links to via url_for('google_login')."""
    if 'user_id' in session:
        return redirect(url_for(home_endpoint_for_role(session.get('role'))))
    if not google_configured():
        print("Google sign-in: GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET are not set (add them to .env)")
        return redirect(url_for('login', message="Google sign-in isn't available right now. Please sign in with your email and password."))

    # Google only accepts the exact redirect address registered in Google
    # Cloud Console. Opening the site as 127.0.0.1 while localhost is
    # registered (or the other way round) breaks sign-in, so move to
    # localhost first; the sign-in cookie then matches too.
    fixed = os.environ.get('GOOGLE_REDIRECT_URI', '').strip()
    if not fixed and request.host.split(':')[0] == '127.0.0.1':
        return redirect(request.url.replace('://127.0.0.1', '://localhost', 1))

    session['remember_pending'] = request.args.get('remember') == '1'
    redirect_uri = fixed or url_for('google_callback', _external=True)
    try:
        return google.authorize_redirect(redirect_uri)
    except Exception as e:
        print(f"Google OAuth start error: {e}")
        return redirect(url_for('login', message='Google sign-in failed. Please try again.'))


@app.route('/login/google/callback')
def google_callback():
    """Google redirects back here after the user approves access. We
    exchange the auth code for a token, pull the user's email/name out
    of it, and either log them into their existing account (matched by
    email) or create a new one on the fly."""
    try:
        token = google.authorize_access_token()
    except Exception as e:
        print(f"Google OAuth error: {str(e)}")
        return redirect(url_for('login', message='Google sign-in failed. Please try again.'))

    userinfo = token.get('userinfo')
    if not userinfo:
        try:
            userinfo = google.parse_id_token(token, nonce=None)
        except Exception:
            userinfo = None

    if not userinfo or not userinfo.get('email'):
        return redirect(url_for('login', message='Google sign-in failed. Please try again.'))
    if userinfo.get('email_verified') is False:
        return redirect(url_for('login', message='Please verify your Google email address first, then try again.'))

    email = userinfo.get('email').strip()
    firstname = userinfo.get('given_name', '') or ''
    lastname = userinfo.get('family_name', '') or ''

    if 'user_id' in session and email.lower() != (session.get('email') or '').lower():
        return redirect(url_for('login', message="You're already signed in as a different account. Log out first."))

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    cursor.execute("SELECT id, firstname, lastname, email, role, country FROM users WHERE lower(email) = lower(?)", (email,))
    user = cursor.fetchone()

    if not user:
        # First time signing in with this Google account — create an
        # account for them. password stays NULL so this account can
        # never be logged into via the normal email/password form.
        cursor.execute('''
            INSERT INTO users (firstname, lastname, email, password, role)
            VALUES (?, ?, ?, NULL, ?)
        ''', (firstname, lastname, email, 'student'))
        conn.commit()
        user_id = cursor.lastrowid
        _mark_joined(conn, user_id)
        user = (user_id, firstname, lastname, email, 'student', None)

    conn.close()

    remember = bool(session.pop('remember_pending', False))
    session.permanent = remember              # "Remember me" ticked before choosing Google
    session['user_id'] = user[0]
    session['firstname'] = user[1]
    session['lastname'] = user[2]
    session['email'] = user[3]
    session['role'] = user[4] or 'student'
    session['country'] = user[5]
    account_on_login(user[0], notify=True, method='google')   # session check + 'new sign-in' notice

    quote = get_daily_quote()
    session['quote_text'] = quote['text']
    session['quote_author'] = quote['author']

    return redirect(url_for(home_endpoint_for_role(session['role'])))

# ============ FORGOT PASSWORD ============
# 1. /forgot-password: the user types their email. If an account exists we
#    email a reset link (the page says the same thing either way, so it
#    can't be used to find out who has an account).
# 2. The link works for 1 hour and only once: it stops working as soon as
#    the password changes.
# 3. /reset-password/<token>: choose a new password. Every device that was
#    signed in is signed out.
# Needs MAIL_USERNAME and MAIL_PASSWORD (same as the contact form).
from itsdangerous import URLSafeTimedSerializer, BadSignature as _BadSig, SignatureExpired as _SigExpired

RESET_LINK_MINUTES = 60
_reset_attempts = {}          # email/IP -> recent request times (simple rate limit)


def _reset_serializer():
    return URLSafeTimedSerializer(app.secret_key, salt='eschool-password-reset')


def _reset_fingerprint(password, epoch):
    """Changes whenever the password (or sign-out-everywhere) changes, so a used link stops working."""
    return hashlib.sha256(f"{password or ''}|{epoch}|{app.secret_key}".encode()).hexdigest()[:20]


def _reset_rate_limited(key, limit=3, window=900):
    now = _time.time()
    recent = [t for t in _reset_attempts.get(key, []) if now - t < window]
    _reset_attempts[key] = recent
    if len(recent) >= limit:
        return True
    recent.append(now)
    return False


def _mail_ready():
    return bool(app.config.get('MAIL_USERNAME') and app.config.get('MAIL_PASSWORD'))


def _link_tries_blocked():
    """Linking a child with an email + code: at most 8 tries per 15 minutes, per parent and per network address,
    so nobody can guess codes or look up children by trying many emails."""
    ip = (request.headers.get('X-Forwarded-For') or request.remote_addr or '').split(',')[0].strip()
    a = _reset_rate_limited(f"link-parent:{session.get('user_id')}", limit=8, window=900)
    b = _reset_rate_limited(f'link-ip:{ip}', limit=20, window=900)
    if a or b:
        return jsonify({'success': False, 'message': 'Too many tries. Please wait 15 minutes, then check the email and code and try again.'}), 429
    return None


@app.route('/forgot-password', methods=['GET', 'POST'])
def forgot_password():
    if 'user_id' in session:
        return redirect(url_for(home_endpoint_for_role(session.get('role'))))

    sent, error, email = False, '', ''
    if request.method == 'POST':
        email = (request.form.get('email') or '').strip()
        if not re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email):
            error = 'Please enter a valid email address.'
        elif not _mail_ready():
            print("Password reset: MAIL_USERNAME / MAIL_PASSWORD are not set")
            error = "We can't send reset emails right now. Please contact support and we'll help you get back in."
        elif _reset_rate_limited('ip:' + (request.remote_addr or '')) or _reset_rate_limited('em:' + email.lower()):
            error = 'Too many requests. Please wait a few minutes and try again.'
        else:
            conn = sqlite3.connect('users.db')
            try:
                row = conn.execute('SELECT id, firstname, email, password FROM users WHERE lower(email) = lower(?)',
                                   (email,)).fetchone()
                if not row:      # a confirmed backup email works too; the link goes to the address typed
                    _security_tables(conn)
                    b = conn.execute('SELECT u.id, u.firstname, s.backup_email, u.password FROM account_security s '
                                     'JOIN users u ON u.id = s.user_id WHERE lower(s.backup_email) = lower(?) '
                                     'AND s.backup_verified = 1', (email,)).fetchone()
                    row = tuple(b) if b else None
                acc = _account_row(conn, row[0]) if row else None
            finally:
                conn.close()
            if row:
                token = _reset_serializer().dumps({'uid': row[0], 'fp': _reset_fingerprint(row[3], acc['epoch'])})
                link = url_for('reset_password', token=token, _external=True)
                name = row[1] or 'there'
                try:
                    mail.send(Message(
                        subject='Reset your Eschool password',
                        recipients=[row[2]],
                        body=(f"Hi {name},\n\n"
                              f"Someone asked to reset the password for your Eschool account.\n\n"
                              f"Choose a new password here (the link works for {RESET_LINK_MINUTES} minutes, once):\n{link}\n\n"
                              f"If this wasn't you, ignore this email. Your password stays the same."),
                        html=(f"<div style=\"font-family:Arial,sans-serif;max-width:520px;margin:auto;color:#0F172A\">"
                              f"<h2 style=\"color:#2563EB\">Reset your Eschool password</h2>"
                              f"<p>Hi {name},</p><p>Someone asked to reset the password for your Eschool account.</p>"
                              f"<p style=\"margin:28px 0\"><a href=\"{link}\" style=\"background:#2563EB;color:#fff;"
                              f"padding:12px 24px;border-radius:999px;text-decoration:none;font-weight:bold\">Choose a new password</a></p>"
                              f"<p style=\"color:#64748B;font-size:13px\">The link works for {RESET_LINK_MINUTES} minutes and only once. "
                              f"If this wasn't you, ignore this email. Your password stays the same.</p></div>"),
                    ))
                except Exception as e:
                    print(f"Password reset email error: {e}")
                    error = "We couldn't send the email just now. Please try again in a few minutes."
            if not error:
                sent = True
    return render_template('Home/forgot_password.html', sent=sent, error=error, email=email)


def _reset_user_from_token(token):
    """(user row, None) for a valid link, or (None, reason)."""
    try:
        data = _reset_serializer().loads(token, max_age=RESET_LINK_MINUTES * 60)
    except _SigExpired:
        return None, 'This reset link has expired. Please ask for a new one.'
    except _BadSig:
        return None, 'This reset link is not valid. Please ask for a new one.'
    conn = sqlite3.connect('users.db')
    try:
        row = conn.execute('SELECT id, firstname, email, password FROM users WHERE id = ?', (data.get('uid'),)).fetchone()
        acc = _account_row(conn, row[0]) if row else None
    finally:
        conn.close()
    if not row or _reset_fingerprint(row[3], acc['epoch']) != data.get('fp'):
        return None, 'This reset link has already been used. Please ask for a new one.'
    return row, None


@app.route('/reset-password/<token>', methods=['GET', 'POST'])
def reset_password(token):
    row, problem = _reset_user_from_token(token)
    if problem:
        return render_template('Home/reset_password.html', invalid=problem, error='', email='')

    error = ''
    if request.method == 'POST':
        new = request.form.get('password') or ''
        confirm = request.form.get('confirm') or ''
        if len(new) < 8:
            error = 'Your new password must be at least 8 characters.'
        elif len(new) > 128:
            error = 'That password is too long.'
        elif new != confirm:
            error = "The two passwords don't match."
        elif row[3] and password_matches(row[3], new):
            error = 'Choose a password different from your current one.'
        else:
            conn = sqlite3.connect('users.db')
            try:
                conn.execute('UPDATE users SET password = ? WHERE id = ?', (hash_password(new), row[0]))
                acc = _account_row(conn, row[0])
                _account_upsert(conn, row[0], session_epoch=acc['epoch'] + 1)   # sign out every device
                create_notification(conn, row[0], 'Password reset',
                                    'Your password was reset with an email link and your devices were signed out.',
                                    icon='fa-key', color='green')
                note_password(conn, row[0], new, changed=True, email=row[2], name=row[1])
                _security_tables(conn)
                conn.execute('UPDATE account_devices SET ended = 1 WHERE user_id = ?', (row[0],))
                _account_event(conn, row[0], 'password_reset', '')
                conn.commit()
            finally:
                conn.close()
            session.clear()
            return redirect(url_for('login', ok='1', message='Your password has been changed. Sign in with your new password.'))
    return render_template('Home/reset_password.html', invalid='', error=error, email=row[2])


