def _admin_dash_stats(conn):
    one = lambda q: conn.execute(q).fetchone()[0]
    try:
        tickets = one("SELECT COUNT(*) FROM complaints WHERE status = 'pending'")
    except sqlite3.Error:
        tickets = 0
    try:
        resources = one('SELECT COUNT(*) FROM resources')
    except sqlite3.Error:
        resources = 0
    return {'total_users': one('SELECT COUNT(*) FROM users'),
            'total_admins': one("SELECT COUNT(*) FROM users WHERE role = 'admin'"),
            'total_resources': resources, 'pending_complaints': tickets}


def _admin_recent_users(conn, q='', limit=10):
    """The newest accounts, or a search by name or email. Only what the table shows."""
    q = (q or '').strip()[:80]
    if q:
        like = f"%{q.lower()}%"
        rows = conn.execute("""SELECT id, firstname, lastname, email, role, country, joined_at FROM users
                               WHERE lower(firstname || ' ' || COALESCE(lastname, '')) LIKE ? OR lower(email) LIKE ? OR CAST(id AS TEXT) = ?
                               ORDER BY id DESC LIMIT ?""", (like, like, q, limit)).fetchall()
    else:
        rows = conn.execute('SELECT id, firstname, lastname, email, role, country, joined_at FROM users ORDER BY id DESC LIMIT ?', (limit,)).fetchall()
    return [{'id': r[0], 'name': f"{r[1] or ''} {r[2] or ''}".strip() or 'No name', 'email': r[3] or '',
             'role': r[4] if r[4] in ('student', 'teacher', 'parent', 'admin') else 'student',
             'country': (r[5] or '').upper()[:2], 'joined': r[6] or ''} for r in rows]


# ============ ADMIN DASHBOARD: everything at a glance ============
# One read-only call that gathers every section of the admin overview. Each
# section is worked out on its own, so if one table is missing or a query
# fails, that card says "not available" and the rest still loads.

STRATEGY_TITLES = {1: 'Active Recall', 2: 'Pomodoro Technique', 3: 'SQ3R Reading Method', 4: 'Memory Palace',
                   5: 'Spaced Repetition', 6: 'Feynman Technique', 7: 'Skimming', 8: 'Mind Mapping',
                   9: 'Interleaved Practice', 10: 'Elaborative Questioning'}
ADMIN_LOG_LABELS = {
    'resource_announce': 'told learners about new resources', 'resource_edit': 'edited a resource',
    'resource_delete': 'deleted a resource', 'resource_bulk_public': 'made resources public',
    'resource_bulk_private': 'made resources private', 'resource_bulk_delete': 'deleted resources',
}


def _dt(col):
    """A date column as 'YYYY-MM-DD HH:MM:SS' whichever way it was saved (ISO with T/Z or SQLite style)."""
    return f"replace(substr({col}, 1, 19), 'T', ' ')"


def _dash_section(out, key, fn):
    try:
        out[key] = fn()
    except Exception as e:          # one broken card must never break the whole dashboard
        print(f'admin dashboard: {key} skipped: {e}')
        out[key] = None


@app.route('/api/admin/dashboard/overview')
def admin_dashboard_overview():
    bad = _admin_guard()
    if bad:
        return bad
    days = _res_period(request.args.get('days'))
    win, win2 = f'-{days} days', f'-{days * 2} days'
    conn = sqlite3.connect('users.db')
    try:
        _res_admin_tables(conn)
        one = lambda q, a=(): conn.execute(q, a).fetchone()[0]
        out = {'success': True, 'days': days, 'now': _iso(_utc_now())}
        role = "COALESCE(u.role, 'student')"

        # ---------- people ----------
        def people():
            roles = dict(conn.execute(f"SELECT {role}, COUNT(*) FROM users u GROUP BY 1").fetchall())
            new_now = dict(conn.execute(f"SELECT {role}, COUNT(*) FROM users u WHERE {_dt('u.joined_at')} >= datetime('now', ?) GROUP BY 1", (win,)).fetchall())
            new_before = dict(conn.execute(f"SELECT {role}, COUNT(*) FROM users u WHERE {_dt('u.joined_at')} >= datetime('now', ?) "
                                           f"AND {_dt('u.joined_at')} < datetime('now', ?) GROUP BY 1", (win2, win)).fetchall())
            def active(span, until='+0 days'):
                q = ("SELECT user_id FROM account_devices WHERE {c} >= datetime('now', ?) AND {c} < datetime('now', ?) "
                     "UNION SELECT user_id FROM ep_events WHERE {e} >= datetime('now', ?) AND {e} < datetime('now', ?)").format(
                    c=_dt('last_seen'), e=_dt('created_at'))
                return one(f"SELECT COUNT(*) FROM users u WHERE {role} = 'student' AND u.id IN ({q})", (span, until, span, until))
            linked = one("SELECT COUNT(DISTINCT parent_id) FROM parent_links WHERE status = 'active'")
            pro = one(f"SELECT COUNT(*) FROM users u WHERE {role} = 'student' AND COALESCE(plan, 'free') != 'free' "
                      f"AND (plan_expires_at IS NULL OR {_dt('plan_expires_at')} > datetime('now'))")
            admins = [{'name': f"{r[0] or ''} {r[1] or ''}".strip() or 'Admin', 'last': r[2]} for r in conn.execute(
                f"""SELECT u.firstname, u.lastname, (SELECT MAX({_dt('d.last_seen')}) FROM account_devices d WHERE d.user_id = u.id)
                    FROM users u WHERE u.role = 'admin' ORDER BY 3 DESC""")]
            return {'learners': roles.get('student', 0), 'teachers': roles.get('teacher', 0), 'parents': roles.get('parent', 0),
                    'admins': roles.get('admin', 0), 'new': new_now, 'new_before': new_before,
                    'active_today': active('-1 days', '+1 days'), 'active_week': active('-7 days', '+1 days'),
                    'active_before': active('-14 days', '-7 days'),
                    'parents_linked': linked, 'pro': pro, 'admin_list': admins}
        _dash_section(out, 'people', people)

        # ---------- sign-ups per day ----------
        def signups():
            today = _utc_now().date()
            daylist = [(today - timedelta(days=k)).isoformat() for k in range(days - 1, -1, -1)]
            series = {}
            for r in ('student', 'teacher', 'parent'):
                got = dict(conn.execute(f"SELECT substr({_dt('u.joined_at')}, 1, 10), COUNT(*) FROM users u WHERE {role} = ? "
                                        f"AND {_dt('u.joined_at')} >= date('now', ?) GROUP BY 1", (r, f'-{days - 1} days')).fetchall())
                series[r] = [int(got.get(d, 0)) for d in daylist]
            return {'days': daylist, 'series': series}
        _dash_section(out, 'signups', signups)

        # ---------- countries ----------
        def countries():
            rows = conn.execute(f"SELECT UPPER(COALESCE(NULLIF(TRIM(u.country), ''), '?')), {role}, COUNT(*) FROM users u "
                                f"WHERE {role} IN ('student', 'teacher', 'parent') GROUP BY 1, 2").fetchall()
            by = {}
            for cc, r, n in rows:
                d = by.setdefault(cc, {'code': cc, 'learners': 0, 'teachers': 0, 'parents': 0})
                d[{'student': 'learners', 'teacher': 'teachers', 'parent': 'parents'}[r]] += n
            for cc, d in by.items():
                d['name'] = PROFILE_COUNTRIES.get(cc, 'Not set' if cc == '?' else cc)
                if cc in COURSES_READY:
                    d['courses'], d['n_courses'] = 'ready', len(COURSE_FILES.get(cc, []))
                elif cc in COURSES_COMING:
                    d['courses'], d['n_courses'] = 'coming', 0
                else:
                    d['courses'], d['n_courses'] = 'none', 0
            lst = sorted(by.values(), key=lambda d: (-d['learners'], -(d['teachers'] + d['parents']), d['name']))
            return {'list': lst, 'count': len([d for d in lst if d['code'] != '?']),
                    'ready': list(COURSES_READY), 'coming': list(COURSES_COMING),
                    'without_courses': sum(d['learners'] for d in lst if d['courses'] == 'none')}
        _dash_section(out, 'countries', countries)

        # ---------- courses ----------
        def courses():
            stats = {}
            for (blob,) in conn.execute(f"SELECT s.courses FROM student_progress_summary s JOIN users u ON u.id = s.student_id WHERE {role} = 'student'"):
                try:
                    lst = json.loads(blob or '[]')
                except ValueError:
                    continue
                for c in lst if isinstance(lst, list) else []:
                    cid = str((c or {}).get('id') or '')
                    if not cid:
                        continue
                    p = max(0, min(100, int(float(c.get('progress') or 0))))
                    st = stats.setdefault(cid, {'started': 0, 'sum': 0, 'done': 0})
                    st['started'] += 1; st['sum'] += p; st['done'] += p >= 100
            out_l = []
            for cc in COURSES_READY:
                for f in COURSE_FILES.get(cc, []):
                    cid = f.rsplit('.', 1)[0]
                    st = stats.get(cid, {'started': 0, 'sum': 0, 'done': 0})
                    out_l.append({'id': cid, 'country': cc, 'name': COURSE_SUBJECT.get(cid, cid.title()),
                                  'modules': EP_COURSE_MODULES.get(cid, 0), 'pro': cid in PRO_ONLY_COURSES,
                                  'started': st['started'], 'avg': round(st['sum'] / st['started']) if st['started'] else 0,
                                  'done': st['done']})
            learners_ready = one(f"SELECT COUNT(*) FROM users u WHERE {role} = 'student' AND UPPER(COALESCE(u.country, '')) IN ({','.join('?' * len(COURSES_READY))})",
                                 tuple(COURSES_READY)) if COURSES_READY else 0
            not_started = one(f"""SELECT COUNT(*) FROM users u WHERE {role} = 'student' AND UPPER(COALESCE(u.country, '')) IN ({','.join('?' * len(COURSES_READY))})
                                  AND u.id NOT IN (SELECT student_id FROM student_progress_summary WHERE COALESCE(modules_completed, 0) > 0)""",
                              tuple(COURSES_READY)) if COURSES_READY else 0
            modules_win = one(f"SELECT COUNT(*) FROM ep_events WHERE kind = 'module' AND {_dt('created_at')} >= datetime('now', ?)", (win,))
            return {'list': out_l, 'total_modules': sum(c['modules'] for c in out_l), 'learners_with_courses': learners_ready,
                    'not_started': not_started, 'modules_done': modules_win}
        _dash_section(out, 'courses', courses)

        # ---------- careers ----------
        def careers():
            counts, chosen = {}, 0
            for txt, area in conn.execute(f"SELECT d.dream_career, d.career_area FROM user_details d JOIN users u ON u.id = d.user_id "
                                          f"WHERE {role} = 'student' AND (COALESCE(TRIM(d.dream_career), '') != '' OR COALESCE(d.career_area, '') != '')"):
                k = _career_match(txt, area)
                chosen += 1
                key = k or 'other'
                counts[key] = counts.get(key, 0) + 1
            top = sorted(((k, n) for k, n in counts.items() if k != 'other'), key=lambda x: -x[1])[:6]
            changed = one(f"SELECT COUNT(*) FROM user_details WHERE {_dt('career_changed_at')} >= datetime('now', ?)", (win,))
            return {'available': len(CAREER_ORDER), 'chosen': chosen, 'other': counts.get('other', 0),
                    'top': [{'key': k, 'name': CAREER_PATHS[k]['name'], 'emoji': CAREER_PATHS[k]['emoji'], 'count': n} for k, n in top],
                    'unpicked': len([k for k in CAREER_ORDER if k not in counts]), 'changed': changed}
        _dash_section(out, 'careers', careers)

        # ---------- strategies ----------
        def strategies():
            _strat_tables(conn)
            since = (_utc_now().date() - timedelta(days=days - 1)).isoformat()
            users = one('SELECT COUNT(DISTINCT user_id) FROM strategy_days WHERE day >= ?', (since,))
            focus = one('SELECT COALESCE(SUM(minutes), 0) FROM focus_blocks WHERE day >= ?', (since,))
            reviews = one(f"SELECT COUNT(*) FROM ep_events WHERE kind = 'review' AND {_dt('created_at')} >= datetime('now', ?)", (win,))
            spins = one('SELECT COALESCE(SUM(spins), 0) FROM strategy_spins WHERE day >= ?', (since,))
            used = dict(conn.execute('SELECT sid, COUNT(DISTINCT user_id) FROM strategy_days WHERE day >= ? GROUP BY sid', (since,)).fetchall())
            added = dict(conn.execute('SELECT sid, COUNT(*) FROM strategy_use GROUP BY sid').fetchall())
            likes = dict(conn.execute('SELECT strategy_id, COUNT(*) FROM strategy_likes GROUP BY strategy_id').fetchall())
            lst = [{'id': i, 'name': t, 'used': int(used.get(i, 0)), 'added': int(added.get(i, 0)), 'likes': int(likes.get(i, 0))}
                   for i, t in STRATEGY_TITLES.items()]
            lst.sort(key=lambda x: (-x['used'], -x['added'], -x['likes']))
            return {'count': STRATEGY_COUNT, 'users': users, 'focus_minutes': focus, 'reviews': reviews, 'spins': spins, 'list': lst}
        _dash_section(out, 'strategies', strategies)

        # ---------- engagement ----------
        def engagement():
            return {'ep': one(f"SELECT COALESCE(SUM(ep), 0) FROM ep_events WHERE {_dt('created_at')} >= datetime('now', ?)", (win,)),
                    'streaks': one("SELECT COUNT(DISTINCT user_id) FROM ep_streaks WHERE COALESCE(run, 0) >= 2"),
                    'badges': one(f"SELECT COUNT(*) FROM achievements_unlocked WHERE {_dt('unlocked_at')} >= datetime('now', ?)", (win,)),
                    'messages': one(f"SELECT COUNT(*) FROM messages WHERE COALESCE(is_broadcast, 0) = 0 AND {_dt('timestamp')} >= datetime('now', ?)", (win,)),
                    'quizzes': one(f"SELECT COUNT(*) FROM ep_events WHERE kind = 'quiz' AND {_dt('created_at')} >= datetime('now', ?)", (win,))}
        _dash_section(out, 'engagement', engagement)

        # ---------- live & tutoring ----------
        def live():
            held = one(f"SELECT COUNT(*) FROM live_classes WHERE state = 'ended' AND {_dt('COALESCE(ended_at, start_time)')} >= datetime('now', ?)", (win,))
            peak = one(f"SELECT AVG(peak_viewers) FROM live_classes WHERE state = 'ended' AND {_dt('COALESCE(ended_at, start_time)')} >= datetime('now', ?)", (win,))
            stars = one(f"SELECT AVG(stars) FROM live_ratings WHERE {_dt('created_at')} >= datetime('now', ?)", (win,))
            upcoming = one(f"SELECT COUNT(*) FROM live_classes WHERE state = 'scheduled' AND {_dt('start_time')} >= datetime('now')")
            now_live = one("SELECT COUNT(*) FROM live_classes WHERE state = 'live'")
            sessions = one(f"SELECT COUNT(*) FROM tutoring_sessions WHERE status = 'completed' AND {_dt('starts_at')} >= datetime('now', ?)", (win,))
            active = one("SELECT COUNT(*) FROM tutoring WHERE status = 'active'")
            return {'held': held, 'avg_viewers': round(peak or 0), 'rating': round(stars, 1) if stars else None, 'upcoming': upcoming,
                    'live_now': now_live, 'sessions': sessions, 'tutoring_active': active}
        _dash_section(out, 'live', live)

        # ---------- payments ----------
        def payments():
            conf = conn.execute(f"SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM plan_payments WHERE status = 'confirmed' "
                                f"AND {_dt('COALESCE(decided_at, created_at)')} >= datetime('now', ?)", (win,)).fetchone()
            conf_before = one(f"SELECT COALESCE(SUM(amount), 0) FROM plan_payments WHERE status = 'confirmed' AND "
                              f"{_dt('COALESCE(decided_at, created_at)')} >= datetime('now', ?) AND {_dt('COALESCE(decided_at, created_at)')} < datetime('now', ?)", (win2, win))
            pend = conn.execute("SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM plan_payments WHERE status = 'pending'").fetchone()
            tut = conn.execute(f"SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM tutoring_payments WHERE status = 'confirmed' "
                               f"AND {_dt('COALESCE(decided_at, created_at)')} >= datetime('now', ?)", (win,)).fetchone()
            ending = one(f"SELECT COUNT(*) FROM users WHERE COALESCE(plan, 'free') != 'free' AND {_dt('plan_expires_at')} BETWEEN datetime('now') AND datetime('now', '+7 days')")
            by_plan = dict(conn.execute(f"SELECT plan, COUNT(*) FROM plan_payments WHERE status = 'confirmed' AND {_dt('COALESCE(decided_at, created_at)')} >= datetime('now', ?) GROUP BY plan", (win,)).fetchall())
            return {'currency': SITE_CURRENCY, 'confirmed': conf[1], 'confirmed_n': conf[0], 'confirmed_before': conf_before,
                    'pending_n': pend[0], 'pending': pend[1], 'tutoring': tut[1], 'tutoring_n': tut[0],
                    'ending_7d': ending, 'by_plan': by_plan}
        _dash_section(out, 'payments', payments)

        # ---------- resources ----------
        def resources():
            r = conn.execute("SELECT COUNT(*), COALESCE(SUM(file_size), 0), COALESCE(SUM(views), 0) FROM resources").fetchone()
            viewers = one(f"SELECT COUNT(*) FROM resource_views WHERE {_dt('created_at')} >= datetime('now', ?)", (win,))
            top = conn.execute("SELECT title, COALESCE(views, 0) FROM resources ORDER BY views DESC, id DESC LIMIT 1").fetchone()
            att = sum(one(f'SELECT COUNT(*) FROM resources r WHERE {w}') for k, w in _RES_ATTENTION.items() if k != 'private')
            missing = len(_res_missing_ids(conn))
            new = one(f"SELECT COUNT(*) FROM resources WHERE {_dt('upload_date')} >= datetime('now', ?)", (win,))
            return {'count': r[0], 'storage': r[1], 'views': r[2], 'new_viewers': viewers, 'new': new,
                    'top': {'title': top[0], 'views': top[1]} if top else None, 'attention': att + missing, 'missing': missing}
        _dash_section(out, 'resources', resources)

        # ---------- support & safety ----------
        def support():
            open_ = one("SELECT COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') != 'resolved'")
            urgent = one("SELECT COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') != 'resolved' AND priority IN ('high', 'urgent')")
            unanswered = one("SELECT COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') = 'pending' AND COALESCE(response, '') = ''")
            reply = one(f"""SELECT AVG((julianday({_dt('response_date')}) - julianday({_dt('created_at')})) * 24)
                            FROM complaints WHERE response_date IS NOT NULL AND {_dt('created_at')} >= datetime('now', ?)""", (win,))
            oldest = one("SELECT MIN(" + _dt('created_at') + ") FROM complaints WHERE COALESCE(status, 'pending') = 'pending' AND COALESCE(response, '') = ''")
            return {'open': open_, 'urgent': urgent, 'unanswered': unanswered, 'oldest_unanswered': oldest,
                    'reply_hours': round(reply, 1) if reply is not None else None,
                    'resolved': one(f"SELECT COUNT(*) FROM complaints WHERE status = 'resolved' AND {_dt('COALESCE(response_date, created_at)')} >= datetime('now', ?)", (win,)),
                    'links': one("SELECT COUNT(*) FROM parent_links WHERE status = 'active'"),
                    'links_waiting': one("SELECT COUNT(*) FROM parent_links WHERE status = 'pending'"),
                    'paused': one(f"SELECT COUNT(*) FROM child_pause WHERE until IS NULL OR {_dt('until')} > datetime('now')"),
                    'deactivated': one('SELECT COUNT(*) FROM account_state WHERE deactivated = 1'),
                    'suspended': one('SELECT COUNT(*) FROM account_state WHERE suspended = 1')}
        _dash_section(out, 'support', support)

        # ---------- needs your action ----------
        def action():
            pay = conn.execute("SELECT COUNT(*), MIN(" + _dt('created_at') + ") FROM plan_payments WHERE status = 'pending'").fetchone()
            tpay = one("SELECT COUNT(*) FROM tutoring_payments WHERE status = 'pending'")
            urgent = one("SELECT COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') != 'resolved' AND priority IN ('high', 'urgent')")
            open_ = one("SELECT COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') != 'resolved'")
            reports = one("SELECT COUNT(*) FROM message_reports WHERE COALESCE(status, 'open') = 'open'")
            hidden = one('SELECT COUNT(*) FROM (SELECT opinion_id FROM opinion_reports GROUP BY opinion_id HAVING COUNT(DISTINCT user_id) >= ?)', (OPINION_HIDE_AT,))
            review = one("SELECT COUNT(*) FROM tutoring_sessions WHERE status = 'review'")
            failed = one(f"SELECT COUNT(*) FROM account_events WHERE kind = 'failed' AND {_dt('created_at')} >= datetime('now', '-1 days')")
            return [
                {'key': 'payments', 'n': pay[0] + tpay, 'since': pay[1], 'level': 'red', 'href': '/admin-payments',
                 'text': 'payment waiting to be confirmed' if pay[0] + tpay == 1 else 'payments waiting to be confirmed',
                 'zero': 'No payments waiting'},
                {'key': 'tickets', 'n': urgent, 'extra': open_, 'level': 'red', 'href': '/admin_support',
                 'text': 'urgent support ticket' if urgent == 1 else 'urgent support tickets', 'zero': 'No urgent tickets'},
                {'key': 'reports', 'n': reports + hidden, 'level': 'amber', 'href': '/admin-reviews',
                 'text': 'reported message or tip to review' if reports + hidden == 1 else 'reported messages and tips to review',
                 'zero': 'No reports waiting'},
                {'key': 'sessions', 'n': review, 'level': 'amber', 'href': '/admin-payments?tab=missed',
                 'text': 'tutoring session to check' if review == 1 else 'tutoring sessions to check', 'zero': 'No sessions to check'},
                {'key': 'files', 'n': len(_res_missing_ids(conn)), 'level': 'amber', 'href': '/admin_resources#all',
                 'text': 'resource file missing' if len(_res_missing_ids(conn)) == 1 else 'resource files missing', 'zero': 'All resource files present'},
                {'key': 'signins', 'n': failed, 'level': 'blue', 'href': '/admin-activity',
                 'text': 'failed sign-in in 24 hours' if failed == 1 else 'failed sign-ins in 24 hours', 'zero': 'No failed sign-ins today'},
            ]
        _dash_section(out, 'action', action)

        # ---------- recent activity ----------
        def activity():
            items = []
            for at, act, tt, tid, detail, fn, ln in conn.execute(
                    """SELECT l.created_at, l.action, l.target_type, l.target_id, l.detail, u.firstname, u.lastname
                       FROM admin_log l LEFT JOIN users u ON u.id = l.admin_id ORDER BY l.id DESC LIMIT 8"""):
                items.append({'at': at, 'who': f"{fn or ''} {ln or ''}".strip() or 'An admin',
                              'what': ADMIN_LOG_LABELS.get(act, (act or '').replace('_', ' ')), 'kind': (act or '').split('_')[0],
                              'detail': str(detail or '')[:120]})
            today = one(f"SELECT COUNT(*) FROM users u WHERE {_dt('u.joined_at')} >= date('now')")
            return {'log': items, 'joined_today': today}
        _dash_section(out, 'activity', activity)

        # ---------- system ----------
        def system():
            try:
                db = os.path.getsize('users.db')
            except OSError:
                db = None
            ok = one(f"SELECT COUNT(*) FROM account_events WHERE kind IN ('signin', 'signin_new') AND {_dt('created_at')} >= datetime('now', '-1 days')")
            failed = one(f"SELECT COUNT(*) FROM account_events WHERE kind = 'failed' AND {_dt('created_at')} >= datetime('now', '-1 days')")
            return {'db': db, 'uploads': one('SELECT COALESCE(SUM(file_size), 0) FROM resources'),
                    'signins_ok': ok, 'signins_failed': failed, 'payments_ready': bool(_payments_ready())}
        _dash_section(out, 'system', system)
        return jsonify(out)
    finally:
        conn.close()


@app.route('/api/admin/dashboard/users')
def admin_dashboard_users():
    """For the overview: the counts, plus 10 newest accounts (or up to 20 search results). Never the whole list."""
    if session.get('role') != 'admin' or 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    conn = sqlite3.connect('users.db')
    try:
        q = request.args.get('q', '')
        return jsonify({'success': True, 'users': _admin_recent_users(conn, q, 20 if q.strip() else 10), **_admin_dash_stats(conn)})
    finally:
        conn.close()

@app.route('/profile')
def profile():
    """The logged-in user's own profile page."""
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if session.get('role') == 'parent':
        return redirect('/parent-settings')     # parents have no profile on Eschool: their details live in Settings
    ctx = build_profile_context(session['user_id'])
    if ctx is None:
        session.clear()
        return redirect(url_for('login'))

    return render_profile(ctx)

