@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'GET':
        redirect_response = redirect_if_logged_in()
        if redirect_response:
            return redirect_response

    if request.method == 'POST':
        firstname = request.form['firstname']
        lastname = request.form['lastname']
        email = (request.form['email'] or '').strip()
        password = request.form['password']
        country = _clean_country(request.form.get('country')) or None

        # the same rules the sign-up page shows (it can be bypassed, so they're checked here too)
        pw_problem = _password_problem(password)
        if pw_problem:
            return render_template('Home/register.html', message=pw_problem)
        if 'confirm_password' in request.form and request.form.get('confirm_password') != password:
            return render_template('Home/register.html', message='The two passwords don\'t match. Please type them again.')

        chosen_role = (request.form.get('role') or '').strip().lower()
        if chosen_role == 'teacher':
            role = 'teacher'
        elif chosen_role == 'parent':
            role = 'parent'
        else:
            role = 'student'      # learner (and anything unexpected)

        conn = sqlite3.connect('users.db', timeout=10)
        try:
            cursor = conn.cursor()
            cursor.execute('''
                INSERT INTO users (firstname, lastname, email, password, role, country)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (firstname, lastname, email, hash_password(password), role, country))
            conn.commit()
            new_id = cursor.lastrowid
            _mark_joined(conn, new_id)
        except sqlite3.IntegrityError:
            conn.rollback()
            return render_template(
                'Home/register.html',
                message='An account with this email already exists. Please log in or use a different email.'
            )
        finally:
            conn.close()

        # signed in straight away: no typing the email and password again
        session.clear()
        session['user_id'] = new_id
        session['firstname'] = firstname
        session['lastname'] = lastname
        session['email'] = email
        session['role'] = role
        session['country'] = country
        account_on_login(new_id, notify=False, method='signup')
        try:
            _c = sqlite3.connect('users.db'); note_password(_c, new_id, password, changed=True, email=email, name=firstname); _c.commit(); _c.close()
        except sqlite3.Error:
            pass
        if role == 'student':
            return redirect('/welcome')          # 3 quick steps: grade, dream career, badge picture
        return redirect(url_for(home_endpoint_for_role(role)))

    return render_template('Home/register.html')


def _password_problem(password):
    """None if the password follows the sign-up rules, else what's missing."""
    if not 8 <= len(password or '') <= 128:
        return 'Please choose a password of at least 8 characters.'
    missing = []
    if not re.search(r'[A-Z]', password):
        missing.append('an uppercase letter')
    if not re.search(r'[0-9]', password):
        missing.append('a number')
    if not re.search(r'[^A-Za-z0-9]', password):
        missing.append('a special character (like ! or #)')
    if missing:
        return 'Your password needs ' + ', '.join(missing[:-1]) + (' and ' if len(missing) > 1 else '') + missing[-1] + '.'
    return None


