@app.context_processor
def inject_user():
    avatar_url = None
    if 'user_id' in session:
        conn = sqlite3.connect('users.db')
        cursor = conn.cursor()
        cursor.execute('SELECT avatar_filename FROM users WHERE id = ?', (session['user_id'],))
        row = cursor.fetchone()
        conn.close()
        if row:   # learners always get their badge picture, others their photo if they have one
            avatar_url = get_avatar_url(session['user_id'], row[0])

    country_name = globals().get('PROFILE_COUNTRIES', {}).get((session.get('country') or '').upper(), '')
    return dict(
        country_name=country_name,          # e.g. 'Kenya', 'Nigeria' (empty if not set)
        register_countries=register_countries,
        # Learners only: ids of the courses for their country (dashboard, progress
        # and search show only these). None for teachers/parents = no filtering.
        my_course_ids=(_course_ids(_clean_country(session.get('country')))
                       if session.get('user_id') and session.get('role', 'student') == 'student' else None),
        firstname=session.get('firstname'),
        lastname=session.get('lastname'),
        user_id=session.get('user_id'),
        role=session.get('role'),
        country=session.get('country'),
        avatar_url=avatar_url,
        quote_text=get_daily_quote()['text'],
        quote_author=get_daily_quote()['author'],
        # The LOGGED-IN user, for the page layouts (header, menus). Pages like
        # /profile/<id> pass their own firstname/lastname/avatar_url for the
        # person being viewed, so the layouts must use `me` instead.
        me=dict(
            id=session.get('user_id'),
            firstname=session.get('firstname') or '',
            lastname=session.get('lastname') or '',
            role=session.get('role'),
            country=session.get('country'),
            avatar_url=avatar_url,
        )
    )

