@app.route('/logout', methods=['GET', 'POST'])
def logout():
    # The menus send a POST. An old-style GET link still works from Eschool's own pages,
    # but not from another website (e.g. a hidden image), which used to sign people out.
    if request.method == 'GET' and request.headers.get('Sec-Fetch-Site') == 'cross-site':
        return redirect('/')
    if session.get('dev'):
        try:
            conn = sqlite3.connect('users.db')
            _security_tables(conn)
            conn.execute('UPDATE account_devices SET ended = 1 WHERE token = ?', (session['dev'],))
            conn.commit()
            conn.close()
        except sqlite3.Error:
            pass
    session.clear()
    response = redirect(url_for('login'))
    response.delete_cookie('session')
    response.headers['Cache-Control'] = 'no-store'
    return response

# ============ MESSAGING: USER SEARCH ============

@app.route('/messages/search_users', methods=['GET'])
def search_users():
    """Search existing accounts by name for the messages page."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    q = request.args.get('q', '').strip()[:60]
    if len(q) < 2:                     # one letter at a time would list everyone
        return jsonify([])
    if _reset_rate_limited(f'msg-search:{session["user_id"]}', limit=40, window=60):
        return jsonify({'success': False, 'message': 'Too many searches. Wait a moment and try again.'}), 429

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    like_term = f'%{q}%'
    _privacy_table(conn)
    _account_table(conn)
    cursor.execute('''
        SELECT id, firstname, lastname, avatar_filename, COALESCE(role, 'student')
        FROM users
        WHERE id != ?
          AND id NOT IN (SELECT user_id FROM privacy_settings WHERE searchable = 0)
          AND id NOT IN (SELECT user_id FROM account_state WHERE deactivated = 1)
          AND (
              firstname LIKE ?
              OR lastname LIKE ?
              OR (firstname || ' ' || lastname) LIKE ?
          )
        ORDER BY firstname, lastname
        LIMIT 80
    ''', (session['user_id'], like_term, like_term, like_term))

    # only people this account is allowed to message (their 'Who can message me' choice, blocks, parental controls)
    rows = [r for r in cursor.fetchall() if can_message(conn, session['user_id'], session.get('role'), r[0])[0]][:20]
    conn.close()

    results = []
    for row in rows:
        user_id, firstname, lastname, avatar_filename, role = row
        firstname = (firstname or '').strip()
        lastname = (lastname or '').strip()
        full_name = f"{firstname} {lastname}".strip()

        if not full_name:
            continue

        initial = (firstname[:1] or lastname[:1]).upper()

        results.append({
            'id': user_id,
            'name': full_name,
            'avatar': initial,
            # The account's real uploaded profile picture, if they have
            # one — the messages.html frontend shows this instead of the
            # initials badge whenever it's present.
            'avatar_url': get_avatar_url(user_id, avatar_filename),
            'role': role,              # student | teacher | parent | admin
            'online': False,
            'lastSeen': ''
        })

    return jsonify(results)


@app.route('/messages/user/<int:other_user_id>', methods=['GET'])
def message_user_info(other_user_id):
    """Name and picture for one account, so /messages?user=<id> (e.g. the
    Message button on a profile) can open a brand-new chat."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if other_user_id == session['user_id']:
        return jsonify({'success': False, 'message': 'That is your own account'}), 400

    conn = sqlite3.connect('users.db')
    row = conn.execute('SELECT id, firstname, lastname, avatar_filename FROM users WHERE id = ?',
                       (other_user_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify({'success': False, 'message': 'User not found'}), 404
    me = session['user_id']
    _messages_tables(conn)
    blocked_by_me = bool(conn.execute('SELECT 1 FROM message_blocks WHERE blocker_id = ? AND blocked_id = ?', (me, other_user_id)).fetchone())
    muted = _is_muted(conn, me, other_user_id)
    allowed, why = can_message(conn, me, session.get('role'), other_user_id)
    conn.close()

    firstname = (row[1] or '').strip()
    lastname = (row[2] or '').strip()
    name = f"{firstname} {lastname}".strip() or 'Eschool user'
    return jsonify({
        'success': True,
        'user': {
            'id': row[0],
            'name': name,
            'avatar': (firstname[:1] or lastname[:1] or '?').upper(),
            'avatar_url': get_avatar_url(row[0], row[3]),
            'online': False,
            'lastSeen': ''
        },
        'blocked': blocked_by_me, 'muted': muted, 'can_message': allowed, 'reason': '' if allowed else why
    })


def _msg_other(other_user_id):
    if 'user_id' not in session:
        return None, (jsonify({'success': False, 'message': 'Authentication required'}), 401)
    if other_user_id == session['user_id']:
        return None, (jsonify({'success': False, 'message': 'That is your own account.'}), 400)
    conn = sqlite3.connect('users.db')
    if not conn.execute('SELECT 1 FROM users WHERE id = ?', (other_user_id,)).fetchone():
        conn.close()
        return None, (jsonify({'success': False, 'message': 'User not found'}), 404)
    _messages_tables(conn)
    return conn, None


@app.route('/messages/block/<int:other_user_id>', methods=['POST', 'DELETE'])
def message_block(other_user_id):
    """Block (POST) or unblock (DELETE): a blocked person can't message or call you, and you can't message them."""
    conn, err = _msg_other(other_user_id)
    if err:
        return err
    try:
        if request.method == 'POST':
            conn.execute('INSERT OR IGNORE INTO message_blocks (blocker_id, blocked_id, created_at) VALUES (?, ?, ?)',
                         (session['user_id'], other_user_id, _iso(datetime.now(timezone.utc))))
        else:
            conn.execute('DELETE FROM message_blocks WHERE blocker_id = ? AND blocked_id = ?', (session['user_id'], other_user_id))
        conn.commit()
        return jsonify({'success': True, 'blocked': request.method == 'POST'})
    finally:
        conn.close()


@app.route('/messages/mute/<int:other_user_id>', methods=['POST', 'DELETE'])
def message_mute(other_user_id):
    """Mute (POST) or unmute (DELETE): messages still arrive, but without notifications."""
    conn, err = _msg_other(other_user_id)
    if err:
        return err
    try:
        if request.method == 'POST':
            conn.execute('INSERT OR IGNORE INTO message_mutes (user_id, muted_id, created_at) VALUES (?, ?, ?)',
                         (session['user_id'], other_user_id, _iso(datetime.now(timezone.utc))))
        else:
            conn.execute('DELETE FROM message_mutes WHERE user_id = ? AND muted_id = ?', (session['user_id'], other_user_id))
        conn.commit()
        return jsonify({'success': True, 'muted': request.method == 'POST'})
    finally:
        conn.close()


@app.route('/messages/report/<int:other_user_id>', methods=['POST'])
def message_report(other_user_id):
    """Report a person. The last 20 messages between you are attached for Eschool staff to review,
    and staff are notified. {"reason": "...", "block": true} also blocks them."""
    conn, err = _msg_other(other_user_id)
    if err:
        return err
    try:
        me = session['user_id']
        if _reset_rate_limited(f'msg-report:{me}', limit=10, window=3600):
            return jsonify({'success': False, 'message': 'Too many reports. Please try again later.'}), 429
        data = request.get_json(silent=True) or {}
        reason = str(data.get('reason') or '').strip()[:500]
        rows = conn.execute('''SELECT id, sender_id, text, timestamp FROM messages
                               WHERE (sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?)
                               ORDER BY id DESC LIMIT 20''', (me, other_user_id, other_user_id, me)).fetchall()
        attached = [{'id': r[0], 'from': r[1], 'text': r[2], 'at': to_iso_utc(r[3])} for r in reversed(rows)]
        now = _iso(datetime.now(timezone.utc))
        conn.execute('INSERT INTO message_reports (reporter_id, reported_id, reason, messages, created_at) VALUES (?, ?, ?, ?, ?)',
                     (me, other_user_id, reason, json.dumps(attached), now))
        if data.get('block'):
            conn.execute('INSERT OR IGNORE INTO message_blocks (blocker_id, blocked_id, created_at) VALUES (?, ?, ?)', (me, other_user_id, now))
        for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
            create_notification(conn, admin_id, 'A chat was reported',
                                'A learner reported someone in Messages. Please review it.', icon='fa-flag', color='red', category='messages')
        conn.commit()
        return jsonify({'success': True, 'blocked': bool(data.get('block'))})
    finally:
        conn.close()


@app.route('/messages/send', methods=['POST'])
def send_message():
    """Send a message to a specific user or broadcast to all users."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    data = request.get_json(silent=True) or {}
    receiver_id = data.get('receiver_id')
    text = (data.get('text') or '').strip()
    is_broadcast = data.get('is_broadcast', False)

    if not text:
        return jsonify({'success': False, 'message': 'Text is required'}), 400
    if len(text) > 2000:
        return jsonify({'success': False, 'message': 'Please keep a message under 2,000 characters.'}), 400

    sender_id = session['user_id']
    if not is_broadcast and _reset_rate_limited(f'msg-send:{sender_id}', limit=30, window=60):
        return jsonify({'success': False, 'message': 'You’re sending messages very fast. Wait a moment, then try again.'}), 429
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    if is_broadcast:
        # Check if user is admin
        cursor.execute('SELECT role FROM users WHERE id = ?', (sender_id,))
        user = cursor.fetchone()
        if not user or user[0] != 'admin':
            conn.close()
            return jsonify({'success': False, 'message': 'Only admins can broadcast'}), 403

        # Send to all users except the sender
        cursor.execute('SELECT id FROM users WHERE id != ?', (sender_id,))
        all_users = cursor.fetchall()
        
        if not all_users:
            conn.close()
            return jsonify({'success': False, 'message': 'No other users to send to'}), 404
        
        broadcast_count = 0
        for user_row in all_users:
            recipient_id = user_row[0]

            cursor.execute('''
                INSERT INTO messages (sender_id, receiver_id, text, is_read, is_broadcast)
                VALUES (?, ?, ?, 0, 1)
            ''', (sender_id, recipient_id, text))

            # Every broadcast recipient also gets a bell notification
            create_notification(
                conn,
                user_id=recipient_id,
                title='New announcement',
                message=text[:120],
                icon='fa-bullhorn',
                color='blue',
                category='announcements'
            )

            broadcast_count += 1
        
        conn.commit()
        conn.close()
        
        return jsonify({
            'success': True, 
            'message': f'Broadcast sent to {broadcast_count} users',
            'broadcast_count': broadcast_count
        })

    else:
        # Send to a specific user
        if not receiver_id:
            conn.close()
            return jsonify({'success': False, 'message': 'receiver_id is required'}), 400

        cursor.execute('SELECT id FROM users WHERE id = ?', (receiver_id,))
        if not cursor.fetchone():
            conn.close()
            return jsonify({'success': False, 'message': 'Recipient not found'}), 404
        if str(receiver_id) == str(sender_id):
            conn.close()
            return jsonify({'success': False, 'message': 'You can’t send a message to yourself.'}), 400

        allowed, reason = can_message(conn, sender_id, session.get('role'), int(receiver_id))
        if not allowed:
            conn.close()
            return jsonify({'success': False, 'message': reason}), 403

        cursor.execute('''
            INSERT INTO messages (sender_id, receiver_id, text, is_read, is_broadcast)
            VALUES (?, ?, ?, 0, 0)
        ''', (sender_id, receiver_id, text))

        message_id = cursor.lastrowid

        # Direct messages also notify the recipient (unless they muted the sender)
        if not _is_muted(conn, int(receiver_id), sender_id):
            cursor.execute('SELECT firstname, lastname FROM users WHERE id = ?', (sender_id,))
            sender_row = cursor.fetchone()
            sender_name = f"{sender_row[0]} {sender_row[1]}".strip() if sender_row else 'Someone'
            create_notification(
                conn,
                user_id=receiver_id,
                title=f'New message from {sender_name}',
                message=text[:120],
                icon='fa-envelope',
                color='green',
                category='messages'
            )

        conn.commit()
        cursor.execute('SELECT id, sender_id, receiver_id, text, timestamp, is_read, is_broadcast FROM messages WHERE id = ?', (message_id,))
        row = cursor.fetchone()
        conn.close()

        message = {
            'id': row[0],
            'sender_id': row[1],
            'receiver_id': row[2],
            'text': row[3],
            'timestamp': to_iso_utc(row[4]),
            'read': bool(row[5]),
            'is_broadcast': bool(row[6]),
            'kind': 'text'
        }

        return jsonify({'success': True, 'message': message})


@app.route('/messages/conversation/<int:other_user_id>', methods=['GET'])
def get_conversation(other_user_id):
    """Return the full message thread between the logged-in user and another specific user."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    my_id = session['user_id']

    conn = sqlite3.connect('users.db')
    _messages_tables(conn)
    cursor = conn.cursor()

    # ?after=ID: only newer messages (polling); ?limit=N (max 200), with ?before=ID for older ones.
    # No parameters: the whole thread, as before.
    def _int(name):
        try:
            return max(0, int(request.args.get(name) or 0))
        except ValueError:
            return 0
    after, before, limit = _int('after'), _int('before'), min(_int('limit'), 200)
    base = '''SELECT id, sender_id, receiver_id, text, timestamp, is_read, is_broadcast, COALESCE(kind, 'text')
                FROM messages WHERE ((sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?))'''
    params = [my_id, other_user_id, other_user_id, my_id]
    if after:
        cursor.execute(base + ' AND id > ? ORDER BY id ASC LIMIT 500', params + [after])
        rows = cursor.fetchall()
    elif limit:
        if before:
            base += ' AND id < ?'; params.append(before)
        cursor.execute(base + ' ORDER BY id DESC LIMIT ?', params + [limit])
        rows = list(reversed(cursor.fetchall()))
    else:
        cursor.execute(base + ' ORDER BY timestamp ASC, id ASC', params)
        rows = cursor.fetchall()

    # Mark messages from the other user as read
    cursor.execute('''
        UPDATE messages SET is_read = 1
        WHERE sender_id = ? AND receiver_id = ? AND is_read = 0
    ''', (other_user_id, my_id))
    conn.commit()
    conn.close()

    thread = [{
        'id': row[0],
        'sender_id': row[1],
        'receiver_id': row[2],
        'text': row[3],
        'timestamp': to_iso_utc(row[4]),
        'read': bool(row[5]),
        'is_broadcast': bool(row[6]),
        'kind': row[7] or 'text'          # 'call' = a call record written by the server, 'file' = a shared document
    } for row in rows]
    file_ids = [m['id'] for m in thread if m['kind'] == 'file']
    if file_ids:
        fconn = sqlite3.connect('users.db')
        try:
            info = _message_files_info(fconn, file_ids)
        finally:
            fconn.close()
        for m in thread:
            if m['id'] in info:
                m['file'] = info[m['id']]

    return jsonify(thread)


# ============ DOCUMENTS IN MESSAGES ============
# A paperclip next to the message box sends a file (PDF, Word, Excel, PowerPoint, pictures, text).
# Files are kept outside static/ under a random name, and only the two people in the chat
# (and admins, for reports) can download them. The same blocks and parent rules as messages apply.
MESSAGE_FILE_MAX = 10 * 1024 * 1024
MESSAGE_FILE_TYPES = {
    'pdf': 'application/pdf', 'doc': 'application/msword',
    'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'xls': 'application/vnd.ms-excel', 'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'ppt': 'application/vnd.ms-powerpoint', 'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'txt': 'text/plain', 'csv': 'text/csv', 'odt': 'application/vnd.oasis.opendocument.text',
    'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'gif': 'image/gif', 'webp': 'image/webp',
}


def _message_files_dir():
    d = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'uploads', 'message_files')
    os.makedirs(d, exist_ok=True)
    return d


def _message_files_table(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS message_files (
        message_id INTEGER PRIMARY KEY, stored TEXT NOT NULL, name TEXT NOT NULL, size INTEGER NOT NULL,
        mime TEXT, created_at TEXT NOT NULL)''')


def _file_size_text(n):
    return f"{n / 1024 / 1024:.1f} MB" if n >= 1024 * 1024 else f"{max(1, round(n / 1024))} KB"


def _message_files_info(conn, ids):
    _message_files_table(conn)
    ids = [int(i) for i in ids][:500]
    if not ids:
        return {}
    rows = conn.execute(f"SELECT message_id, name, size, mime FROM message_files WHERE message_id IN ({','.join('?' * len(ids))})", ids).fetchall()
    return {r[0]: {'name': r[1], 'size': r[2], 'size_text': _file_size_text(r[2]), 'mime': r[3] or '',
                   'ext': (r[1].rsplit('.', 1)[-1].lower() if '.' in r[1] else ''), 'url': f'/messages/file/{r[0]}'} for r in rows}


@app.route('/messages/send-file', methods=['POST'])
def send_message_file():
    """multipart form: receiver_id, file. Sends the file as a message."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    sender_id = session['user_id']
    try:
        receiver_id = int(request.form.get('receiver_id') or 0)
    except ValueError:
        receiver_id = 0
    f = request.files.get('file')
    if not receiver_id or not f or not f.filename:
        return jsonify({'success': False, 'message': 'Choose a file to send.'}), 400
    if receiver_id == sender_id:
        return jsonify({'success': False, 'message': 'You can’t send a file to yourself.'}), 400
    name = secure_filename(f.filename) or 'file'
    ext = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
    if ext not in MESSAGE_FILE_TYPES:
        return jsonify({'success': False, 'message': 'You can send PDF, Word, Excel, PowerPoint, text files and pictures.'}), 400
    data = f.read(MESSAGE_FILE_MAX + 1)
    if len(data) > MESSAGE_FILE_MAX:
        return jsonify({'success': False, 'message': 'Files can be up to 10 MB.'}), 400
    if not data:
        return jsonify({'success': False, 'message': 'That file is empty.'}), 400
    if _reset_rate_limited(f'msg-file:{sender_id}', limit=20, window=3600):
        return jsonify({'success': False, 'message': 'You’ve sent a lot of files. Please wait a while and try again.'}), 429
    conn = sqlite3.connect('users.db')
    try:
        if not conn.execute('SELECT 1 FROM users WHERE id = ?', (receiver_id,)).fetchone():
            return jsonify({'success': False, 'message': 'Recipient not found'}), 404
        allowed, reason = can_message(conn, sender_id, session.get('role'), receiver_id)
        if not allowed:
            return jsonify({'success': False, 'message': reason}), 403
        _messages_tables(conn)
        _message_files_table(conn)
        stored = uuid.uuid4().hex + '.' + ext
        with open(os.path.join(_message_files_dir(), stored), 'wb') as out:
            out.write(data)
        text = f"📎 {name} · {_file_size_text(len(data))}"
        cur = conn.execute("INSERT INTO messages (sender_id, receiver_id, text, is_read, is_broadcast, kind) VALUES (?, ?, ?, 0, 0, 'file')",
                           (sender_id, receiver_id, text))
        mid = cur.lastrowid
        conn.execute('INSERT INTO message_files (message_id, stored, name, size, mime, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                     (mid, stored, name, len(data), MESSAGE_FILE_TYPES[ext], _iso(_utc_now())))
        if not _is_muted(conn, receiver_id, sender_id):
            create_notification(conn, user_id=receiver_id,
                                title=f"New file from {_full_name(session.get('firstname'), session.get('lastname'), 'someone')}",
                                message=name[:120], icon='fa-paperclip', color='green', category='messages')
        conn.commit()
        row = conn.execute('SELECT id, sender_id, receiver_id, text, timestamp, is_read FROM messages WHERE id = ?', (mid,)).fetchone()
        return jsonify({'success': True, 'message': {
            'id': row[0], 'sender_id': row[1], 'receiver_id': row[2], 'text': row[3], 'timestamp': to_iso_utc(row[4]),
            'read': bool(row[5]), 'is_broadcast': False, 'kind': 'file', 'file': _message_files_info(conn, [mid]).get(mid)}})
    finally:
        conn.close()


@app.route('/messages/files')
def message_files_list():
    """?ids=1,2,3 or ?with=<user id>: the files in the signed-in person's chats (for the chat bubbles)."""
    if 'user_id' not in session:
        return jsonify({'success': False}), 401
    me = session['user_id']
    conn = sqlite3.connect('users.db')
    try:
        _messages_tables(conn)
        _message_files_table(conn)
        if request.args.get('with'):
            try:
                other = int(request.args['with'])
            except ValueError:
                return jsonify({'files': []})
            rows = conn.execute('''SELECT id, text FROM messages WHERE kind = 'file' AND
                                   ((sender_id = ? AND receiver_id = ?) OR (sender_id = ? AND receiver_id = ?)) ORDER BY id''',
                                (me, other, other, me)).fetchall()
        else:
            ids = [int(x) for x in re.findall(r'\d+', request.args.get('ids', ''))][:300]
            rows = conn.execute(f'''SELECT id, text FROM messages WHERE kind = 'file' AND (sender_id = ? OR receiver_id = ?)
                                    AND id IN ({','.join('?' * len(ids)) or 'NULL'})''', [me, me] + ids).fetchall() if ids else []
        info = _message_files_info(conn, [r[0] for r in rows])
        return jsonify({'files': [dict(info[r[0]], id=r[0], text=r[1]) for r in rows if r[0] in info]})
    finally:
        conn.close()


@app.route('/messages/file/<int:mid>')
def message_file_download(mid):
    if 'user_id' not in session:
        return redirect(url_for('login'))
    conn = sqlite3.connect('users.db')
    try:
        _message_files_table(conn)
        row = conn.execute('''SELECT f.stored, f.name, f.mime, m.sender_id, m.receiver_id FROM message_files f
                              JOIN messages m ON m.id = f.message_id WHERE f.message_id = ?''', (mid,)).fetchone()
    finally:
        conn.close()
    if not row or session['user_id'] not in (row[3], row[4]) and session.get('role') != 'admin':
        abort(404)
    resp = send_from_directory(_message_files_dir(), row[0], as_attachment=True, download_name=row[1], mimetype=row[2] or 'application/octet-stream')
    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['Cache-Control'] = 'private, no-store'
    return resp


MESSAGE_FILES_JS = r"""/* Eschool: documents in messages. Adds a paperclip next to the message box and turns file
   messages into download cards. Works on every Messages page (learner, parent, teacher). */
(function () {
    var input = document.getElementById('messageInput');
    if (!input || window.__esFiles) return;
    window.__esFiles = true;
    var ACCEPT = '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.odt,.txt,.csv,.png,.jpg,.jpeg,.gif,.webp';
    var MAX = 10 * 1024 * 1024;
    var known = {};          // message id -> file
    var byChat = {};         // other user id -> [file messages in order], for pages without data-mid
    var other = null;

    var css = document.createElement('style');
    css.textContent =
        '.es-attach{flex:0 0 auto;width:42px;height:42px;border-radius:12px;border:1px solid #dfe3ec;background:#fff;color:#4b5468;' +
        'display:inline-grid;place-items:center;cursor:pointer;font-size:16px;margin-right:6px;transition:border-color .15s,color .15s}' +
        '.es-attach:hover:not(:disabled){border-color:#4361ee;color:#4361ee}.es-attach:disabled{opacity:.45;cursor:not-allowed}' +
        '.es-attach.busy i{animation:esSpin 1s linear infinite}@keyframes esSpin{to{transform:rotate(360deg)}}' +
        '.es-file{display:flex;align-items:center;gap:10px;min-width:210px;max-width:300px;padding:9px 11px;margin:2px 0 4px;border-radius:12px;' +
        'background:rgba(255,255,255,.92);border:1px solid rgba(15,23,42,.1);color:#1e293b!important;text-decoration:none!important;text-align:left}' +
        '.es-file:hover{border-color:#4361ee}.es-file .ic{flex:0 0 auto;width:36px;height:36px;border-radius:9px;display:grid;place-items:center;color:#fff;font-size:15px}' +
        '.es-file .tx{min-width:0;flex:1}.es-file b{display:block;font-size:.86rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}' +
        '.es-file small{display:block;font-size:.74rem;color:#64748b}.es-file .dl{flex:0 0 auto;color:#4361ee;font-size:15px}' +
        '.es-file-note{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:9999;background:#1e293b;color:#fff;padding:10px 16px;' +
        'border-radius:10px;font:500 14px system-ui,sans-serif;box-shadow:0 10px 30px rgba(0,0,0,.25);max-width:90vw}';
    document.head.appendChild(css);

    function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
    function say(t) {
        var n = document.createElement('div'); n.className = 'es-file-note'; n.setAttribute('role', 'status'); n.textContent = t;
        document.body.appendChild(n); setTimeout(function () { n.remove(); }, 4000);
    }
    function look(ext) {
        if (ext === 'pdf') return ['fa-file-pdf', '#dc2626'];
        if (ext === 'doc' || ext === 'docx' || ext === 'odt') return ['fa-file-word', '#2563eb'];
        if (ext === 'xls' || ext === 'xlsx' || ext === 'csv') return ['fa-file-excel', '#16a34a'];
        if (ext === 'ppt' || ext === 'pptx') return ['fa-file-powerpoint', '#ea580c'];
        if (/^(png|jpe?g|gif|webp)$/.test(ext)) return ['fa-file-image', '#7c3aed'];
        return ['fa-file-lines', '#64748b'];
    }
    function card(f) {
        var l = look(f.ext);
        return '<a class="es-file" href="' + esc(f.url) + '" download title="Download ' + esc(f.name) + '">' +
            '<span class="ic" style="background:' + l[1] + '"><i class="fas ' + l[0] + '" aria-hidden="true"></i></span>' +
            '<span class="tx"><b>' + esc(f.name) + '</b><small>' + esc(f.size_text) + ' · Download</small></span>' +
            '<span class="dl"><i class="fas fa-download" aria-hidden="true"></i></span></a>';
    }

    /* who the open chat is with: the page's ?user= or the chat it last loaded */
    function chatWith() {
        try { var u = Number(new URL(location.href).searchParams.get('user')); if (u) return u; } catch (e) {}
        return other;
    }
    var realFetch = window.fetch;
    window.fetch = function (u) {
        try { var m = String((u && u.url) || u).match(/\/messages\/conversation\/(\d+)/); if (m) other = Number(m[1]); } catch (e) {}
        return realFetch.apply(this, arguments);
    };

    /* ---- the paperclip ---- */
    var btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'es-attach'; btn.title = 'Send a document'; btn.setAttribute('aria-label', 'Send a document');
    btn.innerHTML = '<i class="fas fa-paperclip" aria-hidden="true"></i>';
    var pick = document.createElement('input');
    pick.type = 'file'; pick.accept = ACCEPT; pick.hidden = true;
    input.parentNode.insertBefore(btn, input); input.parentNode.insertBefore(pick, input);
    function sync() { btn.disabled = input.disabled || btn.classList.contains('busy'); }
    sync(); new MutationObserver(sync).observe(input, { attributes: true, attributeFilter: ['disabled'] });
    btn.addEventListener('click', function () { if (!chatWith()) { say('Open a chat first.'); return; } pick.value = ''; pick.click(); });
    pick.addEventListener('change', function () {
        var f = pick.files && pick.files[0], to = chatWith();
        if (!f || !to) return;
        if (f.size > MAX) { say('Files can be up to 10 MB.'); return; }
        var fd = new FormData(); fd.append('receiver_id', to); fd.append('file', f);
        btn.classList.add('busy'); btn.innerHTML = '<i class="fas fa-spinner" aria-hidden="true"></i>'; sync();
        realFetch('/messages/send-file', { method: 'POST', body: fd, credentials: 'same-origin' })
            .then(function (r) { return r.json().catch(function () { return { success: false, message: 'Could not send the file.' }; }); })
            .then(function (d) {
                if (!d.success) { say(d.message || 'Could not send the file.'); return; }
                if (d.message && d.message.file) known[d.message.id] = d.message.file;
                say('File sent. It shows in the chat in a moment.');
            })
            .catch(function () { say('No connection. The file was not sent.'); })
            .then(function () { btn.classList.remove('busy'); btn.innerHTML = '<i class="fas fa-paperclip" aria-hidden="true"></i>'; sync(); });
    });

    /* ---- file messages become download cards ---- */
    var asking = false, askedChat = {};
    function paint() {
        var need = [];
        document.querySelectorAll('[data-mid]').forEach(function (el) {
            if (el.dataset.esFile) return;
            var id = Number(el.dataset.mid);
            if (el.textContent.indexOf('📎') === -1) return;
            if (known[id]) swap(el, known[id]); else need.push(id);
        });
        if (need.length && !asking) {
            asking = true;
            realFetch('/messages/files?ids=' + need.join(','), { credentials: 'same-origin' }).then(function (r) { return r.json(); })
                .then(function (d) { (d.files || []).forEach(function (f) { known[f.id] = f; }); need.forEach(function (id) { if (!known[id]) known[id] = null; }); })
                .catch(function () {}).then(function () { asking = false; paintKnown(); });
        }
        if (!document.querySelector('[data-mid]')) byText();
    }
    function paintKnown() {
        document.querySelectorAll('[data-mid]').forEach(function (el) { var f = known[Number(el.dataset.mid)]; if (f && !el.dataset.esFile) swap(el, f); });
    }
    function swap(el, f) {
        var walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT), n;
        while ((n = walker.nextNode())) {
            if (n.nodeValue.indexOf('📎') !== -1) {
                var span = document.createElement('span'); span.innerHTML = card(f);
                n.parentNode.replaceChild(span.firstChild, n); el.dataset.esFile = '1'; return;
            }
        }
    }
    /* pages whose bubbles carry no message id: match the file messages of this chat in order */
    function byText() {
        var to = chatWith(); if (!to) return;
        var list = byChat[to];
        if (!list) {
            if (askedChat[to]) return; askedChat[to] = true;
            realFetch('/messages/files?with=' + to, { credentials: 'same-origin' }).then(function (r) { return r.json(); })
                .then(function (d) { byChat[to] = d.files || []; setTimeout(function () { askedChat[to] = false; delete byChat[to]; }, 8000); byText(); })
                .catch(function () { askedChat[to] = false; });
            return;
        }
        var box = document.querySelector('[role="log"]') || document.getElementById('chatMessages') || document.body;
        var used = {}, walker = document.createTreeWalker(box, NodeFilter.SHOW_TEXT), n, hits = [];
        while ((n = walker.nextNode())) if (n.nodeValue.indexOf('📎 ') !== -1 && !(n.parentNode.closest && n.parentNode.closest('.es-file'))) hits.push(n);
        hits.forEach(function (node) {
            var t = node.nodeValue.trim();
            var f = list.filter(function (x, i) { return !used[i] && t.indexOf(x.text) !== -1 && (used[i] = true); })[0];
            if (f) { var span = document.createElement('span'); span.innerHTML = card(f); node.parentNode.replaceChild(span.firstChild, node); }
        });
    }
    var timer = null;
    new MutationObserver(function () { clearTimeout(timer); timer = setTimeout(paint, 120); }).observe(document.body, { childList: true, subtree: true });
    paint();
})();
"""


@app.route('/eschool-files.js')
def eschool_files_script():
    return Response(MESSAGE_FILES_JS, mimetype='application/javascript', headers={'Cache-Control': 'no-cache'})


@app.route('/messages/conversations', methods=['GET'])
def list_conversations():
    """Return every account the logged-in user has exchanged messages with."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    my_id = session['user_id']
    is_admin = session.get('role') == 'admin'

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    # Get all users the user has messaged with
    cursor.execute('''
        SELECT DISTINCT other_id FROM (
            SELECT receiver_id AS other_id FROM messages WHERE sender_id = ?
            UNION
            SELECT sender_id AS other_id FROM messages WHERE receiver_id = ?
        )
    ''', (my_id, my_id))
    other_ids = [row[0] for row in cursor.fetchall()]

    conversations = []
    
    # If admin, add a special broadcast conversation entry
    if is_admin:
        # Count how many broadcast messages the admin has sent
        cursor.execute('''
            SELECT COUNT(*) FROM messages 
            WHERE sender_id = ? AND is_broadcast = 1
        ''', (my_id,))
        broadcast_count = cursor.fetchone()[0]
        
        if broadcast_count > 0:
            # Get the latest broadcast message
            cursor.execute('''
                SELECT text, timestamp FROM messages 
                WHERE sender_id = ? AND is_broadcast = 1
                ORDER BY timestamp DESC LIMIT 1
            ''', (my_id,))
            last_broadcast = cursor.fetchone()
            
            conversations.append({
                'id': -1,  # Special ID for broadcast
                'name': '📢 All Users (Broadcast)',
                'avatar': '📢',
                'avatar_url': None,
                'online': False,
                'lastSeen': '',
                'lastMessage': f'Broadcast: {last_broadcast[0][:50]}...' if last_broadcast else 'Send broadcast to all users',
                'lastTimestamp': to_iso_utc(last_broadcast[1]) if last_broadcast else None,
                'unread': 0,
                'is_broadcast': True
            })

    for other_id in other_ids:
        cursor.execute("SELECT firstname, lastname, avatar_filename, COALESCE(role, 'student') FROM users WHERE id = ?", (other_id,))
        user_row = cursor.fetchone()
        if not user_row:
            continue

        firstname = (user_row[0] or '').strip()
        lastname = (user_row[1] or '').strip()
        avatar_filename = user_row[2]
        full_name = f"{firstname} {lastname}".strip()
        if not full_name:
            continue
        initial = (firstname[:1] or lastname[:1]).upper()

        cursor.execute('''
            SELECT sender_id, text, timestamp
            FROM messages
            WHERE (sender_id = ? AND receiver_id = ?)
               OR (sender_id = ? AND receiver_id = ?)
            ORDER BY timestamp DESC, id DESC
            LIMIT 1
        ''', (my_id, other_id, other_id, my_id))
        last_row = cursor.fetchone()

        last_message = None
        last_timestamp = None
        if last_row:
            prefix = 'You: ' if last_row[0] == my_id else ''
            last_message = f"{prefix}{last_row[1]}"
            last_timestamp = last_row[2]

        cursor.execute('''
            SELECT COUNT(*) FROM messages
            WHERE sender_id = ? AND receiver_id = ? AND is_read = 0
        ''', (other_id, my_id))
        unread = cursor.fetchone()[0]

        conversations.append({
            'id': other_id,
            'name': full_name,
            'avatar': initial,
            # The account's real uploaded profile picture, if they have
            # one — the messages.html frontend shows this instead of the
            # initials badge whenever it's present.
            'avatar_url': get_avatar_url(other_id, avatar_filename),
            'online': False,
            'lastSeen': '',
            'lastMessage': last_message,
            'lastTimestamp': last_timestamp,
            'unread': unread,
            'role': user_row[3],
            'muted': _is_muted(conn, my_id, other_id),
            'blocked': bool(conn.execute('SELECT 1 FROM message_blocks WHERE blocker_id = ? AND blocked_id = ?', (my_id, other_id)).fetchone()),
            'is_broadcast': False
        })

    conn.close()

    # Sort by most recent first
    conversations.sort(key=lambda c: c['lastTimestamp'] or '', reverse=True)

    for c in conversations:
        c['lastTimestamp'] = to_iso_utc(c['lastTimestamp'])

    return jsonify(conversations)

# ============ NOTIFICATIONS ============

@app.route('/notifications', methods=['GET'])
@app.route('/api/notifications', methods=['GET'])
def get_notifications():
    """Return the logged-in user's notifications, newest first (JSON).
      ?limit=N (1-50, default 50)  ?offset=N  ?unread=1 (only unread ones)
    Opened as a page (e.g. "View all notifications"), /notifications goes to the full list in
    Settings > Notifications (parents keep the dashboard with the bell open)."""
    if request.path == '/notifications' and 'text/html' in (request.headers.get('Accept') or '') \
            and request.headers.get('Sec-Fetch-Dest', 'document') == 'document':
        if 'user_id' in session and session.get('role') != 'parent':
            return redirect('/settings#notifications')
        return redirect('/dashboard?notifications=1')
    if 'user_id' not in session:
        return jsonify([])
    try:
        limit = max(1, min(50, int(request.args.get('limit') or 50)))
        offset = max(0, int(request.args.get('offset') or 0))
    except ValueError:
        limit, offset = 50, 0
    only_unread = request.args.get('unread') == '1'

    conn = sqlite3.connect('users.db')
    try:
        fire_live_reminders(conn, session['user_id'])
    except Exception as e:
        print(f"live reminders skipped: {e}")
    _friends_tables(conn)
    try:
        _admin_tables(conn)            # the announcements table, for announcement buttons
        _announce_columns(conn)
        conn.commit()
    except sqlite3.Error as e:
        print(f'announcement columns skipped: {e}')
    cursor = conn.cursor()
    cursor.execute(f'''
        SELECT n.id, n.title, n.message, n.icon, n.color, n.is_read, n.created_at, n.action, n.ref_id,
               fr.status, fr.from_id, an.link, an.link_label
        FROM notifications n
        LEFT JOIN friend_requests fr ON n.action = 'friend_request' AND fr.id = n.ref_id
        LEFT JOIN announcements an ON n.action = 'announcement' AND an.id = n.ref_id
        WHERE n.user_id = ?{' AND n.is_read = 0' if only_unread else ''}
        ORDER BY n.created_at DESC, n.id DESC
        LIMIT ? OFFSET ?
    ''', (session['user_id'], limit, offset))
    rows = cursor.fetchall()
    conn.close()

    notifications = [{
        'id': row[0],
        'title': row[1],
        'message': row[2],
        'icon': row[3],
        'color': row[4],
        'read': bool(row[5]),
        'time': to_iso_utc(row[6]),
        # friend requests get Accept / Decline buttons in the bell
        'action': row[7],
        'ref_id': row[8],
        'request_status': row[9],          # pending | accepted | declined | cancelled
        'from_user_id': row[10],
        # announcements can have a button that opens an Eschool page
        'link': row[11] if row[11] and str(row[11]).startswith('/') and not str(row[11]).startswith('//') else None,
        'link_label': row[12],
    } for row in rows]

    return jsonify(notifications)


@app.route('/notifications/<int:notification_id>/read', methods=['POST'])
def mark_notification_read(notification_id):
    """Mark a single notification as read. Scoped to the logged-in user
    so nobody can mark someone else's notification by guessing an id."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    cursor.execute('''
        UPDATE notifications SET is_read = 1
        WHERE id = ? AND user_id = ?
    ''', (notification_id, session['user_id']))
    conn.commit()
    updated = cursor.rowcount
    conn.close()

    if updated == 0:
        return jsonify({'success': False, 'message': 'Notification not found'}), 404

    return jsonify({'success': True})


@app.route('/api/notification-prefs', methods=['GET', 'POST'])
def api_notification_prefs():
    """
    GET  -> which notifications you get, plus how many you have (total / unread)
    POST -> {"messages": false} switches that kind of notification on/off
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    cats = notify_categories_for(session.get('role'))
    conn = sqlite3.connect('users.db')
    try:
        _notify_prefs_table(conn)
        if request.method == 'POST':
            data = request.get_json(silent=True) or {}
            changed = 0
            for cat, val in data.items():
                if cat in cats and isinstance(val, bool):
                    conn.execute('''INSERT INTO notification_prefs (user_id, category, enabled) VALUES (?, ?, ?)
                                    ON CONFLICT(user_id, category) DO UPDATE SET enabled = excluded.enabled''',
                                 (uid, cat, 1 if val else 0))
                    changed += 1
            if not changed:
                return jsonify({'success': False, 'message': 'Nothing to change.'}), 400
            conn.commit()
        prefs = {cat: notification_enabled(conn, uid, cat) for cat in cats}
        total, unread = conn.execute('SELECT COUNT(*), COALESCE(SUM(CASE WHEN is_read = 0 THEN 1 ELSE 0 END), 0) '
                                     'FROM notifications WHERE user_id = ?', (uid,)).fetchone()
        return jsonify({'success': True, 'prefs': prefs,
                        'categories': [{'key': k, 'desc': v} for k, v in cats.items()],
                        'total': total, 'unread': unread})
    finally:
        conn.close()


