# ============ SUPPORT TICKETS / COMPLAINTS ============

def _complaints_columns(conn):
    """user_seen_reply: when the person who sent the ticket last opened the team's reply ('New reply' badge)."""
    cols = {r[1] for r in conn.execute('PRAGMA table_info(complaints)').fetchall()}
    if cols and 'user_seen_reply' not in cols:
        conn.execute('ALTER TABLE complaints ADD COLUMN user_seen_reply TEXT')
        conn.commit()


def _support_alert(ticket):
    """Tell Eschool staff about a new ticket: a bell notification for every admin, and an
    email to SUPPORT_ALERT_EMAIL (set it in .env) if mail is set up. Sent by the server,
    so no mail keys or addresses are in the page."""
    urgent = ticket.get('priority') == 'urgent' or ticket.get('category') in ('content', 'safety')
    conn = sqlite3.connect('users.db')
    try:
        for (admin_id,) in conn.execute("SELECT id FROM users WHERE role = 'admin'").fetchall():
            create_notification(conn, admin_id, ('URGENT ticket: ' if urgent else 'New ticket: ') + str(ticket.get('subject') or '')[:90],
                                f"#{ticket.get('id')} · {ticket.get('category')} · {ticket.get('priority')}",
                                icon='fa-headset', color='red' if urgent else 'blue', category='announcements')
        conn.commit()
    finally:
        conn.close()
    to = os.environ.get('SUPPORT_ALERT_EMAIL', '').strip()
    if not to or not _mail_ready():
        return
    body = (f"Ticket #{ticket.get('id')} ({ticket.get('category')}, {ticket.get('priority')})\n"
            f"From: {ticket.get('user_name')}\n\n{ticket.get('subject')}\n\n"
            "Open the admin support page to read and answer it.")   # the message itself stays on Eschool
    app_ = app

    def send():
        try:
            with app_.app_context():
                mail.send(Message(subject=('[URGENT] ' if urgent else '') + f"Eschool ticket #{ticket.get('id')}", recipients=[to], body=body))
        except Exception as e:
            print('support alert email:', e)
    threading.Thread(target=send, daemon=True).start()


def _serialize_complaint(row):
    """row layout: id, user_id, subject, description, category, priority, status,
    is_read, response, response_date, created_at, firstname, lastname, email"""
    firstname = (row[11] or '').strip()
    lastname = (row[12] or '').strip()
    full_name = f"{firstname} {lastname}".strip() or 'Unknown User'

    return {
        'id': row[0],
        'user_id': row[1],
        'subject': row[2],
        'description': row[3],
        'category': row[4],
        'priority': row[5],
        'status': row[6],
        'is_read': bool(row[7]),
        'response': row[8],
        'response_date': to_iso_utc(row[9]),
        'created_at': to_iso_utc(row[10]),
        'user_name': full_name,
        'user_email': row[13]
    }


# The admin panel's filter dropdown uses one category set (technical, academic,
# billing, content, account, other) and the student-facing ticket form uses a
# slightly different one (technical, account, course, billing, feature, other).
# Accept the union so neither page's submissions get silently downgraded to "other".
VALID_COMPLAINT_CATEGORIES = {
    'technical', 'academic', 'billing', 'content', 'account', 'other', 'course', 'feature',
    # parent tickets (Parent/parent-support.html)
    'linking', 'payments', 'safety', 'teachers', 'progress',
    # teacher tickets (Teacher/teacher-support.html)
    'uploads', 'live', 'tutoring', 'profile', 'schedule',
}
VALID_COMPLAINT_PRIORITIES = {'low', 'medium', 'high', 'urgent'}
# when a page doesn't ask for a priority, the category decides it (people can't all pick "Urgent")
COMPLAINT_CATEGORY_PRIORITY = {'safety': 'urgent', 'payments': 'high', 'billing': 'high', 'linking': 'medium', 'account': 'medium',
                               'technical': 'medium', 'content': 'high', 'progress': 'low', 'teachers': 'low', 'course': 'low',
                               'feature': 'low', 'other': 'low'}


@app.route('/api/complaints', methods=['GET', 'POST'])
def complaints():
    """GET: admin fetches every ticket. POST: a logged-in user submits a new one."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    conn = sqlite3.connect('users.db', timeout=15)   # waits if another page is saving at the same moment
    cursor = conn.cursor()

    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        subject = (data.get('subject') or '').strip()
        description = (data.get('description') or '').strip()
        category = (data.get('category') or 'other').strip().lower()
        if category not in VALID_COMPLAINT_CATEGORIES:
            category = 'other'
        priority = (data.get('priority') or COMPLAINT_CATEGORY_PRIORITY.get(category, 'medium')).strip().lower()
        if priority not in VALID_COMPLAINT_PRIORITIES:
            priority = 'medium'

        if not subject:
            conn.close()
            return jsonify({'success': False, 'message': 'Subject is required'}), 400
        if len(subject) > 150 or len(description) > 5000:
            conn.close()
            return jsonify({'success': False, 'message': 'Please keep the subject under 150 characters and the message under 5,000.'}), 400
        if _reset_rate_limited(f'ticket:{session["user_id"]}', limit=5, window=3600):
            conn.close()
            return jsonify({'success': False, 'message': 'You’ve sent several tickets in the last hour. Add more to an open ticket instead, or try again later.'}), 429

        # a parent can say which child the ticket is about (must be linked to them)
        if session.get('role') == 'parent' and data.get('child_id'):
            lconn = _links_db()
            try:
                link = _linked_child(lconn, session['user_id'], int(data['child_id']))
            except (TypeError, ValueError, sqlite3.Error):
                link = None
            finally:
                lconn.close()
            if link:
                description = f"About my child: {_full_name(link['firstname'], link['lastname'], 'Child')}\n\n{description}"[:5200]
        # a payment question can point at one of the sender's own payments, so support sees the code straight away
        if data.get('payment_id'):
            pconn = _links_db()
            try:
                _payments_table(pconn)
                pay = pconn.execute(PAYMENT_SELECT + ' WHERE p.id = ? AND p.parent_id = ?', (int(data['payment_id']), session['user_id'])).fetchone()
            except (TypeError, ValueError, sqlite3.Error):
                pay = None
            finally:
                pconn.close()
            if pay:
                pj = _serialize_payment(pay)
                line = (f"About payment #{pj.get('id')}: {pj.get('plan_name') or pj.get('plan')} for {pj.get('days')} days, "
                        f"{_money(pj.get('amount'))}, M-Pesa code {pj.get('reference')}, {pj.get('status')}")
                description = f"{line}\n\n{description}"[:5400]

        cursor.execute('''
            INSERT INTO complaints (user_id, subject, description, category, priority, status, is_read)
            VALUES (?, ?, ?, ?, ?, 'pending', 0)
        ''', (session['user_id'], subject, description, category, priority))
        conn.commit()

        complaint_id = cursor.lastrowid
        cursor.execute('''
            SELECT c.id, c.user_id, c.subject, c.description, c.category, c.priority, c.status,
                   c.is_read, c.response, c.response_date, c.created_at,
                   u.firstname, u.lastname, u.email
            FROM complaints c
            LEFT JOIN users u ON c.user_id = u.id
            WHERE c.id = ?
        ''', (complaint_id,))
        row = cursor.fetchone()
        conn.close()
        ticket = _serialize_complaint(row)
        try:
            _support_alert(ticket)
        except Exception as e:      # the ticket is saved either way
            print('support alert:', e)
        return jsonify({'success': True, 'complaint': ticket})

    # GET — admin only
    if not is_admin():
        conn.close()
        return jsonify({'success': False, 'message': 'Admin access required'}), 403

    cursor.execute('''
        SELECT c.id, c.user_id, c.subject, c.description, c.category, c.priority, c.status,
               c.is_read, c.response, c.response_date, c.created_at,
               u.firstname, u.lastname, u.email
        FROM complaints c
        LEFT JOIN users u ON c.user_id = u.id
        ORDER BY c.created_at DESC, c.id DESC
    ''')
    rows = cursor.fetchall()
    conn.close()

    return jsonify({
        'success': True,
        'complaints': [_serialize_complaint(row) for row in rows]
    })


@app.route('/api/complaints/<int:complaint_id>/read', methods=['POST'])
def mark_complaint_read(complaint_id):
    """Admin opens a ticket — mark it as read."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if not is_admin():
        return jsonify({'success': False, 'message': 'Admin access required'}), 403

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    cursor.execute('UPDATE complaints SET is_read = 1 WHERE id = ?', (complaint_id,))
    conn.commit()
    updated = cursor.rowcount
