@app.route('/api/live/<int:cid>/audience', methods=['GET', 'POST'])
def api_live_audience(cid):
    """Teacher: who can enter this class.
    GET  -> {audience, invited: [...], my_learners: [...]}
    POST {"audience": "everyone" | "my_learners" | "picked", "invite": [user ids]} (invite replaces the list)"""
    conn = _live_db()
    try:
        lc, err = _live_guard(conn, cid, teacher=True)
        if err:
            return err
        if request.method == 'POST':
            d = request.get_json(silent=True) or {}
            aud = d.get('audience') if d.get('audience') in LIVE_AUDIENCES else (lc['audience'] or 'everyone')
            conn.execute('UPDATE live_classes SET audience = ? WHERE id = ?', (aud, cid))
            if isinstance(d.get('invite'), list):
                ids = set()
                for x in d['invite'][:300]:
                    try:
                        ids.add(int(x))
                    except (TypeError, ValueError):
                        pass
                ok = {r[0] for r in conn.execute(f"SELECT id FROM users WHERE COALESCE(role, 'student') = 'student' AND id IN ({','.join('?' * len(ids)) or 'NULL'})", list(ids)).fetchall()}
                new = ok - {r[0] for r in conn.execute('SELECT user_id FROM live_invites WHERE class_id = ?', (cid,)).fetchall()}
                conn.execute('DELETE FROM live_invites WHERE class_id = ?', (cid,))
                now = _iso(_live_now())
                conn.executemany('INSERT INTO live_invites (class_id, user_id, created_at) VALUES (?, ?, ?)', [(cid, u, now) for u in ok])
                name = _full_name(lc['firstname'], lc['lastname'], 'A teacher')
                for u in new:
                    create_notification(conn, u, 'You are invited to a live class',
                                        f'{name} invited you to “{lc["title"]}”. Open Live Classes to join.',
                                        icon='fa-tower-broadcast', color='#ef4444', category='announcements')
            conn.commit()
        invited = [{'id': r['id'], 'name': _full_name(r['firstname'], r['lastname'], 'Learner'), 'avatar_url': get_avatar_url(r['id'], r['avatar_filename'])}
                   for r in conn.execute('''SELECT u.id, u.firstname, u.lastname, u.avatar_filename FROM live_invites i JOIN users u ON u.id = i.user_id
                                            WHERE i.class_id = ? ORDER BY u.firstname''', (cid,)).fetchall()]
        try:
            mine = [{'id': r['id'], 'name': _full_name(r['firstname'], r['lastname'], 'Learner'), 'avatar_url': get_avatar_url(r['id'], r['avatar_filename'])}
                    for r in conn.execute('''SELECT DISTINCT u.id, u.firstname, u.lastname, u.avatar_filename FROM tutoring t JOIN users u ON u.id = t.student_id
                                             WHERE t.teacher_id = ? AND t.status IN ('active', 'accepted', 'ended') ORDER BY u.firstname''', (lc['teacher_id'],)).fetchall()]
        except sqlite3.Error:
            mine = []
        removed = [r[0] for r in conn.execute('SELECT user_id FROM live_removed WHERE class_id = ?', (cid,)).fetchall()]
        lc = _live_class(conn, cid)
        return jsonify({'success': True, 'audience': lc['audience'] or 'everyone', 'audiences': LIVE_AUDIENCES,
                        'invited': invited, 'my_learners': mine, 'removed': removed})
    finally:
        conn.close()


