@app.route('/api/live/<int:cid>/remove', methods=['POST', 'DELETE'])
def api_live_remove(cid):
    """Teacher: POST {"user_id": n} removes someone from the class (they can't come back); DELETE lets them back in."""
    conn = _live_db()
    try:
        lc, err = _live_guard(conn, cid, teacher=True)
        if err:
            return err
        try:
            uid = int((request.get_json(silent=True) or {}).get('user_id') or request.args.get('user_id'))
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Who?'}), 400
        if request.method == 'DELETE':
            conn.execute('DELETE FROM live_removed WHERE class_id = ? AND user_id = ?', (cid, uid))
            _live_event(conn, cid, lc['teacher_id'], 'let_back', str(uid))
        else:
            conn.execute('INSERT OR IGNORE INTO live_removed (class_id, user_id, created_at) VALUES (?, ?, ?)', (cid, uid, _iso(_live_now())))
            _att_close(conn, cid, uid, 'removed by the teacher')
            _live_event(conn, cid, lc['teacher_id'], 'removed', str(uid))
            conn.execute("UPDATE live_viewers SET last_seen = '2000-01-01T00:00:00Z', hand = 0 WHERE class_id = ? AND user_id = ?", (cid, uid))
            conn.execute('DELETE FROM live_signals WHERE class_id = ? AND (from_id = ? OR to_id = ?)', (cid, uid, uid))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/live/<int:cid>/rate', methods=['POST'])
def api_live_rate(cid):
    """A learner who was in the class rates it once it is over: {"stars": 1-5, "comment": "..."}.
    Ratings are shown out of 10 and count towards how Eschool rates teachers."""
    conn = _live_db()
    try:
        lc, err = _live_guard(conn, cid)
        if err:
            return err
        me = session['user_id']
        if (session.get('role') or 'student') != 'student':
            return jsonify({'success': False, 'message': 'Learners rate the classes they joined.'}), 403
        if not conn.execute('SELECT 1 FROM live_viewers WHERE class_id = ? AND user_id = ?', (cid, me)).fetchone():
            return jsonify({'success': False, 'message': 'You can rate a class you joined.'}), 403
        end = _parse_any(lc['start_time'])
        over = (lc['state'] or '') == 'ended' or (end and _live_now() > end + timedelta(minutes=(lc['duration_min'] or 60)))
        if not over:
            return jsonify({'success': False, 'message': 'You can rate the class when it is over.'}), 409
        d = request.get_json(silent=True) or {}
        try:
            stars = int(d.get('stars'))
        except (TypeError, ValueError):
            stars = 0
        if not 1 <= stars <= 5:
            return jsonify({'success': False, 'message': 'Pick a rating.'}), 400
        conn.execute('''INSERT INTO live_ratings (class_id, user_id, teacher_id, stars, comment, created_at) VALUES (?, ?, ?, ?, ?, ?)
                        ON CONFLICT(class_id, user_id) DO UPDATE SET stars = excluded.stars, comment = excluded.comment, created_at = excluded.created_at''',
                     (cid, me, lc['teacher_id'], stars, str(d.get('comment') or '').strip()[:400] or None, _iso(_live_now())))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


# ---------- live class reminders (saved per account, work on every device) ----------
def _live_reminders_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS live_reminders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            class_id INTEGER NOT NULL,
            notified_soon INTEGER NOT NULL DEFAULT 0,
            notified_live INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (user_id, class_id)
        )
    ''')


def my_live_reminder_ids(conn, user_id):
    _live_reminders_table(conn)
    return {r[0] for r in conn.execute('SELECT class_id FROM live_reminders WHERE user_id = ?', (user_id,)).fetchall()}


def fire_live_reminders(conn, user_id):
    """Sends 'starts in 10 minutes' and 'is live now' notifications for the
    classes this person asked to be reminded about. Called whenever the
    notification bell refreshes (every page polls it), so no scheduler is needed."""
    _live_reminders_table(conn)
    now = datetime.now(timezone.utc)
    rows = conn.execute('''
        SELECT r.id, r.notified_soon, r.notified_live, lc.title, lc.start_time, lc.duration_min
        FROM live_reminders r JOIN live_classes lc ON lc.id = r.class_id
        WHERE r.user_id = ? AND (r.notified_soon = 0 OR r.notified_live = 0)
    ''', (user_id,)).fetchall()
    changed = False
    for rid, soon_done, live_done, title, start_raw, duration in rows:
        try:
            start = datetime.fromisoformat(str(start_raw).replace('Z', '+00:00'))
            if start.tzinfo is None:
                start = start.replace(tzinfo=timezone.utc)
        except ValueError:
            continue
        end = start + timedelta(minutes=duration or 60)
        if now >= end:
            conn.execute('UPDATE live_reminders SET notified_soon = 1, notified_live = 1 WHERE id = ?', (rid,))
            changed = True
        elif now >= start and not live_done:
            create_notification(conn, user_id, 'Live class started', f'"{title}" is live now. Open Live Classes to join.',
                                icon='fas fa-broadcast-tower', color='#ef4444')
            conn.execute('UPDATE live_reminders SET notified_soon = 1, notified_live = 1 WHERE id = ?', (rid,))
            changed = True
        elif start - now <= timedelta(minutes=10) and not soon_done:
            mins = max(1, int((start - now).total_seconds() // 60))
            create_notification(conn, user_id, 'Live class starting soon', f'"{title}" starts in {mins} min.',
                                icon='fas fa-clock', color='#f59e0b')
            conn.execute('UPDATE live_reminders SET notified_soon = 1 WHERE id = ?', (rid,))
            changed = True
    if changed:
        conn.commit()


@app.route('/api/live-classes/<int:live_id>/reminder', methods=['POST', 'DELETE'])
def live_class_reminder(live_id):
    """POST turns a reminder on, DELETE turns it off."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please log in again.'}), 401
    conn = sqlite3.connect('users.db', timeout=10)
    try:
        _live_reminders_table(conn)
        if not conn.execute('SELECT 1 FROM live_classes WHERE id = ?', (live_id,)).fetchone():
            return jsonify({'success': False, 'message': 'That class no longer exists.'}), 404
        if request.method == 'DELETE':
            conn.execute('DELETE FROM live_reminders WHERE user_id = ? AND class_id = ?', (session['user_id'], live_id))
            on = False
        else:
            conn.execute('INSERT OR IGNORE INTO live_reminders (user_id, class_id) VALUES (?, ?)', (session['user_id'], live_id))
            on = True
        conn.commit()
        return jsonify({'success': True, 'reminded': on})
    finally:
        conn.close()


