def format_file_size(bytes):
    if bytes == 0:
        return "0 Bytes"
    k = 1024
    sizes = ["Bytes", "KB", "MB", "GB"]
    i = int(math.floor(math.log(bytes) / math.log(k)))
    return f"{bytes / math.pow(k, i):.2f} {sizes[i]}"

RESOURCE_CATEGORIES_EDITABLE = ('mathematics', 'science', 'programming', 'business', 'arts', 'languages', 'general')


@app.route('/api/resources/<int:resource_id>', methods=['PATCH'])
def update_resource(resource_id):
    """The uploader edits their resource: {"title", "description", "category", "difficulty": "grade-10", "privacy": "public"|"private"}."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    d = request.get_json(silent=True) or {}
    conn = sqlite3.connect('users.db')
    try:
        row = conn.execute('SELECT user_id FROM resources WHERE id = ?', (resource_id,)).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Resource not found'}), 404
        if int(row[0]) != int(session['user_id']) and session.get('role') != 'admin':   # any Eschool admin can manage resources
            return jsonify({'success': False, 'message': 'You can only edit your own resources.'}), 403
        sets, vals, errors = [], [], {}
        if 'title' in d:
            t = ' '.join(str(d.get('title') or '').split())
            if not t:
                errors['title'] = 'Give the resource a title.'
            elif len(t) > 150:
                errors['title'] = 'Keep the title under 150 characters.'
            sets.append('title = ?'); vals.append(t)
        if 'description' in d:
            desc = str(d.get('description') or '').strip()
            if len(desc) > 2000:
                errors['description'] = 'Keep the description under 2000 characters.'
            sets.append('description = ?'); vals.append(desc)
        if 'category' in d:
            if d.get('category') not in RESOURCE_CATEGORIES_EDITABLE:
                errors['category'] = 'Pick a subject from the list.'
            sets.append('category = ?'); vals.append(d.get('category'))
        if 'difficulty' in d:
            g = str(d.get('difficulty') or '')
            if not re.match(r'^grade-(?:[1-9]|1[01])$', g):
                errors['difficulty'] = 'Pick a grade from the list.'
            sets.append('difficulty = ?'); vals.append(g)
        if 'privacy' in d:
            if d.get('privacy') not in ('public', 'private'):
                errors['privacy'] = 'Choose public or private.'
            sets.append('privacy = ?'); vals.append(d.get('privacy'))
        if errors:
            return jsonify({'success': False, 'message': next(iter(errors.values())), 'errors': errors}), 400
        notified = None
        if sets:
            conn.execute(f"UPDATE resources SET {', '.join(sets)} WHERE id = ?", vals + [resource_id])
            if session.get('role') == 'admin':
                t = conn.execute('SELECT title FROM resources WHERE id = ?', (resource_id,)).fetchone()
                admin_log(conn, 'resource_edit', 'resource', resource_id, f"“{t[0] if t else resource_id}”: " + ', '.join(k for k in d if k != 'announce'))
                if d.get('privacy') == 'public':
                    notified = _announce_resources(conn, [resource_id], notify=d.get('announce', True) is not False)
            conn.commit()
        return jsonify({'success': True, 'message': 'Saved.', 'notified': notified})
    finally:
        conn.close()


@app.route('/api/resources/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    conn = sqlite3.connect('users.db')
    try:
        row = conn.execute('SELECT user_id, title FROM resources WHERE id = ?', (resource_id,)).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Resource not found'}), 404
        if int(row[0]) != int(session['user_id']) and session.get('role') != 'admin':
            return jsonify({'success': False, 'message': 'You are not allowed to delete this resource'}), 403
        _delete_resource_row(conn, resource_id)
        if session.get('role') == 'admin':
            admin_log(conn, 'resource_delete', 'resource', resource_id, row[1])
        conn.commit()
        return jsonify({'success': True, 'message': 'Resource deleted successfully'})
    except Exception as e:
        print(f"Delete error: {e}")
        return jsonify({'success': False, 'message': 'Server error while deleting'}), 500
    finally:
        conn.close()

# ============ ADMIN: RESOURCES (upload + analytics + management) ============
# Only Eschool (admins) posts resources. When a resource is public, every
# learner gets ONE notification per upload batch, and each resource is only
# ever announced once (resources.announced), so switching private -> public
# -> private -> public never spams learners.

_RES_ADMIN_READY = False


def _res_admin_tables(conn):
    global _RES_ADMIN_READY
    if _RES_ADMIN_READY:
        return
    conn.execute("""CREATE TABLE IF NOT EXISTS resource_downloads (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        resource_id INTEGER NOT NULL,
        user_id INTEGER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""")
    conn.execute('CREATE INDEX IF NOT EXISTS idx_res_dl ON resource_downloads (resource_id, created_at)')
    conn.execute("""CREATE TABLE IF NOT EXISTS resource_saves (
        id INTEGER PRIMARY KEY AUTOINCREMENT, resource_id INTEGER NOT NULL, user_id INTEGER NOT NULL,
        saved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE (resource_id, user_id))""")
    cols = [r[1] for r in conn.execute('PRAGMA table_info(resources)')]
    if 'announced' not in cols:
        conn.execute('ALTER TABLE resources ADD COLUMN announced INTEGER DEFAULT 0')
        # everything already public before this change was already seen by learners
        conn.execute("UPDATE resources SET announced = 1 WHERE privacy = 'public'")
    conn.commit()
    _RES_ADMIN_READY = True


def _delete_resource_row(conn, rid):
    """Remove one resource, its file, its own cover picture and every count row."""
    row = conn.execute('SELECT user_id, file_name, thumbnail_url FROM resources WHERE id = ?', (rid,)).fetchone()
    if not row:
        return False
    owner, fname, thumb = row
    for name in (fname, (thumb or '').rsplit('/', 1)[-1] if '_thumb_' in (thumb or '') and str(thumb).startswith('/uploads/') else None):
        if not name or '/' in name or name.startswith('.'):
            continue
        p = os.path.join(UPLOAD_FOLDER, str(owner), name)
        try:
            if os.path.isfile(p):
                os.remove(p)
        except OSError as e:
            print(f'could not remove {p}: {e}')
    conn.execute('DELETE FROM resources WHERE id = ?', (rid,))
    for t in ('resource_likes', 'resource_views', 'resource_saves', 'resource_downloads'):
        try:
            conn.execute(f'DELETE FROM {t} WHERE resource_id = ?', (rid,))
        except sqlite3.OperationalError:
            pass
    return True


RES_SUBJECT_NAMES = {'mathematics': 'Mathematics', 'science': 'Science', 'programming': 'Physics', 'arts': 'Chemistry',
                     'business': 'Business', 'languages': 'Languages', 'general': 'General'}
RES_KIND_NAMES = {'video': 'video', 'audio': 'audio recording', 'image': 'picture', 'pdf': 'PDF', 'doc': 'document',
                  'presentation': 'slideshow', 'spreadsheet': 'spreadsheet', 'code': 'code file', 'zip': 'file'}


def _announce_resources(conn, ids, notify=True):
    """Tell every learner about public resources not announced yet: one
    notification for the whole batch. notify=False just marks them as
    handled. Returns how many learners were sent it (None if nothing new)."""
    _res_admin_tables(conn)
    ids = [int(i) for i in ids if str(i).isdigit()][:50]
    if not ids:
        return None
    q = ','.join('?' * len(ids))
    rows = conn.execute(f"SELECT id, title, category, file_category FROM resources WHERE privacy = 'public' "
                        f"AND COALESCE(announced, 0) = 0 AND id IN ({q}) ORDER BY id", ids).fetchall()
    if not rows:
        return None
    conn.execute(f"UPDATE resources SET announced = 1 WHERE id IN ({','.join('?' * len(rows))})", [r[0] for r in rows])
    if not notify:
        return None
    subjects = sorted({RES_SUBJECT_NAMES.get(r[2], 'General') for r in rows})
    if len(rows) == 1:
        kind = RES_KIND_NAMES.get(rows[0][3], 'resource')
        title = f'New {kind}: {rows[0][1]}'[:120]
        msg = f'Eschool added “{rows[0][1]}” in {subjects[0]}. Find it in Resources.'
    else:
        title = f'{len(rows)} new resources from Eschool'
        msg = f'Eschool added {len(rows)} new resources in {", ".join(subjects[:3])}{" and more" if len(subjects) > 3 else ""}, starting with “{rows[0][1]}”. Find them in Resources.'
    icon = 'fa-play-circle' if all(r[3] == 'video' for r in rows) else 'fa-folder-open'
    learners = [r[0] for r in conn.execute("SELECT id FROM users WHERE COALESCE(role, 'student') = 'student'")]
    for uid in learners:
        create_notification(conn, uid, title, msg[:500], icon=icon, color='blue', category='announcements')
    return len(learners)


@app.route('/api/admin/resources/announce', methods=['POST'])
def admin_resources_announce():
    """{"ids": [..], "notify": true}: after an upload batch."""
    bad = _admin_guard()
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    conn = sqlite3.connect('users.db')
    try:
        n = _announce_resources(conn, d.get('ids') or [], notify=d.get('notify', True) is not False)
        if n is not None:
            cnt = len(d.get('ids') or [])
            admin_log(conn, 'resource_announce', 'resource', None, f"{cnt} resource{'' if cnt == 1 else 's'}, {n} learners told")
        conn.commit()
        return jsonify({'success': True, 'notified': n or 0})
    finally:
        conn.close()


def _res_day_series(conn, sql, args, days):
    got = dict(conn.execute(sql, args).fetchall())
    today = _utc_now().date()
    out = []
    for k in range(days - 1, -1, -1):
        day = (today - timedelta(days=k)).isoformat()
        out.append(int(got.get(day, 0) or 0))
    return out


def _res_period(days):
    try:
        days = int(days)
    except (TypeError, ValueError):
        days = 30
    return days if days in (7, 30, 90) else 30


_RES_ATTENTION = {
    'unseen': "r.privacy = 'public' AND COALESCE(r.views, 0) = 0 AND r.upload_date < datetime('now', '-14 days')",
    'nocover': "r.file_category = 'video' AND COALESCE(r.thumbnail_url, '') NOT LIKE '/uploads/%'",
    'nodesc': "LENGTH(TRIM(COALESCE(r.description, ''))) = 0",
    'private': "r.privacy = 'private'",
}


def _res_missing_ids(conn):
    out = []
    for rid, owner, fname in conn.execute('SELECT id, user_id, file_name FROM resources'):
        if not fname or not os.path.isfile(os.path.join(UPLOAD_FOLDER, str(owner), fname)):
            out.append(rid)
    return out


@app.route('/api/admin/resources/overview')
def admin_resources_overview():
    bad = _admin_guard()
    if bad:
        return bad
    days = _res_period(request.args.get('days'))
    conn = sqlite3.connect('users.db')
    try:
        _res_admin_tables(conn)
        c = conn.cursor()
        tot = c.execute("""SELECT COUNT(*), COALESCE(SUM(views),0), COALESCE(SUM(downloads),0), COALESCE(SUM(likes),0),
                                  COALESCE(SUM(file_size),0), COALESCE(SUM(CASE WHEN file_category='video' THEN file_size END),0),
                                  COALESCE(SUM(privacy='public'),0)
                           FROM resources""").fetchone()
        saves = c.execute('SELECT COUNT(*) FROM resource_saves s JOIN resources r ON r.id = s.resource_id').fetchone()[0]
        win = f'-{days} days'
        win2 = f'-{days * 2} days'

        def pair(table, col):
            now_ = c.execute(f"SELECT COUNT(*) FROM {table} t JOIN resources r ON r.id = t.resource_id WHERE t.{col} >= datetime('now', ?)", (win,)).fetchone()[0]
            before = c.execute(f"SELECT COUNT(*) FROM {table} t JOIN resources r ON r.id = t.resource_id WHERE t.{col} >= datetime('now', ?) AND t.{col} < datetime('now', ?)", (win2, win)).fetchone()[0]
            return now_, before
        v_now, v_before = pair('resource_views', 'created_at')
        l_now, l_before = pair('resource_likes', 'created_at')
        s_now, s_before = pair('resource_saves', 'saved_at')
        d_now, d_before = pair('resource_downloads', 'created_at')
        new_now = c.execute("SELECT COUNT(*) FROM resources WHERE upload_date >= datetime('now', ?)", (win,)).fetchone()[0]
        reached = c.execute("SELECT COUNT(DISTINCT t.user_id) FROM resource_views t JOIN resources r ON r.id = t.resource_id WHERE t.created_at >= datetime('now', ?)", (win,)).fetchone()[0]
        learners = c.execute("SELECT COUNT(*) FROM users WHERE COALESCE(role, 'student') = 'student'").fetchone()[0]

        def series(table, col):
            return _res_day_series(conn, f"SELECT date(t.{col}), COUNT(*) FROM {table} t JOIN resources r ON r.id = t.resource_id "
                                         f"WHERE t.{col} >= date('now', ?) GROUP BY 1", (f'-{days - 1} days',), days)
        today = _utc_now().date()
        chart = {
            'days': [(today - timedelta(days=k)).isoformat() for k in range(days - 1, -1, -1)],
            'views': series('resource_views', 'created_at'),
            'likes': series('resource_likes', 'created_at'),
            'saves': series('resource_saves', 'saved_at'),
            'downloads': series('resource_downloads', 'created_at'),
            'uploads': _res_day_series(conn, "SELECT date(upload_date), COUNT(*) FROM resources WHERE upload_date >= date('now', ?) GROUP BY 1",
                                       (f'-{days - 1} days',), days),
        }

        def top(order, extra=''):
            return [{'id': r[0], 'title': r[1], 'file_category': r[2], 'value': int(r[3] or 0)} for r in c.execute(
                f"SELECT id, title, file_category, {order} FROM resources r {extra} ORDER BY 4 DESC, id DESC LIMIT 5")]
        top_views = top('COALESCE(views,0)')
        top_recent = [{'id': r[0], 'title': r[1], 'file_category': r[2], 'value': r[3]} for r in c.execute(
            "SELECT r.id, r.title, r.file_category, COUNT(t.id) n FROM resources r JOIN resource_views t ON t.resource_id = r.id "
            "WHERE t.created_at >= datetime('now', ?) GROUP BY r.id ORDER BY n DESC, r.id DESC LIMIT 5", (win,))]
        by_subject = [{'key': r[0] or 'general', 'name': RES_SUBJECT_NAMES.get(r[0] or 'general', (r[0] or 'General').title()), 'count': r[1], 'views': int(r[2] or 0)}
                      for r in c.execute('SELECT category, COUNT(*), SUM(views) FROM resources GROUP BY category ORDER BY 2 DESC')]
        by_type = [{'key': r[0] or 'other', 'count': r[1], 'views': int(r[2] or 0), 'size': int(r[3] or 0)}
                   for r in c.execute('SELECT file_category, COUNT(*), SUM(views), SUM(file_size) FROM resources GROUP BY file_category ORDER BY 2 DESC')]
        by_grade = [{'key': r[0] or '', 'count': r[1], 'views': int(r[2] or 0)}
                    for r in c.execute("SELECT difficulty, COUNT(*), SUM(views) FROM resources GROUP BY difficulty ORDER BY 2 DESC")]
        attention = {k: c.execute(f'SELECT COUNT(*) FROM resources r WHERE {w}').fetchone()[0] for k, w in _RES_ATTENTION.items()}
        attention['missing'] = len(_res_missing_ids(conn))
        return jsonify({'success': True, 'days': days, 'totals': {
            'resources': tot[0], 'public': tot[6], 'private': tot[0] - tot[6], 'views': tot[1], 'downloads': tot[2],
            'likes': tot[3], 'saves': saves, 'storage': tot[4], 'video_storage': tot[5], 'learners': learners,
        }, 'period': {
            'new': new_now, 'reached': reached,
            'views': [v_now, v_before], 'likes': [l_now, l_before], 'saves': [s_now, s_before], 'downloads': [d_now, d_before],
        }, 'chart': chart, 'top_views': top_views, 'top_recent': top_recent,
            'by_subject': by_subject, 'by_type': by_type, 'by_grade': by_grade, 'attention': attention})
    finally:
        conn.close()


_RES_SORTS = {
    'newest': 'r.upload_date DESC, r.id DESC', 'oldest': 'r.upload_date ASC, r.id ASC',
    'views': 'COALESCE(r.views,0) DESC, r.id DESC', 'downloads': 'COALESCE(r.downloads,0) DESC, r.id DESC',
    'likes': 'COALESCE(r.likes,0) DESC, r.id DESC', 'title': 'LOWER(r.title) ASC', 'size': 'COALESCE(r.file_size,0) DESC',
}
_RES_PREVIEW_EXT = {'mp4', 'webm', 'ogg', 'm4v', 'mov', 'mp3', 'wav', 'm4a', 'aac', 'flac',
                    'jpg', 'jpeg', 'png', 'gif', 'webp', 'pdf'}


@app.route('/api/admin/resources/list')
def admin_resources_list():
    bad = _admin_guard()
    if bad:
        return bad
    a = request.args
    try:
        page = max(1, int(a.get('page') or 1))
    except ValueError:
        page = 1
    per = 25
    where, args = [], []
    q = ' '.join((a.get('q') or '').split())[:100]
    if q:
        like = '%' + q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
        where.append("(r.title LIKE ? ESCAPE '\\' OR r.description LIKE ? ESCAPE '\\' OR r.file_name LIKE ? ESCAPE '\\')")
        args += [like, like, like]
    if a.get('category') in RES_SUBJECT_NAMES:
        where.append('r.category = ?'); args.append(a['category'])
    if a.get('type') in ('video', 'audio', 'image', 'pdf', 'doc', 'presentation', 'spreadsheet', 'code', 'zip', 'other'):
        where.append('r.file_category = ?'); args.append(a['type'])
    if re.fullmatch(r'grade-(?:[1-9]|1[01])', a.get('grade') or ''):
        where.append('r.difficulty = ?'); args.append(a['grade'])
    if a.get('privacy') in ('public', 'private'):
        where.append('r.privacy = ?'); args.append(a['privacy'])
    conn = sqlite3.connect('users.db')
    try:
        _res_admin_tables(conn)
        att = a.get('attention')
        if att in _RES_ATTENTION:
            where.append(_RES_ATTENTION[att])
        elif att == 'missing':
            ids = _res_missing_ids(conn) or [0]
            where.append(f"r.id IN ({','.join('?' * len(ids))})"); args += ids
        w = ('WHERE ' + ' AND '.join(where)) if where else ''
        total = conn.execute(f'SELECT COUNT(*) FROM resources r {w}', args).fetchone()[0]
        order = _RES_SORTS.get(a.get('sort'), _RES_SORTS['newest'])
        rows = conn.execute(f"""
            SELECT r.id, r.title, r.description, r.category, r.difficulty, r.file_category, r.file_extension,
                   r.file_size, r.duration, r.pages, r.privacy, COALESCE(r.views,0), COALESCE(r.downloads,0),
                   COALESCE(r.likes,0), r.thumbnail_url, r.upload_date, r.user_id, r.file_name,
                   u.firstname, u.lastname, COALESCE(r.announced,0),
                   (SELECT COUNT(*) FROM resource_saves s WHERE s.resource_id = r.id)
            FROM resources r LEFT JOIN users u ON u.id = r.user_id {w}
            ORDER BY {order} LIMIT ? OFFSET ?""", args + [per, (page - 1) * per]).fetchall()
        items = []
        for r in rows:
            ext = (r[6] or '').lower()
            thumb = r[14] or ''
            if not (thumb.startswith('/') or thumb.startswith('https://')):
                thumb = ''
            items.append({
                'id': r[0], 'title': r[1], 'description': r[2] or '', 'category': r[3] or 'general',
                'subject': RES_SUBJECT_NAMES.get(r[3] or 'general', 'General'), 'grade': r[4] or '',
                'file_category': r[5] or 'other', 'ext': ext, 'size': int(r[7] or 0), 'duration': r[8] or '',
                'pages': int(r[9] or 0), 'privacy': 'private' if r[10] == 'private' else 'public',
                'views': r[11], 'downloads': r[12], 'likes': r[13], 'saves': r[21], 'thumb': thumb,
                'uploaded': r[15], 'by': f"{r[18] or ''} {r[19] or ''}".strip() or 'Eschool',
                'announced': bool(r[20]),
                'url': f'/uploads/{int(r[16])}/{r[17]}' if r[17] else '',
                'preview': ext in _RES_PREVIEW_EXT,
            })
        return jsonify({'success': True, 'items': items, 'total': total, 'page': page, 'pages': max(1, -(-total // per))})
    finally:
        conn.close()


@app.route('/api/admin/resources/<int:rid>/stats')
def admin_resource_stats(rid):
    bad = _admin_guard()
    if bad:
        return bad
    days = _res_period(request.args.get('days'))
    conn = sqlite3.connect('users.db')
    try:
        _res_admin_tables(conn)
        r = conn.execute('SELECT title, COALESCE(views,0), COALESCE(downloads,0), COALESCE(likes,0), upload_date FROM resources WHERE id = ?', (rid,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'That resource no longer exists.'}), 404
        start = (f'-{days - 1} days',)

        def ser(table, col):
            return _res_day_series(conn, f'SELECT date({col}), COUNT(*) FROM {table} WHERE resource_id = ? AND {col} >= date(\'now\', ?) GROUP BY 1',
                                   (rid,) + start, days)
        saves = conn.execute('SELECT COUNT(*) FROM resource_saves WHERE resource_id = ?', (rid,)).fetchone()[0]
        learners = max(1, conn.execute("SELECT COUNT(*) FROM users WHERE COALESCE(role, 'student') = 'student'").fetchone()[0])
        reached = conn.execute('SELECT COUNT(DISTINCT user_id) FROM resource_views WHERE resource_id = ?', (rid,)).fetchone()[0]
        today = _utc_now().date()
        return jsonify({'success': True, 'title': r[0], 'days': days, 'totals': {
            'views': r[1], 'downloads': r[2], 'likes': r[3], 'saves': saves, 'reached': reached,
            'reach_pct': round(reached * 100 / learners, 1)},
            'uploaded': r[4],
            'chart': {'days': [(today - timedelta(days=k)).isoformat() for k in range(days - 1, -1, -1)],
                      'views': ser('resource_views', 'created_at'), 'likes': ser('resource_likes', 'created_at'),
                      'saves': ser('resource_saves', 'saved_at'), 'downloads': ser('resource_downloads', 'created_at')}})
    finally:
        conn.close()


@app.route('/api/admin/resources/bulk', methods=['POST'])
def admin_resources_bulk():
    """{"ids": [..], "action": "public"|"private"|"delete", "announce": true}"""
    bad = _admin_guard()
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    ids = sorted({int(i) for i in (d.get('ids') or []) if str(i).isdigit()})[:100]
    act = d.get('action')
    if not ids or act not in ('public', 'private', 'delete'):
        return jsonify({'success': False, 'message': 'Pick some resources and an action.'}), 400
    conn = sqlite3.connect('users.db')
    try:
        _res_admin_tables(conn)
        q = ','.join('?' * len(ids))
        rows_found = conn.execute(f'SELECT id, title FROM resources WHERE id IN ({q})', ids).fetchall()
        found = [r[0] for r in rows_found]
        names = ', '.join(f'“{r[1]}”' for r in rows_found[:3]) + (f' and {len(rows_found) - 3} more' if len(rows_found) > 3 else '')
        notified = None
        if act == 'delete':
            for rid in found:
                _delete_resource_row(conn, rid)
        else:
            conn.execute(f'UPDATE resources SET privacy = ? WHERE id IN ({q})', [act] + ids)
            if act == 'public':
                notified = _announce_resources(conn, found, notify=d.get('announce', True) is not False)
        admin_log(conn, 'resource_bulk_' + act, 'resource', None, names[:400])
        conn.commit()
        return jsonify({'success': True, 'done': len(found), 'notified': notified})
    finally:
        conn.close()


