# ============ PROFILE: LIVE CLASSES + RATINGS ============
# Uses the same users.db as the rest of the app.

def _profile_db():
    conn = sqlite3.connect('users.db', timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("""
        CREATE TABLE IF NOT EXISTS teacher_ratings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            teacher_id INTEGER NOT NULL,
            reviewer_id INTEGER NOT NULL,
            stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5),
            comment TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (teacher_id, reviewer_id),
            FOREIGN KEY (teacher_id) REFERENCES users (id),
            FOREIGN KEY (reviewer_id) REFERENCES users (id)
        )
    """)
    cols = {r[1] for r in conn.execute('PRAGMA table_info(teacher_ratings)').fetchall()}
    if 'reply' not in cols:      # the teacher's public answer to a review
        conn.execute('ALTER TABLE teacher_ratings ADD COLUMN reply TEXT')
        conn.execute('ALTER TABLE teacher_ratings ADD COLUMN reply_at TIMESTAMP')
        conn.commit()
    return conn


