@app.route('/api/users/<int:user_id>/ratings', methods=['GET'])
def api_user_ratings(user_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    me = session['user_id']
    conn = _profile_db()
    try:
        summary = conn.execute(
            'SELECT COUNT(*) AS n, AVG(stars) AS avg FROM teacher_ratings WHERE teacher_id = ?',
            (user_id,),
        ).fetchone()

        distribution = {str(n): 0 for n in range(1, 6)}
        for r in conn.execute(
            'SELECT stars, COUNT(*) AS n FROM teacher_ratings WHERE teacher_id = ? GROUP BY stars',
            (user_id,),
        ).fetchall():
            distribution[str(r['stars'])] = r['n']

        rows = conn.execute(
            """SELECT r.id, r.reviewer_id, r.stars, r.comment, r.created_at, r.reply, r.reply_at,
                      u.firstname, u.lastname, u.avatar_filename, COALESCE(u.role, 'student') AS reviewer_role
               FROM teacher_ratings r
               LEFT JOIN users u ON u.id = r.reviewer_id
               WHERE r.teacher_id = ?
               ORDER BY r.created_at DESC, r.id DESC
               LIMIT 100""",
            (user_id,),
        ).fetchall()
    finally:
        conn.close()

    reviews, my_review = [], None
    for r in rows:
        first, last = (r['firstname'] or '').strip(), (r['lastname'] or '').strip()
        if r['reviewer_role'] in ('student', None):      # learners are children: first name and initial only
            name = (first + (f' {last[0].upper()}.' if last else '')) or 'A learner'
        else:
            name = f"{first} {last}".strip() or 'Anonymous'
        reviews.append({
            'id': r['id'],
            'reviewer_name': name,
            'reviewer_avatar_url': get_avatar_url(r['reviewer_id'], r['avatar_filename']),
            'stars': r['stars'],
            'comment': r['comment'] or '',
            'created_at': to_iso_utc(r['created_at']),
            'reviewer_id': r['reviewer_id'],
            'reviewer_role': 'Parent' if r['reviewer_role'] == 'parent' else 'Teacher' if r['reviewer_role'] == 'teacher' else 'Learner',
            'reply': r['reply'] or '',
            'reply_at': to_iso_utc(r['reply_at']) if r['reply_at'] else None,
        })
        if r['reviewer_id'] == me:
            my_review = {'stars': r['stars'], 'comment': r['comment'] or ''}

    conn = _profile_db()
    try:
        overall = _rating_summary(conn, [user_id])[user_id]
    finally:
        conn.close()
    # the one rating: reviews, live class ratings and lesson ratings together (1-5 stars)
    distribution = {str(5 - i): n for i, n in enumerate(overall['dist'])}

    return jsonify({
        'success': True,
        'average': overall['avg'],
        'average_out_of_ten': round(overall['avg'] * 2, 1),
        'count': overall['count'],
        'review_count': summary['n'] or 0,
        'sources': overall['sources'],
        'distribution': distribution,
        'reviews': reviews,
        'my_review': my_review,
        'can_review': me != user_id and session.get('role', 'student') in ('student', 'parent') and _review_allowed(me, user_id),
        'can_reply': me == user_id,
    })


def _review_allowed(me, teacher_id):
    c = _profile_db()
    try:
        return _can_review_teacher(c, me, session.get('role', 'student'), teacher_id)
    finally:
        c.close()


def _can_review_teacher(conn, me, role, teacher_id):
    """Only people who really learned with the teacher: a learner who joined one of their live classes
    or had a lesson with them; a parent whose child had a lesson with them, or whose linked child can review them."""
    def learner_ok(uid):
        q = [('SELECT 1 FROM live_viewers v JOIN live_classes c ON c.id = v.class_id WHERE v.user_id = ? AND c.teacher_id = ?', (uid, teacher_id)),
             ('''SELECT 1 FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id WHERE t.student_id = ? AND t.teacher_id = ?
                 AND s.status IN ('completed', 'missed')''', (uid, teacher_id))]
        for sql, args in q:
            try:
                if conn.execute(sql, args).fetchone():
                    return True
            except sqlite3.Error:
                pass
        return False
    if role == 'student':
        return learner_ok(me)
    if role == 'parent':
        try:
            if conn.execute('''SELECT 1 FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id WHERE t.parent_id = ? AND t.teacher_id = ?
                               AND s.status IN ('completed', 'missed')''', (me, teacher_id)).fetchone():
                return True
            kids = [r[0] for r in conn.execute("SELECT student_id FROM parent_links WHERE parent_id = ? AND status = 'active'", (me,))]
        except sqlite3.Error:
            kids = []
        return any(learner_ok(k) for k in kids)
    return False


@app.route('/api/ratings/<int:rating_id>/report', methods=['POST'])
def api_report_rating(rating_id):
    """Report a review. It becomes a support ticket for the Eschool team (with the review text)."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    me = session['user_id']
    if _reset_rate_limited(f'review-report:{me}', limit=10, window=3600):
        return jsonify({'success': False, 'message': 'Too many reports. Please try again later.'}), 429
    conn = _profile_db()
    try:
        r = conn.execute('SELECT id, teacher_id, reviewer_id, stars, comment FROM teacher_ratings WHERE id = ?', (rating_id,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'That review was removed.'}), 404
        reason = str((request.get_json(silent=True) or {}).get('reason') or '').strip()[:300]
        desc = (f"Review #{r['id']} on teacher {r['teacher_id']}'s profile, by user {r['reviewer_id']}, {r['stars']} stars:\n"
                f"“{(r['comment'] or '(no text)')[:1000]}”\n\nWhy it was reported: {reason or '(not given)'}")
        cur = conn.execute("INSERT INTO complaints (user_id, subject, description, category, priority, status, is_read) VALUES (?, ?, ?, 'content', 'high', 'pending', 0)",
                           (me, f'Reported review #{rating_id}', desc))
        conn.commit()
        tid = cur.lastrowid
    finally:
        conn.close()
    try:
        _support_alert({'id': tid, 'subject': f'Reported review #{rating_id}', 'priority': 'high', 'category': 'content',
                        'user_name': _full_name(session.get('firstname'), session.get('lastname'), 'A user')})
    except Exception as e:
        print('support alert:', e)
    return jsonify({'success': True, 'ticket_id': tid})


@app.route('/api/users/<int:user_id>/ratings', methods=['POST'])
def api_post_user_rating(user_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    me = session['user_id']
    if me == user_id:
        return jsonify({'error': "You can't review yourself."}), 400
    if session.get('role', 'student') not in ('student', 'parent'):
        return jsonify({'error': 'Only learners and parents can review teachers.'}), 403

    data = request.get_json(silent=True) or {}
    try:
        stars = int(data.get('stars'))
    except (TypeError, ValueError):
        return jsonify({'error': 'Please pick a star rating.'}), 400
    if stars < 1 or stars > 5:
        return jsonify({'error': 'Stars must be between 1 and 5.'}), 400
    comment = re.sub(r'<[^>]*>', '', (data.get('comment') or '')).strip()
    if len(comment) > 500:
        return jsonify({'error': 'Please keep your review under 500 characters.'}), 400
    if comment and (_OPINION_PHONE.search(comment) or _OPINION_LINK.search(comment)):
        return jsonify({'error': 'Reviews can’t include phone numbers, links or social media names.'}), 400
    if _reset_rate_limited(f'review:{me}', limit=10, window=3600):
        return jsonify({'error': 'Too many reviews just now. Please try again later.'}), 429

    conn = _profile_db()
    try:
        target = conn.execute("SELECT role FROM users WHERE id = ?", (user_id,)).fetchone()
        if not target:
            return jsonify({'error': 'User not found.'}), 404
        if target['role'] != 'teacher':
            return jsonify({'error': 'Only teachers can be rated.'}), 400
        if not _can_review_teacher(conn, me, session.get('role', 'student'), user_id):
            return jsonify({'error': 'You can review a teacher after a lesson or a live class with them.'}), 403

        # Update my existing review if there is one, otherwise add it.
        # (Done in two steps instead of ON CONFLICT, so it also works on a
        # teacher_ratings table created before the one-review-per-person rule.)
        cur = conn.execute(
            """UPDATE teacher_ratings
               SET stars = ?, comment = ?, created_at = CURRENT_TIMESTAMP
               WHERE teacher_id = ? AND reviewer_id = ?""",
            (stars, comment, user_id, me),
        )
        updated = cur.rowcount > 0
        if updated:
            # an old table may hold duplicates from before: keep only the newest
            conn.execute(
                """DELETE FROM teacher_ratings
                   WHERE teacher_id = ? AND reviewer_id = ?
                     AND id NOT IN (SELECT MAX(id) FROM teacher_ratings
                                    WHERE teacher_id = ? AND reviewer_id = ?)""",
                (user_id, me, user_id, me),
            )
        else:
            conn.execute(
                """INSERT INTO teacher_ratings (teacher_id, reviewer_id, stars, comment)
                   VALUES (?, ?, ?, ?)""",
                (user_id, me, stars, comment),
            )
        create_notification(conn, user_id, f"{'Updated' if updated else 'New'} review: {stars} star{'s' if stars != 1 else ''}",
                            f"{_name_of(conn, me)} {'updated their' if updated else 'left you a'} review"
                            + (f': “{comment[:80]}”' if comment else '.'), icon='fa-star', color='orange', category='reviews')
        conn.commit()
    except sqlite3.Error as e:
        print(f"Rating save error: {e}")
        return jsonify({'error': "Couldn't save your review. Please try again."}), 500
    finally:
        conn.close()

    return jsonify({'success': True, 'updated': updated})

@app.route('/api/ratings/<int:rating_id>/reply', methods=['POST'])
def api_reply_to_rating(rating_id):
    """The teacher answers a review on their profile (empty text removes the answer)."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    text = str((request.get_json(silent=True) or {}).get('reply') or '').strip()[:600]
    conn = _profile_db()
    try:
        r = conn.execute('SELECT teacher_id, reviewer_id FROM teacher_ratings WHERE id = ?', (rating_id,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'Review not found.'}), 404
        if r['teacher_id'] != session['user_id']:
            return jsonify({'success': False, 'message': 'You can only answer reviews of you.'}), 403
        stamp = _utc_now().strftime('%Y-%m-%d %H:%M:%S')
        conn.execute('UPDATE teacher_ratings SET reply = ?, reply_at = ? WHERE id = ?',
                     (text or None, stamp if text else None, rating_id))
        if text:
            create_notification(conn, r['reviewer_id'], f"{_name_of(conn, r['teacher_id'], 'Your teacher')} answered your review",
                                text[:120], icon='fa-reply', color='blue')
        conn.commit()
        return jsonify({'success': True, 'reply': text, 'reply_at': to_iso_utc(stamp) if text else None})
    finally:
        conn.close()


@app.route('/api/users/<int:user_id>/teacher-overview')
def api_teacher_overview(user_id):
    """Everything the top of a teacher's profile shows, from real records."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    me, my_role = session['user_id'], session.get('role', 'student')
    own = me == user_id
    conn = _links_db()
    try:
        _tutor_tables(conn)
        if not can_view_profile(conn, me, my_role, user_id):
            return jsonify({'success': False, 'private': True, 'message': 'This profile is private.'}), 403
        cards = _teacher_cards(conn, [user_id])
        if not cards:
            return jsonify({'success': False, 'message': 'Teacher not found'}), 404
        t = cards[0]
        hidden = profile_hidden_parts(conn, me, my_role, user_id)
        vis = '' if own else " AND COALESCE(privacy, 'public') = 'public'"
        res = conn.execute(f'''SELECT COUNT(*), COALESCE(SUM(views), 0), COALESCE(SUM(likes), 0),
                                      SUM(CASE WHEN COALESCE(privacy, 'public') = 'private' THEN 1 ELSE 0 END)
                               FROM resources WHERE user_id = ?{vis}''', (user_id,)).fetchone()
        subjects = [{'key': r[0], 'label': RESOURCE_SUBJECT_LABELS.get(r[0], (r[0] or 'General').title()), 'count': r[1]}
                    for r in conn.execute(f'''SELECT COALESCE(category, 'general'), COUNT(*) FROM resources
                                              WHERE user_id = ?{vis} GROUP BY 1 ORDER BY 2 DESC''', (user_id,)).fetchall()]
        grades = [{'key': r[0], 'count': r[1]} for r in conn.execute(
            f'''SELECT difficulty, COUNT(*) FROM resources WHERE user_id = ?{vis} AND difficulty LIKE 'grade-%'
                GROUP BY 1 ORDER BY CAST(SUBSTR(difficulty, 7) AS INTEGER)''', (user_id,)).fetchall()]
        top = [dict(id=r[0], title=r[1], file_category=r[2] or 'other', thumbnail_url=r[3], views=r[4] or 0, likes=r[5] or 0,
                    category=r[6], difficulty=r[7])
               for r in conn.execute(f'''SELECT id, title, file_category, thumbnail_url, views, likes, category, difficulty
                                         FROM resources WHERE user_id = ?{vis}
                                         ORDER BY views DESC, likes DESC, id DESC LIMIT 3''', (user_id,)).fetchall()]
        now = _iso(_utc_now())
        lc = conn.execute('SELECT COUNT(*), SUM(CASE WHEN start_time >= ? THEN 1 ELSE 0 END) FROM live_classes WHERE teacher_id = ?',
                          (now, user_id)).fetchone()
        nxt = conn.execute('''SELECT title, subject, grade, start_time, duration_min, COALESCE(state, 'scheduled') AS state FROM live_classes
                              WHERE teacher_id = ? AND COALESCE(state, 'scheduled') != 'ended' AND (state = 'live' OR datetime(start_time, '+' || COALESCE(duration_min, 60) || ' minutes') >= datetime(?))
                              ORDER BY start_time LIMIT 1''', (user_id, now)).fetchone()
        learners = None if 'follows' in hidden else teacher_learner_count(conn, user_id)
        av = conn.execute('SELECT avatar_filename FROM users WHERE id = ?', (user_id,)).fetchone()
    finally:
        conn.close()

    about = {k: t[k] for k in ('headline', 'bio', 'subjects', 'levels', 'mode_label', 'location', 'experience_years', 'experience_label', 'joined_at',
                               'qualifications', 'availability', 'accepting', 'has_profile')}
    if own or my_role in ('parent', 'student'):      # the people who can hire this teacher see the price
        about.update(rate=t['rate'], session_minutes=t['session_minutes'])
    out = {
        'success': True, 'own': own, 'viewer_role': my_role, 'hidden': hidden, 'about': about,
        'stats': {'resources': res[0], 'private_resources': (res[3] or 0) if own else None, 'views': res[1], 'likes': res[2],
                  'learners_following': learners, 'rating_avg': t['rating_avg'], 'rating_count': t['rating_count'],
                  'live_total': lc[0] or 0, 'live_upcoming': lc[1] or 0, 'private_students': t['students'],
                  'lessons_done': t['sessions_done'], 'attendance_rate': t['attendance_rate'],
                  'class_rating_avg': t.get('class_rating_avg'), 'class_rating_count': t.get('class_rating_count', 0)},
        'subjects': subjects, 'grades': grades, 'top_resources': top,
        'next_live': dict(nxt) if nxt else None,
    }
    if own:   # what's still missing from a complete profile
        a = t
        out['checklist'] = [
            {'key': 'photo', 'label': 'Profile photo', 'done': bool(av and av[0]), 'href': '/teacher-settings'},
            {'key': 'headline', 'label': 'Headline', 'done': a['has_profile'] and bool(a['headline'])},
            {'key': 'bio', 'label': 'About you (40+ characters)', 'done': len(a['bio'] or '') >= 40},
            {'key': 'subjects', 'label': 'Subjects you teach', 'done': bool(_jlist_safe(a['subjects']))},
            {'key': 'levels', 'label': 'Grades you teach', 'done': bool(a['levels'])},
            {'key': 'qualifications', 'label': 'Qualifications', 'done': bool(a['qualifications'])},
            {'key': 'rate', 'label': 'Private lesson price', 'done': bool(a['rate'])},
            {'key': 'live', 'label': 'First live class', 'done': (lc[0] or 0) > 0, 'href': '/teacher-live'},
        ]
    return jsonify(out)


def _jlist_safe(v):
    return v if isinstance(v, list) else []


@app.after_request
def no_cache_for_logged_in_pages(response):
    if 'user_id' in session and response.mimetype == 'text/html':
        response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        response.headers['Pragma'] = 'no-cache'
    return response


# ============ CALLS ON EVERY PAGE ============
# Adds static/js/eschool-calls.js to every signed-in page (learner, teacher,
# parent) so an incoming call rings and can be answered wherever the person is.
CALLS_SCRIPT_TAG = '<script src="/eschool-calls.js?v=4" defer></script>'


@app.route('/eschool-calls.js')
def eschool_calls_script():
    """Serves the call script from wherever it was put: static/js/, static/,
    or next to backen.py. If it isn't anywhere, the page is told so and the
    Messages page explains it instead of the call buttons doing nothing."""
    here = os.path.dirname(os.path.abspath(__file__))
    static_dir = app.static_folder or os.path.join(here, 'static')
    for folder in (os.path.join(static_dir, 'js'), static_dir, here):
        path = os.path.join(folder, 'eschool-calls.js')
        if os.path.isfile(path):
            resp = send_from_directory(folder, 'eschool-calls.js', mimetype='application/javascript')
            resp.headers['Cache-Control'] = 'no-cache'
            return resp
    print('eschool-calls.js not found. Put it in static/js/ (calls are off until then).')
    return Response('window.EschoolCallsMissing = true;', mimetype='application/javascript',
                    headers={'Cache-Control': 'no-store'})

@app.after_request
def add_call_script_to_pages(response):
    try:
        if ('user_id' not in session or response.status_code != 200
                or response.mimetype != 'text/html' or response.direct_passthrough
                or request.path.startswith('/static/')):
            return response
        html = response.get_data(as_text=True)
        if '<html' not in html.lower():
            return response
        tags = '' if 'eschool-calls.js' in html else CALLS_SCRIPT_TAG
        if not session.get('tz_seen'):
            tags += TZ_SCRIPT
        if 'id="messageInput"' in html and 'eschool-files.js' not in html:
            tags += '<script src="/eschool-files.js?v=1" defer></script>'      # documents in messages
        if not tags:
            return response
        idx = html.lower().rfind('</body>')
        html = html[:idx] + tags + html[idx:] if idx != -1 else html + tags
        response.set_data(html)
    except Exception as e:
        print(f"call script inject skipped: {e}")
    return response

# ============ SAVE BROWSER DATA ON THE SERVER (progress on every device) ============
# Some pages keep things in the browser's localStorage: course modules done,
# module test results, notes, settings and so on. On its own, that data lives
# in ONE browser only: another browser or phone starts empty, and clearing the
# browser loses it.
# This keeps a permanent copy of every signed-in person's localStorage in the
# database (table user_storage) and puts it back wherever they sign in:
#   1. Every signed-in page gets the person's saved data written into
#      localStorage BEFORE the page's own scripts run, so pages simply find it.
#   2. Every change a page makes is sent back to the server (/api/storage)
#      within a few seconds, and when the page is closed.
#   3. If someone else signs in on the same browser, the previous person's
#      data is removed from the browser (it stays safe on the server).
# No template needs to change. Items whose name starts with __es_ or that are
# about calls stay in the browser only.

STORAGE_MAX_VALUE = 1_000_000        # characters in one item
STORAGE_MAX_TOTAL = 8_000_000        # characters for one person in total
STORAGE_MAX_ITEMS = 3000
# lastActivity / eschool_logout are about this device only: copying them to another device signed people out
# the moment they opened Eschool there (the old 'last active' time looked like hours of no activity)
STORAGE_SKIP = r'^(__es_|eschool[-_]?calls?|calls?[-_]|webrtc|rtc[-_]|lastActivity\.|eschool_logout)'
_STORAGE_SKIP_RE = re.compile(STORAGE_SKIP, re.I)


def _storage_table(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS user_storage (
        user_id INTEGER NOT NULL, k TEXT NOT NULL, v TEXT, updated_at TEXT NOT NULL,
        PRIMARY KEY (user_id, k))''')


def _storage_items(conn, uid):
    """{name: value or None (None = removed on purpose)} for one person."""
    _storage_table(conn)
    return {k: v for k, v in conn.execute('SELECT k, v FROM user_storage WHERE user_id = ?', (uid,)).fetchall()
            if not _STORAGE_SKIP_RE.match(k)}


@app.route('/api/storage', methods=['GET', 'POST'])
def api_storage():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    conn = sqlite3.connect('users.db', timeout=10)
    try:
        if request.method == 'GET':
            return jsonify({'success': True, 'user': uid, 'items': _storage_items(conn, uid)})

        data = request.get_json(silent=True, force=True) or {}
        if data.get('user') is not None and str(data.get('user')) != str(uid):
            return jsonify({'success': False, 'message': 'Signed in as someone else now.'}), 409
        items = data.get('items')
        if not isinstance(items, dict):
            return jsonify({'success': False, 'message': 'Nothing to save.'}), 400
        current = _storage_items(conn, uid)
        now = _iso(_utc_now())
        saved = 0
        for k, v in list(items.items())[:STORAGE_MAX_ITEMS]:
            if not isinstance(k, str) or not k or len(k) > 200 or _STORAGE_SKIP_RE.match(k):
                continue
            if v is not None:
                if not isinstance(v, str) or len(v) > STORAGE_MAX_VALUE:
                    continue
            current[k] = v
            conn.execute('''INSERT INTO user_storage (user_id, k, v, updated_at) VALUES (?, ?, ?, ?)
                            ON CONFLICT(user_id, k) DO UPDATE SET v = excluded.v, updated_at = excluded.updated_at''',
                         (uid, k, v, now))
            saved += 1
        total = sum(len(k) + len(v or '') for k, v in current.items())
        if total > STORAGE_MAX_TOTAL or len(current) > STORAGE_MAX_ITEMS:
            conn.rollback()
            return jsonify({'success': False, 'message': 'Too much saved data.'}), 413
        conn.commit()
        return jsonify({'success': True, 'saved': saved})
    finally:
        conn.close()


STORAGE_SYNC_JS = r"""
(function () {
  var S = window.__ES_SYNC, ls;
  try { ls = window.localStorage; ls.getItem('__es_test'); } catch (e) { return; }
  if (!S || !ls || window.__esSyncOn) return;
  window.__esSyncOn = true;
  var USER = '__es_sync_user', PENDING = '__es_sync_pending', me = String(S.user);
  var skipRe = new RegExp(S.skip, 'i');
  function skip(k) { return k == null || skipRe.test(String(k)); }
  function keys() { var out = []; for (var i = 0; i < ls.length; i++) { var k = ls.key(i); if (!skip(k)) out.push(k); } return out; }
  function readJSON(k) { try { return JSON.parse(ls.getItem(k) || '{}') || {}; } catch (e) { return {}; } }
  var items = S.items || {}, has = Object.prototype.hasOwnProperty;
  var last = ls.getItem(USER), pending = {};

  if (last && last !== me) {
    keys().forEach(function (k) { ls.removeItem(k); });          // someone else's data: safe on the server
    ls.removeItem(PENDING);
  } else if (last === me) {
    pending = readJSON(PENDING);                                 // changes not sent last time
  }
  Object.keys(items).forEach(function (k) {                       // what the server has
    if (skip(k)) return;
    try { if (items[k] === null) ls.removeItem(k); else ls.setItem(k, items[k]); } catch (e) {}
  });
  if (!last) {                                                    // first time in this browser:
    keys().forEach(function (k) { if (!has.call(items, k)) pending[k] = ls.getItem(k); });   // send up what only it has
  }
  Object.keys(pending).forEach(function (k) {                     // put back unsent changes
    if (skip(k)) return;
    try { if (pending[k] === null) ls.removeItem(k); else ls.setItem(k, pending[k]); } catch (e) {}
  });
  try { ls.setItem(USER, me); } catch (e) {}

  var known = {};
  keys().forEach(function (k) { known[k] = ls.getItem(k); });
  function remember() { try { ls.setItem(PENDING, JSON.stringify(pending)); } catch (e) {} }
  function scan() {
    keys().forEach(function (k) { var v = ls.getItem(k); if (known[k] !== v) { known[k] = v; pending[k] = v; } });
    Object.keys(known).forEach(function (k) { if (ls.getItem(k) === null) { delete known[k]; pending[k] = null; } });
  }
  var sending = false;
  function flush(leaving) {
    scan();
    var batch = pending, names = Object.keys(batch);
    if (!names.length) { remember(); return; }
    remember();
    var body = JSON.stringify({ user: me, items: batch });
    if (leaving && navigator.sendBeacon) {
      navigator.sendBeacon('/api/storage', new Blob([body], { type: 'application/json' }));
      return;
    }
    if (sending) return;
    sending = true;
    fetch('/api/storage', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: body,
                            credentials: 'same-origin', keepalive: body.length < 60000 })
      .then(function (r) {
        if (r.ok) {
          names.forEach(function (k) { if (pending[k] === batch[k]) delete pending[k]; });
          remember();
        }
      })
      .catch(function () {})
      .then(function () { sending = false; });
  }
  if (Object.keys(pending).length) setTimeout(flush, 300);
  setInterval(flush, 3000);
  window.addEventListener('pagehide', function () { flush(true); });
  document.addEventListener('visibilitychange', function () { if (document.visibilityState === 'hidden') flush(true); });
  window.addEventListener('storage', function (e) {               // another tab changed something
    if (e.storageArea === ls && e.key && !skip(e.key)) known[e.key] = e.newValue;
  });
})();
"""


@app.after_request
def add_storage_sync_to_pages(response):
    """Writes the person's saved data into the page before any other script runs."""
    try:
        if ('user_id' not in session or response.status_code != 200
                or response.mimetype != 'text/html' or response.direct_passthrough
                or request.path.startswith('/static/')):
            return response
        html = response.get_data(as_text=True)
        if '__ES_SYNC' in html or '<html' not in html.lower():
            return response
        conn = sqlite3.connect('users.db', timeout=10)
        try:
            items = _storage_items(conn, session['user_id'])
        finally:
            conn.close()
        data = json.dumps({'user': session['user_id'], 'items': items, 'skip': STORAGE_SKIP})
        data = data.replace('</', '<\\/').replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')
        tag = f'<script>window.__ES_SYNC={data};</script><script>{STORAGE_SYNC_JS}</script>'
        low = html.lower()
        m = re.search(r'<head[^>]*>', low)
        if not m:
            m = re.search(r'<body[^>]*>', low)
        html = html[:m.end()] + tag + html[m.end():] if m else tag + html
        response.set_data(html)
    except Exception as e:
        print(f"storage sync inject skipped: {e}")
    return response


# ============ SWITCH / ADD ACCOUNT (students only) ============

MAX_LINKED_ACCOUNTS = 5


def _student_accounts_guard():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if (session.get('role') or 'student') != 'student':
        return jsonify({'success': False, 'message': 'Only student accounts can use this'}), 403
    return None


# Added accounts are kept in their OWN signed cookie (not only in the login
# session), so the list survives refreshes, logging out and back in, browser
# restarts, and requests that rewrite the session cookie at the same time.
# The cookie is signed with app.secret_key, so it can't be edited by hand,
# and it's only used while you're signed in as one of the accounts in it.
from itsdangerous import URLSafeSerializer, BadSignature

LINKED_COOKIE = 'eschool_accounts'
LINKED_COOKIE_DAYS = 90


def _linked_serializer():
    return URLSafeSerializer(app.secret_key, salt='eschool-linked-accounts')


def _linked_from_cookie():
    raw = request.cookies.get(LINKED_COOKIE)
    if not raw:
        return []
    try:
        ids = _linked_serializer().loads(raw)
    except BadSignature:
        return []
    return [int(i) for i in ids if isinstance(i, int)] if isinstance(ids, list) else []


def _linked_account_ids():
    me = session['user_id']
    ids = [int(i) for i in session.get('linked_accounts', []) if isinstance(i, int)]
    remembered = _linked_from_cookie()
    if me in remembered:              # only trust the cookie for accounts in it
        for i in remembered:
            if i not in ids:
                ids.append(i)
    if me not in ids:
        ids.insert(0, me)
    return ids[:MAX_LINKED_ACCOUNTS]


def _save_linked_ids(response, ids):
    """Store the list in the session AND in the long-lived cookie."""
    session['linked_accounts'] = ids
    session.modified = True
    response.set_cookie(
        LINKED_COOKIE, _linked_serializer().dumps(ids),
        max_age=LINKED_COOKIE_DAYS * 24 * 3600,
        httponly=True, samesite='Lax', secure=request.is_secure
    )
    return response


@app.route('/api/accounts', methods=['GET'])
def list_linked_accounts():
    guard = _student_accounts_guard()
    if guard:
        return guard

    ids = _linked_account_ids()
    placeholders = ','.join('?' for _ in ids)

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    cursor.execute(f'''
        SELECT id, firstname, lastname, email, avatar_filename
        FROM users
        WHERE id IN ({placeholders}) AND COALESCE(role, 'student') = 'student'
    ''', ids)
    rows = cursor.fetchall()
    conn.close()

    valid_ids = [r[0] for r in rows]
    keep = [i for i in ids if i in valid_ids]

    accounts = []
    for uid, first, last, email, avatar in rows:
        first = (first or '').strip()
        last = (last or '').strip()
        accounts.append({
            'id': uid,
            'name': f"{first} {last}".strip() or 'Student',
            'initials': (first[:1] + last[:1]).upper() or 'ES',
            'email_masked': mask_email(email),
            'avatar_url': get_avatar_url(uid, avatar),
            'current': uid == session['user_id']
        })
    accounts.sort(key=lambda a: (not a['current'], a['name'].lower()))

    return _save_linked_ids(jsonify({'success': True, 'accounts': accounts}), keep)


@app.route('/api/accounts/add', methods=['POST'])
def add_linked_account():
    guard = _student_accounts_guard()
    if guard:
        return guard

    data = request.get_json(silent=True) or {}
    email = (data.get('email') or '').strip()
    password = data.get('password') or ''

    if not email or not password:
        return jsonify({'success': False, 'message': 'Enter the email and password'}), 400

    wait = login_wait_minutes(email)
    if wait:
        return jsonify({'success': False, 'message': too_many_attempts_message(wait)}), 429
    # a signed-in person may not try many different email/password pairs either
    who = f"add-account:{session['user_id']}"
    wait = login_wait_minutes(who)
    if wait:
        return jsonify({'success': False, 'message': too_many_attempts_message(wait)}), 429

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    cursor.execute('SELECT id, role, password FROM users WHERE lower(email) = lower(?) AND password IS NOT NULL', (email,))
    user = next((r for r in cursor.fetchall() if password_matches(r[2], password)), None)
    conn.close()

    if not user:
        login_failed(email)
        login_failed(who)
        print(f"add-account failed: user {session['user_id']} tried {email!r} from {request.remote_addr}")
        return jsonify({'success': False, 'message': 'Invalid email or password'}), 401
    login_succeeded(email)
    if (user[1] or 'student') != 'student':
        return jsonify({'success': False, 'message': 'Only student accounts can be added'}), 403

    ids = _linked_account_ids()
    if user[0] in ids:
        return jsonify({'success': False, 'message': 'This account is already added'}), 409
    if len(ids) >= MAX_LINKED_ACCOUNTS:
        return jsonify({'success': False,
                        'message': f'You can add up to {MAX_LINKED_ACCOUNTS} accounts'}), 400

    ids.append(user[0])
    return _save_linked_ids(jsonify({'success': True}), ids)


@app.route('/api/accounts/switch/<int:target_id>', methods=['POST'])
def switch_linked_account(target_id):
    guard = _student_accounts_guard()
    if guard:
        return guard

    if target_id not in _linked_account_ids():
        return jsonify({'success': False, 'message': 'Account not linked in this browser'}), 403

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()
    cursor.execute('''
        SELECT id, firstname, lastname, email, role, country
        FROM users WHERE id = ?
    ''', (target_id,))
    user = cursor.fetchone()
    conn.close()

    if not user or (user[4] or 'student') != 'student':
        return jsonify({'success': False, 'message': 'Account not available'}), 404

    linked = _linked_account_ids()

    session['user_id'] = user[0]
    session['firstname'] = user[1]
    session['lastname'] = user[2]
    session['email'] = user[3]
    session['role'] = 'student'
    session['country'] = user[5]
    account_on_login(user[0], notify=False, method='switch')   # session check
    quote = get_daily_quote()
    session['quote_text'] = quote['text']
    session['quote_author'] = quote['author']

    return _save_linked_ids(jsonify({'success': True}), linked)

# ============ TEACHERS: search + follow stats (dashboard card) ============

@app.route('/api/teachers', methods=['GET'])
def list_teachers():
    """Teachers only. ?q= searches by first name, last name or full name."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    my_id = session['user_id']
    q = (request.args.get('q') or '').strip()

    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    sql = '''
        SELECT id, firstname, lastname, avatar_filename
        FROM users
        WHERE role = 'teacher' AND id != ?
    '''
    params = [my_id]

    if q:
        safe = q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
        like = f'%{safe}%'
        sql += '''
            AND (firstname LIKE ? ESCAPE '\\'
                 OR lastname LIKE ? ESCAPE '\\'
                 OR (firstname || ' ' || lastname) LIKE ? ESCAPE '\\')
        '''
        params += [like, like, like]

    sql += ' ORDER BY firstname, lastname LIMIT 8'
    cursor.execute(sql, params)
    rows = cursor.fetchall()

    following_ids = get_following_ids(cursor, my_id)
    follower_counts = get_follower_counts(cursor, [r[0] for r in rows])
    conn.close()

    teachers = []
    for uid, first, last, avatar in rows:
        first = (first or '').strip()
        last = (last or '').strip()
        name = f"{first} {last}".strip()
        if not name:
            continue
        teachers.append({
            'id': uid,
            'name': name,
            'initials': ((first[:1] + last[:1]).upper() or 'T'),
            'avatar_url': get_avatar_url(uid, avatar),
            'following': uid in following_ids,
            'followers_count': follower_counts.get(uid, 0)
        })

    return jsonify({'success': True, 'teachers': teachers})


@app.route('/api/teachers/follow-stats', methods=['GET'])
def teacher_follow_stats():
    """following_count = teachers I follow, followers_count = teachers who follow me."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    my_id = session['user_id']
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    cursor.execute('''
        SELECT COUNT(*) FROM follows f
        JOIN users u ON u.id = f.following_id
        WHERE f.follower_id = ? AND u.role = 'teacher'
    ''', (my_id,))
    following_count = cursor.fetchone()[0]

    cursor.execute('''
        SELECT COUNT(*) FROM follows f
        JOIN users u ON u.id = f.follower_id
        WHERE f.following_id = ? AND u.role = 'teacher'
    ''', (my_id,))
    followers_count = cursor.fetchone()[0]

    conn.close()
    return jsonify({'success': True,
                    'following_count': following_count,
                    'followers_count': followers_count})


# ============ LEARNER PROFILE: progress, achievements, leaderboard ============
# Built from student_progress_summary, which each learner's dashboard keeps
# up to date. EP (Eschool Points) turn everything a learner does into one comparable
# score for the leaderboard.

# ============ EP (Eschool Points) — kept on the server ============
# Every EP a learner earns is one row in ep_events, so the leaderboard,
# profile and Progress page all read the same numbers, and nobody can give
# themselves EP by editing their browser storage.
#   +10 EP  module finished AND its module test passed (60%+), first time only
#   +5  EP  course quiz passed (once per course per day)
#   +5  EP  Daily Quiz Test passed (once per day)
#   +200 EP whole course finished (every module done)
#   +50 EP  every 10 in a row on the module streak (10, 20, 30 ...)
#   +40 EP  every 10 days in a row on the quiz streak (10, 20, 30 ...)
# There is no limit on how much EP someone can earn.

EP_RULES = {'module': 10, 'quiz': 5, 'course': 200,          # shown on the pages
            'module_streak': 50, 'quiz_streak': 40, 'legendary': 500}
EP_POINTS = {'module': 10, 'quiz': 5, 'daily_quiz': 5, 'course': 200,
             'module_streak': 50, 'quiz_streak': 40, 'legendary': 500}   # legendary: each Legendary badge earned (not Genesis)
EP_STREAK_STEP = 10         # a streak bonus at 10, 20, 30 ...
EP_STREAK_KINDS = {'module': 'module_streak', 'quiz': 'quiz_streak'}
EP_GOAL_MIN, EP_GOAL_MAX = 10, 100000   # weekly goal each learner sets on the Progress page
MODULE_PASS_RATE = 0.6      # module test pass mark (60%), same as courses.html
EP_PER_LEVEL = 100          # all-time EP per level

# How to earn EP, as the Leaderboard page lists it (one place, so pages can't drift)
EP_EARN = [
    ('module', 'Pass a module (finish it + pass its module test)'),
    ('course', 'Finish a whole course'),
    ('quiz', 'Pass a quiz (course quiz or Daily Quiz Test, once a day each)'),
    ('module_streak', 'Every 10 on your module streak'),
    ('quiz_streak', 'Every 10 days on your quiz streak'),
    ('legendary', 'Earn a Legendary badge (Achievements)'),
]

# Leaderboard ranking cache: {(period, hidden ids): (time, ranked)}. Cleared when EP is added.
_LB_CACHE = {}
_LB_CACHE_SECONDS = 30
_LB_LAST_MONTH = {}     # {month start: (time, [(user_id, first, last, avatar, ep)])}

# Module count of each course. Keep in sync with courses.html.
EP_COURSE_MODULES = {'math': 25, 'csl': 28, 'english': 12, 'kiswahili': 15}
EP_COURSE_NAMES = {'math': 'Grade 10 Mathematics', 'csl': 'Grade 10 Community Service Learning (CSL)',
                   'english': 'Grade 10 English', 'kiswahili': 'Grade 10 Kiswahili'}

_DAY_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _ep_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS ep_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            kind TEXT NOT NULL,          -- module | quiz | daily_quiz | course | module_streak | quiz_streak
            ref TEXT NOT NULL,           -- e.g. math:3, math:2026-10-22, 2026-10-22, math
            ep INTEGER NOT NULL,
            day TEXT,                    -- Nairobi date earned; NULL = before EP tracking began
            created_at TEXT NOT NULL,
            UNIQUE (user_id, kind, ref)
        )
    ''')
    conn.execute('CREATE INDEX IF NOT EXISTS idx_ep_events_user_day ON ep_events (user_id, day)')
    conn.execute('''
        CREATE TABLE IF NOT EXISTS ep_backfill (
            user_id INTEGER PRIMARY KEY,
            done_at TEXT NOT NULL
        )
    ''')
    # Where each learner's streaks were last seen, so every 10 in a row is
    # rewarded once, and a broken streak starts a new run.
    conn.execute('''
        CREATE TABLE IF NOT EXISTS ep_streaks (
            user_id INTEGER NOT NULL,
            kind TEXT NOT NULL,              -- module | quiz
            run INTEGER NOT NULL DEFAULT 1,  -- goes up each time the streak breaks
            last_value INTEGER NOT NULL DEFAULT 0,
            awarded INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (user_id, kind)
        )
    ''')
    if 'best' not in {r[1] for r in conn.execute('PRAGMA table_info(ep_streaks)').fetchall()}:
        conn.execute('ALTER TABLE ep_streaks ADD COLUMN best INTEGER NOT NULL DEFAULT 0')
    # Each learner's own weekly EP goal (set on the Progress page)
    conn.execute('''
        CREATE TABLE IF NOT EXISTS ep_goals (
            user_id INTEGER PRIMARY KEY,
            weekly_goal INTEGER NOT NULL,
            updated_at TEXT NOT NULL
        )
    ''')
    # Score (%) of the passed module test / quiz, for the perfect-score achievements
    if 'pct' not in {r[1] for r in conn.execute('PRAGMA table_info(ep_events)').fetchall()}:
        conn.execute('ALTER TABLE ep_events ADD COLUMN pct INTEGER')
    # Keep stored EP in line with the current rules (e.g. course bonus 100 -> 200)
    for kind, pts in EP_POINTS.items():
        conn.execute('UPDATE ep_events SET ep = ? WHERE kind = ? AND ep != ?', (pts, kind, pts))


def _nairobi_now():
    return datetime.now(timezone.utc) + timedelta(hours=3)


def _week_start(day=None):
    """Monday (YYYY-MM-DD) of the Nairobi week that contains `day` (default today)."""
    d = datetime.strptime(day, '%Y-%m-%d') if day else _nairobi_now().replace(tzinfo=None)
    return (d - timedelta(days=d.weekday())).strftime('%Y-%m-%d')


def _week_seconds_left():
    now = _nairobi_now().replace(tzinfo=None)
    monday = datetime.strptime(_week_start(), '%Y-%m-%d')
    return max(0, int((monday + timedelta(days=7) - now).total_seconds()))


def _month_start(day=None):
    """First day (YYYY-MM-DD) of the Nairobi month that contains `day` (default today).
    The leaderboard ranks learners by EP earned this month."""
    d = datetime.strptime(day, '%Y-%m-%d') if day else _nairobi_now().replace(tzinfo=None)
    return d.strftime('%Y-%m-01')


def _next_month_start(day=None):
    d = datetime.strptime(_month_start(day), '%Y-%m-%d')
    return (d.replace(year=d.year + 1, month=1) if d.month == 12 else d.replace(month=d.month + 1)).strftime('%Y-%m-%d')


def _month_end(day=None):
    return (datetime.strptime(_next_month_start(day), '%Y-%m-%d') - timedelta(days=1)).strftime('%Y-%m-%d')


def _month_seconds_left():
    now = _nairobi_now().replace(tzinfo=None)
    return max(0, int((datetime.strptime(_next_month_start(), '%Y-%m-%d') - now).total_seconds()))


def _valid_day(day):
    if not isinstance(day, str) or not _DAY_RE.match(day):
        return False
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except ValueError:
        return False
    return day <= _nairobi_today()


def _ep_add(conn, user_id, kind, ref, day, pct=None):
    """Adds one EP event; returns True if it was new. pct = score % (best one is kept)."""
    cur = conn.execute(
        'INSERT OR IGNORE INTO ep_events (user_id, kind, ref, ep, day, created_at, pct) VALUES (?, ?, ?, ?, ?, ?, ?)',
        (user_id, kind, ref, EP_POINTS[kind], day, datetime.now(timezone.utc).isoformat(), pct))
    if cur.rowcount > 0:
        _LB_CACHE.clear()      # the leaderboard shows new EP straight away
    if cur.rowcount == 0 and pct is not None:
        conn.execute('UPDATE ep_events SET pct = ? WHERE user_id = ? AND kind = ? AND ref = ? AND (pct IS NULL OR pct < ?)',
                     (pct, user_id, kind, ref, pct))
    return cur.rowcount > 0


def _pct(v):
    """A score percentage 0-100 from the page, or None."""
    return v if isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 100 else None


def _ep_totals(conn, only_ids=None):
    """{user_id: {'total', 'week', 'last_at', 'week_last_at'}} for everyone with EP."""
    _ep_table(conn)
    week = _week_start()
    month = _month_start()
    sql = '''
        SELECT user_id,
               SUM(ep) AS total,
               SUM(CASE WHEN day >= ? THEN ep ELSE 0 END) AS week,
               SUM(CASE WHEN day >= ? THEN ep ELSE 0 END) AS month,
               MAX(created_at) AS last_at,
               MAX(CASE WHEN day >= ? THEN created_at END) AS week_last_at,
               MAX(CASE WHEN day >= ? THEN created_at END) AS month_last_at,
               SUM(CASE WHEN kind = 'module' THEN 1 ELSE 0 END) AS modules
        FROM ep_events
    '''
    params = [week, month, week, month]
    if only_ids is not None:
        ids = list(only_ids) or [-1]
        sql += f" WHERE user_id IN ({','.join('?' for _ in ids)})"
        params += ids
    sql += ' GROUP BY user_id'
    return {r['user_id']: {'total': r['total'] or 0, 'week': r['week'] or 0, 'month': r['month'] or 0,
                           'last_at': r['last_at'], 'week_last_at': r['week_last_at'],
                           'month_last_at': r['month_last_at'],
                           'modules': r['modules'] or 0}
            for r in conn.execute(sql, params).fetchall()}


def _ep_summary(conn, user_id):
    """What the Progress page shows: this week, past weeks, all-time."""
    _ep_table(conn)
    week = _week_start()
    rows = conn.execute('SELECT kind, ref, ep, day FROM ep_events WHERE user_id = ? ORDER BY day DESC, id DESC',
                        (user_id,)).fetchall()
    g = conn.execute('SELECT weekly_goal FROM ep_goals WHERE user_id = ?', (user_id,)).fetchone()
    goal = g['weekly_goal'] if g else None
    total = sum(r['ep'] for r in rows)
    earlier = sum(r['ep'] for r in rows if not r['day'])
    by_week = {}
    for r in rows:
        if r['day']:
            wk = _week_start(r['day'])
            by_week[wk] = by_week.get(wk, 0) + r['ep']
    week_ep = by_week.get(week, 0)
    month = _month_start()
    by_month = {}
    for r in rows:
        if r['day']:
            by_month[r['day'][:7]] = by_month.get(r['day'][:7], 0) + r['ep']
    month_history = []          # last 6 months, oldest first, including empty ones
    y, m = int(month[:4]), int(month[5:7])
    for i in range(5, -1, -1):
        mm, yy = m - i, y
        while mm <= 0:
            mm, yy = mm + 12, yy - 1
        key = f'{yy:04d}-{mm:02d}'
        month_history.append({'start': key + '-01', 'label': datetime(yy, mm, 1).strftime('%b'), 'ep': by_month.get(key, 0)})

    # last 8 weeks, oldest first, including empty ones
    monday = datetime.strptime(week, '%Y-%m-%d')
    history = []
    for i in range(7, -1, -1):
        k = (monday - timedelta(days=7 * i)).strftime('%Y-%m-%d')
        history.append({'start': k, 'ep': by_week.get(k, 0)})

    def item(r):
        course, _, rest = r['ref'].partition(':')
        out = {'kind': r['kind'], 'ep': r['ep'], 'day': r['day']}
        if r['kind'] == 'module':
            out.update(course=course, module=int(rest) if rest.isdigit() else None)
        elif r['kind'] in ('quiz', 'course'):
            out.update(course=course)
        if out.get('course'):
            out['course_name'] = EP_COURSE_NAMES.get(out['course'], out['course'])
        elif r['kind'] in ('module_streak', 'quiz_streak'):
            out.update(milestone=int(rest) if rest.isdigit() else None)
        elif r['kind'] == 'legendary':
            out['badge'] = next((d[1] for d in LEGENDARY_DEFS if 'legend_' + d[0] == r['ref']), 'Legendary badge')
        elif r['kind'].startswith('career_') or r['kind'] in ('activity', 'starter'):
            out['label'], out['sub'] = _ep_event_label(r)
        return out

    return {
        'total': total,
        'earlier': earlier,
        'level': total // EP_PER_LEVEL + 1,
        'week': {
            'start': week,
            'end': (monday + timedelta(days=6)).strftime('%Y-%m-%d'),
            'ep': week_ep,
            'goal': goal,                       # None until the learner sets one
            'percent': min(100, round(week_ep / goal * 100)) if goal else None,
            'seconds_left': _week_seconds_left(),
            'items': [item(r) for r in rows if r['day'] and r['day'] >= week],
        },
        'history': history,
        'best_week': max(by_week.values()) if by_week else 0,
        # this month: what the leaderboard ranks by
        'month': {
            'start': month,
            'end': _month_end(),
            'name': datetime.strptime(month, '%Y-%m-%d').strftime('%B %Y'),
            'ep': by_month.get(month[:7], 0),
            'seconds_left': _month_seconds_left(),
            'items': [item(r) for r in rows if r['day'] and r['day'] >= month],
        },
        'month_history': month_history,
        'best_month': max(by_month.values()) if by_month else 0,
        'rules': EP_RULES,
    }


def _ep_streak_bonus(conn, uid, kind, value, day):
    """
    Gives the streak bonus for every 10 in a row (10, 20, 30 ...) once per run.
    A value lower than last time means the streak broke, so a new run starts.
    """
    if not isinstance(value, int) or isinstance(value, bool) or value < 0 or value > 100000:
        return 0
    row = conn.execute('SELECT run, last_value, awarded FROM ep_streaks WHERE user_id = ? AND kind = ?',
                       (uid, kind)).fetchone()
    run, last, awarded = (row['run'], row['last_value'], row['awarded']) if row else (1, 0, 0)
    if value < last:              # streak was broken -> new run
        run, awarded = run + 1, 0
    added = 0
    while awarded + EP_STREAK_STEP <= value:
        awarded += EP_STREAK_STEP
        added += _ep_add(conn, uid, EP_STREAK_KINDS[kind], f'{run}:{awarded}', day)
    conn.execute('''INSERT INTO ep_streaks (user_id, kind, run, last_value, awarded, best) VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(user_id, kind) DO UPDATE SET run = excluded.run,
                        last_value = excluded.last_value, awarded = excluded.awarded,
                        best = MAX(ep_streaks.best, excluded.best)''',
                 (uid, kind, run, value, awarded, value))
    return added


def _module_test_passed(t):
    """{'score': 4, 'total': 5} -> True when the score reaches the 60% pass mark."""
    if not isinstance(t, dict):
        return False
    score, total = t.get('score'), t.get('total')
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in (score, total)):
        return False
    if total <= 0 or total > 100 or score < 0 or score > total:
        return False
    return score >= math.ceil(total * MODULE_PASS_RATE)


_EP_SYNC_LAST = {}   # learner id -> time of their last real EP sync
EP_SYNC_GAP = 4      # seconds between two real syncs of one learner


@app.route('/api/ep/sync', methods=['POST'])
def api_ep_sync():
    """
    The courses page (and Progress page) send what the learner has finished:
      { "courses": [{"id": "math", "completed": [0, 1, 2], "finished": false,
                     "tests": {"0": {"score": 4, "total": 5}, ...}}],          // module test results
        "quizzes": [{"course": "math", "day": "2026-10-22", "pct": 80}],   // passed course-quiz days
        "daily":   [{"day": "2026-10-22", "pct": 90}],                    // passed Daily Quiz Test days
        "streaks": {"module": 12, "quiz": 4} }                  // current streaks (0 if broken)
    The server decides the EP and the date. The very first sync brings in
    older work: modules/courses go in as "earlier" (no week), quiz days keep
    their own dates. After that, a module only earns EP once it is finished
    AND its module test was passed (60%+); new EP is dated today and only
    quizzes from today or yesterday are accepted.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Only learners earn EP.'}), 403

    uid = session['user_id']
    data = request.get_json(silent=True) or {}
    today = _nairobi_today()
    yesterday = (datetime.strptime(today, '%Y-%m-%d') - timedelta(days=1)).strftime('%Y-%m-%d')

    # at most one real sync every few seconds per learner. A call that comes too soon is not lost:
    # the answer says when to send it again (retry_in), and the Courses and Progress pages do.
    now_ts = _clock.time()
    wait = EP_SYNC_GAP - (now_ts - _EP_SYNC_LAST.get(uid, 0))
    if wait > 0:
        conn = _links_db()
        try:
            _ep_table(conn)
            return jsonify({'success': True, 'added': 0, 'throttled': True, 'retry_in': round(wait, 1) + 0.5, **_ep_summary(conn, uid)})
        finally:
            conn.close()
    _EP_SYNC_LAST[uid] = now_ts

    conn = _links_db()
    try:
        _ep_table(conn)
        first = conn.execute('SELECT 1 FROM ep_backfill WHERE user_id = ?', (uid,)).fetchone() is None
        added = 0

        courses = data.get('courses') if isinstance(data.get('courses'), list) else []
        for c in courses[:50]:
            if not isinstance(c, dict):
                continue
            cid = str(c.get('id') or '')
            count = EP_COURSE_MODULES.get(cid)
            if not count:
                continue
            completed = c.get('completed') if isinstance(c.get('completed'), list) else []
            done = {i for i in completed[:200]
                    if isinstance(i, int) and not isinstance(i, bool) and 0 <= i < count}
            tests = c.get('tests') if isinstance(c.get('tests'), dict) else {}
            for idx in sorted(done):
                t = tests.get(str(idx))
                passed = _module_test_passed(t)
                pct = round(t['score'] / t['total'] * 100) if passed else None
                # first sync: older work counts as it was earned before the test rule
                if first or passed:
                    added += _ep_add(conn, uid, 'module', f'{cid}:{idx}', None if first else today, pct)
            if c.get('finished') and len(done) >= count:   # every module finished
                added += _ep_add(conn, uid, 'course', cid, None if first else today)

        quizzes = data.get('quizzes') if isinstance(data.get('quizzes'), list) else []
        for q in quizzes[:500]:
            if not isinstance(q, dict):
                continue
            cid, day = str(q.get('course') or ''), q.get('day')
            if cid in EP_COURSE_MODULES and _valid_day(day) and (first or day in (today, yesterday)):
                added += _ep_add(conn, uid, 'quiz', f'{cid}:{day}', day, _pct(q.get('pct')))

        daily = data.get('daily') if isinstance(data.get('daily'), list) else []
        for d in daily[:500]:   # "2026-10-22" or {"day": "2026-10-22", "pct": 90}
            day, pct = (d.get('day'), _pct(d.get('pct'))) if isinstance(d, dict) else (d, None)
            if _valid_day(day) and (first or day in (today, yesterday)):
                added += _ep_add(conn, uid, 'daily_quiz', day, day, pct)

        streaks = data.get('streaks') if isinstance(data.get('streaks'), dict) else {}
        # a streak can't be longer than what the server has seen: quiz days for the quiz
        # streak, finished modules for the module streak (so a made-up number earns nothing)
        seen_quiz_days = conn.execute("""SELECT COUNT(DISTINCT day) FROM ep_events WHERE user_id = ?
                                         AND kind IN ('quiz', 'daily_quiz') AND day IS NOT NULL""", (uid,)).fetchone()[0] or 0
        seen_modules = conn.execute("SELECT COUNT(*) FROM ep_events WHERE user_id = ? AND kind = 'module'", (uid,)).fetchone()[0] or 0
        caps = {'quiz': seen_quiz_days, 'module': seen_modules}
        for kind in EP_STREAK_KINDS:
            if kind in streaks:
                v = streaks.get(kind)
                if isinstance(v, int) and not isinstance(v, bool) and v > caps.get(kind, v):
                    row = conn.execute('SELECT last_value FROM ep_streaks WHERE user_id = ? AND kind = ?', (uid, kind)).fetchone()
                    v = caps[kind]
                    if row and v < (row[0] or 0):
                        continue        # the cap, not a broken streak, made it smaller: don't start a new run
                added += _ep_streak_bonus(conn, uid, kind, v, None if first else today)

        if first:
            conn.execute('INSERT OR IGNORE INTO ep_backfill (user_id, done_at) VALUES (?, ?)',
                         (uid, datetime.now(timezone.utc).isoformat()))
        # keep the progress parents see up to date right away (no need to open the dashboard)
        _rebuild_progress_summary(conn, uid, courses, streaks)
        _save_score_grades(conn, uid, data.get('grades'))
        conn.commit()
        summary = _ep_summary(conn, uid)
    except sqlite3.Error as e:
        conn.rollback()
        app.logger.exception('EP sync failed')
        return jsonify({'success': False, 'message': f'Could not save EP: {e}'}), 500
    finally:
        conn.close()

    return jsonify({'success': True, 'added': added, **summary})


@app.route('/api/ep/goal', methods=['POST'])
def api_ep_goal():
    """The learner sets their own weekly EP goal once: {"goal": 300}. After that it can't be changed."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Only learners have an EP goal.'}), 403
    goal = (request.get_json(silent=True) or {}).get('goal')
    uid = session['user_id']
    try:
        goal = int(goal)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Enter a whole number of EP.'}), 400
    if not EP_GOAL_MIN <= goal <= EP_GOAL_MAX:
        return jsonify({'success': False,
                        'message': f'Pick a goal between {EP_GOAL_MIN} and {EP_GOAL_MAX:,} EP.'}), 400
    conn = _links_db()
    try:
        _ep_table(conn)
        if conn.execute('SELECT 1 FROM ep_goals WHERE user_id = ?', (uid,)).fetchone():
            return jsonify({'success': False, 'message': "Your weekly EP goal is already set and can't be changed."}), 409
        conn.execute('INSERT INTO ep_goals (user_id, weekly_goal, updated_at) VALUES (?, ?, ?)',
                     (uid, goal, datetime.now(timezone.utc).isoformat()))
        conn.commit()
        summary = _ep_summary(conn, uid)
    finally:
        conn.close()
    return jsonify({'success': True, **summary})


@app.route('/api/ep/summary', methods=['GET'])
def api_ep_summary():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    conn = _links_db()
    try:
        summary = _ep_summary(conn, session['user_id'])
    finally:
        conn.close()
    return jsonify({'success': True, **summary})



SUMMARY_COLS = ('gpa, overall_grade, avg_progress, courses, modules_completed, assessments, '
                'quiz_streak, module_streak, quizzes_passed, courses_completed, best_quiz_streak, '
                'best_module_streak, quiz_last_date, module_last_date, active_days, updated_at')


def _nairobi_today():
    return (datetime.now(timezone.utc) + timedelta(hours=3)).strftime('%Y-%m-%d')


def _live_streak(current, last_date):
    """A streak is broken once a whole day passes without activity (Nairobi time)."""
    if not current or not last_date:
        return 0
    try:
        gap = (datetime.strptime(_nairobi_today(), '%Y-%m-%d') - datetime.strptime(last_date, '%Y-%m-%d')).days
    except ValueError:
        return current or 0
    return current if gap <= 1 else 0


def _learner_stats(row, ep=None):
    """Turns a student_progress_summary row (may be empty) + server EP into what the pages show."""
    r = dict(row) if row is not None else {}
    try:
        courses = json.loads(r.get('courses') or '[]')
        courses = courses if isinstance(courses, list) else []
    except (TypeError, ValueError):
        courses = []
    st = {
        'gpa': r.get('gpa'),
        'overall_grade': r.get('overall_grade'),
        'avg_progress': r.get('avg_progress') or 0,
        'courses': courses,
        'courses_enrolled': len(courses),
        'modules_completed': r.get('modules_completed') or 0,
        'assessments': r.get('assessments') or 0,
        'quizzes_passed': r.get('quizzes_passed') or 0,
        'courses_completed': r.get('courses_completed') or sum(1 for c in courses if (c.get('progress') or 0) >= 100),
        'quiz_streak': _live_streak(r.get('quiz_streak'), r.get('quiz_last_date')),
        'module_streak': _live_streak(r.get('module_streak'), r.get('module_last_date')),
        'active_days': r.get('active_days') or 0,
        'updated_at': r.get('updated_at'),
    }
    st['best_quiz_streak'] = max(r.get('best_quiz_streak') or 0, st['quiz_streak'])
    st['best_module_streak'] = max(r.get('best_module_streak') or 0, st['module_streak'])
    st['gpa_x10'] = round((st['gpa'] or 0) * 10)
    ep = ep or {}
    st['modules_completed'] = max(st['modules_completed'], ep.get('modules', 0))
    st['ep'] = ep.get('total', 0)              # all-time EP (from ep_events)
    st['ep_week'] = ep.get('week', 0)          # EP this week (Mon-Sun, Nairobi)
    st['ep_last_at'] = ep.get('last_at')
    st['ep_week_last_at'] = ep.get('week_last_at')
    st['ep_month'] = ep.get('month', 0)        # EP this month (Nairobi) - what the leaderboard ranks by
    st['ep_month_last_at'] = ep.get('month_last_at')
    st['level'] = st['ep'] // EP_PER_LEVEL + 1
    st['level_progress'] = round((st['ep'] % EP_PER_LEVEL) / EP_PER_LEVEL * 100)
    st['ep_to_next'] = EP_PER_LEVEL - st['ep'] % EP_PER_LEVEL
    return st


def _ranked_learners(conn, only_ids=None, period='month', exclude_ids=None):
    """
    EVERY registered learner, best first, as
    [(rank, user_id, firstname, lastname, avatar, stats)].
    Ranked by EP earned THIS MONTH (1st to the end of the month, Nairobi) —
    that's what decides a learner's place. period='week' and period='all'
    (all-time EP) are only kept for old callers.
    Learners with no EP yet are included with 0. Equal EP share a rank
    (1, 2, 2, 4 ...); in the order shown, whoever reached the score first is higher.
    """
    _progress_summary_table(conn)
    cols = ', '.join('ps.' + c.strip() for c in SUMMARY_COLS.split(','))
    sql = f'''
        SELECT u.id, u.firstname, u.lastname, u.avatar_filename, {cols}
        FROM users u
        LEFT JOIN student_progress_summary ps ON ps.student_id = u.id
        WHERE COALESCE(u.role, 'student') = 'student'
          AND TRIM(COALESCE(u.firstname, '') || COALESCE(u.lastname, '')) != ''
    '''
    params = []
    if only_ids is not None:
        only_ids = list(only_ids) or [-1]
        sql += f" AND u.id IN ({','.join('?' for _ in only_ids)})"
        params = only_ids
    rows = conn.execute(sql, params).fetchall()
    if exclude_ids:   # e.g. learners who chose not to appear on the leaderboard
        rows = [r for r in rows if r['id'] not in exclude_ids]
    totals = _ep_totals(conn, only_ids)
    items = [(r['id'], r['firstname'], r['lastname'], r['avatar_filename'], _learner_stats(r, totals.get(r['id'])))
             for r in rows]

    score_key = {'month': 'ep_month', 'week': 'ep_week'}.get(period, 'ep')
    when_key = {'month': 'ep_month_last_at', 'week': 'ep_week_last_at'}.get(period, 'ep_last_at')
    for t in items:
        t[4]['score'] = t[4][score_key]
    items.sort(key=lambda t: (-t[4]['score'], t[4][when_key] or '9999',
                              ((t[1] or '') + ' ' + (t[2] or '')).lower()))

    ranked, prev, rank = [], None, 0
    for i, t in enumerate(items):
        if t[4]['score'] != prev:
            rank, prev = i + 1, t[4]['score']
        ranked.append((rank,) + t)
    return ranked


# ============ PRIVACY (Settings > Privacy) ============
# Choices a user makes about who can see and contact them. They are checked
# by the server on the profile pages, leaderboard, people search and messages.

PRIVACY_DEFAULTS = {
    'profile_visibility': 'everyone',   # everyone | friends | teachers | private
    'show_on_leaderboard': True,
    'searchable': True,
    'messages_from': 'everyone',        # everyone | following | teachers
    # what other people see on your profile (you, admins and your linked parents always see everything)
    'show_progress': True,              # level and EP
    'show_achievements': True,          # achievements and badges
    'show_rank': True,                  # monthly leaderboard place
    'show_streak': True,                # quiz streak
    'show_follow_counts': True,         # followers / following numbers
}
PROFILE_PRIVACY_PARTS = {'show_progress': 'progress', 'show_achievements': 'achievements', 'show_rank': 'rank',
                         'show_streak': 'streak', 'show_follow_counts': 'follows'}
PRIVACY_CHOICES = {
    'profile_visibility': ('everyone', 'friends', 'teachers', 'private'),
    'messages_from': ('everyone', 'following', 'teachers'),
}
PARENT_PERM_LABELS = {
    'grades': 'Grades & course progress',
    'schedule': 'Your schedule',
    'attendance': 'Attendance',
    'resources': 'Resources',
    'notifications': 'Updates about your activity',
    'messages': 'Who you talk to and your messages',
}


def _privacy_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS privacy_settings (
            user_id INTEGER PRIMARY KEY,
            profile_visibility TEXT NOT NULL DEFAULT 'everyone',
            show_on_leaderboard INTEGER NOT NULL DEFAULT 1,
            searchable INTEGER NOT NULL DEFAULT 1,
            messages_from TEXT NOT NULL DEFAULT 'everyone',
            updated_at TEXT
        )
    ''')
    have = {r[1] for r in conn.execute('PRAGMA table_info(privacy_settings)').fetchall()}
    for col in PROFILE_PRIVACY_PARTS:
        if col not in have:
            conn.execute(f'ALTER TABLE privacy_settings ADD COLUMN {col} INTEGER NOT NULL DEFAULT 1')


def get_privacy(conn, uid):
    _privacy_table(conn)
    cols = list(PRIVACY_DEFAULTS)
    row = conn.execute(f"SELECT {', '.join(cols)} FROM privacy_settings WHERE user_id = ?", (uid,)).fetchone()
    r = conn.execute('SELECT role FROM users WHERE id = ?', (uid,)).fetchone()
    learner = bool(r) and (r[0] or 'student') == 'student'
    out = dict(PRIVACY_DEFAULTS) if not row else \
        {k: (bool(v) if isinstance(PRIVACY_DEFAULTS[k], bool) else v) for k, v in zip(cols, row)}
    # learners are children: "everyone" is not offered to them. Only people they follow (friends),
    # their teachers and their parents can start a chat (or fewer, if they choose "teachers").
    if learner and out['messages_from'] == 'everyone':
        out['messages_from'] = 'following'
    return out


def profile_hidden_parts(conn, viewer_id, viewer_role, target_id):
    """Parts of the target's profile this viewer may not see (Settings > Privacy > Your profile).
    You, admins and your linked parents always see everything."""
    if not viewer_id or viewer_id == target_id or viewer_role == 'admin':
        return []
    if _is_linked_parent(conn, viewer_id, target_id):
        # a linked parent sees what the child allowed on My Children: learning results only with "Grades & GPA" on
        try:
            r = conn.execute("SELECT permissions FROM parent_links WHERE parent_id = ? AND student_id = ? AND status = 'active'",
                             (viewer_id, target_id)).fetchone()
            perms = _clean_permissions(json.loads((r[0] if r else None) or '{}'))
        except (ValueError, sqlite3.Error):
            perms = _clean_permissions({})
        return [] if perms.get('grades') else ['progress', 'streak', 'achievements']
    pv = get_privacy(conn, target_id)
    return [part for key, part in PROFILE_PRIVACY_PARTS.items() if not pv.get(key, True)]


def _users_with_privacy(conn, column, value):
    """Ids of users whose privacy `column` equals `value` (e.g. hidden from the leaderboard).
    Deactivated accounts count as hidden / unsearchable too."""
    _privacy_table(conn)
    ids = {r[0] for r in conn.execute(f'SELECT user_id FROM privacy_settings WHERE {column} = ?', (value,)).fetchall()}
    if (column, value) in (('searchable', 0), ('show_on_leaderboard', 0)):
        ids |= deactivated_user_ids(conn)
    return ids


def _is_linked_parent(conn, parent_id, student_id):
    try:
        return conn.execute("SELECT 1 FROM parent_links WHERE parent_id = ? AND student_id = ? AND status = 'active'",
                            (parent_id, student_id)).fetchone() is not None
    except sqlite3.Error:
        return False


def can_view_profile(conn, viewer_id, viewer_role, target_id):
    """May this viewer open the target's profile (and its progress / achievements)?"""
    if not viewer_id:
        return False
    if viewer_id == target_id or viewer_role == 'admin':
        return True
    if target_id in deactivated_user_ids(conn):
        return False                     # deactivated accounts are hidden
    vis = get_privacy(conn, target_id)['profile_visibility']
    if _is_linked_parent(conn, viewer_id, target_id):
        return True                      # a linked parent can always see their child's profile
    if vis == 'friends':
        # only friends (plus linked parents above, and admins / the person themselves, checked earlier)
        _friends_tables(conn)
        return _are_friends(conn, viewer_id, target_id)
    if vis == 'everyone':
        return True
    return vis == 'teachers' and viewer_role == 'teacher'


_MSG_TABLES_READY = set()


def _messages_tables(conn):
    """Blocks, mutes, reports, and a 'kind' on each message ('text', or 'call' for call records
    the server writes, so a typed "📞 Missed call" can't pass as a real one)."""
    if 'ok' in _MSG_TABLES_READY:
        return
    cols = {r[1] for r in conn.execute('PRAGMA table_info(messages)').fetchall()}
    if cols and 'kind' not in cols:
        conn.execute("ALTER TABLE messages ADD COLUMN kind TEXT DEFAULT 'text'")
        # call records written before this change
        conn.execute("""UPDATE messages SET kind = 'call' WHERE text LIKE '📞 Missed %' OR text LIKE '📞 % declined'
                        OR text GLOB '📞 Voice call · [0-9]*:[0-9][0-9]' OR text GLOB '📞 Video call · [0-9]*:[0-9][0-9]'""")
    conn.execute('''CREATE TABLE IF NOT EXISTS message_blocks (
        blocker_id INTEGER NOT NULL, blocked_id INTEGER NOT NULL, created_at TEXT, PRIMARY KEY (blocker_id, blocked_id))''')
    conn.execute('''CREATE TABLE IF NOT EXISTS message_mutes (
        user_id INTEGER NOT NULL, muted_id INTEGER NOT NULL, created_at TEXT, PRIMARY KEY (user_id, muted_id))''')
    conn.execute('''CREATE TABLE IF NOT EXISTS message_reports (
        id INTEGER PRIMARY KEY AUTOINCREMENT, reporter_id INTEGER NOT NULL, reported_id INTEGER NOT NULL,
        reason TEXT, messages TEXT, status TEXT DEFAULT 'open', created_at TEXT)''')
    conn.commit()
    if cols:
        _MSG_TABLES_READY.add('ok')


def _is_blocked(conn, a, b):
    """True if either person blocked the other."""
    _messages_tables(conn)
    return bool(conn.execute('SELECT 1 FROM message_blocks WHERE (blocker_id = ? AND blocked_id = ?) OR (blocker_id = ? AND blocked_id = ?)',
                             (a, b, b, a)).fetchone())


def _is_muted(conn, uid, other):
    _messages_tables(conn)
    return bool(conn.execute('SELECT 1 FROM message_mutes WHERE user_id = ? AND muted_id = ?', (uid, other)).fetchone())


def can_message(conn, sender_id, sender_role, receiver_id, kind='message'):
    """(allowed, reason) — blocks, then the receiver's 'Who can message me' choice."""
    if sender_id == receiver_id:
        return True, ''
    if _is_blocked(conn, sender_id, receiver_id):
        return False, 'You can’t message or call this person.'
    if sender_role == 'admin':
        return True, ''
    if receiver_id in deactivated_user_ids(conn):
        return False, 'This account is deactivated.'
    ok, why = parental_contact_check(conn, sender_id, receiver_id, kind)   # parental controls
    if not ok:
        return False, why
    rule = get_privacy(conn, receiver_id)['messages_from']
    if rule == 'everyone':
        return True, ''
    # a conversation the receiver started can always be answered
    if conn.execute('SELECT 1 FROM messages WHERE sender_id = ? AND receiver_id = ? LIMIT 1',
                    (receiver_id, sender_id)).fetchone():
        return True, ''
    if sender_role == 'teacher' or _is_linked_parent(conn, sender_id, receiver_id) \
            or _is_linked_parent(conn, receiver_id, sender_id):   # a parent and their own child
        return True, ''
    if rule == 'following' and conn.execute('SELECT 1 FROM follows WHERE follower_id = ? AND following_id = ?',
                                            (receiver_id, sender_id)).fetchone():
        return True, ''
    family = 'their own children' if conn.execute("SELECT 1 FROM users WHERE id = ? AND role = 'parent'", (receiver_id,)).fetchone() \
        else 'their parents'
    who = f'their friends, teachers and {family}' if rule == 'following' else f'teachers and {family}'
    return False, f'This person only accepts messages from {who}.'


