@app.route('/api/privacy', methods=['GET', 'POST'])
def api_privacy():
    """
    GET  -> your privacy choices, your linked parents and what each can see,
            and parent requests waiting for you
    POST -> change choices, e.g. {"show_on_leaderboard": false}
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    conn = _links_db()
    try:
        _privacy_table(conn)
        _access_tables(conn)
        if request.method == 'POST':
            data = request.get_json(silent=True) or {}
            cur = get_privacy(conn, uid)
            for key in PRIVACY_DEFAULTS:
                if key not in data:
                    continue
                val = data[key]
                if key in PRIVACY_CHOICES:
                    if val not in PRIVACY_CHOICES[key]:
                        return jsonify({'success': False, 'message': 'Pick one of the options.'}), 400
                    if key == 'messages_from' and val == 'everyone' and (session.get('role') or 'student') == 'student':
                        return jsonify({'success': False, 'message': 'For your safety, learners can only get messages from friends, teachers and parents.'}), 400
                elif not isinstance(val, bool):
                    return jsonify({'success': False, 'message': 'That setting must be on or off.'}), 400
                cur[key] = val
            cols = list(PRIVACY_DEFAULTS) + ['updated_at']
            vals = [int(cur[k]) if isinstance(cur[k], bool) else cur[k] for k in PRIVACY_DEFAULTS] + [datetime.now(timezone.utc).isoformat()]
            conn.execute(f"INSERT INTO privacy_settings (user_id, {', '.join(cols)}) VALUES (?, {', '.join('?' for _ in cols)}) "
                         "ON CONFLICT(user_id) DO UPDATE SET " + ', '.join(f'{c} = excluded.{c}' for c in cols),
                         [uid] + vals)
            conn.commit()

        parents, requests_ = [], []
        try:
            rows = conn.execute('''
                SELECT pl.id, pl.relationship, pl.status, pl.linked_at, pl.requested_at, pl.expires_at, pl.permissions, pl.perm_requests,
                       u.firstname, u.lastname, u.avatar_filename, u.id AS parent_id
                FROM parent_links pl LEFT JOIN users u ON u.id = pl.parent_id
                WHERE pl.student_id = ? AND pl.status IN ('active', 'pending')
                ORDER BY pl.id DESC''', (uid,)).fetchall()
        except sqlite3.Error:
            rows = []
        now = _iso(_utc_now())
        for r in rows:
            try:
                perms = _clean_permissions(json.loads(r['permissions'] or '{}'))
            except ValueError:
                perms = _clean_permissions({})
            item = {
                'link_id': r['id'],
                'pending': [{'key': k, 'label': PARENT_PERM_LABELS.get(k, k)} for k in _perm_requests(r['perm_requests'])],
                'history': _access_history(conn, r['id'], 6),
                'name': _full_name(r['firstname'], r['lastname'], 'Parent'),
                'avatar_url': get_avatar_url(r['parent_id'], r['avatar_filename']) if r['parent_id'] else None,
                'relationship': (r['relationship'] or '').capitalize() or None,
                'permissions': [{'key': k, 'label': PARENT_PERM_LABELS.get(k, k), 'allowed': perms.get(k, False)}
                                for k in PARENT_PERM_KEYS],
            }
            if r['status'] == 'active':
                item['linked_on'] = _nice_date(r['linked_at'])
                parents.append(item)
            elif not r['expires_at'] or r['expires_at'] >= now:
                item['requested_on'] = _nice_date(r['requested_at'])
                requests_.append(item)

        return jsonify({'success': True, 'privacy': get_privacy(conn, uid),
                        'parents': parents, 'requests': requests_,
                        'role': session.get('role')})
    finally:
        conn.close()


@app.route('/api/privacy/export', methods=['GET', 'POST'])
def api_privacy_export():
    """Download a copy of your Eschool data (JSON). The Settings page sends a POST (checked by the
    cross-site guard); a GET only works when it comes from Eschool's own pages."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if request.method == 'GET' and request.headers.get('Sec-Fetch-Site', 'same-origin') not in ('same-origin', 'none'):
        return jsonify({'success': False, 'message': 'Open Settings > Privacy to download your data.'}), 403
    uid = session['user_id']
    conn = _links_db()

    def rows(sql, params=()):
        try:
            return [dict(r) for r in conn.execute(sql, params).fetchall()]
        except sqlite3.Error:
            return []
    try:
        user = conn.execute('SELECT id, firstname, lastname, email, role, country, plan, plan_started_at, plan_expires_at '
                            'FROM users WHERE id = ?', (uid,)).fetchone()
        data = {
            'exported_at': datetime.now(timezone.utc).isoformat(),
            'account': dict(user) if user else {},
            'personal_details': rows('SELECT * FROM user_details WHERE user_id = ?', (uid,)),
            'privacy_settings': get_privacy(conn, uid),
            'eschool_points': {
                'earned': rows('SELECT kind, ref, ep, day, created_at FROM ep_events WHERE user_id = ? ORDER BY id', (uid,)),
                'spent': rows('SELECT reward_key, title, cost, created_at FROM ep_redemptions WHERE user_id = ? ORDER BY id', (uid,)),
            },
            'achievements_unlocked': rows('SELECT key, unlocked_at FROM achievements_unlocked WHERE user_id = ?', (uid,)),
            'following': rows('SELECT u.firstname, u.lastname, u.role FROM follows f JOIN users u ON u.id = f.following_id '
                              'WHERE f.follower_id = ?', (uid,)),
            'followers': rows('SELECT u.firstname, u.lastname, u.role FROM follows f JOIN users u ON u.id = f.follower_id '
                              'WHERE f.following_id = ?', (uid,)),
            'parent_links': rows('SELECT pl.relationship, pl.status, pl.linked_at, pl.permissions, u.firstname, u.lastname '
                                 'FROM parent_links pl LEFT JOIN users u ON u.id = pl.parent_id WHERE pl.student_id = ?', (uid,)),
            'messages': rows('''SELECT CASE WHEN m.sender_id = ? THEN 'sent' ELSE 'received' END AS direction,
                                       TRIM(COALESCE(o.firstname, '') || ' ' || COALESCE(o.lastname, '')) AS with_person,
                                       m.text, m.timestamp AS sent_at
                                FROM messages m
                                LEFT JOIN users o ON o.id = CASE WHEN m.sender_id = ? THEN m.receiver_id ELSE m.sender_id END
                                WHERE (m.sender_id = ? OR m.receiver_id = ?) AND COALESCE(m.is_broadcast, 0) = 0
                                ORDER BY m.id''', (uid, uid, uid, uid)),
            'notifications': rows('SELECT title, message, is_read, created_at FROM notifications WHERE user_id = ? ORDER BY id', (uid,)),
        }
        if session.get('role') == 'teacher':
            data['teaching'] = {
                'teaching_profile': rows('SELECT headline, bio, subjects, levels, rate, session_minutes, mode, location, '
                                         'experience_years, qualifications, availability, accepting, updated_at '
                                         'FROM tutor_profiles WHERE teacher_id = ?', (uid,)),
                'resources': rows('SELECT title, description, category, difficulty, file_name, privacy, views, upload_date '
                                  'FROM resources WHERE user_id = ? ORDER BY id', (uid,)),
                'live_classes': rows('SELECT title, subject, grade, description, start_time, duration_min, created_at '
                                     'FROM live_classes WHERE teacher_id = ? ORDER BY id', (uid,)),
                'reviews_received': rows('SELECT r.stars, r.comment, r.created_at, r.reply, r.reply_at, '
                                         "TRIM(COALESCE(u.firstname, '') || ' ' || COALESCE(u.lastname, '')) AS reviewer "
                                         'FROM teacher_ratings r LEFT JOIN users u ON u.id = r.reviewer_id '
                                         'WHERE r.teacher_id = ? ORDER BY r.id', (uid,)),
                'schedule': rows('SELECT title, kind, subject, grade, day, start_time, minutes, location, notes, repeat, repeat_until '
                                 'FROM teacher_events WHERE teacher_id = ? ORDER BY id', (uid,)),
            }
    finally:
        conn.close()
    body = json.dumps(data, indent=2, ensure_ascii=False, default=str)
    return Response(body, mimetype='application/json',
                    headers={'Content-Disposition': f'attachment; filename="eschool-my-data-{_nairobi_today()}.json"'})


