# Countries whose courses are ready. Add a code here once its courses are built.
COURSES_READY = ('KE',)
# Countries whose courses are being built ("coming soon" on the courses page).
COURSES_COMING = ('IN', 'PH', 'US', 'GB')
# Each country's courses live in their own folder: static/courses/<code>/<file>.js
# (one file per course). TO ADD A COURSE, JUST PUT ITS FILE IN THE FOLDER: Eschool
# finds it by itself (no restart needed) and reads its id, name, grade and number
# of modules from the file. The files listed here show first, in this order; any
# other file in the folder comes after them, A to Z. Course ids must be different
# in every country (e.g. India's maths could have id 'in-math').
COURSE_FILES = {
    'KE': ['math.js', 'csl.js', 'english.js', 'kiswahili.js'],
}
_COURSE_LISTED = {k: list(v) for k, v in COURSE_FILES.items()}
_COURSE_IDS = {}           # country -> [course ids, in order]
_COURSE_SEEN = {}          # country -> what the folder looked like the last time it was read


def _course_file_meta(text):
    """id, name, grade and number of modules of one course file, read without running it."""
    meta = {}
    for k in ('id', 'name', 'level'):
        m = re.search(r"\b" + k + r"\s*:\s*(['\"])(.*?)\1", text)
        meta[k] = m.group(2) if m else ''
    m = re.search(r"\bmodules\s*:\s*\[", text)
    n = 0
    if m:
        i, depth, L = m.end(), 0, len(text)
        while i < L:
            ch = text[i]
            if ch in '\'"`':
                q = ch; i += 1
                while i < L and text[i] != q:
                    i += 2 if text[i] == '\\' else 1
            elif ch == '/' and text[i + 1:i + 2] == '/':
                j = text.find('\n', i); i = L if j < 0 else j
            elif ch == '/' and text[i + 1:i + 2] == '*':
                j = text.find('*/', i + 2); i = L if j < 0 else j + 1
            elif ch in '[{(':
                if depth == 0 and ch == '{':
                    n += 1
                depth += 1
            elif ch in ']})':
                if depth == 0:
                    break
                depth -= 1
            i += 1
    meta['modules'] = n
    return meta


def _refresh_courses(code):
    """Reads one country's course folder again if a file was added, removed or edited, and
    keeps COURSE_FILES, the course ids, EP_COURSE_MODULES and EP_COURSE_NAMES up to date."""
    folder = os.path.join(app.static_folder, 'courses', code)
    try:
        names = [n for n in os.listdir(folder) if n.endswith('.js')]
        sig = tuple(sorted((n, int(os.path.getmtime(os.path.join(folder, n)))) for n in names))
    except OSError:
        names, sig = [], ()
    if _COURSE_SEEN.get(code) == sig:
        return
    listed = _COURSE_LISTED.get(code, [])
    files = [n for n in listed if n in names] + sorted(n for n in names if n not in listed)
    ids, keep = [], []
    for n in files:
        try:
            with open(os.path.join(folder, n), encoding='utf-8') as fh:
                meta = _course_file_meta(fh.read())
        except (OSError, UnicodeDecodeError):
            print(f'Course file could not be read: static/courses/{code}/{n}')
            continue
        cid = meta['id'] or os.path.splitext(n)[0]
        if cid in ids:
            print(f'Course id "{cid}" is used twice in static/courses/{code}/ ({n} skipped): give it its own id')
            continue
        ids.append(cid); keep.append(n)
        if meta['modules']:
            EP_COURSE_MODULES[cid] = meta['modules']
        if meta['name']:
            EP_COURSE_NAMES[cid] = meta['name']
    COURSE_FILES[code] = keep
    _COURSE_IDS[code] = ids
    _COURSE_SEEN[code] = sig


def _course_ids(code):
    """The ids of one country's courses, read from the course files themselves."""
    if code not in COURSES_READY:
        return []
    _refresh_courses(code)
    return list(_COURSE_IDS.get(code, []))


for _code in COURSES_READY:          # read the course folders once when Eschool starts
    _refresh_courses(_code)


def _course_scripts(code):
    """Web addresses of one country's course files. ?v= changes when a file is
    edited, so browsers fetch the new version instead of an old saved copy."""
    folder = os.path.join(app.static_folder, 'courses', code)
    _refresh_courses(code)
    urls = []
    for name in COURSE_FILES.get(code, []):
        path = os.path.join(folder, name)
        if not os.path.isfile(path):
            print(f'Course file missing: static/courses/{code}/{name}')
            continue
        urls.append(url_for('static', filename=f'courses/{code}/{name}') + f'?v={int(os.path.getmtime(path))}')
    return urls


def _clean_country(value):
    """Turns what a form sent (a code like 'KE' or a name like 'Kenya') into one of
    the codes above. Anything not on the list becomes 'OT'; nothing sent stays ''."""
    v = str(value or '').strip()
    if not v:
        return ''
    if v.upper() in PROFILE_COUNTRIES:
        return v.upper()
    by_name = {name.lower(): code for code, name in PROFILE_COUNTRIES.items()}
    by_name.update({'uk': 'GB', 'usa': 'US', 'united states of america': 'US', 'great britain': 'GB'})
    return by_name.get(v.lower(), 'OT')


def _country_with_the(code):
    """'the Philippines', 'the United States' … for sentences; other names as they are."""
    name = PROFILE_COUNTRIES.get(code, '')
    return ('the ' + name) if code in ('PH', 'US', 'GB', 'NL', 'BS', 'GM', 'AE', 'DO', 'CF', 'KM', 'MV', 'MH', 'SB', 'VA') else name


def register_countries():
    """All countries for the sign-up list, A to Z ("Other country" last)."""
    items = sorted(((c, n) for c, n in PROFILE_COUNTRIES.items() if c != 'OT'), key=lambda x: x[1])
    return items + [('OT', PROFILE_COUNTRIES['OT'])]
PROFILE_GENDERS = ('', 'female', 'male', 'other', 'prefer_not')
_PHONE_RE = re.compile(r'^\+?[0-9 ()-]{7,20}$')


def _profile_details_table(conn):
    conn.execute('''
        CREATE TABLE IF NOT EXISTS user_details (
            user_id INTEGER PRIMARY KEY,
            phone TEXT, bio TEXT, date_of_birth TEXT, gender TEXT,
            school TEXT, grade_level TEXT, admission_no TEXT,
            city TEXT, address TEXT, timezone TEXT,
            guardian_name TEXT, guardian_phone TEXT, guardian_relation TEXT,
            updated_at TEXT
        )
    ''')
    cols = {r[1] for r in conn.execute('PRAGMA table_info(user_details)').fetchall()}
    for col in ('dream_career', 'career_area', 'fav_subjects', 'learning_goal', 'study_time', 'career_changed_at'):
        if col not in cols:
            conn.execute(f'ALTER TABLE user_details ADD COLUMN {col} TEXT')


# A learner's dream career can change once a week, so nobody switches careers just to
# open another career's missions and EP. The first choice is free; the week starts at each change.
CAREER_LOCK_DAYS = 7


def _career_change_after(d):
    """When this learner may change career again (UTC datetime), or None if they can now."""
    when = _parse_any((d or {}).get('career_changed_at'))
    if not when:
        return None
    after = when + timedelta(days=CAREER_LOCK_DAYS)
    return after if after > datetime.now(timezone.utc) else None


def _profile_details(conn, uid):
    _profile_details_table(conn)
    u = conn.execute('SELECT firstname, lastname, email, country, role FROM users WHERE id = ?', (uid,)).fetchone()
    d = conn.execute('SELECT * FROM user_details WHERE user_id = ?', (uid,)).fetchone()
    d = dict(d) if d else {}
    out = {k: (d.get(k) or '') for k in PROFILE_DETAIL_FIELDS}
    out.update({
        'firstname': (u['firstname'] or '') if u else '',
        'lastname': (u['lastname'] or '') if u else '',
        'email': (u['email'] or '') if u else '',
        'country': ((u['country'] or '') if u else '').upper(),
        'role': (u['role'] or 'student') if u else 'student',
        'updated_at': d.get('updated_at'),
    })
    after = _career_change_after(d)
    out['career_change_after'] = after.isoformat() if after else None
    if not out['timezone']:
        out['timezone'] = 'Africa/Nairobi'
    return out


@app.route('/api/profile/details', methods=['GET', 'POST'])
def api_profile_details():
    """GET your personal information; POST the fields you changed to save them."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    conn = _links_db()
    try:
        if request.method == 'GET':
            return jsonify({'success': True, 'details': _profile_details(conn, uid),
                            'countries': PROFILE_COUNTRIES, 'subjects': PROFILE_SUBJECTS})

        data = request.get_json(silent=True) or {}
        errors = {}
        clean = {}

        # names
        for key, label in (('firstname', 'First name'), ('lastname', 'Last name')):
            if key in data:
                v = ' '.join(str(data.get(key) or '').split())
                if not v:
                    errors[key] = f'{label} is required.'
                elif len(v) > 50:
                    errors[key] = f'{label} is too long.'
                elif not re.match(r"^[^\W\d_][^\W\d_ '\-]*(?:[ '\-][^\W\d_]+)*$", v):
                    errors[key] = f'{label} can only have letters, spaces, - and \'.'
                clean[key] = v

        if 'country' in data:
            v = str(data.get('country') or '').upper()
            if v and v not in PROFILE_COUNTRIES:
                errors['country'] = 'Pick a country from the list.'
            clean['country'] = v or None

        for key, max_len in PROFILE_DETAIL_FIELDS.items():
            if key not in data:
                continue
            v = str(data.get(key) or '').strip()
            if len(v) > max_len:
                errors[key] = f'Too long (max {max_len} characters).'
            clean[key] = v

        for key in ('phone', 'guardian_phone'):
            if clean.get(key) and not _PHONE_RE.match(clean[key]):
                errors[key] = 'Enter a valid phone number, e.g. +254 712 345 678.'
        if clean.get('bio'):
            clean['bio'] = re.sub(r'<[^>]*>', '', clean['bio'])
            if _OPINION_PHONE.search(clean['bio']) or _OPINION_LINK.search(clean['bio']):
                errors['bio'] = 'Others can read your bio, so it can’t include phone numbers, links or social media names.'
        for key, allowed in PROFILE_CHOICES.items():
            if key in clean and clean[key] not in allowed:
                errors[key] = 'Pick an option from the list.'
        if clean.get('fav_subjects'):
            picked = [x.strip() for x in clean['fav_subjects'].split(',') if x.strip()]
            if any(x not in PROFILE_SUBJECTS for x in picked):
                errors['fav_subjects'] = 'Pick subjects from the list.'
            elif len(picked) > 5:
                errors['fav_subjects'] = 'Pick up to 5 subjects.'
            clean['fav_subjects'] = ', '.join(dict.fromkeys(picked))
        if clean.get('dream_career'):
            clean['dream_career'] = re.sub(r'<[^>]*>', '', clean['dream_career'])
            if _OPINION_PHONE.search(clean['dream_career']) or _OPINION_LINK.search(clean['dream_career']):
                errors['dream_career'] = 'Just the job name, please (no links or numbers).'
        if clean.get('gender') and clean['gender'] not in PROFILE_GENDERS:
            errors['gender'] = 'Pick an option from the list.'
        if clean.get('date_of_birth'):
            try:
                dob = datetime.strptime(clean['date_of_birth'], '%Y-%m-%d')
                if not (datetime(1900, 1, 1) <= dob <= datetime.now()):
                    errors['date_of_birth'] = 'Enter a real date of birth.'
            except ValueError:
                errors['date_of_birth'] = 'Use the date picker (YYYY-MM-DD).'

        # dream career: once a week (only when the career itself changes, not a spelling fix)
        career_changed = False
        if not errors and ('dream_career' in clean or 'career_area' in clean) and session.get('role', 'student') == 'student':
            _profile_details_table(conn)
            old = conn.execute('SELECT dream_career, career_area, career_changed_at FROM user_details WHERE user_id = ?', (uid,)).fetchone()
            old = dict(old) if old else {}
            old_key = _career_match(old.get('dream_career'), old.get('career_area')) if old else None
            new_key = _career_match(clean.get('dream_career', old.get('dream_career')), clean.get('career_area', old.get('career_area')))
            if new_key != old_key:
                after = _career_change_after(old) if old_key else None     # a first choice is never blocked
                if after:
                    nice = _when_for(session.get('user_id'), after, '%A %d %B at %H:%M')
                    msg = f"You can change your dream career once a week. You can choose a new one on {nice}."
                    return jsonify({'success': False, 'message': msg, 'code': 'career_locked', 'career_change_after': after.isoformat(),
                                    'errors': {'dream_career': msg}}), 400
                career_changed = bool(old_key)          # the week starts when they switch from one career to another

        if errors:
            return jsonify({'success': False, 'message': 'Please fix the highlighted fields.', 'errors': errors}), 400

        _profile_details_table(conn)
        user_cols = {k: clean[k] for k in ('firstname', 'lastname', 'country') if k in clean}
        if user_cols:
            conn.execute(f"UPDATE users SET {', '.join(f'{k} = ?' for k in user_cols)} WHERE id = ?",
                         (*user_cols.values(), uid))
        detail_cols = {k: clean[k] for k in PROFILE_DETAIL_FIELDS if k in clean}
        now = datetime.now(timezone.utc).isoformat()
        conn.execute('INSERT OR IGNORE INTO user_details (user_id, updated_at) VALUES (?, ?)', (uid, now))
        if detail_cols:
            conn.execute(f"UPDATE user_details SET {', '.join(f'{k} = ?' for k in detail_cols)}, updated_at = ? WHERE user_id = ?",
                         (*detail_cols.values(), now, uid))
        if career_changed:
            conn.execute('UPDATE user_details SET career_changed_at = ? WHERE user_id = ?', (now, uid))
        conn.commit()

        # keep the header / menus in step straight away
        for k in ('firstname', 'lastname', 'country'):
            if k in clean:
                session[k] = clean[k]
        return jsonify({'success': True, 'message': 'Personal information saved.',
                        'details': _profile_details(conn, uid), 'countries': PROFILE_COUNTRIES, 'subjects': PROFILE_SUBJECTS})
    finally:
        conn.close()


# ============ ESCHOOL POINTS: balance, history and the rewards shop ============
# Spending EP never lowers TOTAL EP (your level) or MONTHLY EP (your rank):
# spendable balance = total EP earned - EP spent on rewards.

