@app.route('/api/points/redeem', methods=['POST'])
def api_points_redeem():
    """Exchange EP for a reward: {"reward": "basic_2d"}."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Only learners can redeem Eschool Points.'}), 403
    uid = session['user_id']
    body = request.get_json(silent=True) or {}
    reward = EP_REWARDS_BY_KEY.get(str(body.get('reward') or ''))   # the cost always comes from the server's own list
    if not reward:
        return jsonify({'success': False, 'message': 'That reward does not exist.'}), 400
    req_id = str(request.headers.get('Idempotency-Key') or body.get('request_id') or '')
    req_id = req_id if _IDEM_RE.match(req_id) else None
    if _reset_rate_limited(f'redeem:{uid}', 10, 60):
        return jsonify({'success': False, 'message': 'Too many tries. Please wait a minute.'}), 429

    conn = _links_db()
    try:
        _points_tables(conn)
        _ensure_plan_columns(conn)
        conn.commit()
        conn.execute('BEGIN IMMEDIATE')          # no double-spending from two taps at once
        if req_id and conn.execute('SELECT 1 FROM ep_redemptions WHERE user_id = ? AND request_id = ?', (uid, req_id)).fetchone():
            conn.rollback()                      # this exact request already went through (e.g. a retry after a dropped connection)
            data = _points_payload(conn, uid)
            data['message'] = 'Already redeemed. You were only charged once.'
            data['duplicate'] = True
            return jsonify(data)
        _, _, balance = _ep_balance(conn, uid)
        if balance < reward['cost']:
            conn.rollback()
            return jsonify({'success': False,
                            'message': f"You need {reward['cost'] - balance:,} more EP for this."}), 400

        message = ''
        if reward.get('plan'):
            row = conn.execute('SELECT plan, plan_started_at, plan_expires_at FROM users WHERE id = ?', (uid,)).fetchone()
            current = _current_plan(row['plan'], row['plan_started_at'], row['plan_expires_at'])
            if current['key'] in ('basic', 'pro') and current['key'] != reward['plan']:
                conn.rollback()
                return jsonify({'success': False,
                                'message': f"You're on {current['name']} right now ({current['time_left']}). "
                                           f"You can redeem this once it ends."}), 409
            left = EP_PLAN_DAYS_PER_30 - _ep_plan_days_used(conn, uid)
            if reward.get('days', 0) > left:
                conn.rollback()
                return jsonify({'success': False,
                                'message': f"You can get up to {EP_PLAN_DAYS_PER_30} plan days with EP in 30 days "
                                           f"({max(0, left)} left right now)."}), 409
            now = _utc_now()
            running_end = _parse_iso(row['plan_expires_at']) if current['key'] == reward['plan'] else None
            start = (_parse_iso(row['plan_started_at']) or now) if running_end else now
            end = (running_end or now) + timedelta(days=reward['days'])
            conn.execute('UPDATE users SET plan = ?, plan_started_at = ?, plan_expires_at = ? WHERE id = ?',
                         (reward['plan'], _iso(start), _iso(end), uid))
            message = (f"🎉 You now have Eschool {PLAN_NAMES[reward['plan']]} until "
                       f"{_when_for(uid, end, '%b %d, %Y %I:%M %p')}.")
        else:
            if conn.execute('SELECT 1 FROM ep_owned WHERE user_id = ? AND item_key = ?', (uid, reward['key'])).fetchone():
                conn.rollback()
                return jsonify({'success': False, 'message': 'You already own this.'}), 409
            conn.execute('INSERT INTO ep_owned (user_id, item_key) VALUES (?, ?)', (uid, reward['key']))
            col = 'title_key' if reward['group'] == 'titles' else 'frame_key'   # wear it straight away
            conn.execute(f'''INSERT INTO ep_equipped (user_id, {col}) VALUES (?, ?)
                             ON CONFLICT(user_id) DO UPDATE SET {col} = excluded.{col}''', (uid, reward['key']))
            message = f"🎉 {reward['title']} is yours and is now showing on your profile."

        conn.execute('INSERT INTO ep_redemptions (user_id, reward_key, title, cost, created_at, request_id, ip) VALUES (?, ?, ?, ?, ?, ?, ?)',
                     (uid, reward['key'], reward['title'], reward['cost'], datetime.now(timezone.utc).isoformat(),
                      req_id, (request.remote_addr or '')[:64]))
        conn.commit()
        app.logger.info('EP redeem: user %s reward %s cost %s ip %s', uid, reward['key'], reward['cost'], request.remote_addr)
        data = _points_payload(conn, uid)
        data['message'] = message
        return jsonify(data)
    except sqlite3.Error as e:
        conn.rollback()
        app.logger.exception('Redeem failed')
        return jsonify({'success': False, 'message': "Couldn't redeem right now. No EP was taken. Please try again."}), 500
    finally:
        conn.close()


@app.route('/api/points/equip', methods=['POST'])
def api_points_equip():
    """Wear an owned title/frame, or take it off: {"slot": "title"|"frame", "item": "title_scholar"|null}."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'student':
        return jsonify({'success': False, 'message': 'Only learners can do this.'}), 403
    uid = session['user_id']
    data = request.get_json(silent=True) or {}
    slot, item = data.get('slot'), data.get('item')
    if slot not in ('title', 'frame'):
        return jsonify({'success': False, 'message': 'Unknown slot.'}), 400
    conn = _links_db()
    try:
        _points_tables(conn)
        if item is not None:
            reward = EP_REWARDS_BY_KEY.get(str(item))
            if not reward or reward['group'] != ('titles' if slot == 'title' else 'frames'):
                return jsonify({'success': False, 'message': 'That item does not fit here.'}), 400
            if not conn.execute('SELECT 1 FROM ep_owned WHERE user_id = ? AND item_key = ?', (uid, item)).fetchone():
                return jsonify({'success': False, 'message': "You don't own this yet."}), 403
        col = 'title_key' if slot == 'title' else 'frame_key'
        conn.execute(f'''INSERT INTO ep_equipped (user_id, {col}) VALUES (?, ?)
                         ON CONFLICT(user_id) DO UPDATE SET {col} = excluded.{col}''', (uid, item))
        conn.commit()
        return jsonify(_points_payload(conn, uid))
    finally:
        conn.close()


