# ============ ACCOUNT & SECURITY (Settings > Account & Security) ============
# account_state keeps, per user:
#   session_epoch  - bumped by "Log out from all devices" / password change;
#                    any login session holding an older number is ended.
#   deactivated    - 1 after "Deactivate account" (hidden; undone by logging in)
#   settings       - JSON: loginNotifications, sessionTimeoutMinutes
# autoSignOutMinutes: 0 = never sign out for being inactive (the default). The old
# sessionTimeoutMinutes (30) is no longer used, so nobody is signed out unless they turn it on.
ACCOUNT_DEFAULTS = {'loginNotifications': True, 'sessionTimeoutMinutes': 30, 'autoSignOutMinutes': 0}


def _account_table(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS account_state (
        user_id INTEGER PRIMARY KEY,
        session_epoch INTEGER NOT NULL DEFAULT 0,
        deactivated INTEGER NOT NULL DEFAULT 0,
        settings TEXT
    )""")


def _account_row(conn, user_id):
    _account_table(conn)
    row = conn.execute('SELECT session_epoch, deactivated, settings FROM account_state WHERE user_id = ?',
                       (user_id,)).fetchone()
    if not row:
        return {'epoch': 0, 'deactivated': 0, 'settings': dict(ACCOUNT_DEFAULTS)}
    try:
        saved = json.loads(row[2]) if row[2] else {}
    except (TypeError, ValueError):
        saved = {}
    settings = dict(ACCOUNT_DEFAULTS)
    settings.update({k: saved[k] for k in ACCOUNT_DEFAULTS if k in saved})
    if isinstance(saved.get('appearance'), dict):      # Settings > Appearance, saved with the account
        settings['appearance'] = saved['appearance']
    return {'epoch': row[0] or 0, 'deactivated': row[1] or 0, 'settings': settings}


def _account_upsert(conn, user_id, **fields):
    _account_table(conn)
    conn.execute('INSERT OR IGNORE INTO account_state (user_id) VALUES (?)', (user_id,))
    for col, val in fields.items():
        conn.execute(f'UPDATE account_state SET {col} = ? WHERE user_id = ?', (val, user_id))


def deactivated_user_ids(conn):
    _account_table(conn)
    return {r[0] for r in conn.execute('SELECT user_id FROM account_state WHERE deactivated = 1').fetchall()}


def account_on_login(user_id, notify=True, method='password'):
    """Call right after a successful sign-in: reactivates a deactivated
    account, stamps the session so 'log out everywhere' can end it, and
    (if the user wants it) leaves a 'new sign-in' notification."""
    conn = sqlite3.connect('users.db')
    try:
        acc = _account_row(conn, user_id)
        if acc['deactivated']:
            _account_upsert(conn, user_id, deactivated=0)
        session['epoch'] = acc['epoch']
        session['signed_in_at'] = int(_time.time())
        label, seen_before = _new_device_session(conn, user_id, method)
        if method != 'switch':
            _account_event(conn, user_id, 'signin' if (seen_before or method == 'signup') else 'signin_new',
                           label + (' · Google' if method == 'google' else ''))
        if notify and not seen_before and acc['settings'].get('loginNotifications'):     # only a new device
            when = _when_for(user_id, _utc_now(), '%d %b %Y, %H:%M')
            create_notification(conn, user_id, 'New sign-in to your account' if seen_before else 'Sign-in from a new device',
                                f"Signed in on {label} at {when}. If this wasn't you, change your password "
                                f"and sign that device out in Settings > Account & Security.",
                                icon='fa-right-to-bracket', color='blue' if seen_before else 'orange')
        conn.commit()
    finally:
        conn.close()


def _device_check(conn, uid):
    """True if this browser's device was signed out from another device. Also keeps 'last active' fresh,
    and gives sign-ins from before device tracking a device row."""
    try:
        _security_tables(conn)
        tok = session.get('dev')
        if not tok:
            _new_device_session(conn, uid, 'password')
            conn.commit()
            return False
        row = conn.execute('SELECT user_id, ended FROM account_devices WHERE token = ?', (tok,)).fetchone()
        if not row or row[0] != uid:
            _new_device_session(conn, uid, 'password')
            conn.commit()
            return False
        if row[1]:
            return True            # signed out from another device
        now = int(_clock.time())
        if now - int(session.get('dev_seen') or 0) < DEVICE_SEEN_EVERY:
            return False
        conn.execute('UPDATE account_devices SET last_seen = ? WHERE token = ?', (_now_iso(), tok))
        conn.commit()
        session['dev_seen'] = now
    except sqlite3.Error:
        pass
    return False


@app.before_request
def _enforce_account_state():
    """Ends sessions that were logged out everywhere, or whose account was deactivated."""
    uid = session.get('user_id')
    if not uid or request.endpoint in (None, 'static'):
        return None
    conn = sqlite3.connect('users.db')
    ended = False
    try:
        acc = _account_row(conn, uid)
        if not acc['deactivated'] and session.get('epoch', 0) == acc['epoch']:
            ended = _device_check(conn, uid)
    finally:
        conn.close()
    if ended or acc['deactivated'] or session.get('epoch', 0) != acc['epoch']:
        session.clear()
        if request.path.startswith('/api/') or request.is_json:
            return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
        return redirect(url_for('login'))
    return None


@app.route('/api/settings', methods=['GET', 'POST'])
def api_account_settings():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    conn = sqlite3.connect('users.db')
    try:
        acc = _account_row(conn, uid)
        if request.method == 'GET':
            return jsonify({'success': True, 'account': acc['settings']})
        data = request.get_json(silent=True) or {}
        incoming = data.get('account', data) or {}
        settings = acc['settings']
        if 'loginNotifications' in incoming:
            settings['loginNotifications'] = bool(incoming['loginNotifications'])
        if 'autoSignOutMinutes' in incoming:
            try:
                m = int(incoming['autoSignOutMinutes'])
            except (TypeError, ValueError):
                return jsonify({'success': False, 'message': 'Choose Off or a number of minutes.'}), 400
            settings['autoSignOutMinutes'] = 0 if m <= 0 else max(5, min(120, m))
        # Appearance follows the account to every device
        ap = data.get('appearance')
        if isinstance(ap, dict):
            cur = dict(settings.get('appearance') or {})
            if ap.get('themeColor') in ('blue', 'green', 'purple', 'dark'):
                cur['themeColor'] = ap['themeColor']
            if ap.get('themeMode') in ('light', 'dark', 'auto'):
                cur['themeMode'] = ap['themeMode']
            if 'fontSize' in ap:
                try:
                    cur['fontSize'] = max(12, min(20, int(ap['fontSize'])))
                except (TypeError, ValueError):
                    pass
            settings['appearance'] = cur
        _account_upsert(conn, uid, settings=json.dumps(settings))
        conn.commit()
        return jsonify({'success': True, 'account': settings})
    finally:
        conn.close()


_COMMON_PASSWORDS = {'password', 'password1', 'password123', '12345678', '123456789', '1234567890', 'qwerty123',
                     'qwertyuiop', '11111111', '00000000', 'abcd1234', 'iloveyou', 'eschool123', 'kenya2024', 'kenya2025',
                     'kenya2026', 'nairobi123', 'letmein123', 'welcome123', 'admin123'}


def _weak_password_reason(pw, email=None, name=None):
    low = pw.lower()
    if low in _COMMON_PASSWORDS or len(set(pw)) < 4:
        return 'That password is too easy to guess. Try three random words, or mix words and numbers.'
    if not (re.search(r'[A-Za-z]', pw) and re.search(r'[\d\W_]', pw)):
        return 'Use letters together with numbers or symbols.'
    local = (email or '').split('@')[0].lower()
    if (len(local) >= 4 and local in low) or (name and len(name) >= 3 and name.lower() in low):
        return 'Don’t use your name or email in your password.'
    return ''


@app.route('/api/account/change-password', methods=['POST'])
def api_change_password():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    data = request.get_json(silent=True) or {}
    current = data.get('currentPassword') or ''
    new = data.get('newPassword') or ''
    if _reset_rate_limited(f'change-password:{uid}', limit=8, window=3600):
        return jsonify({'success': False, 'message': 'Too many tries. Please wait an hour and try again.'}), 429
    if len(new) < 8:
        return jsonify({'success': False, 'message': 'New password must be at least 8 characters.'}), 400
    if len(new) > 128:
        return jsonify({'success': False, 'message': 'New password is too long.'}), 400
    weak = _weak_password_reason(new, session.get('email'), session.get('firstname'))
    if weak:
        return jsonify({'success': False, 'message': weak}), 400
    conn = sqlite3.connect('users.db')
    try:
        row = conn.execute('SELECT password FROM users WHERE id = ?', (uid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Account not found.'}), 404
        stored = row[0]
        # Google sign-in accounts have no password yet: they can set one here, but only
        # within 15 minutes of signing in (so a borrowed or stolen session can't do it)
        if not stored and int(_time.time()) - int(session.get('signed_in_at') or 0) > 15 * 60:
            return jsonify({'success': False, 'code': 'reauth',
                            'message': 'For your safety, sign out and sign in again with Google, then set your password within 15 minutes.'}), 403
        if stored:
            wait = login_wait_minutes(session.get('email'))
            if wait:
                return jsonify({'success': False, 'message': too_many_attempts_message(wait)}), 429
        if stored and not password_matches(stored, current):
            login_failed(session.get('email'))
            return jsonify({'success': False, 'message': 'Your current password is not correct.'}), 400
        if stored and password_matches(stored, new):
            return jsonify({'success': False, 'message': 'Choose a password different from your current one.'}), 400
        conn.execute('UPDATE users SET password = ? WHERE id = ?', (hash_password(new), uid))
        # sign out every other device; this one stays signed in
        acc = _account_row(conn, uid)
        new_epoch = acc['epoch'] + 1
        _account_upsert(conn, uid, session_epoch=new_epoch)
        create_notification(conn, uid, 'Password changed',
                            'Your password was changed and your other devices were signed out.',
                            icon='fa-key', color='green')
        note_password(conn, uid, new, changed=True, email=session.get('email'), name=session.get('firstname'))
        _security_tables(conn)
        conn.execute('UPDATE account_devices SET ended = 1 WHERE user_id = ? AND token != ?', (uid, session.get('dev') or ''))
        _account_event(conn, uid, 'password', '')
        conn.commit()
        session['epoch'] = new_epoch
        return jsonify({'success': True, 'message': 'Password updated. Your other devices have been signed out.'})
    finally:
        conn.close()


@app.route('/api/account/logout-all', methods=['POST'])
def api_logout_all():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    uid = session['user_id']
    conn = sqlite3.connect('users.db')
    try:
        acc = _account_row(conn, uid)
        _account_upsert(conn, uid, session_epoch=acc['epoch'] + 1)
        conn.commit()
    finally:
        conn.close()
    session.clear()
    return jsonify({'success': True, 'redirect': url_for('login')})


# ============ ACCOUNT SAFETY: devices, recent activity, backup email ============
# account_devices  - one row per sign-in (a browser on a phone or computer). The session
#                    keeps its token in session['dev']; signing a device out ends that session.
# account_events   - what happened to the account: sign-ins, failed passwords, changes.
# account_security - password strength (worked out when the password is typed, never stored),
#                    when it was last changed, the backup email and "ask for my password again".
DEVICE_SEEN_EVERY = 300          # update "last active" at most every 5 minutes
DEVICE_FORGOTTEN_DAYS = 14       # a device not used for this long counts as forgotten
BACKUP_CODE_MINUTES = 15
_EMAIL_RE = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')


def _security_tables(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS account_devices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        token TEXT NOT NULL UNIQUE,
        label TEXT, kind TEXT, method TEXT,
        remember INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL,
        last_seen TEXT NOT NULL,
        ended INTEGER NOT NULL DEFAULT 0)''')
    conn.execute('CREATE INDEX IF NOT EXISTS idx_account_devices_user ON account_devices (user_id, ended)')
    conn.execute('''CREATE TABLE IF NOT EXISTS account_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        kind TEXT NOT NULL,
        detail TEXT,
        n INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL)''')
    conn.execute('CREATE INDEX IF NOT EXISTS idx_account_events_user ON account_events (user_id, id)')
    conn.execute('''CREATE TABLE IF NOT EXISTS account_security (
        user_id INTEGER PRIMARY KEY,
        pw_score INTEGER,
        pw_set_at TEXT,
        backup_email TEXT,
        backup_verified INTEGER NOT NULL DEFAULT 0,
        backup_code TEXT,
        backup_code_at TEXT,
        backup_tries INTEGER NOT NULL DEFAULT 0,
        reauth INTEGER NOT NULL DEFAULT 1)''')


def _now_iso():
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


def _device_from_ua(ua):
    """('Chrome on Windows', 'computer') from a User-Agent header."""
    u = (ua or '').lower()
    if 'ipad' in u or ('android' in u and 'mobile' not in u) or 'tablet' in u:
        kind = 'tablet'
    elif any(w in u for w in ('iphone', 'android', 'mobile')):
        kind = 'phone'
    else:
        kind = 'computer'
    os_name = ('iPhone' if 'iphone' in u else 'iPad' if 'ipad' in u else 'Android' if 'android' in u
               else 'Windows' if 'windows' in u else 'ChromeOS' if 'cros' in u else 'Mac' if 'mac os' in u or 'macintosh' in u
               else 'Linux' if 'linux' in u else '')
    browser = ('Edge' if 'edg/' in u else 'Opera' if 'opr/' in u or 'opera' in u else 'Samsung Internet' if 'samsungbrowser' in u
               else 'Firefox' if 'firefox' in u or 'fxios' in u else 'Chrome' if 'chrome' in u or 'crios' in u
               else 'Safari' if 'safari' in u else 'A browser')
    return (f'{browser} on {os_name}' if os_name else browser), kind


def _sec_row(conn, uid):
    _security_tables(conn)
    conn.execute('INSERT OR IGNORE INTO account_security (user_id) VALUES (?)', (uid,))
    conn.row_factory, old = sqlite3.Row, conn.row_factory
    try:
        return dict(conn.execute('SELECT * FROM account_security WHERE user_id = ?', (uid,)).fetchone())
    finally:
        conn.row_factory = old


def _sec_set(conn, uid, **fields):
    _sec_row(conn, uid)
    for col, val in fields.items():
        conn.execute(f'UPDATE account_security SET {col} = ? WHERE user_id = ?', (val, uid))


def _account_event(conn, uid, kind, detail=''):
    _security_tables(conn)
    conn.execute('INSERT INTO account_events (user_id, kind, detail, created_at) VALUES (?, ?, ?, ?)',
                 (uid, kind, (detail or '')[:120], _now_iso()))
    # keep the newest 60 per account
    conn.execute('DELETE FROM account_events WHERE user_id = ? AND id NOT IN '
                 '(SELECT id FROM account_events WHERE user_id = ? ORDER BY id DESC LIMIT 60)', (uid, uid))


def _password_score(pw, email=None, name=None):
    """0-4 for how hard a password is to guess. Worked out from the typed password; only the number is kept."""
    pw = pw or ''
    if len(pw) < 8 or _weak_password_reason(pw, email, name):
        return 1 if len(pw) >= 8 else 0
    kinds = sum(bool(re.search(p, pw)) for p in (r'[a-z]', r'[A-Z]', r'\d', r'[^A-Za-z0-9]'))
    score = 1 + (kinds >= 3) + (len(pw) >= 12) + (len(pw) >= 16 or (len(pw) >= 12 and kinds == 4))
    return min(4, score)


def note_password(conn, uid, pw, changed=False, email=None, name=None):
    """Remember how strong a password is (never the password). changed=True also stamps the change date."""
    try:
        fields = {'pw_score': _password_score(pw, email, name)}
        if changed:
            fields['pw_set_at'] = _now_iso()
        _sec_set(conn, uid, **fields)
    except sqlite3.Error:
        pass


def _new_device_session(conn, uid, method):
    """Starts a device row for this browser's sign-in and puts its token in the session."""
    _security_tables(conn)
    label, kind = _device_from_ua(request.headers.get('User-Agent'))
    known = {r[0] for r in conn.execute('SELECT DISTINCT label FROM account_devices WHERE user_id = ?', (uid,)).fetchall()}
    seen_before = label in known or not known      # the first device we ever see isn't "new"
    token = _secrets.token_urlsafe(18)
    now = _now_iso()
    conn.execute('INSERT INTO account_devices (user_id, token, label, kind, method, remember, created_at, last_seen) '
                 'VALUES (?, ?, ?, ?, ?, ?, ?, ?)', (uid, token, label, kind, method, int(bool(session.permanent)), now, now))
    session['dev'] = token
    session['dev_seen'] = int(_clock.time())
    return label, seen_before


def account_failed_password(email):
    """A wrong password was typed for this email: add it to that account's activity (grouped per hour)."""
    if not email:
        return
    conn = sqlite3.connect('users.db')
    try:
        row = conn.execute('SELECT id FROM users WHERE lower(email) = lower(?)', (email.strip(),)).fetchone()
        if not row:
            return
        _security_tables(conn)
        last = conn.execute("SELECT id, created_at FROM account_events WHERE user_id = ? AND kind = 'failed' "
                            "ORDER BY id DESC LIMIT 1", (row[0],)).fetchone()
        when = _parse_any(last[1]) if last else None
        if when and (datetime.now(timezone.utc) - when).total_seconds() < 3600:
            conn.execute('UPDATE account_events SET n = n + 1, created_at = ? WHERE id = ?', (_now_iso(), last[0]))
        else:
            label, _ = _device_from_ua(request.headers.get('User-Agent'))
            _account_event(conn, row[0], 'failed', label)
        conn.commit()
    except sqlite3.Error:
        pass
    finally:
        conn.close()


def _reauth_ok(conn, uid, password):
    """For big changes when "ask for my password again" is on. (ok, message)."""
    if not _sec_row(conn, uid).get('reauth'):
        return True, ''
    stored = conn.execute('SELECT password FROM users WHERE id = ?', (uid,)).fetchone()
    stored = stored[0] if stored else None
    if not stored:      # Google-only account: must have signed in within the last 15 minutes
        if int(_clock.time()) - int(session.get('signed_in_at') or 0) <= 15 * 60:
            return True, ''
        return False, 'For your safety, sign out and sign in again with Google, then try within 15 minutes.'
    wait = login_wait_minutes(session.get('email'))
    if wait:
        return False, too_many_attempts_message(wait)
    if not password_matches(stored, password or ''):
        login_failed(session.get('email'))
        return False, 'Your password is not correct.' if password else 'Type your password to confirm.'
    return True, ''


def _security_need_user():
    if 'user_id' not in session:
        return None, (jsonify({'success': False, 'message': 'Please sign in again.'}), 401)
    return session['user_id'], None


@app.route('/api/account/security')
def api_account_security():
    """Everything the Account & Security tab shows."""
    uid, err = _security_need_user()
    if err:
        return err
    conn = sqlite3.connect('users.db')
    conn.row_factory = sqlite3.Row
    try:
        _security_tables(conn)
        sec = _sec_row(conn, uid)
        acc = _account_row(conn, uid)
        user = conn.execute('SELECT id, email, password, role FROM users WHERE id = ?', (uid,)).fetchone()
        if not user:
            return jsonify({'success': False, 'message': 'Account not found.'}), 404
        role = user['role'] or 'student'
        now = datetime.now(timezone.utc)
        my_token = session.get('dev')

        devices = []
        for d in conn.execute('SELECT * FROM account_devices WHERE user_id = ? AND ended = 0 ORDER BY last_seen DESC',
                              (uid,)).fetchall():
            seen = _parse_any(d['last_seen']) or now
            idle_days = (now - seen).total_seconds() / 86400
            # sessions without "Remember me" end when the browser closes; long-quiet ones have surely ended
            if idle_days > REMEMBER_ME_DAYS or (not d['remember'] and idle_days > 2):
                if d['token'] != my_token:
                    conn.execute('UPDATE account_devices SET ended = 1 WHERE id = ?', (d['id'],))
                    continue
            devices.append({'id': d['id'], 'label': d['label'], 'kind': d['kind'], 'this': d['token'] == my_token,
                            'created_at': d['created_at'], 'last_seen': d['last_seen'],
                            'forgotten': d['token'] != my_token and idle_days > DEVICE_FORGOTTEN_DAYS,
                            'google': d['method'] == 'google'})
        conn.commit()

        events = [{'kind': e['kind'], 'detail': e['detail'] or '', 'n': e['n'], 'at': e['created_at']}
                  for e in conn.execute('SELECT kind, detail, n, created_at FROM account_events WHERE user_id = ? '
                                        'ORDER BY id DESC LIMIT 8', (uid,)).fetchall()]

        has_pw = bool(user['password'])
        used_google = conn.execute("SELECT 1 FROM account_devices WHERE user_id = ? AND method = 'google' LIMIT 1",
                                   (uid,)).fetchone() is not None
        signs_in = ' & '.join(x for x in ('Email & password' if has_pw else '', 'Google' if (used_google or not has_pw) else '') if x)

        score = sec.get('pw_score')
        checks = []
        if has_pw:
            checks.append({'key': 'password', 'ok': score is not None and score >= 3,
                           'label': 'Strong password' if (score or 0) >= 3 else ('Make your password stronger' if score is not None else 'Check your password strength')})
        else:
            checks.append({'key': 'password', 'ok': used_google, 'label': 'Signs in with Google'})
        checks.append({'key': 'alerts', 'ok': bool(acc['settings'].get('loginNotifications')),
                       'label': 'Sign-in alerts on' if acc['settings'].get('loginNotifications') else 'Turn on sign-in alerts'})
        forgotten = sum(1 for d in devices if d['forgotten'])
        checks.append({'key': 'devices', 'ok': not forgotten,
                       'label': 'No forgotten devices' if not forgotten else f"Sign out {forgotten} old device{'s' if forgotten > 1 else ''}"})
        checks.append({'key': 'backup', 'ok': bool(sec.get('backup_verified')),
                       'label': 'Backup email added' if sec.get('backup_verified') else 'Add a backup email'})
        if role == 'student':
            linked = conn.execute("SELECT 1 FROM parent_links WHERE student_id = ? AND status = 'active' LIMIT 1",
                                  (uid,)).fetchone() is not None if conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'parent_links'").fetchone() else False
            checks.append({'key': 'parent', 'ok': linked, 'label': 'Parent / guardian linked' if linked else 'Link a parent / guardian'})
        else:
            checks.append({'key': 'reauth', 'ok': bool(sec.get('reauth')),
                           'label': 'Password asked before big changes' if sec.get('reauth') else 'Ask for my password before big changes'})

        joined = None
        try:
            joined = _user_joined(conn, uid)
        except Exception:
            pass
        plan = 'Free'
        try:
            plan = PLAN_NAMES.get(_plan_key_of(conn, uid), 'Free')
        except Exception:
            pass
        pending = sec.get('backup_email') and not sec.get('backup_verified')
        return jsonify({
            'success': True,
            'checks': checks, 'score': sum(1 for c in checks if c['ok']), 'total': len(checks),
            'password': {'has': has_pw, 'score': score, 'set_at': sec.get('pw_set_at')},
            'devices': devices, 'events': events,
            'details': {'eschool_id': 'ES-' + str(uid).zfill(6), 'role': {'student': 'Learner', 'parent': 'Parent', 'teacher': 'Teacher',
                                                                          'admin': 'Admin'}.get(role, role.title()),
                        'joined': joined.isoformat() if joined else None, 'signs_in': signs_in or 'Email & password',
                        'plan': plan, 'email': user['email']},
            'backup': {'email': sec.get('backup_email') or '', 'verified': bool(sec.get('backup_verified')), 'pending': bool(pending)},
            'reauth': bool(sec.get('reauth')),
            'mail_ready': _mail_ready(),
        })
    finally:
        conn.close()


@app.route('/api/account/devices/<int:dev_id>/signout', methods=['POST'])
def api_account_device_signout(dev_id):
    uid, err = _security_need_user()
    if err:
        return err
    conn = sqlite3.connect('users.db')
    try:
        _security_tables(conn)
        row = conn.execute('SELECT token, label FROM account_devices WHERE id = ? AND user_id = ? AND ended = 0',
                           (dev_id, uid)).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'That device is already signed out.'}), 404
        if row[0] == session.get('dev'):
            return jsonify({'success': False, 'message': 'This is the device you are using. Use Log out instead.'}), 400
        conn.execute('UPDATE account_devices SET ended = 1 WHERE id = ?', (dev_id,))
        _account_event(conn, uid, 'device_out', row[1])
        conn.commit()
        return jsonify({'success': True, 'message': f'{row[1]} has been signed out.'})
    finally:
        conn.close()


@app.route('/api/account/devices/signout-others', methods=['POST'])
def api_account_signout_others():
    """Every other device is signed out; this one stays signed in."""
    uid, err = _security_need_user()
    if err:
        return err
    conn = sqlite3.connect('users.db')
    try:
        _security_tables(conn)
        acc = _account_row(conn, uid)
        new_epoch = acc['epoch'] + 1
        _account_upsert(conn, uid, session_epoch=new_epoch)
        n = conn.execute('UPDATE account_devices SET ended = 1 WHERE user_id = ? AND ended = 0 AND token != ?',
                         (uid, session.get('dev') or '')).rowcount
        _account_event(conn, uid, 'others_out', str(n))
        conn.commit()
        session['epoch'] = new_epoch
        return jsonify({'success': True, 'message': 'All your other devices have been signed out.' if n else 'No other devices were signed in.'})
    finally:
        conn.close()


@app.route('/api/account/reauth', methods=['POST'])
def api_account_reauth_setting():
    uid, err = _security_need_user()
    if err:
        return err
    on = bool((request.get_json(silent=True) or {}).get('on'))
    conn = sqlite3.connect('users.db')
    try:
        if not on:      # turning the protection off needs the password too
            ok, msg = (True, '') if not _sec_row(conn, uid).get('reauth') else _reauth_ok(conn, uid, (request.get_json(silent=True) or {}).get('password'))
            if not ok:
                return jsonify({'success': False, 'code': 'password', 'message': msg}), 403
        _sec_set(conn, uid, reauth=int(on))
        conn.commit()
        return jsonify({'success': True, 'reauth': on})
    finally:
        conn.close()


@app.route('/api/account/change-email', methods=['POST'])
def api_account_change_email():
    uid, err = _security_need_user()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    new = (data.get('email') or '').strip()
    if not _EMAIL_RE.match(new) or len(new) > 254:
        return jsonify({'success': False, 'message': 'Please enter a valid email address.'}), 400
    if _reset_rate_limited(f'change-email:{uid}', limit=6, window=3600):
        return jsonify({'success': False, 'message': 'Too many tries. Please wait an hour and try again.'}), 429
    conn = sqlite3.connect('users.db')
    try:
        old = conn.execute('SELECT email FROM users WHERE id = ?', (uid,)).fetchone()
        old = old[0] if old else ''
        if (old or '').lower() == new.lower():
            return jsonify({'success': False, 'message': 'That is already your email address.'}), 400
        if conn.execute('SELECT 1 FROM users WHERE lower(email) = lower(?) AND id != ?', (new, uid)).fetchone():
            return jsonify({'success': False, 'message': 'Another account already uses that email.'}), 400
        ok, msg = _reauth_ok(conn, uid, data.get('password'))
        if not ok:
            return jsonify({'success': False, 'code': 'password', 'message': msg}), 403
        conn.execute('UPDATE users SET email = ? WHERE id = ?', (new, uid))
        sec = _sec_row(conn, uid)
        if (sec.get('backup_email') or '').lower() == new.lower():
            _sec_set(conn, uid, backup_email=None, backup_verified=0, backup_code=None)
        _account_event(conn, uid, 'email', new)
        create_notification(conn, uid, 'Email address changed', f'You now sign in with {new}.', icon='fa-envelope', color='blue')
        conn.commit()
        session['email'] = new
    finally:
        conn.close()
    if old and _mail_ready():       # tell the old address, so a stolen account is noticed
        try:
            mail.send(Message(subject='Your Eschool email address was changed', recipients=[old],
                              body=(f"The email address for your Eschool account was changed to {new}.\n\n"
                                    "If you didn't do this, reply to this email or contact Eschool support straight away.")))
        except Exception as e:
            print(f'Email change notice error: {e}')
    return jsonify({'success': True, 'email': new, 'message': f'Done. You now sign in with {new}.'})


@app.route('/api/account/backup-email', methods=['POST', 'DELETE'])
def api_account_backup_email():
    """POST {email, password} sends a 6-digit code; POST {code} confirms it; DELETE removes it."""
    uid, err = _security_need_user()
    if err:
        return err
    data = request.get_json(silent=True) or {}
    conn = sqlite3.connect('users.db')
    try:
        sec = _sec_row(conn, uid)
        if request.method == 'DELETE':
            _sec_set(conn, uid, backup_email=None, backup_verified=0, backup_code=None, backup_tries=0)
            _account_event(conn, uid, 'backup_off', '')
            conn.commit()
            return jsonify({'success': True, 'message': 'Backup email removed.'})

        if data.get('code') is not None:       # confirming
            code = re.sub(r'\D', '', str(data.get('code')))
            sent_at = _parse_any(sec.get('backup_code_at')) if sec.get('backup_code_at') else None
            if not sec.get('backup_email') or not sec.get('backup_code') or not sent_at:
                return jsonify({'success': False, 'message': 'Ask for a new code first.'}), 400
            if (datetime.now(timezone.utc) - sent_at).total_seconds() > BACKUP_CODE_MINUTES * 60 or sec.get('backup_tries', 0) >= 5:
                return jsonify({'success': False, 'message': 'That code has expired. Send a new one.'}), 400
            if not _hmac_cmp.compare_digest(hashlib.sha256(code.encode()).hexdigest(), sec['backup_code']):
                _sec_set(conn, uid, backup_tries=(sec.get('backup_tries') or 0) + 1)
                conn.commit()
                return jsonify({'success': False, 'message': 'That code is not right. Check the email and try again.'}), 400
            _sec_set(conn, uid, backup_verified=1, backup_code=None, backup_tries=0)
            _account_event(conn, uid, 'backup_on', sec['backup_email'])
            conn.commit()
            return jsonify({'success': True, 'message': 'Backup email confirmed.'})

        email = (data.get('email') or '').strip()
        if not _EMAIL_RE.match(email) or len(email) > 254:
            return jsonify({'success': False, 'message': 'Please enter a valid email address.'}), 400
        main = conn.execute('SELECT email FROM users WHERE id = ?', (uid,)).fetchone()
        if main and (main[0] or '').lower() == email.lower():
            return jsonify({'success': False, 'message': 'Use a different email from the one you sign in with.'}), 400
        if not _mail_ready():
            return jsonify({'success': False, 'message': "We can't send emails right now. Please try again later."}), 503
        if _reset_rate_limited(f'backup-email:{uid}', limit=5, window=3600):
            return jsonify({'success': False, 'message': 'Too many codes sent. Please wait an hour.'}), 429
        ok, msg = _reauth_ok(conn, uid, data.get('password'))
        if not ok:
            return jsonify({'success': False, 'code': 'password', 'message': msg}), 403
        code = f'{_secrets.randbelow(1000000):06d}'
        try:
            mail.send(Message(subject='Your Eschool backup email code', recipients=[email],
                              body=(f"Your code is {code}\n\nType it on the Account & Security page to add this as the backup "
                                    f"email for your Eschool account. It works for {BACKUP_CODE_MINUTES} minutes.\n\n"
                                    "If you didn't ask for this, you can ignore this email.")))
        except Exception as e:
            print(f'Backup email code error: {e}')
            return jsonify({'success': False, 'message': "We couldn't send the email just now. Please try again."}), 502
        _sec_set(conn, uid, backup_email=email, backup_verified=0, backup_tries=0,
                 backup_code=hashlib.sha256(code.encode()).hexdigest(), backup_code_at=_now_iso())
        conn.commit()
        return jsonify({'success': True, 'sent': True, 'message': f'We sent a 6-digit code to {email}.'})
    finally:
        conn.close()


@app.route('/api/account/deactivate', methods=['POST'])
def api_deactivate_account():
    uid, err = _security_need_user()
    if err:
        return err
    conn = sqlite3.connect('users.db')
    try:
        ok, msg = _reauth_ok(conn, uid, (request.get_json(silent=True) or {}).get('password'))
        if not ok:
            return jsonify({'success': False, 'code': 'password', 'message': msg}), 403
        _account_upsert(conn, uid, deactivated=1)
        _security_tables(conn)
        conn.execute('UPDATE account_devices SET ended = 1 WHERE user_id = ?', (uid,))
        _account_event(conn, uid, 'deactivated', '')
        conn.commit()
    finally:
        conn.close()
    session.clear()
    return jsonify({'success': True, 'redirect': url_for('login')})



# columns that point at the owner of a row; used to remove a deleted account's data
_OWNER_COLUMNS = ('user_id', 'student_id', 'parent_id', 'sender_id', 'receiver_id',
                  'follower_id', 'following_id', 'followed_id', 'teacher_id', 'owner_id')


@app.route('/api/account/delete', methods=['DELETE', 'POST'])
def api_delete_account():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if (session.get('role') or 'student') == 'student':
        return jsonify({'success': False, 'message': 'To close a learner account, send a ticket in Help & Support. '
                                                     'We confirm it with your linked parent first.'}), 403
    data = request.get_json(silent=True) or {}
    if (data.get('confirm') or '').strip() != 'DELETE':
        return jsonify({'success': False, 'message': 'Type DELETE to confirm.'}), 400
    uid = session['user_id']
    conn = sqlite3.connect('users.db')
    try:
        tables = [r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'").fetchall()]
        for t in tables:
            if t == 'users':
                continue
            cols = {r[1] for r in conn.execute(f'PRAGMA table_info("{t}")').fetchall()}
            for c in _OWNER_COLUMNS:
                if c in cols:
                    conn.execute(f'DELETE FROM "{t}" WHERE "{c}" = ?', (uid,))
        conn.execute('DELETE FROM users WHERE id = ?', (uid,))
        conn.commit()
    except sqlite3.Error as e:
        conn.rollback()
        print(f'Error deleting account {uid}: {e}')
        return jsonify({'success': False, 'message': 'Could not delete your account. Please try again.'}), 500
    finally:
        conn.close()
    session.clear()
    return jsonify({'success': True, 'redirect': '/'})



# ============ VOICE & VIDEO CALLS (Messages page) ============
# Calls are peer-to-peer WebRTC between the two browsers. The server only
# passes the connection details back and forth ("signalling"):
#   calls     - one row per call: who, voice/video, status, the offer/answer
#   call_ice  - network routes each browser finds, picked up by the other side
# Status: ringing -> accepted -> ended, or ringing -> declined / missed / cancelled.
# When a call finishes, a short line ("Voice call · 3:12", "Missed video call")
# is added to the chat so both people see it in their message history.
CALL_RING_SECONDS = 45


def _calls_tables(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS calls (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        caller_id INTEGER NOT NULL,
        callee_id INTEGER NOT NULL,
        kind TEXT NOT NULL DEFAULT 'audio',
        status TEXT NOT NULL DEFAULT 'ringing',
        offer TEXT,
        answer TEXT,
        created_at TEXT NOT NULL,
        answered_at TEXT,
        ended_at TEXT,
        logged INTEGER NOT NULL DEFAULT 0
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS call_ice (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        call_id INTEGER NOT NULL,
        from_id INTEGER NOT NULL,
        candidate TEXT NOT NULL
    )""")
    conn.execute('CREATE INDEX IF NOT EXISTS idx_call_ice_call ON call_ice (call_id, id)')
    # reconnect support (ICE restart): newer columns, added to older databases too
    cols = {r[1] for r in conn.execute('PRAGMA table_info(calls)').fetchall()}
    if 'restart_seq' not in cols:
        conn.execute('ALTER TABLE calls ADD COLUMN restart_seq INTEGER NOT NULL DEFAULT 0')
    if 'answer_seq' not in cols:
        conn.execute('ALTER TABLE calls ADD COLUMN answer_seq INTEGER NOT NULL DEFAULT 0')


def _now_iso():
    return datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')


def _call_log_message(conn, call):
    """Adds the 'Voice call · 3:12' / 'Missed video call' line to the chat, once."""
    if call['logged']:
        return
    label = 'video call' if call['kind'] == 'video' else 'voice call'
    if call['status'] == 'ended' and call['answered_at']:
        try:
            secs = int((datetime.strptime(call['ended_at'], '%Y-%m-%d %H:%M:%S') -
                        datetime.strptime(call['answered_at'], '%Y-%m-%d %H:%M:%S')).total_seconds())
        except (TypeError, ValueError):
            secs = 0
        text = f"📞 {label.capitalize()} · {secs // 60}:{secs % 60:02d}"
    elif call['status'] == 'declined':
        text = f"📞 {label.capitalize()} declined"
    else:  # missed / cancelled / ended before anyone answered
        text = f"📞 Missed {label}"
    _messages_tables(conn)
    conn.execute("INSERT INTO messages (sender_id, receiver_id, text, is_read, is_broadcast, kind) VALUES (?, ?, ?, 0, 0, 'call')",
                 (call['caller_id'], call['callee_id'], text))
    conn.execute('UPDATE calls SET logged = 1 WHERE id = ?', (call['id'],))
    if call['status'] in ('missed', 'cancelled'):
        row = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (call['caller_id'],)).fetchone()
        who = f"{row[0] or ''} {row[1] or ''}".strip() if row else 'Someone'
        create_notification(conn, call['callee_id'], f'Missed {label} from {who}',
                            'Open Messages to call them back.', icon='fa-phone-slash', color='red',
                            category='messages')


def _expire_ringing(conn):
    """Ringing calls nobody answered in time become 'missed'."""
    cutoff = (datetime.utcnow() - timedelta(seconds=CALL_RING_SECONDS)).strftime('%Y-%m-%d %H:%M:%S')
    rows = conn.execute("SELECT * FROM calls WHERE status = 'ringing' AND created_at < ?", (cutoff,)).fetchall()
    for r in rows:
        conn.execute("UPDATE calls SET status = 'missed', ended_at = ? WHERE id = ?", (_now_iso(), r['id']))
        call = dict(r)
        call.update(status='missed', ended_at=_now_iso())
        _call_log_message(conn, call)
    if rows:
        conn.commit()


def _call_conn():
    conn = sqlite3.connect('users.db')
    conn.row_factory = sqlite3.Row
    _calls_tables(conn)
    _expire_ringing(conn)
    return conn


def _call_for_me(conn, call_id):
    call = conn.execute('SELECT * FROM calls WHERE id = ?', (call_id,)).fetchone()
    me = session.get('user_id')
    if not call or me not in (call['caller_id'], call['callee_id']):
        return None
    return call


def _person(conn, user_id):
    row = conn.execute('SELECT id, firstname, lastname, avatar_filename FROM users WHERE id = ?', (user_id,)).fetchone()
    if not row:
        return None
    first, last = (row['firstname'] or '').strip(), (row['lastname'] or '').strip()
    return {'id': row['id'], 'name': f'{first} {last}'.strip() or 'Eschool user',
            'avatar': (first[:1] or last[:1] or '?').upper(),
            'avatar_url': get_avatar_url(row['id'], row['avatar_filename'])}


@app.route('/api/calls/start', methods=['POST'])
def api_call_start():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    data = request.get_json(silent=True) or {}
    try:
        callee = int(data.get('callee_id'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Choose who to call.'}), 400
    kind = 'video' if data.get('kind') == 'video' else 'audio'
    offer = data.get('offer')
    if callee == me:
        return jsonify({'success': False, 'message': "You can't call yourself."}), 400
    if not isinstance(offer, str) or not offer or len(offer) > 100000:
        return jsonify({'success': False, 'message': 'Could not start the call.'}), 400

    conn = _call_conn()
    try:
        if not conn.execute('SELECT 1 FROM users WHERE id = ?', (callee,)).fetchone():
            return jsonify({'success': False, 'message': 'That person was not found.'}), 404
        allowed, reason = can_message(conn, me, session.get('role'), callee, kind='call')
        if not allowed:
            return jsonify({'success': False, 'message': reason or "You can't call this person."}), 403
        busy = conn.execute("""SELECT 1 FROM calls WHERE status IN ('ringing', 'accepted')
                               AND (caller_id = ? OR callee_id = ?) LIMIT 1""", (callee, callee)).fetchone()
        if not busy:   # or in a group call
            _gc_tables(conn)
            busy = conn.execute("""SELECT 1 FROM group_call_members m JOIN group_calls g ON g.id = m.call_id
                                   WHERE m.user_id = ? AND m.status = 'joined' AND g.status = 'active' LIMIT 1""",
                                (callee,)).fetchone()
        if busy:
            return jsonify({'success': False, 'message': 'They are on another call. Try again in a moment.'}), 409
        # anything I left open (e.g. a closed tab) is finished first
        for old in conn.execute("""SELECT * FROM calls WHERE status IN ('ringing', 'accepted')
                                   AND (caller_id = ? OR callee_id = ?)""", (me, me)).fetchall():
            status = 'ended' if old['status'] == 'accepted' else 'cancelled'
            conn.execute('UPDATE calls SET status = ?, ended_at = ? WHERE id = ?', (status, _now_iso(), old['id']))
            c = dict(old); c.update(status=status, ended_at=_now_iso())
            _call_log_message(conn, c)
        cur = conn.execute('INSERT INTO calls (caller_id, callee_id, kind, status, offer, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                           (me, callee, kind, 'ringing', offer, _now_iso()))
        conn.commit()
        return jsonify({'success': True, 'call_id': cur.lastrowid, 'ring_seconds': CALL_RING_SECONDS})
    finally:
        conn.close()


@app.route('/api/calls/incoming', methods=['GET'])
def api_call_incoming():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _call_conn()
    try:
        call = conn.execute("""SELECT * FROM calls WHERE callee_id = ? AND status = 'ringing'
                               ORDER BY id DESC LIMIT 1""", (session['user_id'],)).fetchone()
        if not call:
            return jsonify({'success': True, 'call': None})
        return jsonify({'success': True, 'call': {
            'id': call['id'], 'kind': call['kind'], 'caller': _person(conn, call['caller_id'])}})
    finally:
        conn.close()


@app.route('/api/calls/<int:call_id>', methods=['GET'])
def api_call_get(call_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        me = session['user_id']
        other = call['callee_id'] if me == call['caller_id'] else call['caller_id']
        out = {'id': call['id'], 'kind': call['kind'], 'status': call['status'],
               'role': 'caller' if me == call['caller_id'] else 'callee',
               'other': _person(conn, other), 'answered_at': to_iso_utc(call['answered_at']),
               'restart_seq': call['restart_seq'], 'answer_seq': call['answer_seq']}
        if me == call['callee_id']:
            out['offer'] = call['offer']
        else:
            out['answer'] = call['answer']
        return jsonify({'success': True, 'call': out})
    finally:
        conn.close()


@app.route('/api/calls/<int:call_id>/answer', methods=['POST'])
def api_call_answer(call_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    answer = (request.get_json(silent=True) or {}).get('answer')
    if not isinstance(answer, str) or not answer or len(answer) > 100000:
        return jsonify({'success': False, 'message': 'Could not answer the call.'}), 400
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call or call['callee_id'] != session['user_id']:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        if call['status'] != 'ringing':
            return jsonify({'success': False, 'message': 'This call has already ended.'}), 409
        conn.execute("UPDATE calls SET status = 'accepted', answer = ?, answered_at = ? WHERE id = ?",
                     (answer, _now_iso(), call_id))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/calls/<int:call_id>/restart', methods=['POST'])
def api_call_restart(call_id):
    """Caller sends a fresh offer to repair a dropped connection (ICE restart)."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    offer = (request.get_json(silent=True) or {}).get('offer')
    if not isinstance(offer, str) or not offer or len(offer) > 100000:
        return jsonify({'success': False, 'message': 'Bad offer.'}), 400
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call or call['caller_id'] != session['user_id']:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        if call['status'] != 'accepted':
            return jsonify({'success': False, 'message': 'This call has already ended.'}), 409
        seq = (call['restart_seq'] or 0) + 1
        conn.execute('UPDATE calls SET offer = ?, restart_seq = ? WHERE id = ?', (offer, seq, call_id))
        conn.commit()
        return jsonify({'success': True, 'seq': seq})
    finally:
        conn.close()


@app.route('/api/calls/<int:call_id>/reanswer', methods=['POST'])
def api_call_reanswer(call_id):
    """Callee answers the caller's repair offer."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    data = request.get_json(silent=True) or {}
    answer, seq = data.get('answer'), data.get('seq')
    if not isinstance(answer, str) or not answer or len(answer) > 100000 or not isinstance(seq, int):
        return jsonify({'success': False, 'message': 'Bad answer.'}), 400
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call or call['callee_id'] != session['user_id']:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        if call['status'] != 'accepted' or seq != call['restart_seq']:
            return jsonify({'success': False, 'message': 'Out of date.'}), 409
        conn.execute('UPDATE calls SET answer = ?, answer_seq = ? WHERE id = ?', (answer, seq, call_id))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/calls/config', methods=['GET'])
def api_call_config():
    """Connection servers for calls. Google STUN always; a TURN relay if set.

    Without a TURN relay, calls between some networks (mobile data, school or
    office Wi-Fi) connect for a moment and then freeze or drop. To add one,
    set these environment variables before starting the app:
        TURN_URLS      e.g. turn:global.relay.example.com:3478,turns:global.relay.example.com:443?transport=tcp
        TURN_USERNAME  the username your TURN provider gives you
        TURN_PASSWORD  the password / credential
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    servers = [{'urls': ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302']}]
    turn_urls = [u.strip() for u in os.environ.get('TURN_URLS', '').split(',') if u.strip()]
    if turn_urls:
        servers.append({'urls': turn_urls,
                        'username': os.environ.get('TURN_USERNAME', ''),
                        'credential': os.environ.get('TURN_PASSWORD', '')})
    return jsonify({'success': True, 'iceServers': servers, 'relay': bool(turn_urls)})


@app.route('/api/calls/<int:call_id>/decline', methods=['POST'])
def api_call_decline(call_id):
    return _finish_call(call_id, decline=True)


@app.route('/api/calls/<int:call_id>/end', methods=['POST'])
def api_call_end(call_id):
    return _finish_call(call_id, decline=False)


def _finish_call(call_id, decline):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        if call['status'] in ('ringing', 'accepted'):
            me = session['user_id']
            if call['status'] == 'accepted':
                status = 'ended'
            elif decline and me == call['callee_id']:
                status = 'declined'
            else:
                status = 'cancelled' if me == call['caller_id'] else 'declined'
            conn.execute('UPDATE calls SET status = ?, ended_at = ? WHERE id = ?', (status, _now_iso(), call_id))
            c = dict(call); c.update(status=status, ended_at=_now_iso())
            _call_log_message(conn, c)
            conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/calls/<int:call_id>/ice', methods=['GET', 'POST'])
def api_call_ice(call_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _call_conn()
    try:
        call = _call_for_me(conn, call_id)
        if not call:
            return jsonify({'success': False, 'message': 'Call not found.'}), 404
        me = session['user_id']
        if request.method == 'POST':
            cand = (request.get_json(silent=True) or {}).get('candidate')
            if not isinstance(cand, str) or not cand or len(cand) > 5000:
                return jsonify({'success': False, 'message': 'Bad candidate.'}), 400
            if call['status'] in ('ringing', 'accepted'):
                conn.execute('INSERT INTO call_ice (call_id, from_id, candidate) VALUES (?, ?, ?)', (call_id, me, cand))
                conn.commit()
            return jsonify({'success': True})
        try:
            after = int(request.args.get('after', 0))
        except ValueError:
            after = 0
        rows = conn.execute('SELECT id, candidate FROM call_ice WHERE call_id = ? AND from_id != ? AND id > ? ORDER BY id',
                            (call_id, me, after)).fetchall()
        return jsonify({'success': True, 'candidates': [{'id': r['id'], 'candidate': r['candidate']} for r in rows]})
    finally:
        conn.close()


# ============ TEACHER DASHBOARD (everything on /teacher-dashboard, from the database) ============
# GET /api/teacher/dashboard -> numbers, trends, today's and upcoming classes and lessons,
# private-teaching requests, ratings, top resources, new learners following, recent activity,
# and a "needs your attention" list. Days are counted in Nairobi time.
# /api/teacher/todos keeps the teacher's to-do list on the server (every device).

def _td_day(ts):
    """'YYYY-MM-DD' in Nairobi time for a stored UTC timestamp, or None."""
    d = _parse_any(ts)
    return (d + timedelta(hours=3)).strftime('%Y-%m-%d') if d else None


def _td_days(n):
    today = datetime.strptime(_nairobi_today(), '%Y-%m-%d')
    return [(today - timedelta(days=i)).strftime('%Y-%m-%d') for i in range(n - 1, -1, -1)]


def _td_since(days):
    """UTC 'YYYY-MM-DD HH:MM:SS' for the start of the Nairobi day `days` days ago."""
    start = datetime.strptime(_nairobi_today(), '%Y-%m-%d') - timedelta(days=days) - timedelta(hours=3)
    return start.strftime('%Y-%m-%d %H:%M:%S')


def _td_todos_table(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS teacher_todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        teacher_id INTEGER NOT NULL,
        text TEXT NOT NULL,
        due TEXT,
        done INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL,
        done_at TEXT)''')


# ============ TEACHER SCHEDULE ============
# A teacher's own events (classes, exams, marking, meetings...), with
# repeats, per-day done/missed, and marked days (holidays, exam weeks).
# Times are Nairobi wall time (day + HH:MM); every item is also sent with
# its UTC 'start' so it sits next to live classes and private lessons.
SCHED_KINDS = {
    'class': ('Class', '#4361ee'), 'practical': ('Practical / lab', '#0ea5e9'), 'exam': ('Exam / test', '#ef4444'),
    'deadline': ('Assignment due', '#f59e0b'), 'marking': ('Marking', '#8b5cf6'), 'meeting': ('Meeting', '#14b8a6'),
    'office': ('Office hours', '#22c55e'), 'personal': ('Personal', '#64748b'),
    'study': ('Study / revision', '#06b6d4'),
}
# the event types a learner can pick on their schedule
LEARNER_SCHED_KINDS = ('class', 'study', 'exam', 'deadline', 'meeting', 'personal')
SCHED_REPEATS = ('none', 'daily', 'weekdays', 'weekly')
MARK_COLORS = ('#ec4899', '#ef4444', '#8b5cf6', '#10b981', '#f59e0b', '#3b82f6')


def _sched_tables(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS teacher_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT, teacher_id INTEGER NOT NULL, title TEXT NOT NULL,
        kind TEXT NOT NULL DEFAULT 'class', subject TEXT, grade TEXT, day TEXT NOT NULL, start_time TEXT NOT NULL,
        minutes INTEGER NOT NULL DEFAULT 60, location TEXT, link TEXT, notes TEXT,
        repeat TEXT NOT NULL DEFAULT 'none', repeat_until TEXT, created_at TEXT, updated_at TEXT)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS teacher_event_days (
        event_id INTEGER NOT NULL, day TEXT NOT NULL, status TEXT NOT NULL, at TEXT,
        PRIMARY KEY (event_id, day))""")          # done | missed | skipped (one day removed from a repeat)
    conn.execute("""CREATE TABLE IF NOT EXISTS teacher_day_marks (
        id INTEGER PRIMARY KEY AUTOINCREMENT, teacher_id INTEGER NOT NULL, day TEXT NOT NULL, label TEXT NOT NULL,
        color TEXT, yearly INTEGER NOT NULL DEFAULT 0, created_at TEXT)""")
    # learners can keep several named study plans ("Exam revision", "Holiday study" ...)
    conn.execute("""CREATE TABLE IF NOT EXISTS study_plans (
        id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL,
        color TEXT, created_at TEXT)""")
    if 'plan_id' not in {r[1] for r in conn.execute('PRAGMA table_info(teacher_events)').fetchall()}:
        conn.execute('ALTER TABLE teacher_events ADD COLUMN plan_id INTEGER')


def _d(s):
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except (TypeError, ValueError):
        return None


def _event_days(ev, start, end):
    """Every day (date) this event happens on between start and end, inclusive."""
    first = _d(ev['day'])
    if not first:
        return []
    rep = ev['repeat'] or 'none'
    if rep == 'none':
        return [first] if start <= first <= end else []
    until = min(_d(ev['repeat_until']) or first + timedelta(days=365), end)
    out, day = [], max(first, start)
    while day <= until:
        delta = (day - first).days
        if rep == 'daily' or (rep == 'weekdays' and day.weekday() < 5) or (rep == 'weekly' and delta % 7 == 0):
            out.append(day)
        day += timedelta(days=1)
    return out


def _own_events(conn, me, start, end):
    """The teacher's own events, one item per day they happen, between two dates."""
    _sched_tables(conn)
    rows = conn.execute('SELECT * FROM teacher_events WHERE teacher_id = ? AND day <= ?', (me, end.isoformat())).fetchall()
    ids = [r['id'] for r in rows] or [-1]
    marks = {}
    for x in conn.execute(f"SELECT event_id, day, status FROM teacher_event_days WHERE event_id IN ({','.join('?' * len(ids))})", ids):
        marks[(x[0], x[1])] = x[2]
    out = []
    for r in rows:
        for day in _event_days(r, start, end):
            key = day.isoformat()
            st = marks.get((r['id'], key))
            if st == 'skipped':
                continue
            hh, mm = (r['start_time'] or '08:00').split(':')[:2]
            local = datetime(day.year, day.month, day.day, int(hh), int(mm))
            label, color = SCHED_KINDS.get(r['kind'], SCHED_KINDS['class'])
            out.append({'type': 'event', 'id': r['id'], 'title': r['title'], 'kind': r['kind'], 'kind_label': label, 'color': color,
                        'subject': r['subject'] or '', 'grade': r['grade'] or '', 'start': _iso(local - timedelta(hours=3)),
                        'minutes': r['minutes'] or 60, 'day': key, 'time': f'{int(hh):02d}:{int(mm):02d}',
                        'location': r['location'] or '', 'link': r['link'] or '', 'notes': r['notes'] or '',
                        'repeat': r['repeat'] or 'none', 'repeat_until': r['repeat_until'] or '', 'first_day': r['day'],
                        'status': st or '', 'plan_id': r['plan_id'] if 'plan_id' in r.keys() else None})
    return out


def _share_tables(conn):
    """Events a teacher shares with learners they teach privately (and so with those learners' parents)."""
    _sched_tables(conn)
    conn.execute("""CREATE TABLE IF NOT EXISTS teacher_event_shares (
        event_id INTEGER NOT NULL, student_id INTEGER NOT NULL, PRIMARY KEY (event_id, student_id))""")


def _my_share_learners(conn, teacher_id):
    """Learners a teacher can share events with: the ones they teach privately (accepted or active)."""
    _tutor_tables(conn)
    out = {}
    for r in conn.execute("""SELECT t.student_id, u.firstname, u.lastname FROM tutoring t LEFT JOIN users u ON u.id = t.student_id
                             WHERE t.teacher_id = ? AND t.status IN ('active', 'accepted') ORDER BY t.id DESC""", (teacher_id,)).fetchall():
        out.setdefault(r['student_id'], {'id': r['student_id'], 'name': _full_name(r['firstname'], r['lastname'], 'Learner')})
    return out


def _event_shares(conn, event_ids):
    _share_tables(conn)
    ids = list(event_ids) or [-1]
    out = {}
    for r in conn.execute(f"SELECT event_id, student_id FROM teacher_event_shares WHERE event_id IN ({','.join('?' * len(ids))})", ids):
        out.setdefault(r[0], []).append(r[1])
    return out


def _event_when(ev, uid, day=None):
    """'Fri Nov 20, 17:00 EAT' for one day of an event, in this person's own time zone, plus how it repeats."""
    d0 = _d(day or ev['day'])
    if not d0:
        return ''
    hh, mm = (ev['start_time'] or '08:00').split(':')[:2]
    start_utc = datetime(d0.year, d0.month, d0.day, int(hh), int(mm), tzinfo=timezone.utc) - timedelta(hours=3)
    text = _when_for(uid, start_utc)
    rep = ev['repeat'] or 'none'
    if not day and rep != 'none':
        text += {'daily': ', every day', 'weekdays': ', every weekday', 'weekly': ', every week'}.get(rep, '')
        until = _d(ev['repeat_until'])
        if until:
            text += f" until {until.strftime('%b %d')}"
    return text


def _notify_event(conn, ev, student_ids, what, day=None):
    """Tells learners an event was shared with them, and the parents who hired this teacher for them.
    what: new | changed | removed | cancelled"""
    if not student_ids:
        return
    t = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (ev['teacher_id'],)).fetchone()
    teacher = _full_name(t['firstname'], t['lastname'], 'Your teacher') if t else 'Your teacher'
    title = ev['title']
    for sid in student_ids:
        kid = conn.execute('SELECT firstname FROM users WHERE id = ?', (sid,)).fetchone()
        kid_name = (kid['firstname'] if kid and kid['firstname'] else 'your child')
        parents = [r[0] for r in conn.execute("""SELECT DISTINCT parent_id FROM tutoring WHERE teacher_id = ? AND student_id = ?
                                                 AND status IN ('active', 'accepted', 'ended')""", (ev['teacher_id'], sid)).fetchall()]
        for uid in dict.fromkeys([sid] + parents):
            is_kid = uid == sid
            whose = 'your' if is_kid else f"{kid_name}'s"
            where = 'Open your Schedule to see it.' if is_kid else 'See it in the Timetable on your Teachers page.'
            when = _event_when(ev, uid, day)
            if what == 'new':
                head, msg, icon, color = 'New on the schedule', f"{teacher} added “{title}” to {whose} schedule: {when}. {where}", 'fa-calendar-plus', '#4361ee'
            elif what == 'changed':
                head, msg, icon, color = 'Schedule changed', f"{teacher} changed “{title}” on {whose} schedule. It is now {when}. {where}", 'fa-calendar-day', '#f59e0b'
            elif what == 'removed':
                head, msg, icon, color = 'Removed from the schedule', f"{teacher} removed “{title}” from {whose} schedule.", 'fa-calendar-minus', 'orange'
            else:
                head, msg, icon, color = 'Cancelled', (f"{teacher} cancelled “{title}” on {when}. The other days stay on {whose} schedule." if day
                                                       else f"{teacher} cancelled “{title}”. It is off {whose} schedule."), 'fa-calendar-xmark', 'orange'
            create_notification(conn, uid, head, msg, icon=icon, color=color, category='tutoring')


def _clean_share(conn, teacher_id, raw):
    """The learner ids a teacher picked, keeping only learners they teach. None if nothing was sent."""
    if raw is None:
        return None
    mine = _my_share_learners(conn, teacher_id)
    out = []
    for x in (raw if isinstance(raw, list) else [])[:100]:
        try:
            x = int(x)
        except (TypeError, ValueError):
            continue
        if x in mine and x not in out:
            out.append(x)
    return out


def _save_shares(conn, eid, ids):
    conn.execute('DELETE FROM teacher_event_shares WHERE event_id = ?', (eid,))
    conn.executemany('INSERT INTO teacher_event_shares (event_id, student_id) VALUES (?, ?)', [(eid, x) for x in ids])


def _shared_events(conn, pairs, start, end):
    """Events teachers shared, one item per day, for (teacher_id, student_id) pairs, or for
    pairs = ('student', id) meaning every teacher who shared with that learner."""
    _share_tables(conn)
    if pairs and pairs[0] == 'student':
        rows = conn.execute("""SELECT e.*, s.student_id, u.firstname AS tf, u.lastname AS tl FROM teacher_event_shares s
                               JOIN teacher_events e ON e.id = s.event_id LEFT JOIN users u ON u.id = e.teacher_id
                               WHERE s.student_id = ? AND e.day <= ?""", (pairs[1], end.isoformat())).fetchall()
    else:
        pairs = list(pairs)
        if not pairs:
            return []
        cond = ' OR '.join(['(e.teacher_id = ? AND s.student_id = ?)'] * len(pairs))
        rows = conn.execute(f"""SELECT e.*, s.student_id, u.firstname AS tf, u.lastname AS tl FROM teacher_event_shares s
                                JOIN teacher_events e ON e.id = s.event_id LEFT JOIN users u ON u.id = e.teacher_id
                                WHERE e.day <= ? AND ({cond})""", [end.isoformat()] + [v for p in pairs for v in p]).fetchall()
    ids = list({r['id'] for r in rows}) or [-1]
    skipped = {(x[0], x[1]) for x in conn.execute(
        f"SELECT event_id, day FROM teacher_event_days WHERE status = 'skipped' AND event_id IN ({','.join('?' * len(ids))})", ids)}
    out = []
    for r in rows:
        for day in _event_days(r, start, end):
            key = day.isoformat()
            if (r['id'], key) in skipped:
                continue
            hh, mm = (r['start_time'] or '08:00').split(':')[:2]
            local = datetime(day.year, day.month, day.day, int(hh), int(mm))
            label, color = SCHED_KINDS.get(r['kind'], SCHED_KINDS['class'])
            out.append({'type': 'teacher', 'id': r['id'], 'title': r['title'], 'kind': r['kind'], 'kind_label': label, 'color': color,
                        'teacher': _full_name(r['tf'], r['tl'], 'Teacher'), 'teacher_id': r['teacher_id'], 'student_id': r['student_id'],
                        'subject': r['subject'] or '', 'grade': r['grade'] or '', 'start': _iso(local - timedelta(hours=3)),
                        'minutes': r['minutes'] or 60, 'day': key, 'time': f'{int(hh):02d}:{int(mm):02d}',
                        'location': r['location'] or '', 'link': r['link'] or '', 'notes': r['notes'] or '',
                        'repeat': r['repeat'] or 'none', 'repeat_until': r['repeat_until'] or '', 'first_day': r['day'], 'status': ''})
    return out


def _marks_between(conn, me, start, end):
    _sched_tables(conn)
    out = []
    for r in conn.execute('SELECT * FROM teacher_day_marks WHERE teacher_id = ? ORDER BY day', (me,)).fetchall():
        d0 = _d(r['day'])
        if not d0:
            continue
        days = [d0] if start <= d0 <= end else []
        if r['yearly']:
            days = []
            for y in range(start.year, end.year + 1):
                try:
                    dd = d0.replace(year=y)
                except ValueError:          # 29 Feb in a normal year
                    dd = d0.replace(year=y, day=28)
                if dd >= d0 and start <= dd <= end:
                    days.append(dd)
        for dd in days:
            out.append({'id': r['id'], 'day': dd.isoformat(), 'label': r['label'], 'color': r['color'] or '#ec4899',
                        'yearly': bool(r['yearly']), 'first_day': r['day']})
    return out


def _sched_guard():
    """Teachers and learners each keep their own schedule (events + marked days) on the server."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') not in ('teacher', 'student'):
        return jsonify({'success': False, 'message': 'Teachers and learners only'}), 403
    return None


def _clean_event(d, old=None):
    """Checks a new or edited event. Returns (values, errors)."""
    old = dict(old) if old else {}
    v, err = {}, {}

    def take(k, default=None):
        return d[k] if k in d else old.get(k, default)
    title = str(take('title', '') or '').strip()[:120]
    if not title:
        err['title'] = 'Give it a title.'
    kind = take('kind', 'class')
    if kind not in SCHED_KINDS:
        kind = 'class'
    day = str(take('day', '') or '')[:10]
    if not _d(day):
        err['day'] = 'Choose a date.'
    tm = str(take('start_time', '') or '')[:5]
    if not re.fullmatch(r'([01]\d|2[0-3]):[0-5]\d', tm):
        err['start_time'] = 'Choose a start time.'
    try:
        minutes = int(take('minutes', 60))
    except (TypeError, ValueError):
        minutes = 0
    if not 5 <= minutes <= 720:
        err['minutes'] = 'Length must be between 5 minutes and 12 hours.'
    rep = take('repeat', 'none')
    rep = rep if rep in SCHED_REPEATS else 'none'
    until = str(take('repeat_until', '') or '')[:10] if rep != 'none' else ''
    if rep != 'none':
        if not _d(until):
            err['repeat_until'] = 'Choose the last day it repeats.'
        elif _d(day) and not (_d(day) <= _d(until) <= _d(day) + timedelta(days=366)):
            err['repeat_until'] = 'The last day must be on or after the first day, and within a year.'
    link = str(take('link', '') or '').strip()[:300]
    if link and not re.match(r'^https?://', link, re.I):
        err['link'] = 'Paste a full link starting with https://'
    grade = str(take('grade', '') or '')
    v.update(title=title, kind=kind, day=day, start_time=tm, minutes=minutes, repeat=rep, repeat_until=until or None, link=link,
             subject=str(take('subject', '') or '').strip()[:40], grade=grade if re.fullmatch(r'Grade (?:[1-9]|1[01])', grade) else '',
             location=str(take('location', '') or '').strip()[:80], notes=str(take('notes', '') or '').strip()[:1000])
    return v, err


@app.route('/api/teacher/schedule')
def api_teacher_schedule():
    guard = _sched_guard()
    if guard:
        return guard
    me = session['user_id']
    today = _d(_nairobi_today())
    start = _d(request.args.get('from')) or today - timedelta(days=35)
    end = _d(request.args.get('to')) or today + timedelta(days=42)
    if end < start or (end - start).days > 400:
        return jsonify({'success': False, 'message': 'Choose a shorter range.'}), 400
    lo = _iso(datetime.combine(start, datetime.min.time()) - timedelta(hours=3))
    hi = _iso(datetime.combine(end + timedelta(days=1), datetime.min.time()) - timedelta(hours=3))
    conn = _links_db()
    if session.get('role') == 'student':
        try:
            return _learner_schedule(conn, me, today, start, end, lo, hi)
        finally:
            conn.close()
    try:
        _sched_tables(conn)
        items = _own_events(conn, me, start, end)
        for r in conn.execute("SELECT id, title, subject, grade, description, start_time, duration_min, platform, COALESCE(state, 'scheduled') AS state, "
                              "'/teacher-live/studio/' || id AS stream_url "
                              'FROM live_classes WHERE teacher_id = ?', (me,)).fetchall():
            st = _parse_any(r['start_time'])
            if st and lo <= _iso(st) < hi:
                items.append({'type': 'live', 'id': r['id'], 'title': r['title'], 'subject': r['subject'] or '', 'grade': r['grade'] or '',
                              'start': _iso(st), 'minutes': r['duration_min'] or 60, 'day': _td_day(_iso(st)),
                              'link': r['stream_url'], 'location': 'Eschool Live', 'notes': r['description'] or '',
                              'color': '#e11d48', 'kind_label': 'Live class',
                              'status': 'completed' if r['state'] == 'ended' else ''})
        try:
            _tutor_tables(conn)
            for r in conn.execute("""SELECT s.*, t.subject, su.firstname, su.lastname FROM tutoring_sessions s
                                     JOIN tutoring t ON t.id = s.tutoring_id LEFT JOIN users su ON su.id = t.student_id
                                     WHERE t.teacher_id = ? AND s.status != 'cancelled'""", (me,)).fetchall():
                st = _parse_any(r['starts_at'])
                if st and lo <= _iso(st) < hi:
                    items.append({'type': 'lesson', 'id': r['id'], 'title': f"{r['subject']} lesson", 'subject': r['subject'] or '',
                                  'student': _full_name(r['firstname'], r['lastname'], 'Learner'), 'start': _iso(st),
                                  'minutes': r['minutes'] or 60, 'day': _td_day(_iso(st)), 'link': r['link'] or '',
                                  'notes': r['topic'] or '', 'status': r['status'], 'color': '#10b981', 'kind_label': 'Private lesson'})
        except sqlite3.OperationalError:
            pass
        marks = _marks_between(conn, me, start, end)
        shares = _event_shares(conn, {x['id'] for x in items if x['type'] == 'event'})
        for x in items:
            if x['type'] == 'event':
                x['shared_with'] = shares.get(x['id'], [])
        learners = list(_my_share_learners(conn, me).values())
    finally:
        conn.close()
    items.sort(key=lambda x: x['start'])
    return jsonify({'success': True, 'today': today.isoformat(), 'from': start.isoformat(), 'to': end.isoformat(),
                    'items': items, 'marks': marks, 'learners': learners,
                    'kinds': {k: {'label': v[0], 'color': v[1]} for k, v in SCHED_KINDS.items()},
                    'subjects': TUTOR_SUBJECTS, 'mark_colors': MARK_COLORS})


def _learner_schedule(conn, me, today, start, end, lo, hi):
    """A learner's schedule: their own events, lessons with teachers their parent
    hired, live classes they asked to be reminded about, and marked days."""
    _sched_tables(conn)
    items = _own_events(conn, me, start, end)
    try:
        wanted = my_live_reminder_ids(conn, me)
        if wanted:
            for r in conn.execute(f"""SELECT lc.id, lc.title, lc.subject, lc.grade, lc.description, lc.start_time, lc.duration_min,
                                      COALESCE(lc.state, 'scheduled') AS state, u.firstname, u.lastname
                                      FROM live_classes lc LEFT JOIN users u ON u.id = lc.teacher_id
                                      WHERE lc.id IN ({','.join('?' * len(wanted))})""", list(wanted)).fetchall():
                st = _parse_any(r['start_time'])
                if st and lo <= _iso(st) < hi:
                    items.append({'type': 'live', 'id': r['id'], 'title': r['title'], 'subject': r['subject'] or '', 'grade': r['grade'] or '',
                                  'start': _iso(st), 'minutes': r['duration_min'] or 60, 'day': _td_day(_iso(st)),
                                  'link': f"/live/watch/{r['id']}", 'location': 'Eschool Live', 'notes': r['description'] or '',
                                  'teacher': _full_name(r['firstname'], r['lastname'], 'Teacher'),
                                  'color': '#e11d48', 'kind_label': 'Live class',
                                  'status': 'completed' if r['state'] == 'ended' else ''})
    except sqlite3.OperationalError:
        pass
    try:
        _tutor_tables(conn)
        for r in _lesson_rows(conn, "t.student_id = ? AND s.status != 'cancelled'", (me,)):
            st = _parse_any(r['starts_at'])
            if not st or not (lo <= _iso(st) < hi):
                continue
            j = _lesson_json(r, 'student')
            items.append({'type': 'lesson', 'id': r['id'], 'title': f"{r['subject']} lesson", 'subject': r['subject'] or '',
                          'teacher': j['teacher'], 'start': _iso(st), 'minutes': r['minutes'] or 60, 'day': _td_day(_iso(st)),
                          'link': '', 'location': 'In person' if r['mode'] == 'in-person' else 'Online: an Eschool call',
                          'notes': (f"Topic: {r['topic']}" if r['topic'] else ''), 'homework': j['homework'],
                          'status': r['status'], 'outcome': j['outcome'], 'outcome_text': j['outcome_text'],
                          'evidence': j['evidence'], 'color': '#10b981', 'kind_label': 'Lesson with a teacher'})
    except sqlite3.OperationalError:
        pass
    try:
        items += _shared_events(conn, ('student', me), start, end)
    except sqlite3.OperationalError:
        pass
    marks = _marks_between(conn, me, start, end)
    # goals: planned study sessions and the day each goal ends
    try:
        _goals_table(conn)
        for g in conn.execute("""SELECT * FROM child_goals WHERE student_id = ? AND parent_id = student_id
                                 AND status IN ('active', 'achieved', 'missed')""", (me,)).fetchall():
            title = _goal_title(g['type'], g['target'], g['course'])
            due = _d(g['due_day'])
            if due and start <= due <= end:
                marks.append({'id': f"goal-{g['id']}", 'goal_id': g['id'], 'day': g['due_day'], 'label': f"Goal ends: {title}",
                              'color': '#8b5cf6', 'yearly': False, 'goal': True})
            days = _jlist_ints(g['study_days'])
            if g['status'] != 'active' or not days or not g['study_time']:
                continue
            hh, mm = (g['study_time'] or '17:00').split(':')[:2]
            day = max(_d(g['start_day']) or start, start)
            while due and day <= min(due, end):
                if day.weekday() in days:
                    local = datetime(day.year, day.month, day.day, int(hh), int(mm))
                    items.append({'type': 'goal', 'id': g['id'], 'title': f"Goal: {title}", 'start': _iso(local - timedelta(hours=3)),
                                  'minutes': g['study_minutes'] or 45, 'day': day.isoformat(), 'link': '', 'location': '',
                                  'notes': g['why'] or '', 'status': '', 'color': '#8b5cf6', 'kind_label': 'Goal study time',
                                  'plan_id': g['plan_id'], 'priority': g['priority'] or 'medium'})
                day += timedelta(days=1)
    except sqlite3.OperationalError:
        pass
    items.sort(key=lambda x: x['start'])
    plans = [dict(r) for r in conn.execute('SELECT id, name, color FROM study_plans WHERE user_id = ? ORDER BY id', (me,)).fetchall()]
    return jsonify({'success': True, 'today': today.isoformat(), 'from': start.isoformat(), 'to': end.isoformat(),
                    'items': items, 'marks': marks, 'plans': plans, 'plan_colors': PLAN_COLORS,
                    'kinds': {k: {'label': SCHED_KINDS[k][0], 'color': SCHED_KINDS[k][1]} for k in LEARNER_SCHED_KINDS},
                    'subjects': TUTOR_SUBJECTS, 'mark_colors': MARK_COLORS})


@app.route('/api/teacher/events', methods=['POST'])
def api_teacher_event_create():
    guard = _sched_guard()
    if guard:
        return guard
    v, err = _clean_event(request.get_json(silent=True) or {})
    if not err and _d(v['day']) < _d(_nairobi_today()):
        err['day'] = "You can't add an event on a day that has passed."
    if err:
        return jsonify({'success': False, 'message': next(iter(err.values())), 'errors': err}), 400
    conn = _links_db()
    try:
        _sched_tables(conn)
        now = _iso(_utc_now())
        cur = conn.execute("""INSERT INTO teacher_events (teacher_id, title, kind, subject, grade, day, start_time, minutes, location,
                              link, notes, repeat, repeat_until, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                           (session['user_id'], v['title'], v['kind'], v['subject'], v['grade'], v['day'], v['start_time'], v['minutes'],
                            v['location'], v['link'], v['notes'], v['repeat'], v['repeat_until'], now, now))
        _set_event_plan(conn, cur.lastrowid, request.get_json(silent=True) or {})
        shared = []
        if session.get('role') == 'teacher':
            _share_tables(conn)
            shared = _clean_share(conn, session['user_id'], (request.get_json(silent=True) or {}).get('share_with')) or []
            _save_shares(conn, cur.lastrowid, shared)
            _notify_event(conn, conn.execute('SELECT * FROM teacher_events WHERE id = ?', (cur.lastrowid,)).fetchone(), shared, 'new')
        conn.commit()
        return jsonify({'success': True, 'id': cur.lastrowid, 'shared': len(shared)})
    finally:
        conn.close()


@app.route('/api/teacher/events/<int:eid>', methods=['PATCH', 'DELETE'])
def api_teacher_event_change(eid):
    guard = _sched_guard()
    if guard:
        return guard
    conn = _links_db()
    try:
        _sched_tables(conn)
        row = conn.execute('SELECT * FROM teacher_events WHERE id = ? AND teacher_id = ?', (eid, session['user_id'])).fetchone()
        if not row:
            return jsonify({'success': False, 'message': 'Event not found.'}), 404
        _share_tables(conn)
        old_shared = _event_shares(conn, [eid]).get(eid, [])
        if request.method == 'DELETE':
            day = str(request.args.get('day') or '')[:10]
            if request.args.get('scope') == 'one' and (row['repeat'] or 'none') != 'none' and _d(day):
                conn.execute('INSERT OR REPLACE INTO teacher_event_days (event_id, day, status, at) VALUES (?, ?, ?, ?)',
                             (eid, day, 'skipped', _iso(_utc_now())))
                msg = 'Removed from that day. The other days stay.'
                if _d(day) >= _d(_nairobi_today()):
                    _notify_event(conn, row, old_shared, 'cancelled', day=day)
            else:
                conn.execute('DELETE FROM teacher_event_days WHERE event_id = ?', (eid,))
                conn.execute('DELETE FROM teacher_event_shares WHERE event_id = ?', (eid,))
                conn.execute('DELETE FROM teacher_events WHERE id = ?', (eid,))
                msg = 'Event deleted.'
                last = _d(row['repeat_until']) if (row['repeat'] or 'none') != 'none' else _d(row['day'])
                if last and last >= _d(_nairobi_today()):
                    _notify_event(conn, row, old_shared, 'cancelled')
            if old_shared:
                msg += ' The learners and their parents have been told.'
            conn.commit()
            return jsonify({'success': True, 'message': msg})
        v, err = _clean_event(request.get_json(silent=True) or {}, old=row)
        if err:
            return jsonify({'success': False, 'message': next(iter(err.values())), 'errors': err}), 400
        conn.execute("""UPDATE teacher_events SET title=?, kind=?, subject=?, grade=?, day=?, start_time=?, minutes=?, location=?, link=?,
                        notes=?, repeat=?, repeat_until=?, updated_at=? WHERE id = ?""",
                     (v['title'], v['kind'], v['subject'], v['grade'], v['day'], v['start_time'], v['minutes'], v['location'], v['link'],
                      v['notes'], v['repeat'], v['repeat_until'], _iso(_utc_now()), eid))
        _set_event_plan(conn, eid, request.get_json(silent=True) or {})
        new = conn.execute('SELECT * FROM teacher_events WHERE id = ?', (eid,)).fetchone()
        if session.get('role') == 'teacher':
            picked = _clean_share(conn, session['user_id'], (request.get_json(silent=True) or {}).get('share_with'))
            shared = old_shared if picked is None else picked
            # learners who were shared before but no longer teach with this teacher keep seeing it until removed here
            if picked is not None:
                _save_shares(conn, eid, shared)
            moved = any(str(row[k] or '') != str(new[k] or '') for k in ('title', 'day', 'start_time', 'minutes', 'location', 'link', 'repeat', 'repeat_until'))
            _notify_event(conn, new, [x for x in shared if x not in old_shared], 'new')
            _notify_event(conn, row, [x for x in old_shared if x not in shared], 'removed')
            if moved:
                _notify_event(conn, new, [x for x in shared if x in old_shared], 'changed')
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/teacher/events/<int:eid>/status', methods=['POST'])
def api_teacher_event_status(eid):
    """Mark one day of an event done or missed ('' clears it)."""
    guard = _sched_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    day, status = str(d.get('day') or '')[:10], d.get('status') or ''
    if not _d(day) or status not in ('done', 'missed', ''):
        return jsonify({'success': False, 'message': 'Choose done or missed.'}), 400
    conn = _links_db()
    try:
        _sched_tables(conn)
        row = conn.execute('SELECT * FROM teacher_events WHERE id = ? AND teacher_id = ?', (eid, session['user_id'])).fetchone()
        if not row or _d(day) not in _event_days(row, _d(day), _d(day)):
            return jsonify({'success': False, 'message': 'That event isn’t on this day.'}), 404
        if status:
            conn.execute('INSERT OR REPLACE INTO teacher_event_days (event_id, day, status, at) VALUES (?, ?, ?, ?)',
                         (eid, day, status, _iso(_utc_now())))
        else:
            conn.execute("DELETE FROM teacher_event_days WHERE event_id = ? AND day = ? AND status != 'skipped'", (eid, day))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/teacher/marks', methods=['POST'])
def api_teacher_mark_create():
    guard = _sched_guard()
