        _sched_tables(conn)
        cur = conn.execute('INSERT INTO teacher_day_marks (teacher_id, day, label, color, yearly, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                           (session['user_id'], day, label, color, 1 if d.get('yearly') else 0, _iso(_utc_now())))
