@app.route('/api/teacher/schedule/import', methods=['POST'])
def api_teacher_schedule_import():
    """Moves events and marked days the old schedule page kept in the browser into the account."""
    guard = _sched_guard()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    kind_of = {'lecture': 'class', 'lab': 'practical', 'assignment': 'deadline', 'exam': 'exam', 'break': 'personal'}
    ev_n = mk_n = 0
    conn = _links_db()
    try:
        _sched_tables(conn)
        now = _iso(_utc_now())
        for e in (d.get('events') or [])[:500]:
            try:
                day = datetime(int(e['year']), int(e['month']) + 1, int(e['day'])).date().isoformat()
                tm = str(e.get('time') or '08:00').split('-')[0].strip()[:5]
                minutes = max(5, min(720, int(e.get('duration') or 60)))
            except (KeyError, TypeError, ValueError):
                continue
            title = str(e.get('title') or '').strip()[:120]
            if not title or not re.fullmatch(r'([01]\d|2[0-3]):[0-5]\d', tm):
                continue
            loc = str(e.get('location') or '').strip()
            if conn.execute('SELECT 1 FROM teacher_events WHERE teacher_id = ? AND title = ? AND day = ? AND start_time = ?',
                            (session['user_id'], title, day, tm)).fetchone():
                continue                    # already moved (e.g. the page was open in two tabs)
            cur = conn.execute("""INSERT INTO teacher_events (teacher_id, title, kind, day, start_time, minutes, location, notes,
                                  repeat, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                               (session['user_id'], title, kind_of.get(e.get('type'), 'class'), day, tm, minutes,
                                '' if loc == 'Not specified' else loc[:80], str(e.get('description') or '')[:1000], 'none', now, now))
            if e.get('status') == 'completed':
                conn.execute('INSERT OR REPLACE INTO teacher_event_days (event_id, day, status, at) VALUES (?, ?, ?, ?)',
                             (cur.lastrowid, day, 'done', now))
            ev_n += 1
        for m in (d.get('marks') or [])[:200]:
            if not _d(m.get('date')) or not str(m.get('label') or '').strip():
                continue
            if conn.execute('SELECT 1 FROM teacher_day_marks WHERE teacher_id = ? AND day = ? AND label = ?',
                            (session['user_id'], str(m['date'])[:10], str(m['label']).strip()[:60])).fetchone():
                continue
            conn.execute('INSERT INTO teacher_day_marks (teacher_id, day, label, color, yearly, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                         (session['user_id'], str(m['date'])[:10], str(m['label']).strip()[:60],
                          m.get('color') if m.get('color') in MARK_COLORS else MARK_COLORS[0], 1 if m.get('yearly') else 0, now))
            mk_n += 1
        conn.commit()
    finally:
        conn.close()
    return jsonify({'success': True, 'events': ev_n, 'marks': mk_n})


@app.route('/api/teacher/dashboard')
def api_teacher_dashboard():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    me = session['user_id']
    conn = _links_db()
    try:
        _tutor_tables(conn)
        _td_todos_table(conn)
        now = _utc_now()
        today = _nairobi_today()
        days30 = _td_days(30)
        week0, week1 = _td_since(6), _td_since(13)          # this 7 days / the 7 before
        month0 = _td_since(29)

        # ---------- money: teachers earn only from lessons families pay for ----------
        week_days, prev_week_days = set(days30[-7:]), set(days30[-14:-7])
        month_start = _month_start()
        pays = [dict(r) for r in conn.execute('''SELECT p.amount, p.sessions, p.status, p.created_at, p.decided_at, p.parent_id,
                                                  t.student_id, t.subject, u.firstname, u.lastname
                                           FROM tutoring_payments p JOIN tutoring t ON t.id = p.tutoring_id
                                           LEFT JOIN users u ON u.id = t.student_id
                                           WHERE t.teacher_id = ? AND p.status NOT IN ('started', 'failed') ORDER BY p.id DESC''', (me,)).fetchall()]
        for x in pays:
            x['day'] = _td_day(x['decided_at'] or x['created_at'])
        confirmed = [x for x in pays if x['status'] == 'confirmed']

        def per_day(rows, value=lambda r: 1):
            out = {d: 0 for d in days30}
            for r in rows:
                if r.get('day') in out:
                    out[r['day']] += value(r)
            return [out[d] for d in days30]

        def week_sum(rows, days, value=lambda r: 1):
            return sum(value(r) for r in rows if r.get('day') in days)

        # ---------- ratings ----------
        rat = conn.execute('''SELECT tr.stars, tr.comment, tr.created_at AS at, u.id AS uid, u.firstname, u.lastname, u.avatar_filename
                              FROM teacher_ratings tr LEFT JOIN users u ON u.id = tr.reviewer_id
                              WHERE tr.teacher_id = ? ORDER BY tr.created_at DESC''', (me,)).fetchall()
        dist = {s: 0 for s in range(1, 6)}
        for r in rat:
            dist[r['stars']] = dist.get(r['stars'], 0) + 1
        one_rating = _rating_summary(conn, [me])[me]
        ratings = {
            'count': one_rating['count'], 'avg': one_rating['avg'], 'sources': one_rating['sources'],
            'dist': one_rating['dist'],                            # 5 stars first, every kind of rating
            'new7': sum(1 for r in rat if (r['at'] or '') >= week0),
            'latest': [{'stars': r['stars'], 'comment': r['comment'] or '', 'at': to_iso_utc(r['at']),
                        'name': _full_name(r['firstname'], r['lastname'], 'Someone'),
                        'avatar_url': get_avatar_url(r['uid'], r['avatar_filename']) if r['uid'] else None} for r in rat[:4]],
        }

        # ---------- the Eschool teacher score (see _teacher_score) ----------
        try:
            card = (_teacher_cards(conn, [me]) or [{}])[0]
            my_score = {k: card.get(k) for k in ('score', 'score_parts', 'score_reasons', 'experience_label', 'experience_years')}
        except sqlite3.Error:
            my_score = None

        # ---------- live classes ----------
        live = []
        for r in conn.execute("SELECT id, title, subject, grade, start_time, duration_min, platform, COALESCE(state, 'scheduled') AS state, "
                              "'/teacher-live/studio/' || id AS stream_url "
                              'FROM live_classes WHERE teacher_id = ?', (me,)).fetchall():
            st = _parse_any(r['start_time'])
            if not st:
                continue
            reminders = conn.execute('SELECT COUNT(*) FROM live_reminders WHERE class_id = ?', (r['id'],)).fetchone()[0] \
                if conn.execute("SELECT 1 FROM sqlite_master WHERE name = 'live_reminders'").fetchone() else 0
            live.append({'type': 'live', 'id': r['id'], 'title': r['title'], 'subject': r['subject'], 'grade': r['grade'],
                         'start': _iso(st), 'minutes': r['duration_min'] or 60, 'platform': r['platform'] or '',
                         'link': r['stream_url'], 'reminders': reminders, 'day': _td_day(_iso(st)),
                         'status': 'completed' if r['state'] == 'ended' else 'live' if r['state'] == 'live' else 'scheduled'})

        # ---------- private teaching ----------
        tut = [_tutoring_json(conn, r, with_detail=False) for r in conn.execute(
            TUTORING_SELECT + ' WHERE t.teacher_id = ? ORDER BY t.id DESC', (me,)).fetchall()]
        lessons = []
        for r in conn.execute('''SELECT s.*, t.subject, su.firstname, su.lastname FROM tutoring_sessions s
                                 JOIN tutoring t ON t.id = s.tutoring_id LEFT JOIN users su ON su.id = t.student_id
                                 WHERE t.teacher_id = ?''', (me,)).fetchall():
            st = _parse_any(r['starts_at'])
            if not st:
                continue
            lessons.append({'type': 'lesson', 'id': r['id'], 'tutoring_id': r['tutoring_id'], 'title': f"{r['subject']} lesson",
                            'subject': r['subject'], 'student': _full_name(r['firstname'], r['lastname'], 'Learner'),
                            'start': _iso(st), 'minutes': r['minutes'] or 60, 'link': r['link'] or '', 'topic': r['topic'] or '',
                            'status': r['status'], 'day': _td_day(_iso(st))})
        paid = conn.execute('''SELECT COALESCE(SUM(p.amount), 0) FROM tutoring_payments p JOIN tutoring t ON t.id = p.tutoring_id
                               WHERE t.teacher_id = ? AND p.status = 'confirmed' AND substr(COALESCE(p.decided_at, p.created_at), 1, 10) >= ?''',
                            (me, month_start)).fetchone()[0]
        done_month = sum(1 for l in lessons if l['status'] == 'completed' and (l['day'] or '') >= month_start)
        rated = [r[0] for r in conn.execute('''SELECT s.parent_rating FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                                              WHERE t.teacher_id = ? AND s.parent_rating IS NOT NULL''', (me,)).fetchall()]
        tutoring = {
            'pending': [t for t in tut if t['status'] == 'pending'],
            'active': sum(1 for t in tut if t['status'] in ('accepted', 'active')),
            'awaiting_payment': sum(1 for t in tut if t['status'] == 'accepted'),
            'students': len({t['child']['id'] for t in tut if t['status'] in ('accepted', 'active')}),
            'lessons_month': done_month,
            'earned_month': paid or 0,
            'lesson_rating': round(sum(rated) / len(rated), 1) if rated else None,
            'to_book': sum(t['sessions_left'] for t in tut if t['status'] == 'active'),
            'engagements': [t for t in tut if t['status'] in ('accepted', 'active')],
        }
        try:
            prof = conn.execute('SELECT accepting, rate FROM tutor_profiles WHERE teacher_id = ?', (me,)).fetchone()
            tutoring['profile'] = {'exists': bool(prof), 'accepting': bool(prof['accepting']) if prof else False,
                                   'rate': prof['rate'] if prof else None}
        except sqlite3.OperationalError:
            tutoring['profile'] = {'exists': False, 'accepting': False, 'rate': None}

        # ---------- schedule: everything from 30 days back to 60 days ahead ----------
        horizon = now + timedelta(days=60)
        try:
            today_d = _d(today)
            own_events = _own_events(conn, me, today_d - timedelta(days=31), today_d + timedelta(days=60))
        except sqlite3.Error:
            own_events = []
        schedule = sorted([x for x in live + lessons + own_events
                           if x.get('status', 'scheduled') != 'cancelled'
                           and now - timedelta(days=31) <= _parse_any(x['start']) <= horizon], key=lambda x: x['start'])
        upcoming = [x for x in schedule if _parse_any(x['start']) + timedelta(minutes=x['minutes']) >= now][:8]
        todays = [x for x in schedule if x['day'] == today]

        # ---------- messages ----------
        unread = conn.execute('SELECT COUNT(*) FROM messages WHERE receiver_id = ? AND is_read = 0', (me,)).fetchone()[0]
        unread_from = conn.execute('''SELECT COUNT(DISTINCT sender_id) FROM messages WHERE receiver_id = ? AND is_read = 0''', (me,)).fetchone()[0]

        # ---------- activity feed ----------
        feed = []
        for r in rat[:10]:
            feed.append({'icon': 'fa-star', 'color': '#f59e0b', 'at': r['at'],
                         'text': f"{_full_name(r['firstname'], r['lastname'], 'Someone')} rated you {r['stars']} out of 5"})
        for t in tut[:10]:
            who = f"{t['child']['name']} asked you" if t['self_paid'] else f"{t['parent']['name']} asked you to teach {t['child']['name']}"
            feed.append({'icon': 'fa-chalkboard-user', 'color': '#10b981', 'at': t['created_at'], 'text': f"{who} for {t['subject']} lessons"})
        for x in confirmed[:10]:
            payer = 'paid' if x['parent_id'] == x['student_id'] else "'s parent paid"
            feed.append({'icon': 'fa-coins', 'color': '#16a34a', 'at': x['decided_at'] or x['created_at'],
                         'text': f"{_full_name(x['firstname'], x['lastname'], 'A learner')}{' ' if payer == 'paid' else ''}{payer} for "
                                 f"{x['sessions']} {x['subject']} lesson{'s' if x['sessions'] != 1 else ''}: {_money(int(x['amount'] or 0))}"})
        for l in sorted([l for l in lessons if l['status'] == 'completed'], key=lambda l: l['start'], reverse=True)[:10]:
            feed.append({'icon': 'fa-circle-check', 'color': '#0ea5e9', 'at': l['start'],
                         'text': f"You taught {l['student']} {l['subject']} (proved by the Eschool call)"})
        for f in feed:
            f['at'] = _iso(_parse_any(f['at'])) if _parse_any(f['at']) else None
        feed = sorted([f for f in feed if f['at']], key=lambda f: f['at'], reverse=True)[:12]

        # ---------- needs your attention ----------
        attention = []
        for t in tutoring['pending'][:5]:
            attention.append({'kind': 'request', 'icon': 'fa-chalkboard-user', 'color': '#10b981', 'id': t['id'],
                              'title': f"Private teaching request: {t['subject']}",
                              'text': (f"{t['child']['name']} (paying for their own lessons)" if t['self_paid'] else f"{t['parent']['name']} for {t['child']['name']}")
                                      + f" · {t['sessions_per_week']} a week · {t['mode_label']}"})
        if unread:
            attention.append({'kind': 'link', 'icon': 'fa-envelope', 'color': '#4361ee', 'href': '/teacher-messages',
                              'title': f"{unread} unread message{'s' if unread != 1 else ''}",
                              'text': f"From {unread_from} {'person' if unread_from == 1 else 'people'}", 'action': 'Open messages'})
        for x in upcoming:
            st = _parse_any(x['start'])
            if x['type'] == 'live' and now <= st <= now + timedelta(hours=24):
                attention.append({'kind': 'link', 'icon': 'fa-video', 'color': '#ef4444', 'href': x['link'] or '/teacher-live',
                                  'external': False, 'title': f"Live class soon: {x['title']}", 'start': x['start'],
                                  'text': f"{x['reminders']} learner{'s' if x['reminders'] != 1 else ''} set a reminder", 'action': 'Open the class link'})
        # finished lessons in the last 14 days with no notes yet. Whether a lesson was taught is proved by the
        # Eschool call, so the teacher only writes what was covered and the homework.
        noted = {r[0] for r in conn.execute('''SELECT s.id FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                                              WHERE t.teacher_id = ? AND LENGTH(TRIM(COALESCE(s.teacher_notes, ''))) > 0 ''', (me,)).fetchall()}
        stale = [l for l in lessons if l['status'] in ('scheduled', 'completed', 'review') and l['id'] not in noted
                 and now - timedelta(days=14) < _parse_any(l['start']) + timedelta(minutes=l['minutes']) < now]
        for l in stale:
            l['outcome_label'] = {'scheduled': 'Eschool is checking the call', 'completed': 'Taught (proved by the Eschool call)',
                                  'review': 'Being checked by Eschool', 'missed': 'Not taught'}[l['status']]
        tutoring['to_record'] = sorted(stale, key=lambda l: l['start'])
        if stale:
            attention.append({'kind': 'link', 'icon': 'fa-clipboard-check', 'color': '#f59e0b', 'href': '#teaching',
                              'title': f"Add notes to {len(stale)} finished lesson{'s' if len(stale) != 1 else ''}",
                              'text': 'Write what you covered and the homework. The learner and the family can read it.', 'action': 'Add lesson notes'})
        if tutoring['to_book']:
            attention.append({'kind': 'link', 'icon': 'fa-calendar-plus', 'color': '#06b6d4', 'href': '#teaching',
                              'title': f"{tutoring['to_book']} paid lesson{'s' if tutoring['to_book'] != 1 else ''} to book",
                              'text': 'These lessons are paid for. Choose the dates and times so you can teach and get paid.', 'action': 'Book lessons'})

        # ---------- headline numbers with trends ----------
        try:
            _refunds_table(conn)
            refunded = conn.execute('SELECT COALESCE(SUM(amount), 0) FROM tutoring_refunds WHERE teacher_id = ?', (me,)).fetchone()[0] or 0
        except sqlite3.Error:
            refunded = 0
        lessons_done = [dict(l, day=l['day']) for l in lessons if l['status'] == 'completed']
        pending_amount = sum(int(x['amount'] or 0) for x in pays if x['status'] == 'pending')
        kpis = {
            'earned': {'month': paid or 0, 'this': week_sum(confirmed, week_days, lambda r: int(r['amount'] or 0)),
                       'last': week_sum(confirmed, prev_week_days, lambda r: int(r['amount'] or 0)),
                       'total': sum(int(x['amount'] or 0) for x in confirmed) - refunded},
            'lessons': {'this': week_sum(lessons_done, week_days), 'last': week_sum(lessons_done, prev_week_days), 'month': done_month},
            'learners': {'value': sum(1 for t in tut if t['status'] == 'active'), 'awaiting_payment': tutoring['awaiting_payment'],
                         'requests': len(tutoring['pending'])},
            'to_book': {'value': tutoring['to_book'], 'booked': sum(t['sessions_booked'] for t in tut if t['status'] == 'active')},
            'pending': {'value': pending_amount, 'count': sum(1 for x in pays if x['status'] == 'pending')},
            'rating': {'value': ratings['avg'], 'count': ratings['count'], 'new7': ratings['new7']},
            'unread': {'value': unread, 'people': unread_from},
            'live_upcoming': sum(1 for x in upcoming if x['type'] == 'live'),
        }

        todos = [dict(id=r['id'], text=r['text'], due=r['due'], done=bool(r['done']))
                 for r in conn.execute('SELECT * FROM teacher_todos WHERE teacher_id = ? ORDER BY done, COALESCE(due, "9999"), id DESC', (me,)).fetchall()]
        # earnings for the last 6 months (the dashboard's small bar chart)
        y0, m0 = int(today[:4]), int(today[5:7])
        month_keys = []
        for k in range(5, -1, -1):
            yy, mm = y0, m0 - k
            while mm < 1:
                yy, mm = yy - 1, mm + 12
            month_keys.append(f'{yy:04d}-{mm:02d}')
        by_month = {k: 0 for k in month_keys}
        for x in confirmed:
            if (x.get('day') or '')[:7] in by_month:
                by_month[x['day'][:7]] += float(x['amount'] or 0)
        months = [{'month': k, 'amount': round(by_month[k], 2)} for k in month_keys]
        return jsonify({
            'success': True, 'today': today, 'kpis': kpis, 'months': months,
            'chart': {'days': days30, 'earnings': per_day(confirmed, lambda r: int(r['amount'] or 0)),
                      'lessons': per_day(lessons_done),
                      'requests': per_day([{'day': _td_day(t['created_at'])} for t in tut])},
            'ratings': ratings, 'score': my_score,
            'tutoring': tutoring, 'schedule': schedule, 'upcoming': upcoming, 'todays': todays,
            'feed': feed, 'attention': attention, 'todos': todos,
        })
    finally:
        conn.close()


@app.route('/api/teacher/todos', methods=['GET', 'POST'])
def api_teacher_todos():
    """GET your to-do list. POST {"text": "...", "due": "YYYY-MM-DD"} adds one."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    me = session['user_id']
    conn = _links_db()
    try:
        _td_todos_table(conn)
        if request.method == 'POST':
            d = request.get_json(silent=True) or {}
            text = ' '.join(str(d.get('text') or '').split())[:160]
            if not text:
                return jsonify({'success': False, 'message': 'Write the task first.'}), 400
            due = str(d.get('due') or '')[:10] or None
            if due and not re.match(r'^\d{4}-\d{2}-\d{2}$', due):
                return jsonify({'success': False, 'message': 'Pick a valid date.'}), 400
            if conn.execute('SELECT COUNT(*) FROM teacher_todos WHERE teacher_id = ?', (me,)).fetchone()[0] >= 200:
                return jsonify({'success': False, 'message': 'Your list is full. Clear some finished tasks first.'}), 400
            conn.execute('INSERT INTO teacher_todos (teacher_id, text, due, created_at) VALUES (?, ?, ?, ?)', (me, text, due, _iso(_utc_now())))
            conn.commit()
        rows = conn.execute('SELECT * FROM teacher_todos WHERE teacher_id = ? ORDER BY done, COALESCE(due, "9999"), id DESC', (me,)).fetchall()
        return jsonify({'success': True, 'todos': [dict(id=r['id'], text=r['text'], due=r['due'], done=bool(r['done'])) for r in rows]})
    finally:
        conn.close()


@app.route('/api/teacher/todos/<int:tid>', methods=['PATCH', 'DELETE'])
def api_teacher_todo(tid):
    """PATCH {"done": true} ticks it; DELETE removes it. /api/teacher/todos/0 with DELETE clears all finished."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    if session.get('role') != 'teacher':
        return jsonify({'success': False, 'message': 'Teachers only'}), 403
    me = session['user_id']
    conn = _links_db()
    try:
        _td_todos_table(conn)
        if request.method == 'DELETE':
            if tid == 0:
                conn.execute('DELETE FROM teacher_todos WHERE teacher_id = ? AND done = 1', (me,))
            else:
                conn.execute('DELETE FROM teacher_todos WHERE id = ? AND teacher_id = ?', (tid, me))
        else:
            d = request.get_json(silent=True) or {}
            if isinstance(d.get('done'), bool):
                conn.execute('UPDATE teacher_todos SET done = ?, done_at = ? WHERE id = ? AND teacher_id = ?',
                             (int(d['done']), _iso(_utc_now()) if d['done'] else None, tid, me))
        conn.commit()
        rows = conn.execute('SELECT * FROM teacher_todos WHERE teacher_id = ? ORDER BY done, COALESCE(due, "9999"), id DESC', (me,)).fetchall()
        return jsonify({'success': True, 'todos': [dict(id=r['id'], text=r['text'], due=r['due'], done=bool(r['done'])) for r in rows]})
    finally:
        conn.close()


# ============ GROUP CALLS (voice & video with up to 8 people) ============
# Every browser connects straight to every other one (a "mesh"), so the sound
# and video never pass through the server; the server only passes the
# connection details between the right pair of people.
#   group_calls          - one row per call: host, voice/video, title, status
#   group_call_members   - who was invited and what they did (invited, joined, left, declined, missed)
#   group_call_signals   - offers / answers / network routes from one person to another
# Rules:
#   - The host invites people they are allowed to message (same rule as 1-to-1 calls).
#   - Whoever joins sends an offer to everyone already in the call, so two
#     people never both start the same connection.
#   - Each browser checks in every couple of seconds; anyone silent for 25 s
#     is treated as gone. The call ends when the last person leaves.
#   - People who never joined get a "Missed group call" notice in the bell.
GROUP_CALL_MAX = 8                 # people in one call, including the host
GROUP_CALL_RING_SECONDS = 45
GROUP_CALL_STALE_SECONDS = 25


def _gc_tables(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS group_calls (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        host_id INTEGER NOT NULL,
        kind TEXT NOT NULL DEFAULT 'audio',
        title TEXT,
        status TEXT NOT NULL DEFAULT 'active',
        created_at TEXT NOT NULL,
        ended_at TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS group_call_members (
        call_id INTEGER NOT NULL,
        user_id INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'invited',
        invited_by INTEGER,
        invited_at TEXT NOT NULL,
        joined_at TEXT,
        left_at TEXT,
        last_seen TEXT,
        muted INTEGER NOT NULL DEFAULT 0,
        cam_off INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (call_id, user_id)
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS group_call_signals (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        call_id INTEGER NOT NULL,
        from_id INTEGER NOT NULL,
        to_id INTEGER NOT NULL,
        type TEXT NOT NULL,
        data TEXT NOT NULL
    )""")
    conn.execute('CREATE INDEX IF NOT EXISTS idx_gcs_to ON group_call_signals (call_id, to_id, id)')


def _gc_conn():
    conn = sqlite3.connect('users.db', timeout=10)
    conn.row_factory = sqlite3.Row
    _gc_tables(conn)
    _calls_tables(conn)
    _gc_tidy(conn)
    return conn


def _gc_ago(seconds):
    return (datetime.utcnow() - timedelta(seconds=seconds)).strftime('%Y-%m-%d %H:%M:%S')


def _gc_tidy(conn):
    """Silent members count as left; unanswered invites become missed; empty calls end."""
    now = _now_iso()
    changed = conn.execute("""UPDATE group_call_members SET status = 'left', left_at = ?
                              WHERE status = 'joined' AND last_seen < ?""", (now, _gc_ago(GROUP_CALL_STALE_SECONDS))).rowcount
    for c in conn.execute("""SELECT id FROM group_calls WHERE status = 'active' AND created_at < ? AND NOT EXISTS (
                               SELECT 1 FROM group_call_members m WHERE m.call_id = group_calls.id AND m.status = 'joined')""",
                          (_gc_ago(10),)).fetchall():
        conn.execute("UPDATE group_calls SET status = 'ended', ended_at = ? WHERE id = ?", (now, c['id']))
        conn.execute('DELETE FROM group_call_signals WHERE call_id = ?', (c['id'],))
        changed += 1
    for r in conn.execute("""SELECT m.call_id, m.user_id, c.host_id, c.kind FROM group_call_members m
                             JOIN group_calls c ON c.id = m.call_id
                             WHERE m.status = 'invited' AND (m.invited_at < ? OR c.status = 'ended')""",
                          (_gc_ago(GROUP_CALL_RING_SECONDS),)).fetchall():
        conn.execute("UPDATE group_call_members SET status = 'missed' WHERE call_id = ? AND user_id = ?", (r['call_id'], r['user_id']))
        host = _person(conn, r['host_id']) or {'name': 'Someone'}
        create_notification(conn, r['user_id'], f"Missed group {'video' if r['kind'] == 'video' else 'voice'} call",
                            f"{host['name']} called you in a group call. Open Messages to call back.",
                            icon='fa-phone-slash', color='red', category='messages')
        changed += 1
    if changed:
        conn.commit()


def _gc_busy(conn, uid, except_call=None):
    """True if this person is already on a 1-to-1 call or in another group call."""
    if conn.execute("""SELECT 1 FROM calls WHERE status IN ('ringing', 'accepted') AND (caller_id = ? OR callee_id = ?) LIMIT 1""",
                    (uid, uid)).fetchone():
        return True
    return conn.execute("""SELECT 1 FROM group_call_members m JOIN group_calls c ON c.id = m.call_id
                           WHERE m.user_id = ? AND m.status = 'joined' AND c.status = 'active' AND c.id != ? LIMIT 1""",
                        (uid, except_call or 0)).fetchone() is not None


def _gc_member(conn, call_id, uid):
    return conn.execute('SELECT * FROM group_call_members WHERE call_id = ? AND user_id = ?', (call_id, uid)).fetchone()


def _gc_invite(conn, call_id, inviter, ids):
    """Adds people to a call. Returns (invited_people, problems)."""
    invited, problems = [], []
    count = conn.execute("SELECT COUNT(*) FROM group_call_members WHERE call_id = ? AND status IN ('invited', 'joined')",
                         (call_id,)).fetchone()[0]
    now = _now_iso()
    for uid in ids:
        p = _person(conn, uid)
        if not p or uid == inviter:
            continue
        if count >= GROUP_CALL_MAX:
            problems.append(f'{p["name"]}: the call is full ({GROUP_CALL_MAX} people).')
            continue
        allowed, reason = can_message(conn, inviter, session.get('role'), uid, kind='call')
        if not allowed:
            problems.append(f'{p["name"]}: {reason or "you can’t call this person."}')
            continue
        row = _gc_member(conn, call_id, uid)
        if row and row['status'] in ('invited', 'joined'):
            continue
        if row:
            conn.execute("""UPDATE group_call_members SET status = 'invited', invited_by = ?, invited_at = ?, left_at = NULL
                            WHERE call_id = ? AND user_id = ?""", (inviter, now, call_id, uid))
        else:
            conn.execute("""INSERT INTO group_call_members (call_id, user_id, status, invited_by, invited_at)
                            VALUES (?, ?, 'invited', ?, ?)""", (call_id, uid, inviter, now))
        invited.append(p)
        count += 1
    return invited, problems


def _gc_state(conn, call_id, me):
    c = conn.execute('SELECT * FROM group_calls WHERE id = ?', (call_id,)).fetchone()
    members = []
    for m in conn.execute("""SELECT * FROM group_call_members WHERE call_id = ?
                             ORDER BY CASE status WHEN 'joined' THEN 0 WHEN 'invited' THEN 1 ELSE 2 END, joined_at, invited_at""",
                          (call_id,)).fetchall():
        p = _person(conn, m['user_id']) or {'id': m['user_id'], 'name': 'Eschool user', 'avatar': '?', 'avatar_url': None}
        p.update(status=m['status'], muted=bool(m['muted']), cam_off=bool(m['cam_off']), is_me=m['user_id'] == me,
                 is_host=m['user_id'] == c['host_id'], joined_at=to_iso_utc(m['joined_at']) if m['joined_at'] else None)
        members.append(p)
    return {'id': c['id'], 'kind': c['kind'], 'title': c['title'] or '', 'status': c['status'],
            'host': _person(conn, c['host_id']), 'created_at': to_iso_utc(c['created_at']), 'members': members,
            'max': GROUP_CALL_MAX}


def _gc_ids(data):
    raw = data.get('member_ids') if isinstance(data.get('member_ids'), list) else []
    out = []
    for v in raw[:20]:
        try:
            v = int(v)
        except (TypeError, ValueError):
            continue
        if v not in out:
            out.append(v)
    return out


@app.route('/api/group-calls/start', methods=['POST'])
def api_group_call_start():
    """{"member_ids": [..], "kind": "audio"|"video", "title": "optional"} -> you join, the others ring."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    data = request.get_json(silent=True) or {}
    ids = [i for i in _gc_ids(data) if i != me]
    kind = 'video' if data.get('kind') == 'video' else 'audio'
    title = ' '.join(str(data.get('title') or '').split())[:60]
    if len(ids) < 1:
        return jsonify({'success': False, 'message': 'Choose at least one person to call.'}), 400
    if len(ids) > GROUP_CALL_MAX - 1:
        return jsonify({'success': False, 'message': f'A group call can have up to {GROUP_CALL_MAX} people, including you.'}), 400
    conn = _gc_conn()
    try:
        if _gc_busy(conn, me):
            return jsonify({'success': False, 'message': 'You are already on a call. End it first.'}), 409
        now = _now_iso()
        cur = conn.execute("INSERT INTO group_calls (host_id, kind, title, status, created_at) VALUES (?, ?, ?, 'active', ?)",
                           (me, kind, title, now))
        call_id = cur.lastrowid
        conn.execute("""INSERT INTO group_call_members (call_id, user_id, status, invited_at, joined_at, last_seen)
                        VALUES (?, ?, 'joined', ?, ?, ?)""", (call_id, me, now, now, now))
        invited, problems = _gc_invite(conn, call_id, me, ids)
        if not invited:
            conn.rollback()
            return jsonify({'success': False, 'message': problems[0] if problems else 'Nobody could be invited.',
                            'problems': problems}), 403
        conn.commit()
        return jsonify({'success': True, 'call': _gc_state(conn, call_id, me), 'problems': problems})
    finally:
        conn.close()


@app.route('/api/group-calls/incoming', methods=['GET'])
def api_group_call_incoming():
    """The group call ringing for you right now, if any."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    conn = _gc_conn()
    try:
        r = conn.execute("""SELECT c.id FROM group_call_members m JOIN group_calls c ON c.id = m.call_id
                            WHERE m.user_id = ? AND m.status = 'invited' AND c.status = 'active'
                            ORDER BY m.invited_at DESC LIMIT 1""", (me,)).fetchone()
        if not r:
            return jsonify({'success': True, 'call': None})
        st = _gc_state(conn, r['id'], me)
        inviter = conn.execute('SELECT invited_by FROM group_call_members WHERE call_id = ? AND user_id = ?', (r['id'], me)).fetchone()
        st['invited_by'] = _person(conn, inviter['invited_by']) if inviter and inviter['invited_by'] else st['host']
        return jsonify({'success': True, 'call': st})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/join', methods=['POST'])
def api_group_call_join(call_id):
    """Join a call you were invited to. Answers with who is already in it:
    your browser then sends each of them an offer."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    conn = _gc_conn()
    try:
        c = conn.execute('SELECT * FROM group_calls WHERE id = ?', (call_id,)).fetchone()
        m = _gc_member(conn, call_id, me)
        if not c or not m:
            return jsonify({'success': False, 'message': 'That call was not found.'}), 404
        if c['status'] != 'active':
            return jsonify({'success': False, 'message': 'That group call has already ended.'}), 410
        if _gc_busy(conn, me, call_id):
            return jsonify({'success': False, 'message': 'You are already on another call.'}), 409
        joined = conn.execute("SELECT COUNT(*) FROM group_call_members WHERE call_id = ? AND status = 'joined' AND user_id != ?",
                              (call_id, me)).fetchone()[0]
        if joined >= GROUP_CALL_MAX:
            return jsonify({'success': False, 'message': 'This call is full.'}), 409
        now = _now_iso()
        # a fresh start: old connection details addressed to or from me are dropped
        conn.execute('DELETE FROM group_call_signals WHERE call_id = ? AND (to_id = ? OR from_id = ?)', (call_id, me, me))
        conn.execute("""UPDATE group_call_members SET status = 'joined', joined_at = COALESCE(joined_at, ?), last_seen = ?,
                        left_at = NULL, muted = 0, cam_off = 0 WHERE call_id = ? AND user_id = ?""", (now, now, call_id, me))
        conn.commit()
        last = conn.execute('SELECT COALESCE(MAX(id), 0) FROM group_call_signals').fetchone()[0]
        st = _gc_state(conn, call_id, me)
        st['peers'] = [p['id'] for p in st['members'] if p['status'] == 'joined' and not p['is_me']]
        return jsonify({'success': True, 'call': st, 'signal_after': last})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/decline', methods=['POST'])
def api_group_call_decline(call_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    conn = _gc_conn()
    try:
        conn.execute("UPDATE group_call_members SET status = 'declined' WHERE call_id = ? AND user_id = ? AND status = 'invited'",
                     (call_id, session['user_id']))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/leave', methods=['POST'])
def api_group_call_leave(call_id):
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    conn = _gc_conn()
    try:
        conn.execute("""UPDATE group_call_members SET status = 'left', left_at = ? WHERE call_id = ? AND user_id = ?
                        AND status = 'joined'""", (_now_iso(), call_id, me))
        conn.execute('DELETE FROM group_call_signals WHERE call_id = ? AND (to_id = ? OR from_id = ?)', (call_id, me, me))
        if not conn.execute("SELECT 1 FROM group_call_members WHERE call_id = ? AND status = 'joined'", (call_id,)).fetchone():
            conn.execute("UPDATE group_calls SET status = 'ended', ended_at = ? WHERE id = ? AND status = 'active'", (_now_iso(), call_id))
            conn.execute('DELETE FROM group_call_signals WHERE call_id = ?', (call_id,))
        conn.commit()
        _gc_tidy(conn)
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/invite', methods=['POST'])
def api_group_call_invite(call_id):
    """Anyone in the call can add more people: {"member_ids": [..]}."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    conn = _gc_conn()
    try:
        c = conn.execute('SELECT * FROM group_calls WHERE id = ?', (call_id,)).fetchone()
        m = _gc_member(conn, call_id, me)
        if not c or not m or m['status'] != 'joined' or c['status'] != 'active':
            return jsonify({'success': False, 'message': 'Join the call first.'}), 403
        invited, problems = _gc_invite(conn, call_id, me, _gc_ids(request.get_json(silent=True) or {}))
        conn.commit()
        if not invited and problems:
            return jsonify({'success': False, 'message': problems[0], 'problems': problems}), 403
        return jsonify({'success': True, 'invited': invited, 'problems': problems, 'call': _gc_state(conn, call_id, me)})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/state', methods=['GET', 'POST'])
def api_group_call_state(call_id):
    """Polled every ~1.5 s by everyone in the call. Keeps you counted as present,
    and hands you the people in the call plus the connection details sent to you.
    POST {"muted": bool, "cam_off": bool} also shares your mic/camera state."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    try:
        after = max(0, int(request.args.get('after') or 0))
    except ValueError:
        after = 0
    conn = _gc_conn()
    try:
        c = conn.execute('SELECT * FROM group_calls WHERE id = ?', (call_id,)).fetchone()
        m = _gc_member(conn, call_id, me)
        if not c or not m:
            return jsonify({'success': False, 'message': 'That call was not found.'}), 404
        if m['status'] == 'joined':
            sets, vals = ['last_seen = ?'], [_now_iso()]
            if request.method == 'POST':
                d = request.get_json(silent=True) or {}
                for k in ('muted', 'cam_off'):
                    if isinstance(d.get(k), bool):
                        sets.append(f'{k} = ?'); vals.append(int(d[k]))
            conn.execute(f"UPDATE group_call_members SET {', '.join(sets)} WHERE call_id = ? AND user_id = ?", vals + [call_id, me])
            conn.commit()
        signals = [dict(id=r['id'], from_id=r['from_id'], type=r['type'], data=r['data']) for r in conn.execute(
            'SELECT * FROM group_call_signals WHERE call_id = ? AND to_id = ? AND id > ? ORDER BY id LIMIT 200',
            (call_id, me, after)).fetchall()]
        st = _gc_state(conn, call_id, me)
        st['my_status'] = m['status']
        return jsonify({'success': True, 'call': st, 'signals': signals})
    finally:
        conn.close()


@app.route('/api/group-calls/<int:call_id>/signal', methods=['POST'])
def api_group_call_signal(call_id):
    """{"to": user_id, "type": "offer"|"answer"|"ice", "data": "..."} to someone else in the call."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    me = session['user_id']
    d = request.get_json(silent=True) or {}
    kind, data = d.get('type'), d.get('data')
    try:
        to = int(d.get('to'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Bad signal.'}), 400
    if kind not in ('offer', 'answer', 'ice') or not isinstance(data, str) or not data or len(data) > 100000:
        return jsonify({'success': False, 'message': 'Bad signal.'}), 400
    conn = _gc_conn()
    try:
        a, b = _gc_member(conn, call_id, me), _gc_member(conn, call_id, to)
        if not a or not b or a['status'] != 'joined' or b['status'] != 'joined':
            return jsonify({'success': False, 'message': 'That person is not in the call.'}), 409
        conn.execute('INSERT INTO group_call_signals (call_id, from_id, to_id, type, data) VALUES (?, ?, ?, ?, ?)',
                     (call_id, me, to, kind, data))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


