@app.route('/api/friends', methods=['GET'])
def api_friends():
    """Your friends, friend requests waiting for you, requests you sent, and the teachers you follow.
    ?user_id=<id> lists another learner's friends (if their profile and friend count are visible to you)."""
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401
    me = session['user_id']
    try:
        uid = int(request.args.get('user_id') or me)
    except ValueError:
        return jsonify({'success': False, 'message': 'Bad user id'}), 400
    conn = _links_db()
    try:
        _friends_tables(conn)
        if uid != me:
            if not can_view_profile(conn, me, session.get('role'), uid) or 'follows' in profile_hidden_parts(conn, me, session.get('role'), uid):
                return jsonify({'success': False, 'private': True, 'message': 'This learner keeps their friends private.'}), 403

        def person(row, extra=None):
            d = {'id': row['id'], 'name': _full_name(row['firstname'], row['lastname'], 'Learner'),
                 'initials': (((row['firstname'] or '')[:1] + (row['lastname'] or '')[:1]).upper() or '?'),
                 'avatar_url': get_avatar_url(row['id'], row['avatar_filename'])}
            d.update(extra or {})
            return d

        friends = [person(r, {'since': to_iso_utc(r['created_at'])}) for r in conn.execute('''
            SELECT u.id, u.firstname, u.lastname, u.avatar_filename, MAX(f1.created_at, f2.created_at) AS created_at
            FROM follows f1 JOIN follows f2 ON f2.follower_id = f1.following_id AND f2.following_id = f1.follower_id
            JOIN users u ON u.id = f1.following_id
            WHERE f1.follower_id = ? AND COALESCE(u.role, 'student') = 'student'
            ORDER BY u.firstname, u.lastname''', (uid,)).fetchall()]
        out = {'success': True, 'is_me': uid == me, 'friends': friends}
        if uid == me:
            out['incoming'] = [person(r, {'request_id': r['rid'], 'sent_at': r['created_at']}) for r in conn.execute('''
                SELECT fr.id AS rid, fr.created_at, u.id, u.firstname, u.lastname, u.avatar_filename
                FROM friend_requests fr JOIN users u ON u.id = fr.from_id
                WHERE fr.to_id = ? AND fr.status = 'pending' ORDER BY fr.id DESC''', (me,)).fetchall()]
            out['sent'] = [person(r, {'request_id': r['rid'], 'sent_at': r['created_at']}) for r in conn.execute('''
                SELECT fr.id AS rid, fr.created_at, u.id, u.firstname, u.lastname, u.avatar_filename
                FROM friend_requests fr JOIN users u ON u.id = fr.to_id
                WHERE fr.from_id = ? AND fr.status = 'pending' ORDER BY fr.id DESC''', (me,)).fetchall()]
            out['teachers'] = [person(r) for r in conn.execute('''
                SELECT u.id, u.firstname, u.lastname, u.avatar_filename FROM follows f JOIN users u ON u.id = f.following_id
                WHERE f.follower_id = ? AND u.role = 'teacher' ORDER BY u.firstname''', (me,)).fetchall()]
        return jsonify(out)
    finally:
        conn.close()


@app.route('/api/people', methods=['GET'])
def list_people():
    """
    ?q=     search by first name, last name or full name (optional)
    ?type=  all (default) | friends (learners only) | teachers
    Without ?q= it returns suggestions: people you follow first, then
    the most-followed learners and teachers.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Authentication required'}), 401

    my_id = session['user_id']
    q = (request.args.get('q') or '').strip()[:60]
    kind = (request.args.get('type') or 'all').strip().lower()
    if q and len(q) < 2:          # one letter at a time would list everyone
        return jsonify({'success': True, 'people': [], 'message': 'Type at least 2 letters.'})
    if q and _reset_rate_limited(f'people-search:{my_id}', limit=40, window=60):
        return jsonify({'success': False, 'message': 'Too many searches. Wait a moment and try again.'}), 429
    _c = sqlite3.connect('users.db'); _privacy_table(_c); _c.close()

    if session.get('role', 'student') == 'student':
        kind = 'friends'      # learners connect with other learners; teachers are found on the Teachers page
    if kind == 'teachers':
        role_sql = "COALESCE(u.role, 'student') = 'teacher'"
    elif kind == 'friends':
        role_sql = "COALESCE(u.role, 'student') = 'student'"
    else:
        role_sql = "COALESCE(u.role, 'student') IN ('student', 'teacher')"

    sql = f'''
        SELECT u.id, u.firstname, u.lastname, u.avatar_filename, COALESCE(u.role, 'student') AS role,
               (SELECT COUNT(*) FROM follows f WHERE f.following_id = u.id) AS followers,
               EXISTS (SELECT 1 FROM follows f WHERE f.follower_id = ? AND f.following_id = u.id) AS i_follow,
               EXISTS (SELECT 1 FROM follows f WHERE f.follower_id = u.id AND f.following_id = ?) AS follows_me
        FROM users u
        WHERE {role_sql} AND u.id != ?
          AND (NOT EXISTS (SELECT 1 FROM privacy_settings ps WHERE ps.user_id = u.id AND ps.searchable = 0)
               OR EXISTS (SELECT 1 FROM follows f2 WHERE f2.follower_id = ? AND f2.following_id = u.id))
    '''
    params = [my_id, my_id, my_id, my_id]

    if q:
        safe = q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
        like = f'%{safe}%'
        sql += '''
            AND (u.firstname LIKE ? ESCAPE '\\'
                 OR u.lastname LIKE ? ESCAPE '\\'
                 OR (u.firstname || ' ' || u.lastname) LIKE ? ESCAPE '\\')
        '''
        params += [like, like, like]
        sql += ' ORDER BY u.firstname, u.lastname LIMIT 15'
    else:
        sql += ' ORDER BY i_follow DESC, followers DESC, u.firstname LIMIT 12'

    conn = sqlite3.connect('users.db')
    _friends_tables(conn)
    cursor = conn.cursor()
    cursor.execute(sql, params)
    rows = cursor.fetchall()
    sent = {r[0] for r in conn.execute("SELECT to_id FROM friend_requests WHERE from_id = ? AND status = 'pending'", (my_id,))}
    received = {r[0]: r[1] for r in conn.execute("SELECT from_id, id FROM friend_requests WHERE to_id = ? AND status = 'pending'", (my_id,))}
    i_am_learner = session.get('role', 'student') == 'student'
    counts = {uid: (teacher_learner_count(conn, uid) if role == 'teacher' else friends_count(conn, uid)) for uid, _a, _b, _c, role, *_ in rows}
    conn.close()

    people = []
    for uid, first, last, avatar, role, followers, i_follow, follows_me in rows:
        if role == 'teacher':
            state = 'teacher'
        elif not i_am_learner:
            state = 'not_allowed'
        elif i_follow and follows_me:
            state = 'friends'
        elif uid in sent:
            state = 'sent'
        elif uid in received:
            state = 'received'
        else:
            state = 'none'
        first = (first or '').strip()
        last = (last or '').strip()
        name = f"{first} {last}".strip()
        if not name:
            continue
        people.append({
            'id': uid,
            'name': name,
            'initials': ((first[:1] + last[:1]).upper() or '?'),
            'avatar_url': get_avatar_url(uid, avatar),
            'role': 'teacher' if role == 'teacher' else 'learner',
            'following': bool(i_follow) if role == 'teacher' else state == 'friends',
            'follows_me': False,
            'state': state,                                   # see relationship()
            'request_id': received.get(uid),
            'followers_count': counts.get(uid, 0),            # learners: friends; teachers: learners following
        })

    return jsonify({'success': True, 'people': people})


@app.route('/api/people/follow-stats', methods=['GET'])
def people_follow_stats():
    """Friends (learners) who follow you, plus how many learners and teachers you follow."""
