def _admin_template_exists(name):
    folder = app.template_folder or 'templates'
    if not os.path.isabs(folder):
        folder = os.path.join(app.root_path, folder)
    return os.path.isfile(os.path.join(folder, name))


@app.context_processor
def inject_admin_nav():
    if session.get('role') != 'admin':
        return {}
    groups = []
    for title, items in ADMIN_NAV:
        shown = [{'href': h, 'endpoint': ep, 'icon': ic, 'label': lb, 'badge': bd}
                 for h, ep, ic, lb, tpl, bd in items if _admin_template_exists(tpl)]
        if shown:
            groups.append({'title': title, 'items': shown})
    return {'admin_nav': groups}


@app.route('/api/admin/badges')
def admin_badges():
    """Numbers for the admin sidebar and header: work waiting for an admin."""
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    me = session['user_id']
    conn = _links_db()

    def one(sql, args=()):
        try:
            r = conn.execute(sql, args).fetchone()
            return r[0] or 0 if r else 0
        except sqlite3.Error:
            return 0
    try:
        out = {
            'support': one("SELECT COUNT(*) FROM complaints WHERE status != 'resolved'"),
            'support_new': one('SELECT COUNT(*) FROM complaints WHERE COALESCE(is_read, 0) = 0'),
            'support_urgent': one("SELECT COUNT(*) FROM complaints WHERE status != 'resolved' AND priority = 'urgent'"),
            'plan_payments': one("SELECT COUNT(*) FROM plan_payments WHERE status = 'pending'"),
            'teaching_payments': one("SELECT COUNT(*) FROM tutoring_payments WHERE status = 'pending'"),
            'messages': one('SELECT COUNT(*) FROM messages WHERE receiver_id = ? AND COALESCE(is_read, 0) = 0 '
                            'AND COALESCE(is_broadcast, 0) = 0', (me,)),
            'notifications': one('SELECT COUNT(*) FROM notifications WHERE user_id = ? AND COALESCE(is_read, 0) = 0', (me,)),
        }
        out['live'] = one("SELECT COUNT(*) FROM live_classes WHERE state = 'live'")
        out['reviews'] = _mod_needs_count(conn)
        out['payments'] = out['plan_payments'] + out['teaching_payments']
        out['success'] = True
        return jsonify(out)
    finally:
        conn.close()


