def _admin_tables(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS admin_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER, action TEXT NOT NULL,
        target_type TEXT, target_id INTEGER, detail TEXT, created_at TEXT NOT NULL)''')
    conn.execute('''CREATE TABLE IF NOT EXISTS announcements (
        id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER, audience TEXT NOT NULL,
        title TEXT NOT NULL, message TEXT NOT NULL, link TEXT, recipients INTEGER DEFAULT 0,
        created_at TEXT NOT NULL, withdrawn_at TEXT)''')
    _account_table(conn)
    cols = {r[1] for r in conn.execute('PRAGMA table_info(account_state)').fetchall()}
    for col, typ in (('suspended', 'INTEGER NOT NULL DEFAULT 0'), ('suspended_reason', 'TEXT'),
                     ('suspended_until', 'TEXT'), ('suspended_by', 'INTEGER')):
        if col not in cols:
            conn.execute(f'ALTER TABLE account_state ADD COLUMN {col} {typ}')


def admin_log(conn, action, target_type=None, target_id=None, detail=''):
    """Record what an admin did. Call before conn.commit()."""
    try:
        _admin_tables(conn)
        conn.execute('INSERT INTO admin_log (admin_id, action, target_type, target_id, detail, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                     (session.get('user_id'), action, target_type, target_id, str(detail or '')[:500], _iso(_utc_now())))
    except sqlite3.Error as e:
        print(f'admin_log skipped: {e}')


def _admin_guard():
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Please sign in again.'}), 401
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'message': 'Admins only'}), 403
    return None


def _suspension(conn, uid):
    """None, or {'reason', 'until'} if the account is suspended right now."""
    try:
        _admin_tables(conn)
        r = conn.execute('SELECT suspended, suspended_reason, suspended_until FROM account_state WHERE user_id = ?', (uid,)).fetchone()
    except sqlite3.Error:
        return None
    if not r or not r[0]:
        return None
    until = _parse_any(r[2])
    if until and until <= _utc_now():
        conn.execute('UPDATE account_state SET suspended = 0, suspended_reason = NULL, suspended_until = NULL WHERE user_id = ?', (uid,))
        conn.commit()
        return None
    return {'reason': r[1] or '', 'until': _iso(until) if until else None}


@app.before_request
def _enforce_suspension():
    uid = session.get('user_id')
    if not uid or request.endpoint in (None, 'static', 'login', 'logout'):
        return None
    conn = sqlite3.connect('users.db')
    try:
        s = _suspension(conn, uid)
    finally:
        conn.close()
    if not s:
        return None
    session.clear()
    until = _parse_any(s['until'])
    msg = 'This account is suspended' + (f" until {(until + timedelta(hours=3)).strftime('%d %b %Y')}" if until else '') + '.'
    if s['reason']:
        msg += f" Reason: {s['reason']}"
    msg += ' Contact Eschool support if you think this is a mistake.'
    if request.path.startswith('/api/') or request.is_json:
        return jsonify({'success': False, 'message': msg}), 401
    return redirect(url_for('login', message=msg))


def _people_row(conn, r, susp, deact):
    return {
        'id': r['id'], 'name': _full_name(r['firstname'], r['lastname'], 'No name'), 'firstname': r['firstname'] or '',
        'lastname': r['lastname'] or '', 'email': r['email'] or '', 'role': r['role'] or 'student',
        'country': r['country'] or '', 'plan': (r['plan'] if 'plan' in r.keys() else None) or 'free',
        'plan_expires_at': r['plan_expires_at'] if 'plan_expires_at' in r.keys() else None,
        'avatar_url': get_avatar_url(r['id'], r['avatar_filename']) if r['avatar_filename'] else None,
        'status': 'suspended' if r['id'] in susp else 'deactivated' if r['id'] in deact else 'active',
        'google': r['password'] is None,
    }


def _people_aggregates(conn):
    """Per-person numbers for the Users list, worked out in a few grouped queries."""
    def grouped(sql, args=()):
        try:
            return {r[0]: r[1] for r in conn.execute(sql, args).fetchall()}
        except sqlite3.Error:
            return {}
    agg = {
        'seen': grouped(f"SELECT user_id, MAX({_dt('last_seen')}) FROM account_devices GROUP BY user_id"),
        'ep_seen': grouped(f"SELECT user_id, MAX({_dt('created_at')}) FROM ep_events GROUP BY user_id"),
        'reports_open': grouped("SELECT reported_id, COUNT(*) FROM message_reports WHERE COALESCE(status, 'open') = 'open' GROUP BY reported_id"),
        'reports_all': grouped('SELECT reported_id, COUNT(*) FROM message_reports GROUP BY reported_id'),
        'tips_reported': grouped('''SELECT o.user_id, COUNT(DISTINCT r.user_id) FROM opinion_reports r JOIN opinions o ON o.id = r.opinion_id
                                    GROUP BY o.user_id'''),
        'blocked_by': grouped('SELECT blocked_id, COUNT(*) FROM message_blocks GROUP BY blocked_id'),
        'tickets_open': grouped("SELECT user_id, COUNT(*) FROM complaints WHERE COALESCE(status, 'pending') != 'resolved' GROUP BY user_id"),
        'lessons_flagged': grouped('''SELECT t.teacher_id, COUNT(*) FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                                      WHERE s.outcome IN ('review', 'not_taught') GROUP BY t.teacher_id'''),
        'warned': grouped('''SELECT l.teacher_id, COUNT(*) FROM live_reviews r JOIN live_classes l ON l.id = r.class_id
                             WHERE r.status = 'warned' GROUP BY l.teacher_id'''),
        'mod_warned': grouped('SELECT user_id, COUNT(*) FROM mod_warnings GROUP BY user_id'),
        'pays_for': grouped("SELECT parent_id, COUNT(DISTINCT student_id) FROM plan_payments WHERE status = 'confirmed' GROUP BY parent_id"),
        'phone': grouped("SELECT user_id, phone FROM user_details WHERE COALESCE(phone, '') != ''"),
    }
    try:
        agg['device'] = {r[0]: r[1] for r in conn.execute(
            f'''SELECT d.user_id, d.label FROM account_devices d JOIN (SELECT user_id, MAX({_dt('last_seen')}) m FROM account_devices GROUP BY user_id) x
                ON x.user_id = d.user_id AND {_dt('d.last_seen')} = x.m''').fetchall()}
    except sqlite3.Error:
        agg['device'] = {}
    return agg


def _people_flags(p, agg):
    uid, f = p['id'], []
    if agg['reports_open'].get(uid):
        f.append(['reports', f"{agg['reports_open'][uid]} open report{'s' if agg['reports_open'][uid] != 1 else ''}", 'bad'])
    elif agg['reports_all'].get(uid):
        f.append(['reports_old', f"{agg['reports_all'][uid]} past report{'s' if agg['reports_all'][uid] != 1 else ''}", 'grey'])
    if agg['tips_reported'].get(uid):
        f.append(['tips', 'Tips reported', 'warn'])
    if agg['blocked_by'].get(uid):
        f.append(['blocked', f"Blocked by {agg['blocked_by'][uid]}", 'warn'])
    if p['role'] == 'teacher' and agg['lessons_flagged'].get(uid):
        f.append(['lessons', f"{agg['lessons_flagged'][uid]} lesson{'s' if agg['lessons_flagged'][uid] != 1 else ''} flagged", 'bad'])
    if p['role'] == 'teacher' and agg['warned'].get(uid):
        f.append(['warned', 'Warned', 'warn'])
    if agg.get('mod_warned', {}).get(uid):
        n = agg['mod_warned'][uid]
        f.append(['mod_warned', f"{n} community warning{'s' if n != 1 else ''}", 'bad' if n >= 3 else 'warn'])
    if agg['tickets_open'].get(uid):
        f.append(['tickets', f"{agg['tickets_open'][uid]} open ticket{'s' if agg['tickets_open'][uid] != 1 else ''}", 'grey'])
    return f


def _people_list(conn, args):
    """Everyone with the filters from the query string. Returns (people, counts)."""
    _admin_tables(conn)
    try:
        _ensure_plan_columns(conn)
    except Exception:
        pass
    susp_rows = {r[0]: r[1] for r in conn.execute('SELECT user_id, suspended_until FROM account_state WHERE suspended = 1').fetchall()}
    deact = deactivated_user_ids(conn)
    agg = _people_aggregates(conn)
    now = _utc_now()
    people = []
    for r in conn.execute('SELECT * FROM users').fetchall():
        p = _people_row(conn, r, set(susp_rows), deact)
        uid = p['id']
        seen = max([x for x in (agg['seen'].get(uid), agg['ep_seen'].get(uid)) if x] or [''])
        p['last_active'] = _an_iso(seen) if seen else None
        p['device'] = agg['device'].get(uid) or ''
        p['joined'] = _an_iso(r['joined_at']) if 'joined_at' in r.keys() and r['joined_at'] else None
        p['phone'] = agg['phone'].get(uid) or ''
        exp = _parse_any(p.get('plan_expires_at'))
        p['plan_active'] = p['plan'] in ('basic', 'pro') and (not exp or exp > now)
        p['plan_days_left'] = max(0, (exp - now).days) if exp and p['plan_active'] else None
        p['pays_for'] = agg['pays_for'].get(uid, 0)
        p['suspended_until'] = _an_iso(susp_rows.get(uid)) if susp_rows.get(uid) else None
        p['flags'] = _people_flags(p, agg)
        p['reported'] = bool(agg['reports_open'].get(uid) or agg['tips_reported'].get(uid))
        last = _parse_any(p['last_active'])
        p['inactive'] = not last or (now - last).days >= 30
        p['active7'] = bool(last and (now - last).days < 7)
        people.append(p)
    counts = {'all': len(people)}
    for p in people:
        counts[p['role']] = counts.get(p['role'], 0) + 1
        counts[p['status']] = counts.get(p['status'], 0) + 1
        if p['role'] == 'student' and p['plan_active']:
            counts['paid'] = counts.get('paid', 0) + 1
        for k in ('reported', 'inactive', 'active7'):
            if p[k]:
                counts[k] = counts.get(k, 0) + 1
        j = _parse_any(p['joined'])
        if j and (now - j).days < 7:
            counts['new7'] = counts.get('new7', 0) + 1
        if p['role'] == 'teacher' and any(f[0] in ('lessons', 'warned') for f in p['flags']):
            counts['teachers_flagged'] = counts.get('teachers_flagged', 0) + 1
        su = _parse_any(p['suspended_until'])
        if p['status'] == 'suspended' and su and (su - now).days < 7:
            counts['suspended_ending'] = counts.get('suspended_ending', 0) + 1
    try:
        counts['parents_linked'] = conn.execute("SELECT COUNT(DISTINCT parent_id) FROM parent_links WHERE status = 'active'").fetchone()[0]
        counts['reports_open'] = conn.execute("SELECT COUNT(*) FROM message_reports WHERE COALESCE(status, 'open') = 'open'").fetchone()[0]
    except sqlite3.Error:
        pass
    # filters
    q = ' '.join((args.get('q') or '').lower().split())[:80]
    if q:
        qd = re.sub(r'\D', '', q)
        people = [p for p in people if q in (p['name'] + ' ' + p['email'] + ' #' + str(p['id'])).lower() or q == str(p['id'])
                  or (len(qd) >= 4 and qd in re.sub(r'\D', '', p['phone']))]
    role = args.get('role') or ''
    if role in ('student', 'teacher', 'parent', 'admin'):
        people = [p for p in people if p['role'] == role]
    status = args.get('status') or ''
    if status in ('active', 'suspended', 'deactivated'):
        people = [p for p in people if p['status'] == status]
    elif status in ('reported', 'inactive'):
        people = [p for p in people if p[status]]
    country = (args.get('country') or '').upper()
    if country:
        people = [p for p in people if (p['country'] or '').upper() == ('' if country == 'NONE' else country)]
    plan = args.get('plan') or ''
    if plan == 'paid':
        people = [p for p in people if p['plan_active']]
    elif plan in ('free', 'basic', 'pro'):
        people = [p for p in people if (p['plan'] if p['plan_active'] or p['plan'] == 'free' else 'free') == plan and p['role'] == 'student']
    joined = args.get('joined') or ''
    if joined.isdigit():
        cut = now - timedelta(days=int(joined))
        people = [p for p in people if _parse_any(p['joined']) and _parse_any(p['joined']) >= cut]
    sort = args.get('sort') or 'newest'
    key = {'newest': lambda p: -p['id'], 'oldest': lambda p: p['id'], 'name': lambda p: p['name'].lower(),
           'role': lambda p: (p['role'], p['name'].lower()),
           'active': lambda p: -(_parse_any(p['last_active']).timestamp() if p['last_active'] else 0),
           'reports': lambda p: (-sum(1 for f in p['flags'] if f[2] == 'bad'), -len(p['flags']), -p['id'])}.get(sort, lambda p: -p['id'])
    people.sort(key=key)
    return people, counts


@app.route('/api/admin/people')
def admin_people():
    g = _admin_guard()
    if g:
        return g
    page = int(request.args.get('page')) if str(request.args.get('page') or '').isdigit() else 1
    page = max(1, page)
    per = 25
    conn = _links_db()
    try:
        people, counts = _people_list(conn, request.args)
        countries = sorted({(p['country'] or '').upper() for p in people if p['country']})
        total = len(people)
        return jsonify({'success': True, 'people': people[(page - 1) * per: page * per], 'total': total,
                        'page': page, 'pages': max(1, (total + per - 1) // per), 'counts': counts, 'me': session['user_id'],
                        'countries': [{'code': c, 'name': PROFILE_COUNTRIES.get(c, c)} for c in countries]})
    finally:
        conn.close()


@app.route('/api/admin/people/export')
def admin_people_export():
    """The filtered list as a CSV file (same filters as the page)."""
    g = _admin_guard()
    if g:
        return g
    import csv, io
    conn = _links_db()
    try:
        people, _ = _people_list(conn, request.args)
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(['ID', 'Name', 'Email', 'Phone', 'Type', 'Country', 'Plan', 'Plan ends', 'Status', 'Joined', 'Last active', 'Flags'])
        safe = lambda v: ("'" + v) if isinstance(v, str) and v[:1] in ('=', '+', '-', '@') else v
        for p in people:
            w.writerow([p['id'], safe(p['name']), safe(p['email']), safe(p['phone']), ROLE_LABELS.get(p['role'], p['role']), p['country'],
                        p['plan'] if p['role'] == 'student' else '', p.get('plan_expires_at') or '', p['status'],
                        p['joined'] or '', p['last_active'] or '', '; '.join(f[1] for f in p['flags'])])
        admin_log(conn, 'Exported users', 'user', None, f'{len(people)} people')
        conn.commit()
        return Response('﻿' + buf.getvalue(), mimetype='text/csv',
                        headers={'Content-Disposition': f'attachment; filename="eschool-users-{_utc_now().strftime("%Y-%m-%d")}.csv"',
                                 'Cache-Control': 'no-store'})
    finally:
        conn.close()


@app.route('/api/admin/reports/message/<int:rid>', methods=['POST'])
def admin_message_report_decide(rid):
    """{"status": "closed" | "actioned" | "open", "note": "..."}: an admin reviewed a reported chat."""
    g = _admin_guard()
    if g:
        return g
    d = request.get_json(silent=True) or {}
    st = d.get('status')
    if st not in ('closed', 'actioned', 'open'):
        return jsonify({'success': False, 'message': 'Choose closed, action taken or open.'}), 400
    conn = _links_db()
    try:
        r = conn.execute('SELECT reported_id, reporter_id FROM message_reports WHERE id = ?', (rid,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'Report not found.'}), 404
        conn.execute('UPDATE message_reports SET status = ? WHERE id = ?', (st, rid))
        note = str(d.get('note') or '').strip()[:300]
        admin_log(conn, {'closed': 'Closed a report', 'actioned': 'Acted on a report', 'open': 'Reopened a report'}[st], 'user', r[0],
                  f'report #{rid}' + (f': {note}' if note else ''))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/admin/people/<int:uid>/file')
def admin_person_file(uid):
    """Everything Eschool knows about one person, for the admin person file."""
    g = _admin_guard()
    if g:
        return g
    conn = _links_db()
    try:
        _admin_tables(conn)
        r = conn.execute('SELECT * FROM users WHERE id = ?', (uid,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'This account no longer exists.'}), 404
        role = r['role'] or 'student'
        now = _utc_now()
        names = {}

        def who(i):
            if i is None:
                return 'Someone'
            if i not in names:
                u = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (i,)).fetchone()
                names[i] = _full_name(u[0], u[1], 'Deleted account') if u else 'Deleted account'
            return names[i]

        def rows(sql, args=(uid,)):
            try:
                return [dict(x) for x in conn.execute(sql, args).fetchall()]
            except sqlite3.Error:
                return []

        def one(sql, args=(uid,)):
            try:
                x = conn.execute(sql, args).fetchone()
                return (x[0] if x and x[0] is not None else 0)
            except sqlite3.Error:
                return 0
        out = {'success': True, 'me': session['user_id']}
        timeline = []

        def tl(at, cat, text, level=''):
            if at:
                timeline.append({'at': _an_iso(at), 'cat': cat, 'text': text, 'level': level})

        # ---- who they are ----
        det = (rows('''SELECT phone, city, school, grade_level, bio, gender, guardian_name, guardian_phone, guardian_relation,
                              dream_career, career_changed_at, timezone FROM user_details WHERE user_id = ?''') or [{}])[0]
        agg = _people_aggregates(conn)
        susp = _suspension(conn, uid)
        p = _people_row(conn, r, {uid} if susp else set(), deactivated_user_ids(conn))
        seen = max([x for x in (agg['seen'].get(uid), agg['ep_seen'].get(uid)) if x] or [''])
        p.update({'details': det, 'suspension': susp, 'joined': _an_iso(r['joined_at']) if 'joined_at' in r.keys() and r['joined_at'] else None,
                  'last_active': _an_iso(seen) if seen else None, 'device': agg['device'].get(uid) or '',
                  'flags': _people_flags(p, agg), 'country_name': PROFILE_COUNTRIES.get((r['country'] or '').upper(), r['country'] or '')})
        exp = _parse_any(p.get('plan_expires_at'))
        p['plan_active'] = p['plan'] in ('basic', 'pro') and (not exp or exp > now)
        out['person'] = p

        # ---- reports and safety ----
        about = []
        for x in rows('SELECT id, reporter_id, reason, messages, status, created_at FROM message_reports WHERE reported_id = ? ORDER BY created_at DESC, id DESC'):
            try:
                msgs = json.loads(x['messages'] or '[]')
            except ValueError:
                msgs = []
            about.append({'id': x['id'], 'by': who(x['reporter_id']), 'by_id': x['reporter_id'], 'reason': x['reason'] or '',
                          'status': x['status'] or 'open', 'at': _an_iso(x['created_at']),
                          'messages': [{'from': 'them' if m.get('from') == uid else who(m.get('from')), 'text': str(m.get('text') or '')[:500],
                                        'at': m.get('at')} for m in msgs[-20:] if isinstance(m, dict)]})
            tl(x['created_at'], 'reports', f"Reported by {who(x['reporter_id'])}" + (f": “{x['reason']}”" if x['reason'] else ''), 'bad')
        made = [{'id': x['id'], 'about': who(x['reported_id']), 'about_id': x['reported_id'], 'reason': x['reason'] or '',
                 'status': x['status'] or 'open', 'at': _an_iso(x['created_at'])}
                for x in rows('SELECT id, reported_id, reason, status, created_at FROM message_reports WHERE reporter_id = ? ORDER BY id DESC')]
        for x in made:
            tl(x['at'], 'reports', f"Reported {x['about']}" + (f": “{x['reason']}”" if x['reason'] else ''))
        tips = []
        for x in rows('''SELECT o.id, o.text, o.created_at, COUNT(DISTINCT r.user_id) AS n, GROUP_CONCAT(DISTINCT r.reason) AS reasons, MAX(r.created_at) AS last
                         FROM opinions o JOIN opinion_reports r ON r.opinion_id = o.id WHERE o.user_id = ? GROUP BY o.id ORDER BY last DESC'''):
            tips.append({'id': x['id'], 'text': (x['text'] or '')[:300], 'reports': x['n'], 'reasons': (x['reasons'] or '')[:300],
                         'hidden': x['n'] >= OPINION_HIDE_AT, 'at': _an_iso(x['last'])})
            tl(x['last'], 'reports', f"Their tip was reported by {x['n']} {'person' if x['n'] == 1 else 'people'}" + (' and is hidden' if x['n'] >= OPINION_HIDE_AT else ''), 'warn')
        blocked_by = [{'id': x['blocker_id'], 'name': who(x['blocker_id']), 'at': _an_iso(x['created_at'])}
                      for x in rows('SELECT blocker_id, created_at FROM message_blocks WHERE blocked_id = ? ORDER BY created_at DESC')]
        for x in blocked_by:
            tl(x['at'], 'reports', f"Blocked by {x['name']}", 'warn')
        blocked = [{'id': x['blocked_id'], 'name': who(x['blocked_id']), 'at': _an_iso(x['created_at'])}
                   for x in rows('SELECT blocked_id, created_at FROM message_blocks WHERE blocker_id = ? ORDER BY created_at DESC')]
        removed = [{'class': x['title'] or 'A live class', 'teacher': who(x['teacher_id']), 'at': _an_iso(x['created_at'])}
                   for x in rows('''SELECT r.created_at, l.title, l.teacher_id FROM live_removed r LEFT JOIN live_classes l ON l.id = r.class_id
                                    WHERE r.user_id = ? ORDER BY r.created_at DESC''')]
        for x in removed:
            tl(x['at'], 'reports', f"Removed from the live class “{x['class']}” by {x['teacher']}", 'warn')
        log = rows('''SELECT l.action, l.detail, l.created_at, a.firstname AS af, a.lastname AS al FROM admin_log l LEFT JOIN users a ON a.id = l.admin_id
                      WHERE l.target_type = 'user' AND l.target_id = ? ORDER BY l.id DESC LIMIT 200''')
        for x in log:
            x['by'] = _full_name(x.pop('af'), x.pop('al'), 'An admin')
            x['created_at'] = _an_iso(x['created_at'])
            if x['action'] == 'Viewed person file':
                continue
            tl(x['created_at'], 'admin', f"{x['by']}: {x['action']}" + (f" ({x['detail']})" if x['detail'] else ''),
               'bad' if x['action'] in ('Suspended account', 'Deleted account') else '')
        suspensions = [x for x in log if x['action'] in ('Suspended account', 'Lifted suspension')]
        warnings = []
        if role == 'teacher':
            warnings = [{'class': x['title'], 'note': x['note'] or '', 'at': _an_iso(x['decided_at']), 'status': x['status']}
                        for x in rows('''SELECT l.title, r.note, r.decided_at, r.status FROM live_reviews r JOIN live_classes l ON l.id = r.class_id
                                         WHERE l.teacher_id = ? AND r.status IN ('warned') ORDER BY r.decided_at DESC''')]
            for x in warnings:
                tl(x['at'], 'admin', f"Warned about the live class “{x['class']}”" + (f": {x['note']}" if x['note'] else ''), 'bad')
        out['safety'] = {'about': about, 'made': made, 'tips': tips, 'blocked_by': blocked_by, 'blocked': blocked,
                         'removed': removed, 'suspensions': suspensions, 'warnings': warnings,
                         'muted_by': one('SELECT COUNT(*) FROM message_mutes WHERE muted_id = ?')}

        # ---- sign-ins and devices ----
        devices = [{'label': x['label'] or 'Device', 'kind': x['kind'], 'google': x['method'] == 'google', 'first': _an_iso(x['created_at']),
                    'last': _an_iso(x['last_seen']), 'ended': bool(x['ended'])}
                   for x in rows('SELECT label, kind, method, created_at, last_seen, ended FROM account_devices WHERE user_id = ? ORDER BY last_seen DESC LIMIT 30')]
        EV = {'signin': 'Signed in', 'signin_new': 'Signed in on a new device', 'failed': 'Failed sign-in', 'password': 'Changed their password',
              'email': 'Changed their email', 'backup_email': 'Set a backup email', 'backup_on': 'Turned on backup email', 'backup_off': 'Removed backup email',
              'device_out': 'Signed a device out', 'others_out': 'Signed out other devices', 'deactivated': 'Deactivated their account', 'signup': 'Created the account'}
        events = []
        for x in rows('SELECT kind, detail, n, created_at FROM account_events WHERE user_id = ? ORDER BY id DESC LIMIT 200'):
            text = EV.get(x['kind'], (x['kind'] or '').replace('_', ' ').capitalize()) + (f" ({x['detail']})" if x['detail'] else '') + (f" ×{x['n']}" if (x['n'] or 0) > 1 else '')
            events.append({'at': _an_iso(x['created_at']), 'kind': x['kind'], 'text': text})
            if x['kind'] != 'signin':
                tl(x['created_at'], 'account', text, 'warn' if x['kind'] in ('failed', 'signin_new', 'deactivated') else '')
        sec = (rows('SELECT pw_set_at, backup_email, backup_verified FROM account_security WHERE user_id = ?') or [{}])[0]
        out['account'] = {'devices': devices, 'events': events,
                          'failed_30': one(f"SELECT COALESCE(SUM(COALESCE(n, 1)), 0) FROM account_events WHERE user_id = ? AND kind = 'failed' AND {_dt('created_at')} >= datetime('now', '-30 days')"),
                          'signins_30': one(f"SELECT COUNT(*) FROM account_events WHERE user_id = ? AND kind IN ('signin', 'signin_new') AND {_dt('created_at')} >= datetime('now', '-30 days')"),
                          'password_set': _an_iso(sec.get('pw_set_at')) if sec.get('pw_set_at') else None,
                          'backup_email': bool(sec.get('backup_email')), 'backup_verified': bool(sec.get('backup_verified')),
                          'google': r['password'] is None}

        # ---- learning / teaching ----
        learn = {}
        if role == 'student':
            ep = conn.execute(f"SELECT COALESCE(SUM(ep), 0), COALESCE(SUM(CASE WHEN {_dt('created_at')} >= datetime('now', '-7 days') THEN ep ELSE 0 END), 0) FROM ep_events WHERE user_id = ?", (uid,)).fetchone()
            prog = (rows('SELECT avg_progress, modules_completed, courses_completed, quizzes_passed, active_days, courses FROM student_progress_summary WHERE student_id = ?') or [{}])[0]
            try:
                courses = [{'name': c.get('name') or c.get('id'), 'progress': int(float(c.get('progress') or 0))} for c in json.loads(prog.get('courses') or '[]')]
            except (ValueError, TypeError, AttributeError):
                courses = []
            att = rows('''SELECT a.class_id, l.title, MIN(a.joined_at) AS joined, SUM((julianday(COALESCE(a.left_at, a.last_seen)) - julianday(a.joined_at)) * 1440) AS mins
                          FROM live_attendance a LEFT JOIN live_classes l ON l.id = a.class_id WHERE a.user_id = ? GROUP BY a.class_id ORDER BY joined DESC LIMIT 50''')
            for x in att:
                tl(x['joined'], 'learning', f"Attended the live class “{x['title'] or 'Live class'}” for {round(x['mins'] or 0)} min")
            learn = {'ep': ep[0], 'ep_week': ep[1], 'streak': one('SELECT MAX(COALESCE(run, 0)) FROM ep_streaks WHERE user_id = ?'),
                     'best_streak': one('SELECT MAX(COALESCE(best, 0)) FROM ep_streaks WHERE user_id = ?'),
                     'avg_progress': prog.get('avg_progress') or 0, 'modules': prog.get('modules_completed') or 0,
                     'courses_done': prog.get('courses_completed') or 0, 'quizzes': prog.get('quizzes_passed') or 0,
                     'active_days': prog.get('active_days') or 0, 'courses': courses,
                     'badges': one('SELECT COUNT(*) FROM achievements_unlocked WHERE user_id = ?'),
                     'career': det.get('dream_career') or '', 'career_since': _an_iso(det.get('career_changed_at')) if det.get('career_changed_at') else None,
                     'strategies': one('SELECT COUNT(DISTINCT sid) FROM strategy_days WHERE user_id = ?'),
                     'focus_minutes': one('SELECT COALESCE(SUM(minutes), 0) FROM focus_blocks WHERE user_id = ?'),
                     'live_attended': len(att), 'live_minutes': round(sum(x['mins'] or 0 for x in att)),
                     'live': [{'title': x['title'] or 'Live class', 'at': _an_iso(x['joined']), 'minutes': round(x['mins'] or 0)} for x in att[:10]],
                     'resources_viewed': one('SELECT COUNT(*) FROM resource_views WHERE user_id = ?'),
                     'friends': one("SELECT COUNT(*) FROM friend_requests WHERE (from_id = ? OR to_id = ?) AND status = 'accepted'", (uid, uid))}
            KIND = {'module': 'Finished a module', 'quiz': 'Passed a quiz', 'review': 'Did a review', 'focus': 'Did a focus session',
                    'surprise': 'Did the Surprise task', 'career_mission': 'Finished a career mission', 'career_story': 'Read a career story',
                    'activity': 'Did an activity', 'starter': 'Getting-started step'}
            for x in rows('SELECT kind, ref, ep, created_at FROM ep_events WHERE user_id = ? ORDER BY id DESC LIMIT 80'):
                tl(x['created_at'], 'learning', f"{KIND.get(x['kind'], (x['kind'] or '').replace('_', ' ').capitalize())}" + (f" · {x['ref']}" if x['ref'] else '') + f" (+{x['ep']} EP)")
            for x in rows('SELECT key, unlocked_at FROM achievements_unlocked WHERE user_id = ? ORDER BY unlocked_at DESC LIMIT 30'):
                tl(x['unlocked_at'], 'learning', f"Unlocked the badge “{str(x['key']).replace('_', ' ')}”")
        elif role == 'teacher':
            lc = rows('''SELECT id, title, state, start_time, went_live_at, ended_at, duration_min, peak_viewers FROM live_classes WHERE teacher_id = ?
                         ORDER BY COALESCE(went_live_at, start_time) DESC LIMIT 60''')
            for x in lc:
                if x['went_live_at']:
                    tl(x['went_live_at'], 'learning', f"Taught the live class “{x['title']}”" + (f" for {_span_minutes(x['went_live_at'], x['ended_at'])} min" if x['ended_at'] else ''))
            lessons = rows('''SELECT s.outcome, s.status, s.starts_at FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id WHERE t.teacher_id = ?''')
            learn = {'live_classes': len([x for x in lc if x['went_live_at']]),
                     'live_minutes': sum(_span_minutes(x['went_live_at'], x['ended_at']) for x in lc if x['went_live_at'] and x['ended_at']),
                     'live_rating': round(one('SELECT AVG(stars) FROM live_ratings WHERE teacher_id = ?') or 0, 1) or None,
                     'rating': _rating_summary(conn, [uid])[uid]['avg'],
                     'ratings': _rating_summary(conn, [uid])[uid]['count'],
                     'reviews': one('SELECT COUNT(*) FROM teacher_ratings WHERE teacher_id = ?'),
                     'lessons': len(lessons), 'lessons_taught': sum(1 for x in lessons if x['outcome'] == 'taught'),
                     'lessons_flagged': sum(1 for x in lessons if x['outcome'] in ('review', 'not_taught')),
                     'learners': one("SELECT COUNT(DISTINCT student_id) FROM tutoring WHERE teacher_id = ? AND status IN ('active', 'accepted', 'ended')"),
                     'followers': one('SELECT COUNT(*) FROM follows WHERE following_id = ?'),
                     'classes': [{'id': x['id'], 'title': x['title'], 'state': x['state'], 'at': _an_iso(x['went_live_at'] or x['start_time']),
                                  'minutes': _span_minutes(x['went_live_at'], x['ended_at']) if x['went_live_at'] and x['ended_at'] else None,
                                  'planned': x['duration_min']} for x in lc[:10]]}
        elif role == 'parent':
            learn = {'children': []}
        if role == 'admin':
            learn['admin_actions'] = one('SELECT COUNT(*) FROM admin_log WHERE admin_id = ?')
            learn['resources'] = one('SELECT COUNT(*) FROM resources WHERE user_id = ?')
        out['learning'] = learn

        # ---- money ----
        pays = rows('''SELECT id, parent_id, student_id, plan, days, amount, method, reference, status, created_at, decided_at FROM plan_payments
                       WHERE parent_id = ? OR student_id = ? ORDER BY id DESC LIMIT 50''', (uid, uid))
        for x in pays:
            x['payer'], x['for'] = who(x['parent_id']), who(x['student_id'])
            x['created_at'] = _an_iso(x['created_at'])
            tl(x['created_at'], 'money', f"{x['plan'].title()} plan for {x['for']}, {x['days']} days: {_money(x['amount'])} ({x['status']})" + (f" · paid by {x['payer']}" if x['parent_id'] != uid else ''),
               'bad' if x['status'] == 'rejected' else '')
        tpays = rows('''SELECT p.id, p.amount, p.sessions, p.status, p.created_at, t.teacher_id, t.student_id, t.parent_id, t.subject FROM tutoring_payments p
                        JOIN tutoring t ON t.id = p.tutoring_id WHERE t.parent_id = ? OR t.teacher_id = ? OR t.student_id = ? ORDER BY p.id DESC LIMIT 50''', (uid, uid, uid))
        for x in tpays:
            x['teacher'], x['learner'], x['payer'] = who(x['teacher_id']), who(x['student_id']), who(x['parent_id'])
            x['created_at'] = _an_iso(x['created_at'])
            tl(x['created_at'], 'money', f"Tutoring: {x['sessions']} {x['subject']} lessons, {_money(x['amount'])} ({x['status']}) · {x['payer']} → {x['teacher']}")
        conf = lambda lst, f: sum(x['amount'] or 0 for x in lst if x['status'] == 'confirmed' and f(x))
        out['money'] = {'plan_payments': pays, 'tutoring_payments': tpays, 'currency': SITE_CURRENCY,
                        'plans_paid': conf(pays, lambda x: x['parent_id'] == uid), 'plans_for_them': conf(pays, lambda x: x['student_id'] == uid),
                        'tutoring_paid': conf(tpays, lambda x: x['parent_id'] == uid), 'tutoring_earned': conf(tpays, lambda x: x['teacher_id'] == uid),
                        'tutoring_for_them': conf(tpays, lambda x: x['student_id'] == uid),
                        'pending': sum(1 for x in pays + tpays if x['status'] == 'pending'),
                        'plan': p['plan'], 'plan_expires_at': p.get('plan_expires_at'), 'plan_active': p['plan_active']}

        # ---- support ----
        tickets = rows('SELECT id, subject, description, category, priority, status, response, response_date, created_at FROM complaints WHERE user_id = ? ORDER BY id DESC')
        for x in tickets:
            x['created_at'] = _an_iso(x['created_at'])
            x['description'] = (x['description'] or '')[:600]
            x['response'] = (x['response'] or '')[:400]
            tl(x['created_at'], 'support', f"Opened ticket #{x['id']} “{x['subject']}” ({x['status']})")
        out['support'] = tickets

        # ---- family ----
        links = rows('''SELECT pl.id, pl.parent_id, pl.student_id, pl.status, pl.relationship, pl.permissions, pl.linked_at, pl.requested_at
                        FROM parent_links pl WHERE pl.parent_id = ? OR pl.student_id = ? ORDER BY pl.id DESC''', (uid, uid))
        fam = []
        for x in links:
            other = x['student_id'] if x['parent_id'] == uid else x['parent_id']
            o = conn.execute("SELECT COALESCE(role, 'student'), plan, plan_expires_at FROM users WHERE id = ?", (other,)).fetchone()
            try:
                perms = json.loads(x['permissions'] or '{}')
            except (ValueError, TypeError):
                perms = {}
            fam.append({'id': other, 'name': who(other), 'role': o[0] if o else '', 'status': x['status'], 'relationship': x['relationship'] or '',
                        'since': _an_iso(x['linked_at'] or x['requested_at']), 'plan': (o[1] if o else '') or 'free',
                        'sees': sorted(k for k, v in (perms.items() if isinstance(perms, dict) else []) if v)})
            tl(x['linked_at'] or x['requested_at'], 'family', f"Linked with {who(other)} ({x['status']})")
        if role == 'parent':
            out['learning']['children'] = [f for f in fam if f['status'] == 'active']
        access = [{'at': _an_iso(x['created_at']), 'text': x['text'], 'by': x['by_role'], 'parent': who(x['parent_id']), 'learner': who(x['student_id'])}
                  for x in rows('SELECT parent_id, student_id, text, by_role, created_at FROM access_log WHERE parent_id = ? OR student_id = ? ORDER BY id DESC LIMIT 40', (uid, uid))]
        controls = [{'at': _an_iso(x['created_at']), 'text': x['text'], 'parent': who(x['parent_id']), 'learner': who(x['student_id'])}
                    for x in rows('SELECT parent_id, student_id, text, created_at FROM controls_log WHERE parent_id = ? OR student_id = ? ORDER BY id DESC LIMIT 40', (uid, uid))]
        for x in controls:
            tl(x['at'], 'family', f"Parental controls: {x['text']}")
        out['family'] = {'links': fam, 'access': access, 'controls': controls}

        # ---- admin history ----
        out['admin_history'] = log
        if role == 'admin':
            out['their_admin_actions'] = [dict(x, created_at=_an_iso(x['created_at'])) for x in rows(
                'SELECT action, target_type, target_id, detail, created_at FROM admin_log WHERE admin_id = ? ORDER BY id DESC LIMIT 60')]

        # ---- created account / what needs attention ----
        if p['joined']:
            tl(p['joined'], 'account', 'Joined Eschool')
        timeline.sort(key=lambda x: _parse_any(x['at']) or datetime.min.replace(tzinfo=timezone.utc), reverse=True)
        out['timeline'] = timeline[:300]
        att = []
        open_about = [x for x in about if x['status'] == 'open']
        if open_about:
            reasons = ', '.join(sorted({x['reason'] for x in open_about if x['reason']}))[:120]
            att.append(f"{len(open_about)} open report{'s' if len(open_about) != 1 else ''} about them" + (f" ({reasons})" if reasons else ''))
        recent = [x for x in about if _parse_any(x['at']) and (now - _parse_any(x['at'])).days < 30]
        if len(recent) >= 2:
            att.append(f"reported {len(recent)} times in the last 30 days")
        hid = len([t for t in tips if t['hidden']])
        if hid:
            att.append(f"{hid} tip{'s' if hid != 1 else ''} hidden after reports")
        if blocked_by:
            att.append(f"blocked by {len(blocked_by)} {'person' if len(blocked_by) == 1 else 'people'}")
        n_susp = sum(1 for x in suspensions if x['action'] == 'Suspended account')
        if n_susp:
            att.append(f"suspended {n_susp} time{'s' if n_susp != 1 else ''} before")
        if warnings:
            att.append(f"warned about {len(warnings)} live class{'es' if len(warnings) != 1 else ''}")
        if role == 'teacher' and learn.get('lessons_flagged'):
            att.append(f"{learn['lessons_flagged']} paid lesson{'s' if learn['lessons_flagged'] != 1 else ''} flagged as not proved or not taught")
        if out['account']['failed_30'] >= 5:
            att.append(f"{out['account']['failed_30']} failed sign-ins in 30 days")
        out['attention'] = att
        admin_log(conn, 'Viewed person file', 'user', uid, p['name'])
        conn.commit()
        return jsonify(out)
    finally:
        conn.close()


@app.route('/api/admin/people/<int:uid>')
def admin_person(uid):
    g = _admin_guard()
    if g:
        return g
    conn = _links_db()
    try:
        _admin_tables(conn)
        r = conn.execute('SELECT * FROM users WHERE id = ?', (uid,)).fetchone()
        if not r:
            return jsonify({'success': False, 'message': 'This account no longer exists.'}), 404
        susp = {uid} if _suspension(conn, uid) else set()
        p = _people_row(conn, r, susp, deactivated_user_ids(conn))

        def one(sql, args=(uid,)):
            try:
                x = conn.execute(sql, args).fetchone()
                return x[0] or 0 if x else 0
            except sqlite3.Error:
                return 0

        def rows(sql, args=(uid,)):
            try:
                return [dict(x) for x in conn.execute(sql, args).fetchall()]
            except sqlite3.Error:
                return []
        det = rows('SELECT phone, city, school, grade_level, bio FROM user_details WHERE user_id = ?')
        p['details'] = det[0] if det else {}
        p['suspension'] = _suspension(conn, uid)
        p['stats'] = {
            'resources': one('SELECT COUNT(*) FROM resources WHERE user_id = ?'),
            'followers': one('SELECT COUNT(*) FROM follows WHERE following_id = ?'),
            'following': one('SELECT COUNT(*) FROM follows WHERE follower_id = ?'),
            'messages_sent': one('SELECT COUNT(*) FROM messages WHERE sender_id = ? AND COALESCE(is_broadcast, 0) = 0'),
            'tickets': one('SELECT COUNT(*) FROM complaints WHERE user_id = ?'),
            'live_classes': one('SELECT COUNT(*) FROM live_classes WHERE teacher_id = ?'),
            'reviews_received': one('SELECT COUNT(*) FROM teacher_ratings WHERE teacher_id = ?'),
            'rating': _rating_summary(conn, [uid])[uid]['avg'] or None,
            'paid_plans': one("SELECT COALESCE(SUM(amount), 0) FROM plan_payments WHERE parent_id = ? AND status = 'confirmed'"),
            'paid_teaching': one("SELECT COALESCE(SUM(amount), 0) FROM tutoring_payments WHERE parent_id = ? AND status = 'confirmed'"),
            'earned_teaching': one("SELECT COALESCE(SUM(p.amount), 0) FROM tutoring_payments p JOIN tutoring t ON t.id = p.tutoring_id "
                                   "WHERE t.teacher_id = ? AND p.status = 'confirmed'"),
        }
        p['links'] = rows('''SELECT u.id, u.firstname, u.lastname, u.role, pl.status, pl.relationship FROM parent_links pl
                             JOIN users u ON u.id = CASE WHEN pl.parent_id = ? THEN pl.student_id ELSE pl.parent_id END
                             WHERE pl.parent_id = ? OR pl.student_id = ?''', (uid, uid, uid))
        for l in p['links']:
            l['name'] = _full_name(l.pop('firstname'), l.pop('lastname'), 'Someone')
        p['tickets'] = rows('SELECT id, subject, status, priority, created_at FROM complaints WHERE user_id = ? ORDER BY id DESC LIMIT 4')
        p['log'] = rows('''SELECT l.action, l.detail, l.created_at, a.firstname AS af FROM admin_log l LEFT JOIN users a ON a.id = l.admin_id
                           WHERE l.target_type = 'user' AND l.target_id = ? ORDER BY l.id DESC LIMIT 6''')
        return jsonify({'success': True, 'person': p, 'me': session['user_id']})
    finally:
        conn.close()


VALID_ROLES = ('student', 'teacher', 'parent', 'admin')


@app.route('/api/admin/people/<int:uid>/action', methods=['POST'])
def admin_person_action(uid):
    """{"action": "role"|"suspend"|"unsuspend"|"reset_password"|"sign_out", ...}"""
    g = _admin_guard()
    if g:
        return g
    d = request.get_json(silent=True) or {}
    act = d.get('action')
    me = session['user_id']
    conn = _links_db()
    try:
        _admin_tables(conn)
        u = conn.execute('SELECT id, firstname, lastname, email, role FROM users WHERE id = ?', (uid,)).fetchone()
        if not u:
            return jsonify({'success': False, 'message': 'This account no longer exists.'}), 404
        name = _full_name(u['firstname'], u['lastname'], u['email'] or f'#{uid}')
        out = {'success': True}
        if act in ('role', 'suspend', 'reset_password', 'sign_out') and uid == me and act != 'sign_out':
            return jsonify({'success': False, 'message': 'You can\'t do that to your own account here. Use Settings.'}), 400
        if act == 'role':
            role = d.get('role')
            if role not in VALID_ROLES:
                return jsonify({'success': False, 'message': 'Choose learner, teacher, parent or admin.'}), 400
            old = u['role'] or 'student'
            if old == role:
                return jsonify({'success': False, 'message': 'That is already their role.'}), 400
            if old == 'admin' and conn.execute("SELECT COUNT(*) FROM users WHERE role = 'admin'").fetchone()[0] <= 1:
                return jsonify({'success': False, 'message': 'Eschool needs at least one admin.'}), 400
            conn.execute('UPDATE users SET role = ? WHERE id = ?', (role, uid))
            acc = _account_row(conn, uid)
            _account_upsert(conn, uid, session_epoch=acc['epoch'] + 1)      # signs them in again with the new role
            create_notification(conn, uid, 'Your account type changed',
                                f"An Eschool admin changed your account to {ROLE_LABELS.get(role, role)}. Sign in again to see your new pages.",
                                icon='fa-user-gear', color='blue')
            admin_log(conn, 'Changed role', 'user', uid, f'{name}: {ROLE_LABELS.get(old, old)} to {ROLE_LABELS.get(role, role)}')
        elif act == 'suspend':
            reason = str(d.get('reason') or '').strip()[:300]
            if len(reason) < 5:
                return jsonify({'success': False, 'message': 'Write a short reason. The person sees it when they try to sign in.'}), 400
            try:
                days = int(d.get('days') or 0)
            except (TypeError, ValueError):
                days = 0
            until = _iso(_utc_now() + timedelta(days=days)) if 0 < days <= 3650 else None
            if (u['role'] or '') == 'admin':
                return jsonify({'success': False, 'message': 'Change this admin to another role before suspending them.'}), 400
            acc = _account_row(conn, uid)
            _account_upsert(conn, uid, suspended=1, suspended_reason=reason, suspended_until=until, suspended_by=me,
                            session_epoch=acc['epoch'] + 1)
            admin_log(conn, 'Suspended account', 'user', uid, f"{name} {'for ' + str(days) + ' days' if until else 'until lifted'}: {reason}")
        elif act == 'unsuspend':
            _account_upsert(conn, uid, suspended=0, suspended_reason=None, suspended_until=None)
            create_notification(conn, uid, 'Your account is active again', 'Your Eschool account is no longer suspended. Welcome back.',
                                icon='fa-circle-check', color='green')
            admin_log(conn, 'Lifted suspension', 'user', uid, name)
        elif act == 'reset_password':
            if u['role'] == 'admin':
                return jsonify({'success': False, 'message': 'Admins change their own password in Settings.'}), 400
            import secrets
            temp = 'es-' + secrets.token_urlsafe(6).replace('-', 'x').replace('_', 'y')
            conn.execute('UPDATE users SET password = ? WHERE id = ?', (hash_password(temp), uid))
            acc = _account_row(conn, uid)
            _account_upsert(conn, uid, session_epoch=acc['epoch'] + 1)
            create_notification(conn, uid, 'Your password was reset',
                                'An Eschool admin reset your password at your request. Change it in Settings after you sign in.',
                                icon='fa-key', color='orange')
            admin_log(conn, 'Reset password', 'user', uid, name)
            out['temp_password'] = temp
        elif act == 'sign_out':
            acc = _account_row(conn, uid)
            _account_upsert(conn, uid, session_epoch=acc['epoch'] + 1)
            admin_log(conn, 'Signed out of all devices', 'user', uid, name)
        else:
            return jsonify({'success': False, 'message': 'Unknown action.'}), 400
        conn.commit()
        return jsonify(out)
    finally:
        conn.close()


ROLE_LABELS = {'student': 'Learner', 'teacher': 'Teacher', 'parent': 'Parent', 'admin': 'Admin'}


@app.route('/api/admin/people/<int:uid>', methods=['DELETE'])
def admin_person_delete(uid):
    """Deletes an account and everything it owns. JSON: {"confirm": "<their email>"}"""
    g = _admin_guard()
    if g:
        return g
    if uid == session['user_id']:
        return jsonify({'success': False, 'message': 'You can\'t delete your own account.'}), 400
    d = request.get_json(silent=True) or {}
    conn = _links_db()
    try:
        _admin_tables(conn)
        u = conn.execute('SELECT firstname, lastname, email, role FROM users WHERE id = ?', (uid,)).fetchone()
        if not u:
            return jsonify({'success': False, 'message': 'This account no longer exists.'}), 404
        if (d.get('confirm') or '').strip().lower() != (u['email'] or '').lower():
            return jsonify({'success': False, 'message': 'Type their email address exactly to confirm.'}), 400
        if u['role'] == 'admin':
            return jsonify({'success': False, 'message': 'Change this admin to another role first.'}), 400
        tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table'").fetchall()]
        for t in tables:
            if t in ('users', 'admin_log'):
                continue
            cols = {c[1] for c in conn.execute(f'PRAGMA table_info("{t}")').fetchall()}
            for c in _OWNER_COLUMNS:
                if c in cols:
                    conn.execute(f'DELETE FROM "{t}" WHERE "{c}" = ?', (uid,))
        conn.execute('DELETE FROM users WHERE id = ?', (uid,))
        admin_log(conn, 'Deleted account', 'user', uid, f"{_full_name(u['firstname'], u['lastname'], '')} <{u['email']}> ({ROLE_LABELS.get(u['role'] or 'student')})")
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


