# ----- payments (plans + private teaching) -----
@app.route('/api/admin/money')
def admin_money():
    g = _admin_guard()
    if g:
        return g
    status = request.args.get('status', 'pending')
    kind = request.args.get('kind', '')
    q = (request.args.get('q') or '').strip().lower()
    conn = _links_db()
    try:
        _payments_table(conn)
        _tutor_tables(conn)
        names = {r['id']: (_full_name(r['firstname'], r['lastname'], 'Someone'), r['email'] or '') for r in conn.execute('SELECT id, firstname, lastname, email FROM users')}
        def nm(i):
            return names.get(i, ('Deleted account', ''))
        items = []
        if kind in ('', 'plan'):
            _plan_pay_columns(conn)
            for r in conn.execute("SELECT * FROM plan_payments WHERE status NOT IN ('started', 'failed') ORDER BY id DESC LIMIT 500").fetchall():
                items.append({'kind': 'plan', 'id': r['id'], 'payer': nm(r['parent_id'])[0], 'payer_email': nm(r['parent_id'])[1], 'payer_id': r['parent_id'],
                              'for': nm(r['student_id'])[0], 'for_id': r['student_id'],
                              'what': f"Eschool {PLAN_NAMES.get(r['plan'], r['plan'])} · {r['days']} days", 'amount': r['amount'] or 0,
                              'reference': (r['receipt'] or r['reference']) if r['method'] == 'stripe' else r['reference'], 'phone': r['phone'] or '',
                              'method': 'Card' if r['method'] == 'stripe' else 'M-Pesa code',
                              'status': r['status'], 'note': r['note'] or '',
                              'created_at': _an_iso(r['created_at']), 'decided_at': _an_iso(r['decided_at']),
                              'decided_by': nm(r['decided_by'])[0] if r['decided_by'] else None})
        if kind in ('', 'teaching'):
            for r in conn.execute('''SELECT p.*, t.subject, t.teacher_id, t.student_id FROM tutoring_payments p
                                     LEFT JOIN tutoring t ON t.id = p.tutoring_id WHERE p.status NOT IN ('started', 'failed') ORDER BY p.id DESC LIMIT 500''').fetchall():
                items.append({'kind': 'teaching', 'id': r['id'], 'payer': nm(r['parent_id'])[0], 'payer_email': nm(r['parent_id'])[1], 'payer_id': r['parent_id'],
                              'for': nm(r['student_id'])[0], 'for_id': r['student_id'],
                              'what': f"{r['sessions']} session{'s' if r['sessions'] != 1 else ''} of {r['subject'] or 'lessons'} with {nm(r['teacher_id'])[0]}",
                              'teacher_id': r['teacher_id'], 'amount': r['amount'] or 0, 'reference': r['receipt'] or r['reference'], 'phone': r['phone'] or '',
                              'method': {'stripe': 'Card', 'mpesa_stk': 'M-Pesa prompt'}.get(r['method'], 'M-Pesa code'),
                              'status': r['status'], 'note': r['note'] or '', 'created_at': _an_iso(r['created_at']),
                              'decided_at': _an_iso(r['decided_at']), 'decided_by': nm(r['decided_by'])[0] if r['decided_by'] else None})
        summary = {'pending': 0, 'pending_amount': 0, 'confirmed_month': 0, 'confirmed_total': 0, 'rejected': 0, 'plan_total': 0, 'teaching_total': 0}
        month = (_utc_now() + timedelta(hours=3)).strftime('%Y-%m')
        monthly = {}
        for it in items:
            if it['status'] == 'pending':
                summary['pending'] += 1; summary['pending_amount'] += it['amount']
            elif it['status'] == 'confirmed':
                summary['confirmed_total'] += it['amount']
                summary[it['kind'] + '_total'] += it['amount']
                m = (it['decided_at'] or it['created_at'] or '')[:7]
                if m == month:
                    summary['confirmed_month'] += it['amount']
                if m:
                    monthly.setdefault(m, {'plan': 0, 'teaching': 0})[it['kind']] += it['amount']
            elif it['status'] == 'rejected':
                summary['rejected'] += 1
        # duplicate M-Pesa codes across both kinds are a warning sign
        seen = {}
        for it in items:
            seen.setdefault((it['reference'] or '').upper(), []).append(it)
        for ref, group in seen.items():
            if ref and len(group) > 1:
                for it in group:
                    it['duplicate'] = True
        shown = [it for it in items if (status in ('', 'all') or it['status'] == status)
                 and (not q or q in ' '.join(str(it[k]) for k in ('payer', 'payer_email', 'for', 'what', 'reference', 'phone')).lower())]
        shown.sort(key=lambda it: it['created_at'] or '', reverse=True)
        months = sorted(monthly)[-6:]
        return jsonify({'success': True, 'items': shown[:300], 'summary': summary,
                        'monthly': [{'month': m, **monthly[m]} for m in months]})
    finally:
        conn.close()


# ----- live classes -----
@app.route('/api/admin/live')
def admin_live_list():
    g = _admin_guard()
    if g:
        return g
    conn = _live_db()
    try:
        rows = conn.execute('''SELECT l.*, u.firstname, u.lastname,
                                (SELECT COUNT(*) FROM live_viewers v WHERE v.class_id = l.id) AS joined,
                                (SELECT COUNT(*) FROM live_chat c WHERE c.class_id = l.id AND c.deleted = 0) AS chat
                               FROM live_classes l LEFT JOIN users u ON u.id = l.teacher_id ORDER BY l.start_time DESC LIMIT 300''').fetchall()
        now = _utc_now()
        out = []
        for r in rows:
            st = r['state'] or 'scheduled'
            seen_alive = _parse_any(r['teacher_seen']) if 'teacher_seen' in r.keys() else None
            stale = st == 'live' and (not seen_alive or (now - seen_alive).total_seconds() > 180)
            out.append({'id': r['id'], 'title': r['title'], 'subject': r['subject'], 'grade': r['grade'],
                        'teacher': _full_name(r['firstname'], r['lastname'], 'Deleted teacher'), 'teacher_id': r['teacher_id'],
                        'start': _an_iso(r['start_time']), 'minutes': r['duration_min'], 'state': st, 'stale': stale,
                        'went_live_at': _an_iso(r['went_live_at']), 'ended_at': _an_iso(r['ended_at']),
                        'joined': r['joined'], 'peak': r['peak_viewers'] or 0, 'chat': r['chat']})
        counts = {s: sum(1 for x in out if x['state'] == s) for s in ('live', 'scheduled', 'ended')}
        return jsonify({'success': True, 'classes': out, 'counts': counts})
    finally:
        conn.close()


@app.route('/api/admin/live/<int:cid>', methods=['POST', 'DELETE'])
def admin_live_action(cid):
    """POST {"action": "end", "reason": "..."} ends a class now. DELETE {"reason": "..."} removes it."""
    g = _admin_guard()
    if g:
        return g
    d = request.get_json(silent=True) or {}
    reason = str(d.get('reason') or '').strip()[:300]
    conn = _live_db()
    try:
        lc = conn.execute('SELECT * FROM live_classes WHERE id = ?', (cid,)).fetchone()
        if not lc:
            return jsonify({'success': False, 'message': 'This class no longer exists.'}), 404
        if len(reason) < 5:
            return jsonify({'success': False, 'message': 'Write a short reason. The teacher will see it.'}), 400
        if request.method == 'DELETE':
            for t in ('live_viewers', 'live_signals', 'live_chat', 'live_attendance', 'live_events', 'live_reviews'):
                conn.execute(f'DELETE FROM {t} WHERE class_id = ?', (cid,))
            for (name,) in conn.execute("SELECT file_name FROM session_recordings WHERE kind = 'live' AND ref_id = ?", (cid,)).fetchall():
                try:
                    if name and '/' not in name and os.path.isfile(_rec_path(name)):
                        os.remove(_rec_path(name))
                except OSError:
                    pass
            conn.execute("DELETE FROM session_recordings WHERE kind = 'live' AND ref_id = ?", (cid,))
            conn.execute('DELETE FROM live_classes WHERE id = ?', (cid,))
            create_notification(conn, lc['teacher_id'], 'Live class removed',
                                f"An Eschool admin removed your live class \"{lc['title']}\". Reason: {reason}", icon='fa-video-slash', color='red')
            admin_log(conn, 'Removed live class', 'live', cid, f"\"{lc['title']}\": {reason}")
        else:
            if (lc['state'] or '') == 'ended':
                return jsonify({'success': False, 'message': 'This class has already ended.'}), 400
            conn.execute("UPDATE live_classes SET state = 'ended', ended_at = COALESCE(ended_at, ?) WHERE id = ?", (_iso(_utc_now()), cid))
            conn.execute('DELETE FROM live_signals WHERE class_id = ?', (cid,))
            _live_event(conn, cid, session['user_id'], 'admin_ended', reason)
            _att_close(conn, cid)
            conn.execute("UPDATE session_recordings SET status = 'done' WHERE kind = 'live' AND ref_id = ? AND status = 'recording'", (cid,))
            create_notification(conn, lc['teacher_id'], 'Live class ended by Eschool',
                                f"An Eschool admin ended \"{lc['title']}\". Reason: {reason}", icon='fa-circle-stop', color='red')
            admin_log(conn, 'Ended live class', 'live', cid, f"\"{lc['title']}\": {reason}")
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


