# ----- the teacher's studio uploads the recording in pieces -----
@app.route('/api/live/<int:cid>/recording', methods=['POST'])
def api_live_recording_chunk(cid):
    """Body: one piece of the recording (video/webm or video/mp4). ?rid= the recording it belongs to
    (missing on the first piece), ?seq= its number (0, 1, 2...; a resent piece is ignored),
    ?final=1 on the last one."""
    if not RECORD_LIVE_CLASSES:
        return jsonify({'success': False, 'message': 'Recording is off.'}), 410
    conn = _live_db()
    try:
        lc, err = _live_guard(conn, cid, teacher=True)
        if err:
            return err
        ended = _parse_any(lc['ended_at'])
        late_ok = (lc['state'] or '') == 'ended' and request.args.get('rid') and ended and (_live_now() - ended).total_seconds() <= 120
        if (lc['state'] or '') != 'live' and not late_ok:      # the last piece may arrive just after the class ends
            return jsonify({'success': False, 'message': 'The class is not live.'}), 409
        mime = (request.mimetype or '').lower()
        if mime not in ('video/webm', 'video/mp4', 'audio/webm'):
            return jsonify({'success': False, 'message': 'Unsupported recording type.'}), 415
        if (request.content_length or 0) > RECORDING_MAX_CHUNK:
            return jsonify({'success': False, 'message': 'Piece too large.'}), 413
        try:
            seq = int(request.args.get('seq', '0'))
            rid = int(request.args.get('rid') or 0)
        except ValueError:
            return jsonify({'success': False, 'message': 'Bad piece number.'}), 400
        data = request.get_data(cache=False)
        os.makedirs(RECORDINGS_DIR, exist_ok=True)
        now = _iso(_live_now())
        if rid:
            rec = conn.execute("SELECT id, file_name, bytes, last_seq FROM session_recordings WHERE id = ? AND kind = 'live' AND ref_id = ?",
                               (rid, cid)).fetchone()
            if not rec:
                return jsonify({'success': False, 'message': 'Recording not found.'}), 404
        else:
            name = f'live_{cid}_{uuid.uuid4().hex}.' + ('mp4' if mime == 'video/mp4' else 'webm')
            cur = conn.execute('''INSERT INTO session_recordings (kind, ref_id, teacher_id, file_name, mime, started_at, ended_at, status)
                                  VALUES ('live', ?, ?, ?, ?, ?, ?, 'recording')''', (cid, lc['teacher_id'], name, mime, now, now))
            rec = (cur.lastrowid, name, 0, -1)
            _live_event(conn, cid, lc['teacher_id'], 'rec_start')
        if seq > rec[3] and data:
            if rec[2] + len(data) > RECORDING_MAX_BYTES:
                return jsonify({'success': False, 'message': 'This recording reached its size limit.', 'rid': rec[0], 'full': True}), 413
            with open(_rec_path(rec[1]), 'ab') as f:
                f.write(data)
            conn.execute('''UPDATE session_recordings SET bytes = bytes + ?, chunks = chunks + 1, last_seq = ?, ended_at = ?,
                            status = ? WHERE id = ?''', (len(data), seq, now, 'done' if request.args.get('final') else 'recording', rec[0]))
        elif request.args.get('final'):
            conn.execute("UPDATE session_recordings SET status = 'done', ended_at = ? WHERE id = ?", (now, rec[0]))
        conn.commit()
        if request.args.get('final'):
            threading.Thread(target=_rec_tidy, args=(_rec_path(rec[1]),), daemon=True).start()
        return jsonify({'success': True, 'rid': rec[0]})
    finally:
        conn.close()


# ----- admin: live classes and paid lessons, with the evidence -----
def _live_flags(c, now):
    """Problems Eschool spots by itself for one class (list of [key, label, level])."""
    flags = []
    start, went, ended = _parse_any(c['start_time']), _parse_any(c['went_live_at']), _parse_any(c['ended_at'])
    planned = int(c['duration_min'] or 60)
    st = c['state'] or 'scheduled'
    if st == 'scheduled' and start and now > start + timedelta(minutes=30):
        flags.append(['no_show', 'Teacher never went live', 'bad'])
    if went and start and (went - start).total_seconds() > 10 * 60:
        flags.append(['late', f'Started {round((went - start).total_seconds() / 60)} min late', 'bad'])
    if st == 'ended' and went and ended:
        mins = (ended - went).total_seconds() / 60
        if mins < planned * 0.7:
            flags.append(['short', f'Short: {round(mins)} of {planned} min', 'bad'])
    if c['admin_ended']:
        flags.append(['admin', 'Ended by an admin', 'warn'])
    if c['rating_n'] and (c['rating_avg'] or 5) <= 2.5:
        flags.append(['rating', f"Low rating ★{round(c['rating_avg'], 1)}", 'warn'])
    if st == 'live' and (not _parse_any(c['teacher_seen']) or (now - _parse_any(c['teacher_seen'])).total_seconds() > 180):
        flags.append(['gone', 'Teacher not checking in', 'bad'])
    if st == 'ended' and went and RECORD_LIVE_CLASSES and not c['rec_n'] and went >= _parse_any(c['rec_since'] or '2100-01-01'):
        flags.append(['norec', 'No recording', 'warn'])
    return flags


def _lesson_flags(x):
    o = x['outcome']
    f = []
    if o == 'review':
        f.append(['review', 'Being checked: ' + (x.get('evidence') or 'no proof'), 'bad'])
    elif o == 'not_taught':
        f.append(['not_taught', 'Not taught (lesson given back)', 'bad'])
    elif o == 'learner_absent':
        f.append(['absent', "Learner didn't join", 'warn'])
    if x.get('parent_report'):
        f.append(['report', 'Parent reported a problem', 'bad'])
    if x.get('parent_rating') and x['parent_rating'] <= 2:
        f.append(['rating', f"Parent rated ★{x['parent_rating']}", 'warn'])
    return f


@app.route('/api/admin/live/overview')
def admin_live_overview():
    g = _admin_guard()
    if g:
        return g
    days = _res_period(request.args.get('days'))
    now = _utc_now()
    since = now - timedelta(days=days)
    conn = _live_db()
    try:
        _rec_cleanup(conn)
        conn.commit()
        first_rec = conn.execute('SELECT MIN(started_at) FROM session_recordings').fetchone()[0]
        rows = conn.execute('''
            SELECT l.*, u.firstname, u.lastname,
              (SELECT COUNT(DISTINCT a.user_id) FROM live_attendance a WHERE a.class_id = l.id AND a.user_id != l.teacher_id) AS att_n,
              (SELECT COUNT(*) FROM live_viewers v WHERE v.class_id = l.id) AS viewers_n,
              (SELECT COUNT(*) FROM live_chat c WHERE c.class_id = l.id AND c.deleted = 0) AS chat_n,
              (SELECT COUNT(*) FROM live_invites i WHERE i.class_id = l.id) AS invited_n,
              (SELECT COUNT(*) FROM live_ratings r WHERE r.class_id = l.id) AS rating_n,
              (SELECT AVG(stars) FROM live_ratings r WHERE r.class_id = l.id) AS rating_avg,
              (SELECT COUNT(*) FROM session_recordings s WHERE s.kind = 'live' AND s.ref_id = l.id) AS rec_n,
              (SELECT COALESCE(SUM(bytes), 0) FROM session_recordings s WHERE s.kind = 'live' AND s.ref_id = l.id) AS rec_bytes,
              (SELECT MAX(id) FROM session_recordings s WHERE s.kind = 'live' AND s.ref_id = l.id AND s.status != 'recording') AS rec_id,
              (SELECT COUNT(*) FROM live_events e WHERE e.class_id = l.id AND e.kind = 'admin_ended') AS admin_ended,
              rv.status AS review_status, rv.note AS review_note
            FROM live_classes l LEFT JOIN users u ON u.id = l.teacher_id LEFT JOIN live_reviews rv ON rv.class_id = l.id
            ORDER BY COALESCE(l.went_live_at, l.start_time) DESC LIMIT 600''').fetchall()
        classes = []
        for r in rows:
            c = dict(r)
            c['rec_since'] = first_rec
            st = c['state'] or 'scheduled'
            start = _parse_any(c['start_time'])
            when = _parse_any(c['went_live_at']) or start
            if st == 'ended' and when and when < since:
                continue
            went, ended = _parse_any(c['went_live_at']), _parse_any(c['ended_at'])
            flags = _live_flags(c, now)
            classes.append({
                'id': c['id'], 'kind': 'class', 'title': c['title'], 'subject': c['subject'], 'grade': c['grade'],
                'teacher': _full_name(c['firstname'], c['lastname'], 'Deleted teacher'), 'teacher_id': c['teacher_id'],
                'start': _an_iso(c['start_time']), 'minutes': int(c['duration_min'] or 60), 'state': st,
                'went_live_at': _an_iso(c['went_live_at']), 'ended_at': _an_iso(c['ended_at']),
                'actual': round((ended - went).total_seconds() / 60) if went and ended else (round((now - went).total_seconds() / 60) if went and st == 'live' else None),
                'joined': max(c['att_n'] or 0, c['viewers_n'] or 0), 'invited': c['invited_n'] or 0, 'peak': c['peak_viewers'] or 0,
                'chat': c['chat_n'] or 0, 'audience': c['audience'] or 'everyone',
                'rating': round(c['rating_avg'], 1) if c['rating_avg'] else None, 'rating_n': c['rating_n'] or 0,
                'recording': {'id': c['rec_id'], 'bytes': c['rec_bytes']} if c['rec_n'] else None,
                'flags': flags, 'review': c['review_status'] or '', 'review_note': c['review_note'] or ''})
        # paid lessons in the period (and the ones coming up)
        lconn = _links_db()
        try:
            _tutor_tables(lconn)
            lrows = _lesson_rows(lconn, 's.starts_at >= ?', (_iso(since),))
            lessons = []
            parents = {}
            for r in lrows:
                x = _lesson_json(r, 'admin')
                try:
                    x['parent_rating'] = r['parent_rating']
                except (IndexError, KeyError):
                    x['parent_rating'] = None
                pid = r['parent_id']
                if pid not in parents:
                    p = lconn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (pid,)).fetchone()
                    parents[pid] = _full_name(p[0], p[1], 'Parent') if p else 'Parent'
                x['parent'], x['parent_id'], x['kind'] = parents[pid], pid, 'lesson'
                x['flags'] = _lesson_flags(x)
                lessons.append(x)
        finally:
            lconn.close()
        ended = [c for c in classes if c['state'] == 'ended' and c['went_live_at']]
        live_now = [c for c in classes if c['state'] == 'live']
        taught = sum(c['actual'] or 0 for c in ended)
        planned = sum(c['minutes'] for c in ended)
        inv = [c for c in ended if c['invited']]
        total_rec = conn.execute("SELECT COUNT(*), COALESCE(SUM(bytes), 0) FROM session_recordings WHERE kind = 'live'").fetchone()
        need_c = [c for c in classes if c['flags'] and c['review'] not in ('ok', 'resolved', 'warned')]
        need_l = [x for x in lessons if x['outcome'] == 'review' or (x.get('parent_report') and not x.get('decision_note'))]
        viewers_now = sum(len(_live_active_viewers(conn, c['id'])) for c in live_now)
        upcoming = [c for c in classes if c['state'] == 'scheduled' and _parse_any(c['start']) and _parse_any(c['start']) >= now]
        return jsonify({'success': True, 'days': days, 'keep_days': RECORDING_KEEP_DAYS, 'recording_on': RECORD_LIVE_CLASSES,
                        'kpis': {'live_now': len(live_now), 'viewers_now': viewers_now, 'held': len(ended),
                                 'upcoming': len(upcoming), 'upcoming_today': len([c for c in upcoming if (_parse_any(c['start']) - now).total_seconds() < 86400]),
                                 'minutes_taught': taught, 'minutes_planned': planned,
                                 'avg_learners': round(sum(c['joined'] for c in ended) / len(ended), 1) if ended else 0,
                                 'attendance': round(sum(min(c['joined'], c['invited']) for c in inv) * 100 / max(1, sum(c['invited'] for c in inv))) if inv else None,
                                 'recorded': len([c for c in ended if c['recording']]), 'rec_files': total_rec[0], 'rec_bytes': total_rec[1],
                                 'review': len(need_c) + len(need_l),
                                 'lessons': len(lessons), 'lessons_taught': len([x for x in lessons if x['outcome'] == 'taught'])},
                        'classes': classes, 'lessons': lessons,
                        'review_ids': {'class': [c['id'] for c in need_c], 'lesson': [x['id'] for x in need_l]}})
    finally:
        conn.close()


def _span_minutes(a, b):
    a, b = _parse_any(a), _parse_any(b)
    return max(0, round((b - a).total_seconds() / 60)) if a and b else 0


@app.route('/api/admin/live/<int:cid>/report')
def admin_live_report(cid):
    g = _admin_guard()
    if g:
        return g
    conn = _live_db()
    try:
        lc = _live_class(conn, cid)
        if not lc:
            return jsonify({'success': False, 'message': 'This class no longer exists.'}), 404
        now = _utc_now()
        names = {}

        def who(uid):
            if uid not in names:
                u = conn.execute("SELECT firstname, lastname, COALESCE(role, 'student') FROM users WHERE id = ?", (uid,)).fetchone()
                names[uid] = (_full_name(u[0], u[1], 'Deleted account'), u[2]) if u else ('Deleted account', 'student')
            return names[uid]
        # attendance: every time each person was in the class
        people = {}
        for a in conn.execute('SELECT user_id, role, joined_at, last_seen, left_at, device FROM live_attendance WHERE class_id = ? ORDER BY id', (cid,)):
            uid = a['user_id']
            end = a['left_at'] or (a['last_seen'] if (lc['state'] or '') == 'ended' or (now - (_parse_any(a['last_seen']) or now)).total_seconds() > ATTEND_GAP_SECS else _iso(now))
            p = people.setdefault(uid, {'id': uid, 'name': who(uid)[0], 'role': 'teacher' if uid == lc['teacher_id'] else (a['role'] or who(uid)[1]),
                                        'segments': [], 'minutes': 0, 'device': a['device'] or ''})
            p['segments'].append({'from': _an_iso(a['joined_at']), 'to': _an_iso(end), 'open': not a['left_at'] and end == _iso(now)})
            p['minutes'] += _span_minutes(a['joined_at'], end)
            p['device'] = a['device'] or p['device']
        # older classes (before the attendance log): first join only
        for v in conn.execute('SELECT user_id, joined_at, last_seen FROM live_viewers WHERE class_id = ?', (cid,)):
            if v['user_id'] not in people:
                people[v['user_id']] = {'id': v['user_id'], 'name': who(v['user_id'])[0], 'role': who(v['user_id'])[1], 'device': '',
                                        'segments': [{'from': _an_iso(v['joined_at']), 'to': None, 'open': False}], 'minutes': None, 'old': True}
        invited = [r[0] for r in conn.execute('SELECT user_id FROM live_invites WHERE class_id = ?', (cid,))]
        absent = [{'id': u, 'name': who(u)[0]} for u in invited if u not in people]
        removed = [{'id': r[0], 'name': who(r[0])[0], 'at': _an_iso(r[1])} for r in conn.execute('SELECT user_id, created_at FROM live_removed WHERE class_id = ?', (cid,))]
        LABEL = {'went_live': 'went live', 'back_live': 'went live again', 'ended': 'ended the class', 'admin_ended': 'An admin ended the class',
                 'joined': 'joined', 'left': 'left', 'hand_up': 'raised their hand', 'cam_on': 'turned the camera on', 'cam_off': 'turned the camera off',
                 'mic_on': 'turned the mic on', 'mic_off': 'turned the mic off', 'screen_on': 'started sharing the screen',
                 'screen_off': 'stopped sharing the screen', 'chat_locked_on': 'locked the chat', 'chat_locked_off': 'unlocked the chat',
                 'removed': 'removed', 'let_back': 'let back in', 'rec_start': 'Recording started',
                 'teacher_back': 'came back to the class'}
        events = []
        for e in conn.execute('SELECT user_id, kind, detail, created_at FROM live_events WHERE class_id = ? ORDER BY id LIMIT 2000', (cid,)):
            text = LABEL.get(e['kind'], e['kind'].replace('_', ' '))
            detail = e['detail'] or ''
            if e['kind'] in ('removed', 'let_back') and detail.isdigit():
                text, detail = f"{text} {who(int(detail))[0]}", ''
            actor = '' if e['kind'] in ('admin_ended', 'rec_start') else (who(e['user_id'])[0] if e['user_id'] else '')
            events.append({'at': _an_iso(e['created_at']), 'who': actor, 'text': text, 'detail': detail, 'kind': e['kind']})
        chat = [{'at': _an_iso(c['created_at']), 'who': who(c['user_id'])[0], 'teacher': c['user_id'] == lc['teacher_id'],
                 'text': c['text'], 'deleted': bool(c['deleted'])}
                for c in conn.execute('SELECT user_id, text, created_at, deleted FROM live_chat WHERE class_id = ? ORDER BY id', (cid,))]
        ratings = [{'who': who(r['user_id'])[0], 'stars': r['stars'], 'comment': r['comment'] or '', 'at': _an_iso(r['created_at'])}
                   for r in conn.execute('SELECT user_id, stars, comment, created_at FROM live_ratings WHERE class_id = ? ORDER BY created_at', (cid,))]
        recs = [{'id': r['id'], 'started': _an_iso(r['started_at']), 'ended': _an_iso(r['ended_at']), 'bytes': r['bytes'],
                 'seconds': max(0, round(((_parse_any(r['ended_at']) or now) - (_parse_any(r['started_at']) or now)).total_seconds())),
                 'status': r['status'], 'mime': r['mime'],
                 'delete_on': _iso((_parse_any(r['started_at']) or now) + timedelta(days=RECORDING_KEEP_DAYS)),
                 'url': f'/api/admin/recordings/{r["id"]}'}
                for r in conn.execute("SELECT * FROM session_recordings WHERE kind = 'live' AND ref_id = ? ORDER BY id", (cid,))]
        hist = conn.execute('''SELECT l.*, NULL AS admin_ended,
                                 (SELECT COUNT(*) FROM live_ratings r WHERE r.class_id = l.id) AS rating_n,
                                 (SELECT AVG(stars) FROM live_ratings r WHERE r.class_id = l.id) AS rating_avg,
                                 1 AS rec_n, NULL AS rec_since
                               FROM live_classes l WHERE l.teacher_id = ? AND COALESCE(l.went_live_at, l.start_time) >= ?''',
                            (lc['teacher_id'], _iso(now - timedelta(days=30)))).fetchall()
        flagged = sum(1 for h in hist if _live_flags(dict(h), now))
        rv = conn.execute('SELECT r.status, r.note, r.decided_at, u.firstname, u.lastname FROM live_reviews r LEFT JOIN users u ON u.id = r.decided_by WHERE r.class_id = ?', (cid,)).fetchone()
        c = dict(lc)
        c.update({'admin_ended': bool(conn.execute("SELECT 1 FROM live_events WHERE class_id = ? AND kind = 'admin_ended'", (cid,)).fetchone()),
                  'rating_n': len(ratings), 'rating_avg': (sum(r['stars'] for r in ratings) / len(ratings)) if ratings else None,
                  'rec_n': len(recs), 'rec_since': conn.execute('SELECT MIN(started_at) FROM session_recordings').fetchone()[0]})
        flags = _live_flags(c, now)
        went, ended = _parse_any(lc['went_live_at']), _parse_any(lc['ended_at'])
        planned = int(lc['duration_min'] or 60)
        learners_in = [p for p in people.values() if p['role'] != 'teacher']
        # Eschool's finding, in one sentence
        if not went:
            finding = ('bad', 'The teacher never went live.' if flags and flags[0][0] == 'no_show' else 'This class has not started yet.')
        elif (lc['state'] or '') == 'live':
            finding = ('info', f"Live now for {round((now - went).total_seconds() / 60)} min with {len([p for p in learners_in if any(s['open'] for s in p['segments'])])} learners in the class.")
        else:
            mins = round((ended - went).total_seconds() / 60) if ended else 0
            late = round((went - _parse_any(lc['start_time'])).total_seconds() / 60) if _parse_any(lc['start_time']) else 0
            bits = [f"The teacher taught for {mins} of {planned} planned minutes"]
            if late > 10:
                bits.append(f"starting {late} minutes late")
            bits.append(f"{len(learners_in)} learner{'s' if len(learners_in) != 1 else ''} attended")
            good = mins >= planned * 0.7 and late <= 10
            finding = ('ok' if good else 'bad', ('Taught as planned. ' if good else 'Not taught as planned. ') + ', '.join(bits) + '.')
        return jsonify({'success': True, 'class': {
            'id': cid, 'title': lc['title'], 'subject': lc['subject'], 'grade': lc['grade'], 'description': lc['description'] or '',
            'teacher': _full_name(lc['firstname'], lc['lastname'], 'Deleted teacher'), 'teacher_id': lc['teacher_id'],
            'start': _an_iso(lc['start_time']), 'minutes': planned, 'state': lc['state'] or 'scheduled',
            'went_live_at': _an_iso(lc['went_live_at']), 'ended_at': _an_iso(lc['ended_at']), 'peak': lc['peak_viewers'] or 0,
            'audience': LIVE_AUDIENCES.get(lc['audience'] or 'everyone', ''), 'flags': flags},
            'finding': {'level': finding[0], 'text': finding[1]},
            'people': sorted(people.values(), key=lambda p: (p['role'] != 'teacher', p['segments'][0]['from'] or '')),
            'absent': absent, 'removed': removed, 'events': events, 'chat': chat, 'ratings': ratings, 'recordings': recs,
            'teacher_month': {'classes': len(hist), 'flagged': flagged},
            'review': {'status': rv[0], 'note': rv[1] or '', 'at': _an_iso(rv[2]), 'by': _full_name(rv[3], rv[4], 'An admin')} if rv else None,
            'keep_days': RECORDING_KEEP_DAYS})
    finally:
        conn.close()


@app.route('/api/admin/live/<int:cid>/review', methods=['POST'])
def admin_live_review(cid):
    """{"status": "ok" | "warned" | "resolved" | "open", "note": "...", "tell_teacher": true}"""
    g = _admin_guard()
    if g:
        return g
    d = request.get_json(silent=True) or {}
    status = d.get('status')
    if status not in ('ok', 'warned', 'resolved', 'open'):
        return jsonify({'success': False, 'message': 'Pick a decision.'}), 400
    note = str(d.get('note') or '').strip()[:600]
    if status == 'warned' and len(note) < 5:
        return jsonify({'success': False, 'message': 'Write what the teacher is being warned about. They will see it.'}), 400
    conn = _live_db()
    try:
        lc = conn.execute('SELECT title, teacher_id FROM live_classes WHERE id = ?', (cid,)).fetchone()
        if not lc:
            return jsonify({'success': False, 'message': 'This class no longer exists.'}), 404
        conn.execute('''INSERT INTO live_reviews (class_id, status, note, decided_by, decided_at) VALUES (?, ?, ?, ?, ?)
                        ON CONFLICT(class_id) DO UPDATE SET status = excluded.status, note = excluded.note,
                        decided_by = excluded.decided_by, decided_at = excluded.decided_at''',
                     (cid, status, note, session['user_id'], _iso(_utc_now())))
        if status == 'warned' or (d.get('tell_teacher') and note):
            create_notification(conn, lc['teacher_id'], 'About your live class' if status != 'warned' else 'Warning about your live class',
                                f"Eschool reviewed \"{lc['title']}\". {note}", icon='fa-scale-balanced', color='red' if status == 'warned' else 'blue')
        admin_log(conn, 'live_review', 'live', cid, f"\"{lc['title']}\": {status}" + (f" ({note[:120]})" if note else ''))
        conn.commit()
        return jsonify({'success': True})
    finally:
        conn.close()


@app.route('/api/admin/recordings/<int:rid>')
def admin_recording_file(rid):
    """Plays a recording for an admin (supports seeking). Every first open is written to the admin log."""
    g = _admin_guard()
    if g:
        return g
    from flask import send_file
    conn = _live_db()
    try:
        r = conn.execute('SELECT * FROM session_recordings WHERE id = ?', (rid,)).fetchone()
        if not r or not r['file_name'] or '/' in r['file_name'] or not os.path.isfile(_rec_path(r['file_name'])):
            return jsonify({'success': False, 'message': 'This recording is no longer available.'}), 404
        if r['kind'] == 'live':   # recordings can only be watched once the class is over, never while it is live
            st = conn.execute('SELECT state FROM live_classes WHERE id = ?', (r['ref_id'],)).fetchone()
            if st and (st[0] or 'scheduled') != 'ended':
                return jsonify({'success': False, 'message': 'The recording can be watched once the class ends.'}), 409
        rng = request.headers.get('Range', '')
        if not rng or rng.startswith('bytes=0-'):
            admin_log(conn, 'recording_watched', 'recording', rid, f"{r['kind']} {r['ref_id']}")
            conn.commit()
        resp = send_file(os.path.abspath(_rec_path(r['file_name'])), mimetype=r['mime'] or 'video/webm', conditional=True,
                         download_name=f"eschool-{r['kind']}-{r['ref_id']}-recording.{r['file_name'].rsplit('.', 1)[-1]}",
                         as_attachment=bool(request.args.get('download')))
        resp.headers['Cache-Control'] = 'private, no-store'
        resp.headers['X-Content-Type-Options'] = 'nosniff'
        return resp
    finally:
        conn.close()


@app.route('/api/admin/lessons/<int:sid>/report')
def admin_lesson_report(sid):
    g = _admin_guard()
    if g:
        return g
    conn = _links_db()
    try:
        _tutor_tables(conn)
        _lesson_columns(conn)
        rows = _lesson_rows(conn, 's.id = ?', (sid,))
        if not rows:
            return jsonify({'success': False, 'message': 'Lesson not found'}), 404
        s = rows[0]
        x = _lesson_json(s, 'admin')
        keys = s.keys()
        x['parent_rating'] = s['parent_rating'] if 'parent_rating' in keys else None
        x['parent_comment'] = s['parent_comment'] if 'parent_comment' in keys else ''
        x['child_attended'] = s['child_attended'] if 'child_attended' in keys else None
        x['decided_at'] = _an_iso(s['decided_at']) if 'decided_at' in keys else None
        p = conn.execute('SELECT firstname, lastname FROM users WHERE id = ?', (s['parent_id'],)).fetchone()
        x['parent'] = _full_name(p[0], p[1], 'Parent') if p else 'Parent'
        x['flags'] = _lesson_flags(x)
        # the Eschool calls between teacher and learner around the lesson
        _calls_tables(conn)
        start = _parse_any(s['starts_at']) or _utc_now()
        w0, w1 = start - timedelta(hours=2), start + timedelta(minutes=int(s['minutes'] or 60) + LESSON_GRACE_MINUTES + 60)
        calls = []
        for c in conn.execute('''SELECT caller_id, callee_id, kind, status, created_at, answered_at, ended_at FROM calls
                                 WHERE ((caller_id = ? AND callee_id = ?) OR (caller_id = ? AND callee_id = ?)) ORDER BY id DESC LIMIT 300''',
                              (s['teacher_id'], s['student_id'], s['student_id'], s['teacher_id'])):
            made = _parse_any(c['created_at'])
            if not made or made < w0 or made > w1:
                continue
            calls.append({'by': 'teacher' if c['caller_id'] == s['teacher_id'] else 'learner', 'kind': c['kind'], 'status': c['status'],
                          'at': _an_iso(c['created_at']), 'answered': _an_iso(c['answered_at']), 'ended': _an_iso(c['ended_at']),
                          'minutes': _span_minutes(c['answered_at'], c['ended_at']) if c['answered_at'] else 0})
        calls.reverse()
        pay = conn.execute('''SELECT COALESCE(SUM(amount), 0), COALESCE(SUM(sessions), 0) FROM tutoring_payments
                              WHERE tutoring_id = ? AND status = 'confirmed' ''', (s['tutoring_id'],)).fetchone()
        t = conn.execute('SELECT rate, session_minutes, status, sessions_paid FROM tutoring WHERE id = ?', (s['tutoring_id'],)).fetchone()
        recent = conn.execute('''SELECT s.outcome FROM tutoring_sessions s JOIN tutoring t ON t.id = s.tutoring_id
                                 WHERE t.teacher_id = ? AND s.starts_at >= ? AND s.status != 'scheduled' ''',
                              (s['teacher_id'], _iso(_utc_now() - timedelta(days=30)))).fetchall()
        recs = [{'id': r[0], 'bytes': r[1], 'url': f'/api/admin/recordings/{r[0]}'} for r in conn.execute(
            "SELECT id, bytes FROM session_recordings WHERE kind = 'lesson' AND ref_id = ? ORDER BY id", (sid,))]
        o = x['outcome']
        finding = {'taught': ('ok', x.get('evidence') or 'Taught.'), 'learner_absent': ('warn', x.get('evidence') or "The learner didn't join."),
                   'not_taught': ('bad', 'Decided: not taught. ' + (x.get('evidence') or '')), 'review': ('bad', x.get('evidence') or 'No proof yet.'),
                   'scheduled': ('info', 'This lesson has not happened yet.'), 'cancelled': ('info', 'This lesson was cancelled.')}.get(o, ('info', x.get('evidence') or ''))
        return jsonify({'success': True, 'lesson': x, 'calls': calls, 'recordings': recs,
                        'finding': {'level': finding[0], 'text': finding[1]},
                        'payment': {'paid': pay[0], 'sessions': pay[1], 'rate': t['rate'] if t else None, 'currency': SITE_CURRENCY,
                                    'plan_status': t['status'] if t else None},
                        'teacher_month': {'lessons': len(recent), 'flagged': sum(1 for r in recent if r[0] in ('review', 'not_taught'))}})
    finally:
        conn.close()


